    def __init__(self, athlete_id: str, intervals_api_key: str, github_token: str = None, 
                 github_repo: str = None, debug: bool = False, week_start_day: int = None,
                 zone_preference: dict = None, report_main_sports=None):
        self.athlete_id = athlete_id
        self._budget_identity = RequestBudget.fingerprint(athlete_id, intervals_api_key)
        self.intervals_auth = base64.b64encode(f"API_KEY:{intervals_api_key}".encode()).decode()
        self.github_token = github_token
        self.github_repo = github_repo
        self.debug = debug
        self.script_dir = Path(__file__).parent
        self.data_dir = Path.cwd()  # Data files (history.json, ftp_history.json) write to caller's working directory
        self.week_start_day = week_start_day if week_start_day is not None else self.WEEK_START_DAY
        self.zone_preference = zone_preference or {}  # {"run": "hr", "cycling": "power", ...}
        self.report_main_sports = self._parse_report_main_sports(report_main_sports)
        self._cached_script_hash = None  # lazy-computed
        # v3.121: Retry-After seconds from the MOST RECENT interval/stream fetch only.
        # Both fetchers reset it to None on entry, so a 429 value can never leak into
        # a later request. Valid only immediately after the fetcher returns.
        self._last_retry_after_secs = None
        # v3.133: generic-read retry accounting. Deliberately per instance and never
        # reset, so history and current-data work share one extra-attempt budget.
        self._read_retry_extra_attempts_used = 0
        # v3.133: consecutive FINAL failures of _get_activity_messages in this run.
        # Any successful retrieval, including a successful empty response, resets it.
        self._messages_consecutive_failures = 0
        # v3.147: at most eight new curves per instance/sync. Safe-read retries
        # share the existing four-extra-attempt budget (at most twelve sends).
        self._power_curve_fetches_used = 0
        self._power_curve_run_cache = {}
        self._decoupling_fetches_used = 0
        self._decoupling_run_cache = {}

    _budget_factory = RequestBudget

    @staticmethod
    def _check_interval(config, environ=None):
        env = os.environ if environ is None else environ
        if env.get("GITHUB_ACTIONS") == "true":
            return 60
        value = config.get("check_interval_minutes", 1)
        if type(value) is not int or value not in (1, 2, 5, 10):
            print("Warning: invalid check_interval_minutes; using one-minute checks (choose 1, 2, 5 or 10).")
            return 60
        return value * 60

    @property
    def request_budget(self):
        if not hasattr(self, "_request_budget"):
            factory = self._budget_factory
            if factory is RequestBudget and ExportFreshness.context(os.environ)["mode"] in ("hosted_scheduled", "on_demand"):
                factory = HostedRequestBudget
            self._request_budget = factory(
                getattr(self, "data_dir", Path.cwd()), "sync", RequestBudgetRefused,
                self._budget_identity)
        return self._request_budget

    def begin_tick(self):
        if not hasattr(self, "_acquisition"):
            self._acquisition = AcquisitionStore(self)
            self._hosted_cache = HostedSlowCache(self)
            self._hosted_cache.restore()
        return self._acquisition.begin()

    def _source_freshness(self, data, retained=False):
        store, budget = self._acquisition, self.request_budget
        now = store.now()
        sources = {}
        def unknown(group, present=False, empty=False):
            return {"status": "fresh" if empty else "stale" if present else "unavailable",
                "reason": "not_required" if empty else "acquisition_age_unknown" if present else "no_snapshot",
                "snapshot_present": present or empty, "last_attempt_at": None,
                "last_success_at": None, "source_acquired_at": None, "age_seconds": None,
                "max_age_seconds": 86400 if group in store.SCHEDULED else None,
                "next_due_at": None, "next_eligible_at": None,
                "coverage": "complete" if empty else "partial" if present else "unknown", "scope": {"resources": []}}

        def stamp(value):
            try:
                parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
                return parsed.astimezone(timezone.utc).timestamp()
            except (ValueError, TypeError, AttributeError):
                return None

        previous = data.get("source_freshness", {}).get("sources", {}) if retained else {}
        evaluated = {}
        for group in store.SOURCES:
            evaluated[group] = store.source_status(group, retained=retained)
            sources[group] = evaluated[group] or store.clone(previous.get(group, unknown(group)))

        if not retained:
            recent = data.get("recent_activities", [])
            active_ids = {str(a.get("id")) for a in recent}
            def identities(*fields):
                return {str(a.get("id")) for a in recent if any(a.get(field) for field in fields)}
            required = {
                "activity_details": identities("has_intervals", "has_dfa", "has_structure"),
                "activity_streams": identities("has_dfa", "has_structure", "dfa_rollup"),
                "activity_power": identities("power_curve_expected"),
                "activity_decoupling": identities("decoupling_detail", "decoupling_detail_status"),
                "activity_terrain": identities("has_terrain"),
                "route_attachments": getattr(self, "_route_source_ids", set()),
            }
            for group, needed in required.items():
                observed_ids = set()
                for key, entry in store.entries.items():
                    resource = entry["descriptor"]["endpoint"].split("/")[-1]
                    if entry["group"] == group and resource in (needed if group == "route_attachments" else active_ids):
                        store.consumed.setdefault(key, entry)
                        observed_ids.add(resource)
                observed = store.source_status(group)
                sources[group] = observed or unknown(group, present=bool(needed), empty=not needed)
                if observed and needed - observed_ids:
                    row = sources[group]
                    if row["status"] == "fresh":
                        row.update(status="stale", reason="acquisition_age_unknown")
                    row.update(coverage="partial", last_success_at=None, source_acquired_at=None, age_seconds=None)
                    row["scope"]["untracked_resources"] = sorted(needed - observed_ids)
            if not any(str(a.get("start_date_local", a.get("date", "")))[:10] >= (
                    datetime.now() - timedelta(days=6)).strftime("%Y-%m-%d") for a in recent):
                if store.source_status("messages") is None:
                    sources["messages"] = unknown("messages", empty=True)
            for group, filename, ttl in (("saved_workouts", "saved_workouts.json", 21600),
                                          ("history", "history.json", 29 * 86400)):
                try:
                    value = getattr(self, "_saved_workouts_data", None) if group == "saved_workouts" else None
                    if value is None:
                        value = json.loads((self.data_dir / filename).read_text())
                    if group == "saved_workouts":
                        refresh, state = value.get("refresh", {}), value.get("fetch_state", {})
                        success = stamp(refresh.get("last_success_at"))
                        attempt = stamp(state.get("last_attempt_at"))
                        valid = self._sw_cache_is_valid(value)
                        status = "fresh" if refresh.get("status") == "ok" else "stale"
                    else:
                        success = stamp(value.get("generated_at"))
                        attempt = stamp(value.get("refresh_state", {}).get("last_attempt_at"))
                        valid = isinstance(value.get("weekly_180d"), list)
                        status = "stale" if value.get("refresh_state", {}).get("consecutive_failures") else "fresh"
                    if valid and success is not None:
                        due = success + ttl
                        sources[group] = dict(unknown(group, present=True), status=status, reason=None,
                            last_attempt_at=store.stamp(attempt), last_success_at=store.stamp(success),
                            source_acquired_at=store.stamp(success), age_seconds=now - success if success <= now else None,
                            max_age_seconds=ttl, next_due_at=store.stamp(due), next_eligible_at=store.stamp(due),
                            coverage="complete", scope={"resource": filename})
                except (OSError, ValueError, TypeError, AttributeError):
                    pass

        with budget._lock():
            budget._load_storage()
            state = getattr(budget, "state", {})
            hold = max(state.get("hold_until", 0), budget._local_hold)
            known = not budget.degraded
            if not known and not any(w["code"] == "private_state_unavailable" for w in store.warnings):
                store.warn("private_state_unavailable", "Private source state unavailable; source capacity is unknown.", None)
            totals = state.get("days", {}).get(getattr(budget, "day", ""), {})
            daily, sync_limit = budget._effective_allowances()
            last_tick = state.get("schedule", {}).get("last_tick") or now
            eligible = max(hold, last_tick + (store.schedule["effective_interval_seconds"] or 600))
            active_wait = (store.schedule["state"] in ("running", "stepped_down")
                           and hold <= now and not budget.stopped)
            for group, row in sources.items():
                if group not in store.SCHEDULED:
                    row.update(max_age_seconds=None, next_due_at=None)
                success = stamp(row["source_acquired_at"])
                if retained and active_wait and group in store.CORE and success is not None:
                    interval = store.schedule["effective_interval_seconds"]
                    row.update(max_age_seconds=interval, next_due_at=store.stamp(success + interval),
                               next_eligible_at=store.stamp(eligible))
                if success is not None:
                    row["age_seconds"] = now - success if success <= now else None
                    # Consumed rows were checked individually, including mixed groups.
                    # Only a real success in this invocation bypasses scheduled expiry.
                    if (success > now or group in store.SCHEDULED
                            and (retained or evaluated[group] is None)
                            and (retained or store.companion_success.get(group) != success)
                            and now - success >= row["max_age_seconds"]):
                        if row["status"] == "fresh":
                            row.update(status="stale", reason="validity_expired")
                if (group in ("saved_workouts", "history") and row["status"] == "stale"
                        and budget.stopped):
                    row.update(status="deferred", reason="request_budget")
                if retained and not active_wait and row["status"] != "unavailable" and group in store.CORE:
                    row.update(status="deferred", reason="scheduler", next_eligible_at=store.stamp(eligible))
                if row["status"] in ("deferred", "stale", "unavailable"):
                    row["next_eligible_at"] = store.stamp(max(hold, stamp(row["next_eligible_at"]) or now))
            affected = sorted(group for group, row in sources.items() if row["status"] != "fresh")
            if affected:
                store.warn("source_stale", "Sources need refresh: " + ", ".join(affected) + ".", eligible,
                           emit=affected != state.get("source_warning"))
            if hold > now and not any(w["code"] == "rate_hold" for w in store.warnings):
                store.warn("rate_hold", "Requests held until " + store.stamp(hold) + ".", hold)
            if known:
                state["source_warning"] = affected
                active_warnings = {w["code"] for w in store.warnings}
                state["warning_since"] = {k: v for k, v in state.get("warning_since", {}).items() if k in active_warnings}
                budget._save_storage()
            hosted = isinstance(budget, HostedRequestBudget)
            return {"version": 1, "as_of": store.stamp(now), "budget": {
                "scope": budget.SCOPE, "capacity_status": "known" if known else "unknown",
                "utc_day": getattr(budget, "day", budget._day(now)), "requests_this_run": budget.count,
                "requests_today": sum(sum(v.values()) for v in totals.values()) if known and not hosted else None,
                "sync_requests_today": sum(totals.get("sync", {}).values()) if known and not hosted else None,
                "provider_daily_limit": daily, "sync_daily_limit": None if hosted else sync_limit,
                "reserved_external": None if hosted else budget.EXTERNAL_RESERVE,
                "sync_remaining": max(0, budget._remaining()) if known and not hosted else None,
                "window_requests": len(state.get("window", [])) if known else None,
                "window_limit": budget.WINDOW_LIMIT, "hold_until": store.stamp(hold) if hold > now else None,
                "next_eligible_at": store.stamp(eligible)}, "schedule": store.clone(store.schedule),
                "warnings": store.clone(store.warnings), "sources": sources}

    def _adopt_native_cache(self, group, activity_id, valid, outcome=None):
        store = getattr(self, "_acquisition", None)
        if store is not None:
            store.adopt(group, activity_id, valid, outcome)

    def _save_schedule_transition(self):
        path = self.data_dir / "latest.json"
        try:
            prior = json.loads(path.read_text())
        except (OSError, ValueError):
            return
        old = prior.get("source_freshness", {})
        store, budget = self._acquisition, self.request_budget
        hold = max(getattr(budget, "state", {}).get("hold_until", 0), budget._local_hold)
        # An ordinary timer tick before the chosen deadline is not a deferral.
        if (store.schedule["state"] in ("running", "stepped_down")
                and old.get("schedule") == store.schedule and not budget.stopped
                and old.get("budget", {}).get("hold_until") is None and hold <= store.now()):
            return
        fresh = self._source_freshness(prior, retained=True)
        if (old.get("schedule") == fresh["schedule"]
                and old.get("budget", {}).get("hold_until") == fresh["budget"]["hold_until"]):
            return
        prior["source_freshness"] = fresh
        previous = prior.get("export_freshness") or {}
        if not isinstance(previous, dict):
            previous = {}
        export = ExportFreshness.build(
            previous.get("generated_at", prior.get("metadata", {}).get("last_updated")),
            ExportFreshness.context(os.environ), fresh, datetime.now(timezone.utc), previous)
        if export is not None:
            prior["export_freshness"] = export
        fd, name = tempfile.mkstemp(prefix=".freshness-", dir=path.parent)
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as out:
                json.dump(prior, out, indent=2, default=str)
            os.replace(name, path)
        finally:
            if os.path.exists(name):
                os.unlink(name)

    def _intervals_request(self, url, **kwargs):
        """One accounted send, including specialised reads and attachments."""
        path = urlsplit(url).path.split("/")
        attachment = kwargs.pop("budget_attachment", False)
        if attachment:
            # Each hop is anonymous, including when local netrc auth is configured.
            kwargs.pop("headers", None)
            kwargs.pop("cookies", None)
            kwargs["auth"] = lambda prepared: prepared
        if urlsplit(url).hostname != "intervals.icu":
            if not attachment:
                raise ValueError("unexpected API origin")
            self._external_attachment_sends = getattr(self, "_external_attachment_sends", 0) + 1
            return requests.get(url, timeout=kwargs.pop("timeout"), allow_redirects=False, **kwargs)
        endpoint = path[5] if len(path) > 5 else (
            "activity_detail" if path[3:4] == ["activity"] else "profile")
        priority = "optional"
        if attachment:
            endpoint = "attachment"
        elif getattr(self, "_budget_history", False):
            endpoint = "history_" + endpoint
        elif path[3:4] == ["athlete"] and endpoint in ("activities", "wellness", "events"):
            if endpoint != "events" or len(path) == 6:
                priority = "core"
        if endpoint == "events" and (kwargs.get("params") or {}).get("category") == "INJURED,SICK":
            endpoint = "health_events"
        response = self.request_budget.request(
            requests, "get", url, endpoint, priority, **kwargs)
        if not attachment and 300 <= response.status_code < 400:
            raise requests.exceptions.HTTPError("redirect not followed", response=response)
        return response
    
    @property
    def script_hash(self) -> str:
        """SHA256 of sync.py itself. Used to invalidate cached files on any code change."""
        if self._cached_script_hash is None:
            script_path = Path(__file__).resolve()
            h = hashlib.sha256()
            with open(script_path, 'rb') as f:
                for chunk in iter(lambda: f.read(8192), b''):
                    h.update(chunk)
            self._cached_script_hash = h.hexdigest()[:12]  # short hash, sufficient for change detection
        return self._cached_script_hash
    
    @staticmethod
    def _decode_github_content(raw) -> str:
        """
        Decode a GitHub Contents API `content` field strictly.

        base64.b64decode(validate=False) silently DISCARDS characters outside the
        base64 alphabet, so a body with stray punctuation around an otherwise valid
        payload decodes to the same bytes as the clean one. That is how a malformed
        remote body could be compared equal to the intended content and reported as
        "No changes detected", or accepted as proof that a write landed.

        The GitHub API line-wraps its base64, so newlines and surrounding whitespace
        are removed first, and only then is the remainder decoded with validate=True.
        Raises ValueError on anything unusable; callers turn that into
        PublishPreReadFailed or PublishOutcomeUnknown.
        """
        if not isinstance(raw, str):
            raise ValueError("content is missing or not a string")
        compact = "".join(raw.split())     # strips \n, \r, spaces and tabs only
        if not compact:
            raise ValueError("content is empty")
        try:
            decoded = base64.b64decode(compact, validate=True)
        except Exception as e:
            raise ValueError(f"content is not valid base64 ({e})")
        try:
            return decoded.decode("utf-8")
        except UnicodeDecodeError as e:
            raise ValueError(f"content is not valid UTF-8 ({e})")

    def _read_retry_delay(self, attempt: int, retry_after_secs: Optional[int]) -> int:
        """
        Delay before attempt+1. Retry-After may RAISE the ladder value but never
        lower it. The value is a local throughout: it is never stored on self, so it
        cannot leak into a later request or into interval fetch-state scheduling.
        """
        ladder = self.READ_RETRY_BACKOFF_SECS
        delay = ladder[min(attempt - 1, len(ladder) - 1)]
        if retry_after_secs is not None:
            delay = max(delay, int(retry_after_secs))
        return delay

    def _admit_read_retry(self, attempt: int, started_at: float, delay: int,
                          charge_instance_budget: bool) -> bool:
        """
        Decide whether attempt+1 may BEGIN, and reserve budget only if it may.

        Checked BEFORE sleeping, so a Retry-After too large to fit inside the
        admission window re-raises immediately instead of sleeping and then
        declining. The instance counter is incremented only on an admitted retry.
        """
        if attempt >= self.READ_RETRY_MAX_ATTEMPTS:
            return False
        if (time.monotonic() - started_at) + delay >= self.READ_RETRY_ADMISSION_CAP_SECS:
            return False
        if charge_instance_budget:
            if self._read_retry_extra_attempts_used >= self.READ_RETRY_INSTANCE_EXTRA_ATTEMPTS:
                return False
            self._read_retry_extra_attempts_used += 1
        return True

    def _read_with_retry(self, send, charge_instance_budget: bool = True):
        """
        Run a bounded safe read, retrying only eligible transport failures and
        statuses. Returns the final Response; the caller still calls
        raise_for_status(), so an exhausted retryable status surfaces as the ordinary
        requests.exceptions.HTTPError it always was.

        On exhausted transport failure the ORIGINAL exception object is re-raised, so
        its requests.exceptions.RequestException subclass is preserved. That is
        load-bearing: _build_health_context catches RequestException specifically and
        must keep degrading to source_status "partial" rather than killing the sync.

        Retries POST/PUT/DELETE nothing: this is a read-only helper by construction.
        """
        started_at = time.monotonic()
        attempt = 0
        while True:
            attempt += 1
            error = None
            response = None
            retry_after = None
            try:
                response = send()
            except RequestBudgetRefused as error:
                if attempt > 1 and charge_instance_budget:
                    self._read_retry_extra_attempts_used -= 1
                error.had_send = attempt > 1
                raise
            except (requests.exceptions.Timeout,
                    requests.exceptions.ConnectionError) as e:
                error = e
            except requests.exceptions.RequestException:
                raise
            else:
                if charge_instance_budget and response.status_code == 429:
                    return response
                if response.status_code not in self.READ_RETRY_STATUSES:
                    return response
                if response.status_code in (429, 503):
                    retry_after = self._parse_retry_after(
                        response.headers.get("Retry-After"))

            delay = self._read_retry_delay(attempt, retry_after)
            if not self._admit_read_retry(attempt, started_at, delay,
                                          charge_instance_budget):
                if error is not None:
                    raise error
                return response
            time.sleep(delay)

    def _intervals_get(self, endpoint: str, params: Dict = None) -> Dict:
        store = getattr(self, "_acquisition", None)
        if store is not None and not getattr(self, "_budget_history", False):
            group = {"": "profile", "activities": "activities", "wellness": "wellness",
                     "events": "health_events" if (params or {}).get("category") == "INJURED,SICK" else "calendar",
                     "power-curves": "aggregate_curves", "hr-curves": "aggregate_curves"}.get(endpoint)
            if group is not None:
                ttl = 3600 if group == "profile" else 21600 if group == "aggregate_curves" else (
                    store.schedule["effective_interval_seconds"] or 60)
                return store.acquire(group, endpoint, params,
                                     lambda: self._fetch_intervals_json(endpoint, params), ttl)
        return self._fetch_intervals_json(endpoint, params)

    def _fetch_intervals_json(self, endpoint: str, params: Dict = None) -> Dict:
        """Fetch from Intervals.icu API"""
        if endpoint:
            url = f"{self.INTERVALS_BASE_URL}/athlete/{self.athlete_id}/{endpoint}"
        else:
            url = f"{self.INTERVALS_BASE_URL}/athlete/{self.athlete_id}"
        headers = {
            "Authorization": f"Basic {self.intervals_auth}",
            "Accept": "application/json"
        }
        if endpoint == "activity-power-curves":
            # Descriptive season data has a strict one-send budget. No redirect
            # or retry may turn its one admission into multiple HTTP requests.
            response = self._intervals_request(url, headers=headers, params=params,
                                    timeout=self.INTERVALS_READ_TIMEOUT, allow_redirects=False)
            if response.status_code != 200:
                raise requests.exceptions.HTTPError("season_curve_read_failed", response=response)
        else:
            response = self._read_with_retry(
                lambda: self._intervals_request(url, headers=headers, params=params,
                                     timeout=self.INTERVALS_READ_TIMEOUT))
        response.raise_for_status()
        return response.json()

    def _get_activity_messages(self, activity_id: str) -> Tuple[str, List[str]]:
        store = getattr(self, "_acquisition", None)
        if store is None:
            return self._read_activity_messages(activity_id)
        def fetch():
            status, texts = self._read_activity_messages(activity_id)
            if status == "deferred":
                raise RequestBudgetRefused("messages deferred")
            if status != "ok":
                raise requests.exceptions.RequestException("messages unavailable")
            return texts
        try:
            texts = store.acquire("messages", "activity/" + str(activity_id) + "/messages", {}, fetch, 21600)
        except RequestBudgetRefused:
            return "deferred", []
        except requests.exceptions.RequestException:
            return "unavailable", []
        key, _ = store.key("activity/" + str(activity_id) + "/messages", {})
        return ("ok" if store.consumed[key].get("status") == "fresh" else "deferred"), texts

    def _read_activity_messages(self, activity_id: str) -> Tuple[str, List[str]]:
        """
        Fetch messages/notes for a completed activity.

        Returns (status, texts) where status is "ok" or "unavailable". A successful
        empty response is ("ok", []) and means the activity genuinely has no notes.
        A transport failure, an HTTP error, an unparseable body or an unexpected
        shape is ("unavailable", []): not retrieved, which is not the same fact and
        must not reach the AI layer as confirmed absence.

        Circuit break: after MESSAGES_FAILURE_BREAK_COUNT consecutive FINAL failures
        in this run, remaining activities are reported unavailable without issuing a
        request, so a dead endpoint costs one initial attempt per activity at most
        three times rather than once per activity in the window. The break path
        issues no attempt and therefore consumes no retry budget.
        """
        if self._messages_consecutive_failures >= self.MESSAGES_FAILURE_BREAK_COUNT:
            return ("unavailable", [])
        url = f"{self.INTERVALS_BASE_URL}/activity/{activity_id}/messages"
        headers = {
            "Authorization": f"Basic {self.intervals_auth}",
            "Accept": "application/json"
        }
        try:
            response = self._read_with_retry(
                lambda: self._intervals_request(url, headers=headers,
                                     timeout=self.INTERVALS_READ_TIMEOUT))
            response.raise_for_status()
            messages = response.json()
        except RequestBudgetRefused:
            return ("deferred", [])
        except Exception:
            self._messages_consecutive_failures += 1
            return ("unavailable", [])
        if not isinstance(messages, list):
            # A 200 that is not a list is not a confirmed empty library.
            self._messages_consecutive_failures += 1
            return ("unavailable", [])
        texts = []
        for item in messages:
            # Element-level validation, not just the outer list. A non-object entry,
            # or a content field that is not text, would otherwise raise here, well
            # outside the guarded block, and kill the whole sync over a chat note.
            if not isinstance(item, dict):
                self._messages_consecutive_failures += 1
                return ("unavailable", [])
            raw = item.get("content")
            if raw is not None and not isinstance(raw, str):
                self._messages_consecutive_failures += 1
                return ("unavailable", [])
            if raw is None or not raw.strip():
                # Either field can carry the note. Fall back when content is null,
                # empty or whitespace-only, not only when the key is absent.
                fallback = item.get("text", "")
                if fallback is not None and not isinstance(fallback, str):
                    self._messages_consecutive_failures += 1
                    return ("unavailable", [])
                raw = fallback or ""
            if raw.strip():
                texts.append(raw)
        self._messages_consecutive_failures = 0
        return ("ok", texts)
    
    @observe_source("activity_details")
    def _fetch_activity_intervals(self, activity_id: str) -> tuple:
        """
        Fetch interval segments for a single activity.

        Distinguishes terminal from transient errors so the caller can decide
        whether to write the cache entry (terminal: definitive answer, cache it
        and skip on future syncs) or skip the write (transient: retry next sync).

        Returns (status, payload):
            ("ok", icu_intervals_list)  — 200 with non-empty icu_intervals
            ("no_data", [])             — 200 with empty/missing icu_intervals
                                          (legitimate unstructured ride)
            ("terminal_error", "http_NNN") — 404, 410 (resource genuinely gone)
            ("transient", reason_str)   — everything else: 5xx, 429, all other
                                          4xx (incl. 401/403 — auth/config flakes
                                          must NOT become permanent cache truth),
                                          network, timeout, parse error,
                                          unexpected response shape
        """
        self._last_retry_after_secs = None
        url = f"{self.INTERVALS_BASE_URL}/activity/{activity_id}"
        headers = {
            "Authorization": f"Basic {self.intervals_auth}",
            "Accept": "application/json"
        }
        try:
            response = self._intervals_request(url, headers=headers, params={"intervals": "true"}, timeout=30)
        except RequestBudgetRefused:
            return ("deferred", "request_budget")
        except requests.exceptions.Timeout:
            return ("transient", "timeout")
        except requests.exceptions.RequestException as e:
            return ("transient", f"network: {str(e)[:80]}")

        status_code = response.status_code
        if status_code == 200:
            try:
                data = response.json()
            except ValueError:
                return ("transient", "parse_error")
            if not isinstance(data, dict):
                return ("transient", "unexpected_shape")
            intervals = data.get("icu_intervals", [])
            if not isinstance(intervals, list):
                return ("transient", "unexpected_shape")
            if not intervals:
                return ("no_data", [])
            return ("ok", intervals)
        elif status_code in (404, 410):
            return ("terminal_error", f"http_{status_code}")
        else:
            # Conservative: all other non-2xx (incl. 401/403/5xx/429) treated as
            # transient. Better to retry than permanently cache an auth/config flake.
            # v3.121: on 429 surface Retry-After so the caller can honour it.
            if status_code == 429:
                self._last_retry_after_secs = self._parse_retry_after(
                    response.headers.get("Retry-After"))
            return ("transient", f"http_{status_code}")

    def _fetch_activity_streams(self, activity_id: str, types: List[str]) -> tuple:
        """
        Fetch per-second streams for a single activity.

        Generic streams fetcher for any rollup metric that needs second-by-second data.
        Distinguishes terminal from transient errors so the caller can decide whether
        to write a cache entry (terminal: definitive, skip on future syncs) or skip
        the write (transient: retry next sync).

        Returns (status, payload):
            ("ok", streams_dict)        — 200 with at least one requested stream
                                          populated; dict keyed by stream type,
                                          value is the data list
            ("no_data", {})             — 200 but none of the requested streams
                                          present (legitimate — e.g., no AlphaHRV
                                          Connect IQ field installed, sourced via
                                          Strava which strips dev fields)
            ("terminal_error", "http_NNN") — 404, 410 (resource genuinely gone)
            ("transient", reason_str)   — everything else: 5xx, 429, all other
                                          4xx (incl. 401/403 — auth/config flakes
                                          must NOT become permanent cache truth),
                                          network, timeout, parse error,
                                          unexpected response shape

        Within one sync run (v3.157) a successful /streams response is requested
        once per activity and reused by every consumer, each filtering its own
        stream types from a private copy. A 429 with its Retry-After and a 404/410
        are shared too; after any other transient failure the next consumer may
        request once more, and that second result is then shared.

        Note on cache invalidation: streams are fetched once per activity. If the
        underlying FIT is reprocessed in AlphaHRV's mobile app and re-uploaded,
        the cached rollup will be stale. Rare in practice; workaround is to delete
        intervals.json.
        """
        self._last_retry_after_secs = None
        memo = getattr(self, "_stream_responses", None)
        if not isinstance(memo, dict):
            memo = self._stream_responses = {}
        entry = memo.get(activity_id)
        if entry is None or (entry[2] < 2 and self._stream_failure_retryable(entry[0])):
            attempts = 1 if entry is None else entry[2] + 1
            result = self._request_activity_streams(activity_id)
            if result == ("result", ("deferred", "request_budget")):
                attempts -= 1
            entry = (result, self._last_retry_after_secs, attempts)
            memo[activity_id] = entry
        (kind, value), retry_after, _attempts = entry
        self._last_retry_after_secs = retry_after
        if kind != "data":
            return value
        wanted = set(types)
        out = {}
        for s in value:
            stype = s.get("type")
            if stype in wanted:
                sdata = s.get("data")
                if isinstance(sdata, list):
                    out[stype] = list(sdata)
        if not out:
            return ("no_data", {})
        return ("ok", out)

    @staticmethod
    def _stream_failure_retryable(result: tuple) -> bool:
        """True for a transient /streams failure other than 429 (v3.157).

        A rate limit is shared so nobody asks again in the same run, and 404/410
        are definitive. After a timeout, network, server or malformed response the
        next consumer may try once more; that second result is then shared.
        """
        kind, value = result
        return kind == "result" and value[0] == "transient" and value[1] != "http_429"

    @observe_source("activity_streams")
    def _request_activity_streams(self, activity_id: str) -> tuple:
        """
        Make the single /streams request for one activity.

        Returns ("data", stream_list) for a 200 list response, otherwise
        ("result", (status, payload)) using _fetch_activity_streams' statuses.
        Sets _last_retry_after_secs on 429.
        """
        url = f"{self.INTERVALS_BASE_URL}/activity/{activity_id}/streams"
        headers = {
            "Authorization": f"Basic {self.intervals_auth}",
            "Accept": "application/json"
        }
        try:
            response = self._intervals_request(url, headers=headers, timeout=30)
        except RequestBudgetRefused:
            return ("result", ("deferred", "request_budget"))
        except requests.exceptions.Timeout:
            return ("result", ("transient", "timeout"))
        except requests.exceptions.RequestException as e:
            return ("result", ("transient", f"network: {str(e)[:80]}"))

        status_code = response.status_code
        if status_code == 200:
            try:
                data = response.json()
            except ValueError:
                return ("result", ("transient", "parse_error"))
            if not isinstance(data, list):
                return ("result", ("transient", "unexpected_shape"))
            return ("data", data)
        elif status_code in (404, 410):
            return ("result", ("terminal_error", f"http_{status_code}"))
        else:
            # Conservative: all other non-2xx (incl. 401/403/5xx/429) treated as
            # transient. Better to retry than permanently cache an auth/config flake.
            # v3.121: on 429 surface Retry-After so the caller can honour it.
            if status_code == 429:
                self._last_retry_after_secs = self._parse_retry_after(
                    response.headers.get("Retry-After"))
            return ("result", ("transient", f"http_{status_code}"))

    @observe_source("activity_terrain")
    def _fetch_terrain_streams(self, activity_id: str) -> tuple:
        """
        Fetch latlng + altitude streams for terrain analysis.
        
        Distinguishes terminal from transient errors so the caller can decide
        whether to write a terminal status (skip on future syncs) or leave
        unmarked (retry on next sync).
        
        The latlng stream uses Intervals' dual-array shape (data=lat, data2=lng)
        which the generic fetcher discards, so this terrain-specific fetcher
        returns the raw stream list rather than reusing _fetch_activity_streams.
        
        Returns (status, payload):
            ("ok", streams_list)         — 200 with usable streams
            ("no_gps", None)             — 200 but no latlng stream present
            ("no_elevation", streams_list) — 200 with latlng but no altitude
                                            (caller may still want trackpoints)
            ("terminal_error", "http_NNN") — 404, 410 (resource genuinely gone)
            ("transient", reason_str)    — everything else: 5xx, 429, all other
                                           4xx (incl. 401/403 — auth/config flakes
                                           must NOT become permanent cache truth),
                                           network, timeout, parse error,
                                           unexpected response shape
        """
        url = f"{self.INTERVALS_BASE_URL}/activity/{activity_id}/streams.json?types=time,distance,altitude,latlng"
        headers = {
            "Authorization": f"Basic {self.intervals_auth}",
            "Accept": "application/json"
        }
        try:
            response = self._intervals_request(url, headers=headers, timeout=30)
        except RequestBudgetRefused:
            return ("transient", "request_budget")
        except requests.exceptions.Timeout:
            return ("transient", "timeout")
        except requests.exceptions.RequestException as e:
            return ("transient", f"network: {str(e)[:80]}")
        
        status_code = response.status_code
        if status_code == 200:
            try:
                data = response.json()
            except ValueError:
                return ("transient", "parse_error")
            if not isinstance(data, list):
                return ("transient", "unexpected_shape")
            latlng_stream = next((s for s in data if s.get("type") == "latlng"), None)
            altitude_stream = next((s for s in data if s.get("type") == "altitude"), None)
            if not latlng_stream:
                return ("no_gps", None)
            lat_arr = latlng_stream.get("data") or []
            lng_arr = latlng_stream.get("data2") or []
            valid_pairs = sum(1 for la, ln in zip(lat_arr, lng_arr) if la is not None and ln is not None)
            if valid_pairs < 10:
                return ("no_gps", None)
            if not altitude_stream or not (altitude_stream.get("data") or []):
                return ("no_elevation", data)
            return ("ok", data)
        elif status_code in (404, 410):
            return ("terminal_error", f"http_{status_code}")
        else:
            # Conservative: all other non-2xx (incl. 401/403/5xx/429) treated as
            # transient. Better to retry than permanently cache an auth/config flake.
            return ("transient", f"http_{status_code}")

    POWER_CURVE_MAX_ACTIVITIES = 8
    POWER_CURVE_SECONDS = (1, 5, 60, 300, 1200, 3600)

    @observe_source("activity_power")
    def _fetch_activity_power_curve(self, activity_id: str) -> tuple:
        """Exact per-activity watts only; transient failures never become truth."""
        if self._power_curve_fetches_used >= self.POWER_CURVE_MAX_ACTIVITIES:
            return ("transient", "request_budget")
        self._power_curve_fetches_used += 1
        url = f"{self.INTERVALS_BASE_URL}/activity/{activity_id}/power-curve.json"
        headers = {"Authorization": f"Basic {self.intervals_auth}",
                   "Accept": "application/json"}
        try:
            response = self._read_with_retry(
                lambda: self._intervals_request(url, headers=headers,
                                     timeout=self.INTERVALS_READ_TIMEOUT))
        except RequestBudgetRefused as error:
            if not getattr(error, "had_send", False):
                self._power_curve_fetches_used -= 1
            return ("transient", "request_budget")
        except requests.exceptions.RequestException:
            return ("transient", "transport_error")
        if response.status_code in (404, 410):
            return ("terminal_error", f"http_{response.status_code}")
        if response.status_code != 200:
            return ("transient", f"http_{response.status_code}")
        try:
            data = response.json()
        except ValueError:
            return ("transient", "parse_error")
        if not isinstance(data, dict):
            return ("transient", "unexpected_shape")
        secs, watts = data.get("secs"), data.get("watts")
        if not isinstance(secs, list) or not isinstance(watts, list) or len(secs) != len(watts):
            return ("transient", "unexpected_shape")
        curve, seen = {}, set()
        for seconds, value in zip(secs, watts):
            if (isinstance(seconds, bool) or not isinstance(seconds, (int, float))
                    or not math.isfinite(seconds) or seconds <= 0 or seconds in seen):
                return ("transient", "unexpected_shape")
            seen.add(seconds)
            if value is None:
                continue
            if (isinstance(value, bool) or not isinstance(value, (int, float))
                    or not math.isfinite(value) or value < 0):
                return ("transient", "unexpected_shape")
            if seconds in self.POWER_CURVE_SECONDS:
                curve[str(int(seconds))] = value
        return ("ok", curve)

    def _build_power_curve_for_activity(self, act: Dict, previous_lookup: Dict,
                                       has_power: bool) -> Dict:
        """Copy success/terminal results; retry transient or budget skips next sync."""
        act_id = act.get("id")
        if not has_power or act_id is None:
            return {}
        key = str(act_id)
        def within_duration(curve):
            duration = act.get("moving_time")
            return {sec: watts for sec, watts in curve.items()
                    if not isinstance(duration, (int, float)) or int(sec) <= duration}

        prev = previous_lookup.get(key, {})
        if isinstance(prev.get("power_curve"), dict):
            self._adopt_native_cache("activity_power", key, all(
                sec in {str(s) for s in self.POWER_CURVE_SECONDS}
                and self._structure_number(watts) and watts >= 0
                for sec, watts in prev["power_curve"].items()))
            return {"power_curve": within_duration(prev["power_curve"])}
        if prev.get("power_curve_status") == "failed":
            error = prev.get("power_curve_error")
            self._adopt_native_cache("activity_power", key, error in AcquisitionStore.TERMINAL_HTTP, error)
            return {k: prev[k] for k in ("power_curve_status", "power_curve_error") if k in prev}
        if key not in self._power_curve_run_cache:
            status, payload = self._fetch_activity_power_curve(key)
            result = {}
            if status == "ok":
                # The curve is authoritative for exact available durations;
                # additionally reject points longer than a known activity.
                result["power_curve"] = within_duration(payload)
            elif status == "terminal_error":
                result = {"power_curve_status": "failed", "power_curve_error": payload}
            self._power_curve_run_cache[key] = result
        result = dict(self._power_curve_run_cache[key])
        if "power_curve" in result:
            result["power_curve"] = within_duration(result["power_curve"])
        return result

    DECOUPLING_MAX_ACTIVITIES = 8
    DECOUPLING_DETAIL_VERSION = 1

    @observe_source("activity_decoupling")
    def _fetch_activity_power_vs_hr(self, activity_id: str) -> tuple:
        """Sibling of the curve read; only 404/410 are terminal cache truth."""
        if self._decoupling_fetches_used >= self.DECOUPLING_MAX_ACTIVITIES:
            return ("transient", "request_budget")
        self._decoupling_fetches_used += 1
        url = f"{self.INTERVALS_BASE_URL}/activity/{activity_id}/power-vs-hr"
        headers = {"Authorization": f"Basic {self.intervals_auth}",
                   "Accept": "application/json"}
        try:
            response = self._read_with_retry(
                lambda: self._intervals_request(url, headers=headers,
                                     timeout=self.INTERVALS_READ_TIMEOUT))
        except RequestBudgetRefused as error:
            if not getattr(error, "had_send", False):
                self._decoupling_fetches_used -= 1
            return ("transient", "request_budget")
        except requests.exceptions.RequestException:
            return ("transient", "transport_error")
        if response.status_code in (404, 410):
            return ("terminal_error", f"http_{response.status_code}")
        if response.status_code != 200:
            return ("transient", f"http_{response.status_code}")
        try:
            data = response.json()
        except ValueError:
            return ("transient", "parse_error")
        detail = self._decoupling_detail(data)
        return ("ok", detail) if detail is not None else ("transient", "unexpected_shape")

    @classmethod
    def _decoupling_power_trend(cls, early, late):
        delta = late - early
        limit = max(5.0, early * .05)
        return "rising" if delta > limit else "falling" if delta < -limit else "steady"

    @classmethod
    def _decoupling_detail(cls, data):
        """Compact observed bucket facts; upstream HR is already lag-aligned.

        Bucket watts/HR are rounded upstream. Their ratio is a reconstruction,
        not a replacement for the authoritative higher-precision half ratios.
        No fit curves, model correction or raw series enter latest.json.
        """
        number = cls._structure_number
        if not isinstance(data, dict):
            return None
        series = data.get("series")
        indices = [data.get(k) for k in ("start", "mid", "end")]
        if (not isinstance(series, list) or not 2 <= len(series) <= 10080
                or any(type(v) is not int for v in indices)
                or not 0 <= indices[0] < indices[1] < indices[2] <= len(series)):
            return None
        size, warmup, cooldown, lag = [data.get(k) for k in
                                     ("bucketSize", "warmup", "cooldown", "hrLag")]
        if (not number(size) or not 0 < size <= 3600
                or any(not number(v) or not 0 <= v <= 604800 for v in (warmup, cooldown, lag))):
            return None
        ratios = [data.get(k) for k in ("powerHrFirst", "powerHrSecond")]
        upstream = data.get("decoupling")
        if (any(not number(v) or v <= 0 for v in ratios) or not number(upstream)
                or abs((ratios[0] - ratios[1]) / ratios[0] * 100 - upstream) > .001):
            return None
        selected = series[indices[0]:indices[2]]
        previous_end = None
        for bucket in selected:
            if not isinstance(bucket, dict):
                return None
            start, secs, moving = [bucket.get(k) for k in ("start", "secs", "movingSecs")]
            if (not number(start) or not 0 <= start <= 604800
                    or not number(secs) or not 0 < secs <= 604800 - start
                    or not number(moving) or not 0 <= moving <= secs
                    or (previous_end is not None and start < previous_end)):
                return None
            previous_end = start + secs
            for key in ("watts", "hr"):
                value = bucket.get(key)
                if value is not None and (not number(value) or not 0 <= value <= 10000):
                    return None
        start_s = selected[0]["start"]
        mid_s = series[indices[1]]["start"]
        end_s = selected[-1]["start"] + selected[-1]["secs"]
        halves = []
        for a, b, left, right in ((indices[0], indices[1], start_s, mid_s),
                                   (indices[1], indices[2], mid_s, end_s)):
            buckets = series[a:b]
            paired = [v for v in buckets if v.get("watts") is not None
                      and v.get("hr") is not None and v["hr"] > 0]
            if not paired or right <= left:
                return None
            # Upstream secs can bridge a recording gap and exceed bucketSize.
            # Cap nominal support: never extrapolate bucket power through that
            # excess or claim that bucket availability proves sensor coverage.
            support = lambda v: min(v["secs"], v["movingSecs"], size)
            paired_s = sum(support(v) for v in paired)
            halves.append({
                "duration_s": sum(v["secs"] for v in buckets),
                "span_s": right - left,
                "paired_s": paired_s,
                "bucket_coverage_pct": round(paired_s / (right - left) * 100, 3),
                "avg_power_w": statistics.mean(v["watts"] for v in paired),
                "avg_hr_bpm": statistics.mean(v["hr"] for v in paired),
                "work_kj": sum(v["watts"] * support(v) for v in paired) / 1000,
            })
        early, late = halves
        if early["avg_power_w"] <= 0:
            return None
        changes = {}
        for field in ("avg_power_w", "avg_hr_bpm", "work_kj", "duration_s"):
            before, after = early[field], late[field]
            changes[field] = {"absolute": round(after - before, 3),
                              "pct": round((after - before) / before * 100, 3) if before else None}
        ratio1 = early["avg_power_w"] / early["avg_hr_bpm"]
        ratio2 = late["avg_power_w"] / late["avg_hr_bpm"]
        trend = cls._decoupling_power_trend(early["avg_power_w"], late["avg_power_w"])
        for half in halves:
            for field in ("avg_power_w", "avg_hr_bpm", "work_kj"):
                half[field] = round(half[field], 3)
        return {"method": "intervals_power_vs_hr_v1",
                "window": {"bucket_size_s": size, "start_bucket": indices[0],
                           "mid_bucket": indices[1], "end_bucket": indices[2],
                           "start_s": start_s, "mid_s": mid_s, "end_s": end_s,
                           "warmup_s": warmup, "cooldown_s": cooldown, "hr_lag_s": lag},
                "early": early, "late": late, "change": changes,
                "power_hr_first": ratios[0], "power_hr_second": ratios[1],
                "upstream_decoupling": upstream,
                "bucket_decoupling": round((ratio1 - ratio2) / ratio1 * 100, 6),
                "power_trend": trend, "comparability": trend + "_power"}

    @classmethod
    def _decoupling_plan_context(cls, summary):
        """Conservative target contrast over supplied measured step-work time.

        Summary rows do not carry clock bounds or roles. Do not invent those:
        repeat recoveries are excluded, and ranges must separate even at their
        nearest edges. This flag is context only, never formal adherence.
        """
        number = cls._structure_number
        if (not isinstance(summary, dict) or summary.get("method") != "plan_match_v2"
                or summary.get("status") not in ("followed", "partly_followed")
                or not (summary.get("plan") or {}).get("event_id")
                or summary.get("omitted_steps")
                or any(x in summary.get("issues", []) for x in
                       ("pairing_conflict", "ambiguous_pairing", "stale", "detail_unavailable"))):
            return None
        rows = summary.get("steps")
        if not isinstance(rows, list) or not rows:
            return None
        targets = []
        for row in rows:
            if (not isinstance(row, list) or len(row) not in (4, 5)
                    or not number(row[0]) or row[0] <= 0 or not number(row[2])
                    or row[2] < 0 or type(row[3]) is not bool):
                return None
            band = row[1] if isinstance(row[1], list) else [row[1], row[1]]
            if (len(band) != 2 or any(not number(v) for v in band)
                    or not 0 <= band[0] <= band[1] <= 3000):
                return None
            targets.append((row[0], band))
        total = sum(t[0] for t in targets)
        halves = []
        for left, right in ((0, total / 2), (total / 2, total)):
            sums, cursor = [0, 0], 0
            for duration, band in targets:
                overlap = max(0, min(right, cursor + duration) - max(left, cursor))
                for j in (0, 1):
                    sums[j] += overlap * band[j]
                cursor += duration
            halves.append([v / (right - left) for v in sums])
        early, late = halves
        rising = late[0] - early[1] > max(5, early[1] * .05)
        falling = early[0] - late[1] > max(5, early[0] * .05)
        return {"basis": "qualified_step_work_time_halves",
                "early_target_w": [round(v, 3) for v in early],
                "late_target_w": [round(v, 3) for v in late],
                "changes_power": rising or falling}

    def _build_decoupling_for_activity(self, act, previous_lookup, has_power, has_hr, summary):
        if (not has_power or not has_hr or act.get("id") is None
                or self._report_sport(act.get("type")) != "cycling"):
            return {}
        # Source revisions, time/trim settings and source measures, not formatting
        # preferences or the mutable plan assessment. No periodic success refetch.
        fields = ("id", "type", "start_date", "start_date_local", "elapsed_time", "moving_time",
                  "icu_sync_date", "icu_intervals_edited", "icu_warmup_time", "icu_cooldown_time",
                  "decoupling", "icu_average_watts", "average_watts", "avg_watts", "average_power", "avgWatts",
                  "average_heartrate", "avg_hr", "average_heart_rate", "avgHr", "icu_average_hr",
                  "icu_joules", "stream_types", "recording_stops", "icu_recording_time")
        fingerprint = self._structure_fingerprint({k: act.get(k) for k in fields})
        key = (str(act["id"]), fingerprint)
        prev = previous_lookup.get(key[0], {})
        cache = prev.get("decoupling_cache") or {}
        if (cache.get("version") == self.DECOUPLING_DETAIL_VERSION
                and cache.get("activity_key") == fingerprint
                and (isinstance(prev.get("decoupling_detail"), dict) or cache.get("status") == "failed")):
            result = {k: prev[k] for k in ("decoupling_detail", "decoupling_cache") if k in prev}
            detail = prev.get("decoupling_detail") or {}
            if cache.get("status") != "failed":
                valid = (cache.get("status") == "ok" and detail.get("method") == "intervals_power_vs_hr_v1"
                    and detail.get("power_trend") in ("steady", "rising", "falling")
                    and all(self._structure_number(detail.get(k)) for k in
                            ("power_hr_first", "power_hr_second", "upstream_decoupling", "bucket_decoupling"))
                    and all(isinstance(detail.get(half), dict) and all(
                        self._structure_number(detail[half].get(field)) for field in
                        ("duration_s", "span_s", "paired_s", "avg_power_w", "avg_hr_bpm", "work_kj"))
                        for half in ("early", "late")))
                self._adopt_native_cache("activity_decoupling", key[0], valid)
            else:
                error = cache.get("error")
                self._adopt_native_cache("activity_decoupling", key[0], error in AcquisitionStore.TERMINAL_HTTP, error)
        else:
            if key not in self._decoupling_run_cache:
                status, payload = self._fetch_activity_power_vs_hr(key[0])
                result = {}
                if (status == "ok" and self._structure_number(act.get("decoupling"))
                        and abs(act["decoupling"] - payload["upstream_decoupling"]) > .001):
                    status = "transient"  # two upstream reads disagree; retry next sync
                if status in ("ok", "terminal_error"):
                    result["decoupling_cache"] = {"version": self.DECOUPLING_DETAIL_VERSION,
                        "activity_key": fingerprint, "status": "ok" if status == "ok" else "failed"}
                    if status == "ok":
                        result["decoupling_detail"] = payload
                    else:
                        result["decoupling_cache"]["error"] = payload
                self._decoupling_run_cache[key] = result
            result = self._decoupling_run_cache[key]
        # JSON-shaped deep copy keeps plan recalculation from mutating the cache.
        result = json.loads(json.dumps(result))
        detail = result.get("decoupling_detail")
        if detail is not None:
            detail["comparability"] = detail["power_trend"] + "_power"
            detail.pop("plan_comparison", None)
            context = self._decoupling_plan_context(summary)
            if context:
                detail["plan_comparison"] = context
                if context["changes_power"]:
                    detail["comparability"] = "plan_changes_power"
        return result

    @staticmethod
    def _fact_number(value):
        return (value if isinstance(value, (int, float)) and not isinstance(value, bool)
                and math.isfinite(value) and 0 <= value <= 1e12 else None)

    @staticmethod
    def _fact_date(value):
        try:
            return datetime.fromisoformat(value).strftime("%Y-%m-%d")
        except (TypeError, ValueError):
            return None

    @classmethod
    def _fact_indoor(cls, act):
        if cls.SPORT_FAMILIES.get(act.get("type")) != "cycling":
            return None
        if act.get("type") == "VirtualRide" or "virtual" in str(act.get("sub_type", "")).lower():
            return True
        flags = [act.get(k) for k in ("trainer", "indoor", "virtual", "is_virtual")]
        if any(v is True for v in flags):
            return True
        if any(v is not None and not isinstance(v, bool) for v in flags):
            return None
        return False

    @classmethod
    def _cycling_fact_indoor(cls, act):
        """Facts-local identity; legacy formatted/FTP/sustainability rules stay separate."""
        if cls._report_sport(act.get("type")) != "cycling":
            return None
        if act.get("type") == "VirtualRide" or "virtual" in str(act.get("sub_type", "")).lower():
            return True
        flags = [act.get(k) for k in ("trainer", "indoor", "virtual", "is_virtual")]
        if any(v is True for v in flags):
            return True
        if any(v is not None and not isinstance(v, bool) for v in flags):
            return None
        return False

    def _fact_activity(self, act, formatted=False, raw_by_id=None):
        """Canonical cycling observations only; no inference from activity names."""
        if self._report_sport(act.get("type")) != "cycling":
            return None
        date = self._fact_date(act.get("date" if formatted else "start_date_local"))
        if date is None or act.get("id") is None:
            return None
        number = self._fact_number
        if formatted:
            row = {k: number(act.get(k)) for k in
                   ("moving_time_s", "distance_m", "elevation_m", "work_kj", "carbs_used", "max_hr")}
            raw = (raw_by_id or {}).get(str(act["id"]))
            indoor = (self._cycling_fact_indoor(raw) if raw is not None
                      and raw.get("type") == act.get("type")
                      and self._fact_date(raw.get("start_date_local")) == date else None)
            power_keys = ("avg_power", "normalized_power")
        else:
            row = {dest: number(act.get(src)) for dest, src in
                   (("moving_time_s", "moving_time"), ("distance_m", "distance"),
                    ("elevation_m", "total_elevation_gain"), ("carbs_used", "carbs_used"))}
            joules = number(act.get("icu_joules"))
            row["work_kj"] = round(joules / 1000, 1) if joules else None
            row["max_hr"] = next((number(act[k]) for k in
                ("max_heartrate", "max_hr", "max_heart_rate", "maxHr", "icu_max_hr")
                if number(act.get(k)) is not None and act[k] > 0), None)
            indoor = self._cycling_fact_indoor(act)
            power_keys = ("average_watts", "avg_watts", "average_power", "avgWatts",
                          "icu_average_watts", "weighted_average_watts", "np", "icu_pm_np",
                          "normalizedPower", "icu_weighted_avg_watts")
        if row["max_hr"] == 0:
            row["max_hr"] = None
        row.update(activity_id=str(act["id"]), date=date,
                   activity_name=act.get("name") if isinstance(act.get("name"), str) else None,
                   environment="indoor_virtual" if indoor is True else "outdoor" if indoor is False else "unknown")
        curve = act.get("power_curve")
        row["power_curve"] = {str(sec): number(curve.get(str(sec))) for sec in self.POWER_CURVE_SECONDS
            if isinstance(curve, dict) and number(curve.get(str(sec))) is not None
            and (row["moving_time_s"] is None or sec <= row["moving_time_s"])}
        row["has_power"] = act.get("power_curve_expected") is True or bool(row["power_curve"]) or any(
            number(act.get(k)) is not None and act[k] > 0 for k in power_keys
        ) or "watts" in (act.get("stream_types") or [])
        return row

    @staticmethod
    def _fact_max(records, key):
        candidates = [r for r in records if r and r.get(key) is not None]
        return min(candidates, key=lambda r: (-r[key], r.get("date", r.get("week_start", "")),
                                              r.get("activity_id", ""))) if candidates else None

    def _fact_work_bucket(self, rows, **identity):
        work = [r["work_kj"] for r in rows if r.get("work_kj") is not None]
        carbs = [r["carbs_used"] for r in rows if r.get("carbs_used") is not None]
        return {**identity, "work_kj": round(sum(work), 1) if work else None,
                "carbs_used": round(sum(carbs), 1) if carbs else None,
                "cycling_activity_count": len(rows), "work_activities": len(work),
                "carbs_activities": len(carbs)}

    def _build_fun_facts(self, activities, start, end, formatted=False, include_week=False,
                         raw_activities=None):
        """Observed cycling facts, never a training-test/capability calculation."""
        rows_by_id = {}
        raw_by_id = {}
        for raw in raw_activities or []:
            key = str(raw.get("id"))
            if key not in raw_by_id:
                raw_by_id[key] = raw
            elif raw_by_id[key] != raw:
                raw_by_id[key] = None
        for act in activities:
            row = self._fact_activity(act, formatted, raw_by_id)
            if row and start <= row["date"] <= end:
                rows_by_id.setdefault(row["activity_id"], row)
        rows = sorted(rows_by_id.values(), key=lambda r: (r["date"], r["activity_id"]))
        fields = ("moving_time_s", "work_kj", "carbs_used", "distance_m", "elevation_m", "max_hr")
        counts = {k: sum(r[k] is not None for r in rows) for k in fields}
        total = lambda k, rs: (round(sum(r[k] for r in rs if r[k] is not None), 3)
                              if not rs or any(r[k] is not None for r in rs) else None)
        power_rows = [r for r in rows if r["has_power"]]
        expected = {str(s): sum(r["moving_time_s"] is None or r["moving_time_s"] >= s
                               for r in power_rows) for s in self.POWER_CURVE_SECONDS}
        available = {str(s): sum(str(s) in r["power_curve"] for r in power_rows)
                     for s in self.POWER_CURVE_SECONDS}
        power = {"status": "complete" if expected == available else "partial",
                 "expected": expected, "available": available}
        if not power_rows:
            power["status"] = "no_power"
        elif not any(available.values()):
            power["status"] = "unavailable"
        identity = lambda r: {k: r[k] for k in ("activity_id", "activity_name", "date")}
        peaks = {}
        for seconds in self.POWER_CURVE_SECONDS:
            points = [{**identity(r), "watts": r["power_curve"][str(seconds)]}
                      for r in rows if str(seconds) in r["power_curve"]]
            peaks[str(seconds)] = self._fact_max(points, "watts")
        max_hr = self._fact_max(rows, "max_hr")
        longest = self._fact_max(rows, "moving_time_s")
        days = defaultdict(list)
        weeks = defaultdict(list)
        for row in rows:
            days[row["date"]].append(row)
            day = datetime.strptime(row["date"], "%Y-%m-%d")
            anchor = datetime.strptime(end, "%Y-%m-%d")
            ws = anchor - timedelta(days=((anchor - day).days // 7) * 7 + 6)
            weeks[ws.strftime("%Y-%m-%d")].append(row)
        result = {"start": start, "end": end, "cycling_activity_count": len(rows),
                  "sport_identity_rule": self.SPORT_IDENTITY_RULE,
                  **{k: total(k, rows) for k in ("moving_time_s", "work_kj", "carbs_used")},
                  "distance_elevation": {}, "max_power": peaks.pop("1"), "peaks": peaks,
                  "max_hr": {**identity(max_hr), "bpm": max_hr["max_hr"]} if max_hr else None,
                  "longest_ride": {**identity(longest), "moving_time_s": longest["moving_time_s"],
                                   "distance_m": longest["distance_m"],
                                   "environment": longest["environment"]} if longest else None,
                  "biggest_day": self._fact_max([
                      self._fact_work_bucket(rs, date=d) for d, rs in days.items()], "work_kj"),
                  "coverage": {**counts, "power": power}}
        for environment in ("indoor_virtual", "outdoor", "unknown"):
            group = [r for r in rows if r["environment"] == environment]
            result["distance_elevation"][environment] = {
                "cycling_activity_count": len(group),
                **{k: total(k, group) for k in ("distance_m", "elevation_m")},
                "distance_activities": sum(r["distance_m"] is not None for r in group),
                "elevation_activities": sum(r["elevation_m"] is not None for r in group)}
        if include_week:
            buckets = []
            for ws, group in weeks.items():
                we = (datetime.strptime(ws, "%Y-%m-%d") + timedelta(days=6)).strftime("%Y-%m-%d")
                buckets.append(self._fact_work_bucket(group, week_start=ws,
                    start=max(start, ws), end=min(end, we), partial=start > ws or end < we,
                    chunk=(datetime.strptime(end, "%Y-%m-%d") - datetime.strptime(we, "%Y-%m-%d")).days // 7 + 1))
            result["biggest_week"] = self._fact_max(buckets, "work_kj")
        return result

    @staticmethod
    def _sport_fact_environment(act, sport):
        """Structured setting only; machine and outdoor distances stay separate."""
        kind = act.get("type")
        flags = [act.get(key) for key in ("trainer", "indoor")]
        positive = any(value is True for value in flags)
        malformed = any(value is not None and not isinstance(value, bool) for value in flags)
        if sport == "swimming":
            if kind == "OpenWaterSwim":
                return "unknown" if positive or malformed else "open_water"
            return "pool_other"
        if kind in ("VirtualRun", "VirtualSki", "VirtualRow") or positive:
            return "indoor"
        if malformed:
            return "unknown"
        if sport == "nordic_skiing":
            return "roller" if kind == "RollerSki" else "snow"
        return "outdoor"

    def _sport_fact_rows(self, activities, start, end):
        """Preserve selection identities; reconcile extra metrics before collapsing IDs."""
        observations, _ = self._report_observations(activities, start, end)
        originals = defaultdict(list)
        for act in activities:
            if isinstance(act, dict) and act.get("id") not in (None, ""):
                originals[str(act["id"])].append(act)
        rows = defaultdict(list)
        for act in observations:
            sport = self._report_sport(act.get("type"))
            if sport not in ("running", "swimming", "nordic_skiing", "rowing"):
                continue
            row = {"activity_id": None, "activity_name": None,
                   "date": act["start_date_local"][:10], "activity_type": act["type"],
                   "environment": "unknown", "moving_time_s": None,
                   "distance_m": None, "elevation_m": None, "max_hr": None}
            rows[sport].append(row)
            if act.get("_report_conflict") or act.get("id") in (None, ""):
                continue
            group = originals[str(act["id"])]
            # A malformed duplicate date must not disappear from the fact check.
            if any(a.get("start_date_local") != act["start_date_local"] or
                   a.get("type") != act["type"] for a in group):
                continue

            def agreed(values):
                return values[0] if values and all(v == values[0] for v in values) else None

            for dest, key in (("moving_time_s", "moving_time"), ("distance_m", "distance"),
                              ("elevation_m", "total_elevation_gain")):
                row[dest] = agreed([self._fact_number(a.get(key)) for a in group])
            hrs = []
            for original in group:
                values = {self._fact_number(original.get(key)) for key in
                          ("max_heartrate", "max_hr", "max_heart_rate", "maxHr", "icu_max_hr")}
                values.discard(None)
                values.discard(0)
                hrs.append(next(iter(values)) if len(values) == 1 else None)
            row["max_hr"] = agreed(hrs)
            names = [a.get("name") if isinstance(a.get("name"), str) else None for a in group]
            settings = [self._sport_fact_environment(a, sport) for a in group]
            row.update(activity_id=str(act["id"]), activity_name=agreed(names),
                       environment=agreed(settings) or "unknown")
        return rows

    def _sport_period_facts(self, activities, selection, season=False):
        """Reduce observations for the supplied ready selection; never reselect sports."""
        if not isinstance(selection, dict) or not isinstance(selection.get("selected"), dict):
            return None
        start, end = selection.get("start"), selection.get("end")
        if (not isinstance(start, str) or not isinstance(end, str) or
                self._fact_date(start) != start or self._fact_date(end) != end or start > end):
            return None
        result = {"start": start, "end": end, "sports": {}}
        if season:
            result["completed_weeks"] = selection["weeks"]
        sports = [s for s in ("running", "swimming", "nordic_skiing", "rowing")
                  if s in selection["selected"]]
        if not sports:
            return result
        groups = self._sport_fact_rows(activities, start, end)

        def total(rows, key):
            values = [r[key] for r in rows if r[key] is not None]
            return round(math.fsum(values), 3) if values else None

        def winner(rows, key):
            valid = [r for r in rows if r[key] is not None]
            return min(valid, key=lambda r: (-r[key], r["date"], r["activity_id"],
                                            r["activity_type"])) if valid else None

        def identity(row):
            return {key: row[key] for key in
                    ("activity_id", "activity_name", "date", "activity_type")}

        for sport in sports:
            rows = groups[sport]
            hr, longest = winner(rows, "max_hr"), winner(rows, "moving_time_s")
            facts = {"activity_count": len(rows), "moving_time_s": total(rows, "moving_time_s"),
                     "coverage": {key: sum(r[key] is not None for r in rows)
                                  for key in ("moving_time_s", "max_hr")},
                     "max_hr": {**identity(hr), "bpm": hr["max_hr"]} if hr else None,
                     "distance_elevation": {}}
            if not season:
                facts["longest_session"] = ({**identity(longest),
                    **{key: longest[key] for key in ("moving_time_s", "distance_m", "environment")}}
                    if longest else None)
            for setting in ("outdoor", "indoor", "open_water", "pool_other", "snow", "roller", "unknown"):
                group = [r for r in rows if r["environment"] == setting]
                if not group:
                    continue
                bucket = {"activity_count": len(group), "distance_m": total(group, "distance_m"),
                          "distance_activities": sum(r["distance_m"] is not None for r in group)}
                if (sport == "running" and setting == "outdoor" or
                        sport == "nordic_skiing" and setting in ("snow", "roller")):
                    bucket.update(elevation_m=total(group, "elevation_m"),
                                  elevation_activities=sum(r["elevation_m"] is not None for r in group))
                facts["distance_elevation"][setting] = bucket
            result["sports"][sport] = facts
        return result

    def _build_sport_fun_facts(self, activities, selections):
        """Optional sibling only; legacy cycling objects and persistence stay untouched."""
        periods = {key: self._sport_period_facts(activities, block, season=key == "season")
                   for key, block in selections.items()}
        if not any(block and block["sports"] for block in periods.values()):
            return None
        return {"schema_version": 1, "sport_identity_rule": self.SPORT_IDENTITY_RULE,
                "selection_rule": self.REPORT_INTENSITY_RULE, **periods}

    def _report_wellness(self, wellness, start, end, athlete_units=None):
        """Observed local-day statistics, not the seven-day display slice."""
        rows = {w["id"][:10]: w for w in wellness
                if isinstance(w.get("id"), str) and start <= w["id"][:10] <= end}
        result = {"start": start, "end": end}
        for label, key, divisor in (("hrv", "hrv", 1), ("resting_hr", "restingHR", 1),
                                    ("sleep_hours", "sleepSecs", 3600),
                                    ("sleep_quality", "sleepQuality", 1), ("weight_kg", "weight", 1)):
            valid = lambda v: (self._is_valid_hrv(v) if key == "hrv" else
                               self._structure_number(v) and v > 0)
            values = [(date, w[key] / divisor) for date, w in sorted(rows.items()) if valid(w.get(key))]
            nums = [v for _, v in values]
            result[label] = {"avg": round(statistics.mean(nums), 2) if nums else None,
                             "min": min(nums) if nums else None, "max": max(nums) if nums else None,
                             "days": len(nums)}
            if label == "weight_kg":
                result[label].update(latest=nums[-1] if nums else None,
                                     latest_date=values[-1][0] if nums else None)
                result["weight_display"] = {
                    k: self._to_display(result[label][k], "weight", athlete_units)
                    for k in ("avg", "latest")}
        return result

    def _hard_day_evidence(self, group, formatted_by_id):
        """Explain the existing preferred-basis daily ladder, without reclassifying."""
        by_basis, members = {}, []
        for act in group:
            zones, basis = self._get_activity_zones(act, sport_family=self.SPORT_FAMILIES.get(act.get("type")))
            if zones and basis:
                totals = by_basis.setdefault(basis, {})
                for key, seconds in zones.items():
                    totals[key] = totals.get(key, 0) + seconds
                row = formatted_by_id.get(str(act.get("id")), {})
                members.append({"activity_id": act.get("id"), "name": act.get("name"),
                                "basis": basis, "targets_intensity": (row.get("plan_pairing") or {}).get("targets_intensity"),
                                "cycling": self._report_sport(act.get("type")) == "cycling",
                                "z3_s": zones.get("z3", 0)})
        hard, basis = self._classify_hard_day(by_basis)
        if not hard:
            return None
        triggers = []
        for source, rungs in (("power", ((3, 1800), (4, 600), (5, 300), (6, 120), (7, 60))),
                              ("hr", ((4, 600), (5, 300)))):
            zones = by_basis.get(source, {})
            for zone, minimum in rungs:
                seconds = sum(zones.get("z" + str(z), 0) for z in range(zone, 8))
                if seconds >= minimum:
                    triggers.append({"basis": source, "rung": "z" + str(zone) + ("+" if zone < 7 else ""),
                                     "seconds": seconds, "threshold_s": minimum})
        z3_rides = [m for m in members if m["basis"] == "power" and m["z3_s"] > 0]
        only_z3 = len(triggers) == 1 and triggers[0]["basis"] == "power" and triggers[0]["rung"] == "z3+"
        return {"basis": basis, "triggers": triggers, "activities": members,
                "power_z3_only_non_intensity": bool(only_z3 and z3_rides and all(
                    m["cycling"] and m["targets_intensity"] is False for m in z3_rides))}

    def _rolling_7d_chunks(self, activities, wellness, formatted, today, current_ctl,
                           primary_sport=None):
        """Four disjoint rolling weeks; reuse metric gates, never phase detection."""
        anchor = datetime.strptime(today, "%Y-%m-%d")
        chunks = []
        first_report = None
        for index in range(4):
            end = (anchor - timedelta(days=index * 7)).strftime("%Y-%m-%d")
            start = (anchor - timedelta(days=index * 7 + 6)).strftime("%Y-%m-%d")
            acts = [a for a in activities if start <= a.get("start_date_local", "")[:10] <= end]
            days = [w for w in wellness if start <= w.get("id", "")[:10] <= end]
            zones = self._aggregate_zones(acts)
            by_date = defaultdict(list)
            for act in acts:
                by_date[act["start_date_local"][:10]].append(act)
            formatted_by_id = {str(a.get("id")): a for a in formatted}
            hard_day_details = []
            for date, group in sorted(by_date.items()):
                evidence = self._hard_day_evidence(group, formatted_by_id)
                if evidence:
                    hard_day_details.append({"date": date, **evidence})
            hard_days = len(hard_day_details)
            durability = self._calculate_durability(acts, acts)
            ef = self._calculate_efficiency_factor(acts, acts)
            hrrc = self._calculate_hrrc_trend(acts, acts)
            hrv = [w["hrv"] for w in days if self._is_valid_hrv(w.get("hrv"))]
            rhr = [w["restingHR"] for w in days if w.get("restingHR")]
            sleep = [w["sleepSecs"] / 3600 for w in days if w.get("sleepSecs")]
            end_wellness = next((w for w in days if w.get("id", "")[:10] == end), {})
            report = self._report_pack(self._report_intensity(
                activities, start, end, week_mode="rolling", as_of=today))
            if index == 0:
                first_report = report
            if report == first_report:
                # Each chunk was selected independently. Reuse identical values
                # only; the consuming chunk always owns its own date bounds.
                report = {"ref": "derived_metrics.report_intensity_7d"}
            chunks.append({
                "chunk": index + 1, "start": start, "end": end,
                "total_hours": round(sum(a.get("moving_time", 0) or 0 for a in acts) / 3600, 2),
                "total_tss": round(sum(a.get("icu_training_load", 0) or 0 for a in acts), 0),
                "seiler_tid_primary": self._report_seiler_tid(acts, primary_sport),
                "report_intensity": report,
                "zone_distribution": {
                    **{key + "_hours": round(zones[key + "_time"] / 3600, 2)
                       for key in ("z1", "z2", "z3", "z4_plus", "total")},
                    "zone_basis": zones["zone_basis"]},
                "hard_days": hard_days,
                "hard_day_details": hard_day_details,
                "hard_days_coverage": self._hard_days_coverage(acts),
                "wellness": self._report_wellness(wellness, start, end),
                "durability_mean": durability["mean_decoupling_7d"],
                "durability_qualifying": durability["qualifying_sessions_7d"],
                "durability_sport": "cycling",
                "ef_mean": ef["mean_ef_7d"], "ef_qualifying": ef["qualifying_sessions_7d"],
                "hrrc_mean": hrrc["mean_hrrc_7d"], "hrrc_qualifying": hrrc["qualifying_sessions_7d"],
                "avg_hrv": round(statistics.mean(hrv), 1) if hrv else None,
                "avg_resting_hr": round(statistics.mean(rhr), 1) if rhr else None,
                "avg_sleep_hours": round(statistics.mean(sleep), 2) if sleep else None,
                "wellness_days": {"hrv": len(hrv), "resting_hr": len(rhr), "sleep": len(sleep)},
                "ctl_end": current_ctl if index == 0 else end_wellness.get("ctl"),
                "fun_facts": self._build_fun_facts(formatted, start, end, formatted=True,
                                                  raw_activities=activities)})
        return chunks

    def _season_fun_facts(self, weekly_rows):
        """Reduce the completed-week cache only; never include its partial last row."""
        weeks = [r["fun_facts"] for r in weekly_rows[:-1]]
        if not weeks:
            return None
        result = self._build_fun_facts([], weeks[0]["start"], weeks[-1]["end"], include_week=True)
        result["completed_weeks"] = len(weeks)
        result["cycling_activity_count"] = sum(w["cycling_activity_count"] for w in weeks)
        for key in ("moving_time_s", "work_kj", "carbs_used"):
            values = [w[key] for w in weeks if w[key] is not None]
            result[key] = round(sum(values), 3) if values else None
        for key in result["coverage"]:
            if key != "power":
                result["coverage"][key] = sum(w["coverage"][key] for w in weeks)
        for key in ("moving_time_s", "work_kj", "carbs_used"):
            if result["cycling_activity_count"] and not result["coverage"][key]:
                result[key] = None
        for env, block in result["distance_elevation"].items():
            for key in block:
                values = [w["distance_elevation"][env][key] for w in weeks
                          if w["distance_elevation"][env][key] is not None]
                block[key] = round(sum(values), 3) if values else None
            for key, count in (("distance_m", "distance_activities"), ("elevation_m", "elevation_activities")):
                if block["cycling_activity_count"] and not block[count]:
                    block[key] = None
        for key, metric in (("max_power", "watts"), ("max_hr", "bpm"),
                            ("longest_ride", "moving_time_s"), ("biggest_day", "work_kj")):
            result[key] = self._fact_max([w[key] for w in weeks], metric)
        result["peaks"] = {s: self._fact_max([w["peaks"][s] for w in weeks], "watts")
                           for s in result["peaks"]}
        result["biggest_week"] = self._fact_max([
            {"week_start": w["start"], "start": w["start"], "end": w["end"], "partial": False,
             "work_kj": w["work_kj"], "carbs_used": w["carbs_used"],
             "cycling_activity_count": w["cycling_activity_count"],
             "work_activities": w["coverage"]["work_kj"],
             "carbs_activities": w["coverage"]["carbs_used"]} for w in weeks
             if w["coverage"]["work_kj"] > 0], "work_kj")
        power = result["coverage"]["power"]
        for kind in ("expected", "available"):
            power[kind] = {s: sum(w["coverage"]["power"][kind][s] for w in weeks)
                           for s in power[kind]}
        statuses = {w["coverage"]["power"]["status"] for w in weeks}
        power["status"] = ("stale" if "stale" in statuses else
                           "unavailable" if not any(power["available"].values()) and any(power["expected"].values()) else
                           "partial" if statuses - {"complete", "no_power"} else
                           "complete" if any(power["expected"].values()) else "no_power")
        return result

    def _cached_fact_power_valid(self, facts, start, end):
        """Only a well-formed in-window observation cache can survive a failure."""
        try:
            if facts["start"] != start or not start <= facts["end"] <= end:
                return False
            power = facts["coverage"]["power"]
            if power["status"] not in ("complete", "partial", "unavailable", "no_power", "stale"):
                return False
            for kind in ("expected", "available"):
                if any(type(power[kind][str(s)]) is not int or power[kind][str(s)] < 0
                       for s in self.POWER_CURVE_SECONDS):
                    return False
            for point in [facts["max_power"], *(facts["peaks"][str(s)] for s in self.POWER_CURVE_SECONDS[1:])]:
                if point is not None and (not isinstance(point["activity_id"], str)
                        or self._fact_number(point["watts"]) is None
                        or self._fact_date(point["date"]) != point["date"]
                        or not start <= point["date"] <= facts["end"]):
                    return False
            return True
        except (KeyError, TypeError, AttributeError):
            return False

    def _pack_weekly_fact_power(self, facts, meta):
        """Persist only the attributed maxima needed across history refreshes."""
        grouped = {}
        points = [facts["max_power"], *(facts["peaks"][str(s)] for s in self.POWER_CURVE_SECONDS[1:])]
        for index, point in enumerate(points):
            if point is not None:
                key = (point["activity_id"], point["date"])
                grouped.setdefault(key, [*key, *([None] * 6)])[index + 2] = point["watts"]
        def counts(values):
            vector = [values[str(s)] for s in self.POWER_CURVE_SECONDS]
            return vector[0] if len(set(vector)) == 1 else vector
        power = facts["coverage"]["power"]
        result = {"power": [grouped[k] for k in sorted(grouped)], "expected": counts(power["expected"])}
        coverage = {}
        implied = "complete" if any(power["expected"].values()) else "no_power"
        if power["status"] != implied:
            coverage["status"] = power["status"]
        if power["available"] != power["expected"]:
            coverage["available"] = counts(power["available"])
        default_end = min(meta["end"], (datetime.strptime(facts["start"], "%Y-%m-%d") + timedelta(days=6)).strftime("%Y-%m-%d"))
        for key, default in (("sampled_at", meta.get("sampled_at")),
                             ("start", facts["start"]), ("end", default_end)):
            if power.get(key) != default:
                coverage[key] = power.get(key)
        if coverage:
            result["coverage"] = coverage
        return result

    def _unpack_weekly_fact_power(self, row, meta, names):
        """Read compact or earlier full caches; malformed rows cannot be reused."""
        try:
            raw, start = row["fun_facts"], row["week_start"]
            if "power" not in raw:
                return raw  # The earlier full-week schema remains readable.
            if meta.get("weekly_cache_version") != 1:
                return None
            end = min(meta["end"], (datetime.strptime(start, "%Y-%m-%d") + timedelta(days=6)).strftime("%Y-%m-%d"))
            def counts(value):
                vector = [value] * 6 if type(value) is int else value
                if not isinstance(vector, list) or len(vector) != 6 or any(type(n) is not int or n < 0 for n in vector):
                    raise ValueError("invalid coverage")
                return dict(zip(map(str, self.POWER_CURVE_SECONDS), vector))
            expected = counts(raw["expected"])
            extra = raw.get("coverage", {})
            available = counts(extra["available"]) if "available" in extra else dict(expected)
            power = {"expected": expected, "available": available,
                     "status": "complete" if any(expected.values()) else "no_power",
                     "sampled_at": meta.get("sampled_at"), "start": start, "end": end}
            power.update({k: extra[k] for k in ("status", "sampled_at", "start", "end") if k in extra})
            if (power["start"] != start or self._fact_date(power["end"]) != power["end"]
                    or not start <= power["end"] <= end):
                return None
            points = {str(s): None for s in self.POWER_CURVE_SECONDS}
            if not isinstance(raw["power"], list) or len(raw["power"]) > 6:
                return None
            for item in raw["power"]:
                if (not isinstance(item, list) or len(item) != 8 or not isinstance(item[0], str)
                        or not item[0] or self._fact_date(item[1]) != item[1]
                        or not start <= item[1] <= power["end"] or all(w is None for w in item[2:])):
                    return None
                for s, watts in zip(self.POWER_CURVE_SECONDS, item[2:]):
                    if watts is not None:
                        if self._fact_number(watts) is None or points[str(s)] is not None:
                            return None
                        points[str(s)] = {"watts": watts, "activity_id": item[0], "date": item[1],
                                          "activity_name": names.get((item[0], item[1]))}
            if any(available[s] > expected[s] or (available[s] > 0) != (points[s] is not None) for s in points):
                return None
            observed_status = ("complete" if any(expected.values()) else "no_power") if available == expected else (
                "partial" if any(available.values()) else "unavailable")
            if power["status"] not in (observed_status, "stale") and not (
                    power["status"] == "unavailable" and not any(available.values())):
                return None
            return {"start": start, "end": end, "max_power": points.pop("1"),
                    "peaks": points, "coverage": {"power": power}}
        except (KeyError, TypeError, ValueError, AttributeError):
            return None

    def _history_fun_fact_power(self, weekly_rows, activities, previous):
        """One aggregate read on history refresh; weekly maxima are the disk cache."""
        start, end = weekly_rows[0]["week_start"], datetime.now().strftime("%Y-%m-%d")
        old_meta = previous.get("fun_facts_power") or {}
        if not isinstance(old_meta, dict):
            old_meta = {}
        names = {}
        prior_facts = previous.get("fun_facts")
        season = prior_facts.get("season") if isinstance(prior_facts, dict) else None
        season = season if isinstance(season, dict) else {}
        prior_peaks = season.get("peaks")
        prior_peaks = prior_peaks if isinstance(prior_peaks, dict) else {}
        for point in [season.get("max_power"), *prior_peaks.values()]:
            if isinstance(point, dict) and isinstance(point.get("activity_name"), str):
                names[(point.get("activity_id"), point.get("date"))] = point["activity_name"]
        for act in activities:
            if isinstance(act.get("name"), str):
                names[(str(act.get("id")), self._fact_date(act.get("start_date_local")))] = act["name"]
        old_rows = {}
        for row in previous.get("weekly_180d", []) or []:
            if isinstance(row, dict):
                facts = self._unpack_weekly_fact_power(row, old_meta, names)
                if (old_meta.get("sport_identity_rule") == self.SPORT_IDENTITY_RULE
                        and self._cached_fact_power_valid(facts, row.get("week_start"), end)):
                    old_rows[row["week_start"]] = facts
        stamp = self._history_stamp_utc(old_meta.get("sampled_at"))
        now = datetime.now(timezone.utc)
        cache_fresh = (old_meta.get("status") == "ok" and old_meta.get("start") == start
                       and old_meta.get("end") == end and stamp is not None
                       and 0 <= (now - stamp).total_seconds() < 86400
                       and all(old_rows.get(r["week_start"]) for r in weekly_rows)
                       and old_meta.get("activity_key") == self._structure_fingerprint(activities))
        curves, error = None, None
        if not cache_fresh:
            query = (start, end)
            cached = getattr(self, "_fun_fact_curve_run", None)
            if cached is not None:
                if cached[0] == query:
                    curves, error = cached[1:]
                else:
                    error = "request_budget"
            else:
                try:
                    payload = self._intervals_get("activity-power-curves", {
                        "oldest": start, "newest": end, "type": "Ride",
                        "secs": ",".join(map(str, self.POWER_CURVE_SECONDS))})
                    curves = self._parse_fun_fact_curves(payload, start, end)
                except requests.exceptions.RequestException as exc:
                    response = getattr(exc, "response", None)
                    error = "http_" + str(response.status_code) if response is not None else "transport_error"
                except (ValueError, TypeError, KeyError):
                    error = "invalid_response"
                self._fun_fact_curve_run = (query, curves, error)
        meta = {"start": start, "end": end, "status": "ok" if curves is not None or cache_fresh else "unavailable",
                "sampled_at": old_meta.get("sampled_at") if cache_fresh else now.isoformat() if curves is not None else None,
                "activity_key": self._structure_fingerprint(activities), "weekly_cache_version": 1,
                "sport_identity_rule": self.SPORT_IDENTITY_RULE}
        if error:
            meta["error"] = error
        matched = set()
        for week in weekly_rows:
            ws = week["week_start"]
            we = min(end, (datetime.strptime(ws, "%Y-%m-%d") + timedelta(days=6)).strftime("%Y-%m-%d"))
            group = []
            for act in activities:
                date = self._fact_date(act.get("start_date_local"))
                if date is None or not ws <= date <= we:
                    continue
                act = dict(act)
                curve = (curves or {}).get(str(act.get("id")))
                if curve and curve["date"] == date and self._report_sport(act.get("type")) == "cycling":
                    act["power_curve"] = curve["power_curve"]
                    matched.add(str(act["id"]))
                group.append(act)
            facts = self._build_fun_facts(group, ws, we)
            power = facts["coverage"]["power"]
            power["sampled_at"] = meta["sampled_at"]
            power.update(start=ws, end=we)
            if curves is None:
                prior = old_rows.get(ws)
                if prior:
                    facts["max_power"], facts["peaks"] = prior["max_power"], prior["peaks"]
                    facts["coverage"]["power"] = dict(prior["coverage"]["power"])
                    if not cache_fresh:
                        facts["coverage"]["power"]["status"] = "stale"
                        meta["status"] = "stale"
                        meta["sampled_at"] = old_meta.get("sampled_at")
                else:
                    power["status"] = "unavailable"
            week["fun_facts"] = facts
        if curves is not None:
            meta["unmatched_curves"] = len(set(curves) - matched)
        return meta

    def _parse_fun_fact_curves(self, payload, start, end):
        """Validate the supplied ActivityPowerCurvePayload; never pad short arrays."""
        if (not isinstance(payload, dict) or type(payload.get("after_kj")) is not int
                or payload["after_kj"] != 0):
            raise ValueError("invalid_response")
        seconds, raw = payload.get("secs"), payload.get("curves")
        if (not isinstance(seconds, list) or not seconds or not isinstance(raw, list)
                or any(type(s) is not int or s not in self.POWER_CURVE_SECONDS for s in seconds)
                or len(set(seconds)) != len(seconds)):
            raise ValueError("invalid_response")
        result = {}
        for curve in raw:
            if not isinstance(curve, dict):
                raise ValueError("invalid_response")
            aid, date, watts = curve.get("id"), self._fact_date(curve.get("start_date_local")), curve.get("watts")
            if (not isinstance(aid, str) or not aid or aid in result or date is None
                    or not start <= date <= end or not isinstance(watts, list) or len(watts) > len(seconds)
                    or any(w is not None and self._fact_number(w) is None for w in watts)):
                raise ValueError("invalid_response")
            result[aid] = {"date": date, "power_curve": {str(s): w for s, w in zip(seconds, watts) if w is not None}}
        return result

    def _post_workout_fields(self, act: Dict, avg_power, avg_speed, temp_unit, units) -> Dict:
        """Add presentation fields without changing any legacy activity value."""
        def number(value):
            return (isinstance(value, (int, float)) and not isinstance(value, bool)
                    and math.isfinite(value))

        def rounded_duration(seconds):
            if not number(seconds) or seconds < 0:
                return None
            minutes = int(seconds / 60 + 0.5)
            return self._format_duration(minutes * 60) if minutes else "0m"

        elapsed = act.get("elapsed_time")
        if not number(elapsed) or elapsed < 0:
            elapsed = None
        weight = act.get("icu_weight")
        if not number(weight) or not 30 <= weight <= 200 or not number(avg_power) or avg_power <= 0:
            weight = None
        source, minimum, average, maximum = None, None, None, None
        if act.get("average_weather_temp") is not None:
            source = "weather"
            minimum, average, maximum = (act.get(k) for k in
                ("min_weather_temp", "average_weather_temp", "max_weather_temp"))
        elif act.get("average_temp") is not None:
            source = "device"
            minimum, average, maximum = (act.get(k) for k in
                ("min_temp", "average_temp", "max_temp"))
        temp_display = lambda value: ({"value": round(value), "unit": "°F" if temp_unit == "F" else "°C"}
                                      if value is not None else None)
        pace = None
        if (act.get("type") in {"Run", "TrailRun", "VirtualRun", "Walk", "Hike"}
                and number(avg_speed) and avg_speed > 0):
            # Use canonical avg_speed before display-speed rounding.
            speed = avg_speed * 0.621371 if units.get("distance") == "imperial" else avg_speed
            seconds = int(3600 / speed + 0.5)
            pace = {"value": f"{seconds // 60}:{seconds % 60:02d}",
                    "unit": "/mi" if units.get("distance") == "imperial" else "/km"}
        return {
            "elapsed_hours": round(elapsed / 3600, 2) if elapsed is not None else None,
            "elapsed_formatted": rounded_duration(elapsed),
            "min_temp": minimum, "max_temp": maximum, "temp_source": source,
            "power_weight_kg": weight,
            "avg_power_wkg": round(avg_power / weight, 2) if weight is not None else None,
            "display": {
                "moving_time": rounded_duration(act.get("moving_time")),
                "elapsed_time": rounded_duration(elapsed),
                "min_temp": temp_display(minimum), "avg_temp": temp_display(average),
                "max_temp": temp_display(maximum),
                "power_weight": self._to_display(weight, "weight", units),
                "pace": pace,
            },
        }

    def _athlete_units_from_dict(self, athlete: Dict) -> Dict[str, str]:
        """
        Extract the athlete's unit preferences from an already-fetched athlete dict.
        
        Returns a dict mapping concept to unit code:
            {
              "wind":     "m/s" | "km/h" | "mph",
              "temp":     "c" | "f",
              "rain":     "mm" | "in",
              "distance": "metric" | "imperial",
              "weight":   "kg" | "lb",
              "height":   "cm" | "in"
            }
        
        Used to populate the `units` block on weather_summary so the data values
        can stay in stable keys (e.g. avg_wind_speed) regardless of athlete
        settings, with the unit resolved separately. Falls back to all-metric
        defaults if the input dict is missing or empty.
        """
        defaults = {
            "wind": "m/s", "temp": "c", "rain": "mm",
            "distance": "metric", "weight": "kg", "height": "cm"
        }
        if not athlete:
            return defaults
        # Map Intervals settings to our normalized codes.
        wind_map = {"MPS": "m/s", "KPH": "km/h", "MPH": "mph"}
        rain_map = {"MM": "mm", "IN": "in"}
        return {
            "wind": wind_map.get(athlete.get("wind_speed"), defaults["wind"]),
            "temp": "f" if athlete.get("fahrenheit") else "c",
            "rain": rain_map.get(athlete.get("rain"), defaults["rain"]),
            "distance": "imperial" if athlete.get("measurement_preference") not in ("meters", None) else "metric",
            "weight": "lb" if athlete.get("weight_pref_lb") else "kg",
            "height": "in" if athlete.get("height_units") == "IN" else "cm"
        }

    def _to_display(self, value: Optional[float], kind: str,
                    athlete_units: Optional[Dict[str, str]] = None) -> Optional[Dict]:
        """
        Convert a canonical-metric value into a display-ready {value, unit} pair
        based on the athlete's Intervals.icu unit preferences.
        
        Canonical (input) units are fixed by sync.py — calculations always use these:
          - distance / position / total_distance: km
          - elevation / total_elevation: m (positive or signed)
          - elevation_per_distance: m/km
          - weight: kg
          - height: m
          - speed: km/h
        
        Display blocks let the AI narrate without doing unit math. Metric athletes
        get the same numeric value with a metric unit code; imperial athletes get
        the converted value with an imperial unit code. The conversion is a no-op
        on metric (input == output, just rounded).
        
        kinds: "distance" | "elevation" | "elevation_per_distance" |
               "weight"   | "height"    | "speed"
        
        Returns {"value": <rounded float>, "unit": <code>} — or None if value is None.
        Unit codes (display, lowercase): km/mi, m/ft, m/km, ft/mi, kg/lb, cm/in, km/h, mph.
        """
        if value is None:
            return None
        units = athlete_units or {}
        
        if kind == "distance":
            if units.get("distance") == "imperial":
                return {"value": round(value * 0.621371, 2), "unit": "mi"}
            return {"value": round(value, 2), "unit": "km"}
        
        if kind == "elevation":
            if units.get("distance") == "imperial":
                return {"value": round(value * 3.28084), "unit": "ft"}
            return {"value": round(value), "unit": "m"}
        
        if kind == "elevation_per_distance":
            # m/km → ft/mi: m * 3.28084 / (km * 0.621371) = m/km * 5.28
            if units.get("distance") == "imperial":
                return {"value": round(value * 5.28), "unit": "ft/mi"}
            return {"value": round(value), "unit": "m/km"}
        
        if kind == "weight":
            if units.get("weight") == "lb":
                return {"value": round(value * 2.20462, 1), "unit": "lb"}
            return {"value": round(value, 1), "unit": "kg"}
        
        if kind == "height":
            # canonical input is meters
            if units.get("height") == "in":
                return {"value": round(value * 39.3701), "unit": "in"}
            return {"value": round(value * 100), "unit": "cm"}
        
        if kind == "speed":
            # canonical input is km/h (sync.py converts m/s → km/h regardless of pref)
            if units.get("distance") == "imperial":
                return {"value": round(value * 0.621371, 1), "unit": "mph"}
            return {"value": round(value, 1), "unit": "km/h"}
        
        return None

    def _refresh_terrain_display(self, terrain_summary: Dict,
                                 athlete_units: Optional[Dict[str, str]] = None) -> Dict:
        """
        Refresh display blocks on a copy-forward terrain_summary using current
        athlete_units. Canonical metric fields (total_distance_km, climbs[].position_km,
        etc.) are preserved verbatim; only the display sub-objects are recomputed.
        
        This lets terrain caches (recent_activities[].terrain_summary copy-forward
        and routes.json attachment-id cache) survive a unit preference change
        without invalidating the expensive trackpoint analysis.
        
        Defensive: if the cached object pre-dates v3.109 and has no display block,
        one is created. If athlete_units is None, the cached display is preserved
        (fall-back to whatever was last written).
        """
        if not isinstance(terrain_summary, dict):
            return terrain_summary
        if athlete_units is None:
            return terrain_summary
        
        out = dict(terrain_summary)  # shallow copy
        out["display"] = {
            "total_distance": self._to_display(out.get("total_distance_km"), "distance", athlete_units),
            "total_elevation": self._to_display(out.get("total_elevation_m"), "elevation", athlete_units),
            "elevation_per_distance": self._to_display(out.get("elevation_per_km"), "elevation_per_distance", athlete_units),
        }
        for key in ("climbs", "descents"):
            segments = out.get(key)
            if not isinstance(segments, list):
                continue
            refreshed = []
            for seg in segments:
                if not isinstance(seg, dict):
                    refreshed.append(seg)
                    continue
                seg_out = dict(seg)
                seg_out["display"] = {
                    "position": self._to_display(seg_out.get("position_km"), "distance", athlete_units),
                    "distance": self._to_display(seg_out.get("distance_km"), "distance", athlete_units),
                    "elevation": self._to_display(seg_out.get("elevation_m"), "elevation", athlete_units),
                }
                refreshed.append(seg_out)
            out[key] = refreshed
        return out

    def _load_previous_latest(self) -> Dict[str, Dict]:
        """
        Read previous latest.json and build an activity-id-keyed lookup dict.
        
        Used as the persistent state for terrain/weather summaries — fields
        already populated on a previous sync are copied forward instead of
        being re-fetched. The presence of `terrain_summary` (or terminal
        `terrain_status`) on a record IS the "already pulled" signal.
        
        Returns a dict mapping str(activity_id) -> {
            "terrain_summary": <dict or absent>,
            "terrain_status":  <str or absent>,
            "terrain_error":   <str or absent>,
            "weather_summary": <dict or absent>
            # weather_status not copied forward — re-evaluated each sync from
            # current activity-list `has_weather` field.
        }
        Empty dict when latest.json is absent (first sync, fresh data dir).
        Activity IDs are normalized to strings to defend against type mismatch
        between dict construction and lookup.
        """
        latest_path = self.data_dir / "latest.json"
        if not latest_path.exists():
            return {}
        try:
            with open(latest_path, 'r') as f:
                data = json.load(f)
        except Exception as e:
            if self.debug:
                print(f"    ⚠️  Could not read previous latest.json: {e}")
            return {}
        
        lookup = {}
        for act in data.get("recent_activities", []):
            act_id = act.get("id")
            if act_id is None:
                continue
            entry = {}
            if "terrain_summary" in act:
                entry["terrain_summary"] = act["terrain_summary"]
            if "terrain_status" in act:
                entry["terrain_status"] = act["terrain_status"]
            if "terrain_error" in act:
                entry["terrain_error"] = act["terrain_error"]
            if "weather_summary" in act:
                entry["weather_summary"] = act["weather_summary"]
            summary = self._activity_plan_match(act)
            if summary is not None:
                entry["structure_summary"] = summary
            for key in ("power_curve", "power_curve_status", "power_curve_error", "plan_pairing", "dfa_rollup", "chat_notes",
                        "decoupling_detail", "decoupling_cache"):
                if key in act:
                    entry[key] = act[key]
            if entry:
                lookup[str(act_id)] = entry
        return lookup

    def _build_terrain_for_activity(self, act: Dict, previous_lookup: Dict[str, Dict],
                                    athlete_units: Optional[Dict[str, str]] = None) -> Dict:
        """
        Resolve terrain fields for one activity per the per-activity decision logic.
        
        Returns a dict of fields to attach to the activity record (may be empty).
        Possible keys in the returned dict: terrain_summary, terrain_status,
        terrain_error.
        
        Decision tree:
          1. activity.type not in OUTDOOR_TYPES        → return {} (no field; type is the indoor signal)
          2. previous has terrain_summary              → copy forward (success, never re-fetch)
          3. previous has terminal terrain_status      → copy forward (no_gps/no_elevation/failed are terminal)
          4. otherwise                                  → fetch streams, classify, attach
                ok            → terrain_summary
                no_gps        → terrain_status="no_gps"
                no_elevation  → terrain_status="no_elevation" (still terminal — won't gain altitude later)
                terminal_error→ terrain_status="failed", terrain_error=<code>
                transient     → return {} (no field written → retry next sync)
        
        athlete_units (v3.109): when provided, fresh terrain analyses get display
        blocks; copy-forward also refreshes display blocks from canonical metric
        fields so a unit-preference change picks up next sync without invalidating
        the (expensive) terrain cache.
        """
        act_type = act.get("type", "")
        if act_type not in self.OUTDOOR_TYPES:
            return {}
        
        act_id = act.get("id")
        if act_id is None:
            return {}
        prev = previous_lookup.get(str(act_id), {})
        
        # Copy-forward: success — refresh display blocks from canonical fields
        if "terrain_summary" in prev:
            terrain = prev["terrain_summary"]
            self._adopt_native_cache("activity_terrain", act_id, isinstance(terrain, dict)
                and all(self._structure_number(terrain.get(k)) and terrain[k] >= 0
                        for k in ("total_distance_km", "total_elevation_m", "elevation_per_km"))
                and all(isinstance(terrain.get(k), list) and all(isinstance(v, dict) for v in terrain[k])
                        for k in ("climbs", "descents")))
            return {"terrain_summary": self._refresh_terrain_display(prev["terrain_summary"], athlete_units)}
        # Copy-forward: terminal non-success
        prev_status = prev.get("terrain_status")
        if prev_status in {"no_gps", "no_elevation", "failed"}:
            outcome = prev.get("terrain_error") if prev_status == "failed" else prev_status
            self._adopt_native_cache("activity_terrain", act_id,
                prev_status != "failed" or outcome in AcquisitionStore.TERMINAL_HTTP, outcome)
            out = {"terrain_status": prev_status}
            if "terrain_error" in prev:
                out["terrain_error"] = prev["terrain_error"]
            return out
        
        # Not yet attempted: fetch and classify
        status, payload = self._fetch_terrain_streams(act_id)
        if status == "ok":
            trackpoints = self._streams_to_trackpoints(payload)
            if len(trackpoints) < 2:
                return {"terrain_status": "no_gps"}
            # Defensive: even when _fetch_terrain_streams reports the altitude
            # array exists, individual values may all be None (sensor failure
            # mid-ride, malformed upload). _streams_to_trackpoints filters
            # None elevations per-point. If no trackpoint ended up with an
            # `ele` key, we'd otherwise produce a misleading flat summary.
            if not any("ele" in tp for tp in trackpoints):
                return {"terrain_status": "no_elevation"}
            summary = self._analyze_terrain(
                trackpoints, source="activity_streams", include_polyline=False,
                athlete_units=athlete_units
            )
            if summary is None:
                # Final guard — _analyze_terrain returns None for degenerate
                # paths beyond the all-None case caught above.
                return {"terrain_status": "no_elevation"}
            return {"terrain_summary": summary}
        elif status == "no_gps":
            return {"terrain_status": "no_gps"}
        elif status == "no_elevation":
            # Has GPS but no altitude. Coach can't reason about climbs/grade,
            # so we mark terminal rather than emit a misleading "flat" summary.
            return {"terrain_status": "no_elevation"}
        elif status == "terminal_error":
            return {"terrain_status": "failed", "terrain_error": payload}
        else:
            # transient — write nothing, retry next sync
            if self.debug:
                print(f"    ⚠️  Terrain fetch transient failure for {act_id}: {payload} (will retry)")
            return {}

    def _build_weather_for_activity(self, act: Dict, previous_lookup: Dict[str, Dict],
                                    units: Dict[str, str]) -> Dict:
        """
        Resolve weather fields for one activity.
        
        Weather is provided by Intervals on the activity-list response (no extra
        API call), gated on `has_weather: true`. Unlike terrain, weather has NO
        terminal failure mode — `weather_status: "unavailable"` is never copied
        forward, because Intervals may compute weather later and we want to
        re-evaluate every sync.
        
        Decision tree:
          1. activity.type not in OUTDOOR_TYPES → return {} (no field)
          2. previous has weather_summary       → copy forward (one less rebuild)
          3. has_weather true                   → build summary from current data
          4. else                               → weather_status="unavailable"
        
        Note: step 2 is purely an optimization (avoid rebuilding the summary
        every sync). Since Intervals' weather fields don't change once set,
        the copy-forward result is identical to a fresh build.
        """
        act_type = act.get("type", "")
        if act_type not in self.OUTDOOR_TYPES:
            return {}
        
        act_id = act.get("id")
        prev = previous_lookup.get(str(act_id), {}) if act_id is not None else {}
        if "weather_summary" in prev:
            return {"weather_summary": prev["weather_summary"]}
        
        if not act.get("has_weather"):
            return {"weather_status": "unavailable"}
        
        # Build summary from existing fields on the activity list response.
        # Stable keys + explicit `units` block (no dynamic suffixes).
        summary = {
            "source": "intervals_open_meteo",
            "units": {
                "wind": units.get("wind", "m/s"),
                "temp": units.get("temp", "c"),
                "rain": units.get("rain", "mm"),
            },
            "avg_wind_speed": act.get("average_wind_speed"),
            "avg_wind_gust": act.get("average_wind_gust"),
            "prevailing_wind_deg": act.get("prevailing_wind_deg"),
            "headwind_pct": act.get("headwind_percent"),
            "tailwind_pct": act.get("tailwind_percent"),
            "avg_temp": act.get("average_weather_temp"),
            "avg_temp_device": act.get("average_temp"),
            "avg_feels_like": act.get("average_feels_like"),
            "min_feels_like": act.get("min_feels_like"),
            "max_feels_like": act.get("max_feels_like"),
            "min_temp": act.get("min_weather_temp"),
            "max_temp": act.get("max_weather_temp"),
            "clouds_pct": act.get("average_clouds"),
            "rain": act.get("max_rain"),
            "snow": act.get("max_snow"),
        }
        # Round numerics for cleaner JSON; preserve None values.
        for k, v in list(summary.items()):
            if isinstance(v, float):
                summary[k] = round(v, 2)
        return {"weather_summary": summary}

    def _dfa_coverage_by_third(self, valid_mask, drift_mask, artifacts):
        """Coverage in original coordinates. Retained and drift masks are distinct."""
        n = len(valid_mask)
        third = n // 3

        def _max_gap(mask):
            longest = run = 0
            for valid in mask:
                run = 0 if valid else run + 1
                longest = max(longest, run)
            return longest

        def _span(start, end):
            total = end - start
            valid = sum(valid_mask[start:end])
            drift_valid = sum(drift_mask[start:end])
            return {
                "start_sample_idx": start,
                "end_sample_idx_exclusive": end,
                "total_samples": total,
                "valid_samples": valid,
                "valid_pct": round(100.0 * valid / total, 3) if total else None,
                "drift_valid_samples": drift_valid,
                "drift_valid_pct": round(100.0 * drift_valid / total, 3) if total else None,
            }

        spans = []
        for role, start, end in (("early", 0, third), ("middle", third, n - third),
                                 ("late", n - third, n)):
            span = _span(start, end)
            span.update({
                "role": role,
                "artifact_observed_samples": sum(a is not None for a in artifacts[start:end]),
                "max_invalid_run_samples": _max_gap(valid_mask[start:end]),
                "max_drift_gap_samples": _max_gap(drift_mask[start:end]),
                "bins": None,
                "min_bin_valid_pct": None,
                "min_bin_drift_valid_pct": None,
                "allowed_drift_gap_samples": None,
            })
            if role != "middle":
                bins = []
                if third >= self.DFA_DRIFT_BINS:
                    bins = [
                        _span(start + k * third // self.DFA_DRIFT_BINS,
                              start + (k + 1) * third // self.DFA_DRIFT_BINS)
                        for k in range(self.DFA_DRIFT_BINS)
                    ]
                span["bins"] = bins
                span["min_bin_valid_pct"] = min((b["valid_pct"] for b in bins), default=None)
                span["min_bin_drift_valid_pct"] = min(
                    (b["drift_valid_pct"] for b in bins), default=None)
                span["allowed_drift_gap_samples"] = min(
                    self.DFA_DRIFT_GAP_CEILING_SAMPLES,
                    max(self.DFA_DRIFT_GAP_FLOOR_SAMPLES,
                        third * self.DFA_DRIFT_MAX_GAP_PCT // 100))
            spans.append(span)
        return spans

    def _dfa_timebase_status(self, time_stream, n):
        if not isinstance(time_stream, list) or len(time_stream) != n or not n:
            return "unverified"
        times = [self._finite_num(t) for t in time_stream]
        if any(t is None for t in times):
            return "unverified"
        if any(t - times[0] != i for i, t in enumerate(times)):
            return "nonuniform"
        return "verified_1hz"

    def _compute_dfa_drift(self, dfa_stream, drift_mask, time_stream, quality, supra_pct):
        """Fixed recording-span contrast; eligibility does not prove steady effort."""
        metadata = {
            "method": self.DFA_DRIFT_METHOD,
            "status": "unavailable",
            "reasons": [],
            "time_basis": "original_sample_index",
            "timebase_status": self._dfa_timebase_status(time_stream, len(dfa_stream)),
        }
        reasons = metadata["reasons"]
        if not quality["sufficient"]:
            if quality["valid_secs"] < self.DFA_MIN_DURATION_SECS:
                reasons.append("whole_session_duration")
            if quality["valid_pct"] < self.DFA_SUFFICIENT_MIN_VALID_PCT:
                reasons.append("whole_session_coverage")
            return None, metadata

        early, _, late = quality["coverage_by_third"]
        if early["total_samples"] < self.DFA_DRIFT_MIN_WINDOW_SAMPLES:
            reasons.append("window_too_short")
        for span in (early, late):
            if span["drift_valid_samples"] < self.DFA_DRIFT_MIN_VALID_SAMPLES:
                reasons.append(span["role"] + "_too_few_samples")
        if reasons:
            return None, metadata

        means = []
        for span in (early, late):
            values = [dfa_stream[i] for i in range(span["start_sample_idx"],
                                                  span["end_sample_idx_exclusive"])
                      if drift_mask[i]]
            mean = self._finite_num(sum(values) / len(values))
            if mean is None:
                reasons.append("invalid_dfa")
                return None, metadata
            means.append(round(mean, 3))
        delta = self._finite_num(round(means[1] - means[0], 3))
        if delta is None:
            reasons.append("invalid_dfa")
            return None, metadata

        if len(dfa_stream) < self.DFA_DRIFT_MIN_SESSION_SAMPLES:
            reasons.append("short_session")
        if metadata["timebase_status"] != "verified_1hz":
            reasons.append("timebase_" + metadata["timebase_status"])
        # Exact count inequalities, not rounded display percentages. Missing
        # artifact readings are drift gaps only, including inside each sixth.
        for span in (early, late):
            if 100 * span["drift_valid_samples"] < self.DFA_DRIFT_MIN_COVERAGE_PCT * span["total_samples"]:
                reasons.append(span["role"] + "_coverage")
        for span in (early, late):
            if any(100 * b["drift_valid_samples"] < self.DFA_DRIFT_MIN_BIN_COVERAGE_PCT * b["total_samples"]
                   for b in span["bins"]):
                reasons.append(span["role"] + "_distribution")
        for span in (early, late):
            if span["max_drift_gap_samples"] > span["allowed_drift_gap_samples"]:
                reasons.append(span["role"] + "_gap")
        if supra_pct > self.DFA_DRIFT_INTERPRETABLE_MAX_LT2_PCT:
            reasons.append("supra_fraction")
        metadata["status"] = "descriptive_only" if reasons else "eligible"
        return {
            "first_third_avg": means[0],
            "last_third_avg": means[1],
            "delta": delta,
            "interpretable": not reasons,
        }, metadata

    def _dfa_drift_eligible(self, block):
        """Fail closed for legacy, unsupported or contradictory cached metadata."""
        quality = block.get("quality") or {}
        drift = block.get("drift") or {}
        metadata = block.get("drift_quality") or {}
        return (
            quality.get("sufficient") is True
            and metadata.get("method") == self.DFA_DRIFT_METHOD
            and metadata.get("status") == "eligible"
            and metadata.get("reasons") == []
            and metadata.get("time_basis") == "original_sample_index"
            and metadata.get("timebase_status") == "verified_1hz"
            and drift.get("interpretable") is True
            and all(self._finite_num(drift.get(k)) is not None
                    for k in ("first_third_avg", "last_third_avg", "delta"))
        )

    def _dfa_quality_summary(self, block):
        quality = block.get("quality") or {}
        return {key: quality.get(key) for key in (
            "valid_secs", "total_secs", "valid_pct", "sufficient", "artifact_state",
            "artifact_coverage_pct", "coverage_by_third")}

    def _compute_dfa_block(self, streams: Dict[str, List]) -> Optional[Dict]:
        """
        Compute per-session DFA a1 rollup from raw streams.

        Inputs: streams dict from _fetch_activity_streams, expected keys:
          dfa_a1, artifacts, heartrate, watts, time (time proves continuous 1 Hz for drift)

        Returns the dfa block dict, or None if dfa_a1 stream is absent entirely
        (i.e. AlphaHRV did not record on this activity).

        When dfa_a1 IS present but data is insufficient to interpret (too short,
        too noisy), returns a block with quality.sufficient=False so the AI can
        distinguish "no AlphaHRV" (None → no dfa key in output) from "AlphaHRV
        ran but unusable" (block present, sufficient=False).

        Filtering rules (in order):
          1. Drop non-finite alpha1 and values < DFA_MIN_VALID_VALUE (sentinel zeros)
          2. Drop seconds where artifacts > DFA_ARTIFACT_MAX_PCT (5%, Altini convention)
        Both filters applied jointly to dfa_a1, hr, watts so they stay aligned.
        """
        dfa_stream = streams.get("dfa_a1")
        if not dfa_stream:
            return None  # no AlphaHRV recording on this activity

        # v3.122: unknown artifact samples stay None. Padding them with 0.0 reported a perfect
        # artifact rate for recordings carrying no artifact data at all, made the artifact
        # filter silently inert, and still passed quality.sufficient.
        raw_artifacts = streams.get("artifacts")
        hr_stream = streams.get("heartrate") or [None] * len(dfa_stream)
        watts_stream = streams.get("watts") or [None] * len(dfa_stream)

        # Align all streams to dfa_a1 length (defensive — should already match)
        n = len(dfa_stream)
        if not raw_artifacts:
            artifacts_stream = [None] * n
        elif len(raw_artifacts) != n:
            artifacts_stream = (list(raw_artifacts) + [None] * n)[:n]
        else:
            artifacts_stream = raw_artifacts
        if len(hr_stream) != n:
            hr_stream = (hr_stream + [None] * n)[:n]
        if len(watts_stream) != n:
            watts_stream = (watts_stream + [None] * n)[:n]

        # v3.122: normalise ONCE, post-alignment. "Observed" means a finite number (and, for
        # artifacts, non-negative); everything else becomes None. State, coverage, the average,
        # the sample filter and segment eligibility all consume these same lists, so they cannot
        # disagree about what observed means. _crossing_stats sums valid_hr / valid_watts and
        # rounds descriptive averages BEFORE eligibility runs, so a NaN would poison those sums
        # and a nonnumeric value would raise before the helper could fail closed. Finite-only
        # here; non-positive-HR and unknown-power rejection stays in the helper, so zero HR and
        # zero watts survive and TIZ, drift, valid_pct and sufficient are all unchanged.
        artifacts_stream = [
            a if (a is not None and a >= 0.0) else None
            for a in (self._finite_num(x) for x in artifacts_stream)
        ]
        hr_stream = [self._finite_num(x) for x in hr_stream]
        watts_stream = [self._finite_num(x) for x in watts_stream]
        # v3.140: NaN used to survive the minimum-value comparison and poison
        # rollups. Normalise alpha1 independently of the new drift mask.
        dfa_stream = [self._finite_num(x) for x in dfa_stream]

        # Apply filters
        # v3.113: valid_idx records each surviving sample's ORIGINAL stream index. The valid_*
        # arrays are compacted (dropped samples are skipped), so array-index adjacency != stream
        # adjacency. Crossing contiguity must be measured against valid_idx, not position.
        # NOTE (v3.122): stream index is a SAMPLE index, not an elapsed second - they coincide
        # only at 1 Hz with no pauses. Existing *_secs wire keys remain nominal
        # sample counts for compatibility; locals explicitly name samples.
        valid_dfa, valid_hr, valid_watts, valid_idx = [], [], [], []
        artifact_sum = 0.0
        artifact_count = 0
        for i in range(n):
            d = dfa_stream[i]
            a = artifacts_stream[i]
            if a is not None:
                artifact_sum += a
                artifact_count += 1
            if d is None or d < self.DFA_MIN_VALID_VALUE:
                continue
            if a is not None and a > self.DFA_ARTIFACT_MAX_PCT:
                continue
            valid_dfa.append(d)
            valid_hr.append(hr_stream[i])
            valid_watts.append(watts_stream[i])
            valid_idx.append(i)

        valid_samples = len(valid_dfa)
        total_samples = n
        valid_pct = round(100.0 * valid_samples / total_samples, 1) if total_samples else 0.0
        # v3.122: artifact_count is the OBSERVED (finite, non-negative) sample count, so it
        # doubles as coverage - a full-length stream containing nulls or NaN is partial, not
        # complete. sufficient is deliberately NOT gated on artifact coverage.
        # Drift additionally excludes unknown artifacts; TIZ retains the original mask.
        artifact_rate_avg = round(artifact_sum / artifact_count, 2) if artifact_count else None
        # Three decimals: at one decimal a near-complete stream (Jul 24: 10,802 of 10,806
        # observed = 99.962984%) serialises as 100.0 while artifact_state is partial, which
        # reads as a contradiction to any consumer. Not capped or floored - the value stays
        # true and the state stays authoritative.
        artifact_coverage_pct = round(100.0 * artifact_count / n, 3) if n else 0.0
        if artifact_count == 0:
            artifact_state = "absent"
        elif artifact_count == n:
            artifact_state = "complete"
        else:
            artifact_state = "partial"
        sufficient = (
            valid_samples >= self.DFA_MIN_DURATION_SECS
            and valid_pct >= self.DFA_SUFFICIENT_MIN_VALID_PCT
        )

        quality = {
            "valid_secs": valid_samples,
            "total_secs": total_samples,
            "valid_pct": valid_pct,
            "artifact_state": artifact_state,
            "artifact_coverage_pct": artifact_coverage_pct,
            "artifact_rate_avg": artifact_rate_avg,
            "sufficient": sufficient,
        }
        valid_mask = [False] * n
        for i in valid_idx:
            valid_mask[i] = True
        drift_mask = [valid_mask[i] and artifacts_stream[i] is not None for i in range(n)]
        quality["coverage_by_third"] = self._dfa_coverage_by_third(
            valid_mask, drift_mask, artifacts_stream)

        if not sufficient:
            _, drift_quality = self._compute_dfa_drift(
                dfa_stream, drift_mask, streams.get("time"), quality, None)
            # Emit minimal block — AI sees AlphaHRV ran but data unusable
            return {
                "avg": None,
                "p25": None, "p50": None, "p75": None,
                "tiz_easy": None,
                "tiz_endurance": None,
                "tiz_tempo": None,
                "tiz_supra": None,
                "drift": None,
                "drift_quality": drift_quality,
                "easy_guard_crossing": None,
                "lt1_crossing": None,
                "lt2_crossing": None,
                "quality": quality,
            }

        # Sufficient — full rollup
        sorted_dfa = sorted(valid_dfa)
        avg = round(sum(valid_dfa) / valid_samples, 3)
        p25 = round(sorted_dfa[valid_samples // 4], 3)
        p50 = round(sorted_dfa[valid_samples // 2], 3)
        p75 = round(sorted_dfa[(valid_samples * 3) // 4], 3)

        # 4-band TIZ with HR/power cross-references per band
        def _band_stats(predicate):
            secs = 0
            hr_sum, hr_n = 0, 0
            w_sum, w_n = 0, 0
            for i in range(valid_samples):
                if predicate(valid_dfa[i]):
                    secs += 1
                    if valid_hr[i] is not None:
                        hr_sum += valid_hr[i]
                        hr_n += 1
                    if valid_watts[i] is not None:
                        w_sum += valid_watts[i]
                        w_n += 1
            if secs == 0:
                return None
            return {
                "secs": secs,
                "pct": round(100.0 * secs / valid_samples, 1),
                "avg_hr": round(hr_sum / hr_n) if hr_n else None,
                "avg_watts": round(w_sum / w_n) if w_n else None,
            }

        # TIZ band boundaries: the four boundaries (1.0 / 0.75 / 0.5) are explicit. DFA_LT1 is
        # 0.75, so the 1.0 edge references DFA_EASY_GUARD to avoid collapsing the model. Band
        # VALUES are unchanged; band NAMES are marker-consistent (v3.115, easy renamed v3.118):
        # easy (a1>1.0 — the easy state above the easy_guard, NOT a session classification),
        # endurance (0.75-1.0, approaching LT1 from below; 0.75 is LT1), tempo (0.5-0.75), supra (a1<0.5).
        tiz_easy = _band_stats(lambda d: d > self.DFA_EASY_GUARD)
        tiz_endurance = _band_stats(lambda d: self.DFA_LT1 <= d <= self.DFA_EASY_GUARD)
        tiz_tempo = _band_stats(lambda d: self.DFA_LT2 <= d < self.DFA_LT1)
        tiz_supra = _band_stats(lambda d: d < self.DFA_LT2)

        drift, drift_quality = self._compute_dfa_drift(
            dfa_stream, drift_mask, streams.get("time"), quality,
            tiz_supra["pct"] if tiz_supra else 0.0)

        # LT1 / LT2 crossing-band estimates (the actually-coachable threshold candidates)
        def _crossing_stats(center, band):
            # v3.113 contiguous-dwell gate (see class constants). Build segments of in-band
            # samples, bridging <= DFA_CROSSING_MAX_GAP_SAMPLES of original stream index (dropped or
            # out-of-band seconds). Only segments reaching DFA_MIN_CROSSING_DWELL_SECS in-band
            # seconds qualify; HR/watts pool across qualifying segments only. This rejects the
            # warmup/cooldown/descent scatter that previously smeared threshold estimates.
            # Contiguity is measured on valid_idx (original ride-time), NOT array position,
            # because valid_* are compacted.
            lo, hi = center - band, center + band
            segments = []          # {count, hr_sum, hr_n, w_sum, w_n} per contiguous segment
            cur = None
            last_orig = None
            total_in_band = 0
            for i in range(valid_samples):
                if not (lo <= valid_dfa[i] <= hi):
                    continue
                total_in_band += 1
                orig = valid_idx[i]
                if cur is None or (orig - last_orig - 1) > self.DFA_CROSSING_MAX_GAP_SAMPLES:
                    cur = {"count": 0, "hr_sum": 0, "hr_n": 0, "w_sum": 0, "w_n": 0,
                           "start_sample_idx": orig, "end_sample_idx": orig}
                    segments.append(cur)
                cur["count"] += 1
                cur["end_sample_idx"] = orig
                if valid_hr[i] is not None:
                    cur["hr_sum"] += valid_hr[i]
                    cur["hr_n"] += 1
                if valid_watts[i] is not None:
                    cur["w_sum"] += valid_watts[i]
                    cur["w_n"] += 1
                last_orig = orig

            qualifying = [s for s in segments if s["count"] >= self.DFA_MIN_CROSSING_DWELL_SECS]
            best_segment_secs = max((s["count"] for s in segments), default=0)

            if total_in_band == 0:
                reason = "no_samples_in_band"
            elif total_in_band < self.DFA_MIN_CROSSING_DWELL_SECS:
                reason = "insufficient_total_dwell"
            elif not qualifying:
                reason = "no_contiguous_dwell"
            else:
                reason = "ok"

            if qualifying:
                hr_n = sum(s["hr_n"] for s in qualifying)
                w_n = sum(s["w_n"] for s in qualifying)
                avg_hr = round(sum(s["hr_sum"] for s in qualifying) / hr_n) if hr_n else None
                avg_watts = round(sum(s["w_sum"] for s in qualifying) / w_n) if w_n else None
            else:
                avg_hr = None
                avg_watts = None

            # v3.122 estimate eligibility. Every qualifying segment is judged independently
            # over itself PLUS the alphaHRV lookback that produced its a1 values; the marker is
            # eligible only when all of them pass. Dwell failure outranks eligibility failure.
            # Mixed segment failures resolve through ESTIMATE_REASON_PRIORITY, not by which
            # segment happened to come first in time. avg_hr/avg_watts stay descriptive here
            # even when ineligible - consumers read the flag, never infer from absence.
            seg_reasons = [
                self._segment_estimate_reason(s, artifacts_stream, hr_stream, watts_stream)
                for s in qualifying
            ]
            n_eligible = sum(1 for r in seg_reasons if r == "ok")
            failing = [r for r in seg_reasons if r != "ok"]
            if reason != "ok":
                estimate_eligible = False
                estimate_reason = reason
            elif not failing:
                estimate_eligible = True
                estimate_reason = "ok"
            else:
                estimate_eligible = False
                order = {r: i for i, r in enumerate(self.ESTIMATE_REASON_PRIORITY)}
                # Deterministic under an incomplete priority list: unknown reasons sort last,
                # then alphabetically. Never falls back to segment order in time.
                estimate_reason = min(failing, key=lambda r: (order.get(r, len(order)), r))

            return {
                "marker_dfa_a1": center,
                "secs_in_band": total_in_band,
                "contiguous_secs": best_segment_secs,
                "n_qualifying_segments": len(qualifying),
                "n_eligible_segments": n_eligible,
                "reason": reason,
                "estimate_eligible": estimate_eligible,
                "estimate_reason": estimate_reason,
                "avg_hr": avg_hr,
                "avg_watts": avg_watts,
            }

        easy_guard_crossing = _crossing_stats(self.DFA_EASY_GUARD, self.DFA_EASY_GUARD_BAND)
        lt1_crossing = _crossing_stats(self.DFA_LT1, self.DFA_LT1_BAND)
        lt2_crossing = _crossing_stats(self.DFA_LT2, self.DFA_LT2_BAND)

        return {
            "avg": avg,
            "p25": p25, "p50": p50, "p75": p75,
            "tiz_easy": tiz_easy,
            "tiz_endurance": tiz_endurance,
            "tiz_tempo": tiz_tempo,
            "tiz_supra": tiz_supra,
            "drift": drift,
            "drift_quality": drift_quality,
            "easy_guard_crossing": easy_guard_crossing,
            "lt1_crossing": lt1_crossing,
            "lt2_crossing": lt2_crossing,
            "quality": quality,
        }

    @staticmethod
    def _finite_num(v) -> Optional[float]:
        """Finite numeric value, else None. Rejects bool, non-numeric types, NaN and inf."""
        if isinstance(v, bool) or not isinstance(v, (int, float)):
            return None
        f = float(v)
        return f if math.isfinite(f) else None

    def _segment_estimate_reason(self, seg, artifacts_stream, hr_stream, watts_stream) -> str:
        """
        Judge one dwell-qualified crossing segment for threshold-estimate eligibility (v3.122).

        alphaHRV publishes a1 from the prior DFA_LOOKBACK_BEATS beats, so the window's
        DURATION varies with HR and can never be a fixed sample count. The segment's a1 values
        were produced by that lookback, so the lookback is evaluated with the segment.

        Fails closed throughout: unknown OR excessive artifact, invalid HR, invalid power, an
        unresolvable lookback, or non-stationary power all make the segment ineligible. Zero
        watts are VALID and included - coasting inside the a1-producing window is itself
        non-stationary load, and dropping it would hide the contamination.

        Failure classes are checked over the complete span in a fixed order, so the emitted
        reason never depends on which bad sample appears first.

        Streams are the v3.122 finite-normalised lists from _compute_dfa_block.
        """
        start = seg["start_sample_idx"]
        end = seg["end_sample_idx"]

        # 1. Resolve the lookback; it defines the span. Walk back from immediately before the
        #    segment. A hole fails rather than being skipped to reach earlier beats.
        beats = 0.0
        i = start - 1
        while i >= 0 and beats < self.DFA_LOOKBACK_BEATS:
            hr = hr_stream[i]
            if hr is None or hr <= 0:
                return "lookback_gap"
            beats += hr / 60.0
            i -= 1
        if beats < self.DFA_LOOKBACK_BEATS:
            return "lookback_incomplete"
        span = range(i + 1, end + 1)

        # 2. Whole-span coverage, fixed order. Bridged gaps inside the segment are part of the
        #    span: an excessive-artifact sample there contaminates the a1 values regardless of
        #    having been dropped from valid_dfa.
        arts = [artifacts_stream[j] for j in span]
        if any(a is None for a in arts):
            return "unknown_artifact"
        if any(a > self.DFA_ARTIFACT_MAX_PCT for a in arts):
            return "excessive_artifact"
        hrs = [hr_stream[j] for j in span]
        if any(h is None or h <= 0 for h in hrs):
            return "unknown_hr"
        watts = [watts_stream[j] for j in span]
        if any(w is None for w in watts):
            return "unknown_power"

        # 3. Stationarity, per the characterised formula.
        mean = sum(watts) / len(watts)
        if mean <= 0:
            return "non_positive_power_mean"
        if 100.0 * statistics.pstdev(watts) / mean > self.DFA_CROSSING_MAX_POWER_CV_PCT:
            return "non_stationary_power"
        return "ok"

    def _build_dfa_summary(self, dfa_block: Dict, schema_version: Optional[int] = 2) -> Dict:
        """
        Build the compact dfa_summary attached to recent_activities[] in latest.json (v3.100).

        Near-pure extractor — every number comes from _compute_dfa_block output; the only
        derived field is dominant_band, which selects a band (no arithmetic). v3.118: that
        selection reads raw band secs, not the rounded pct, and breaks exact ties by
        descending intensity rather than alphabetically — see the comment on the rule below.
        Caller must only invoke this when dfa_block["quality"]["sufficient"] is True;
        the sufficient=False branch of _compute_dfa_block returns all-None tiz_* fields
        and is not summarisable. Per-band None (zero time in band) is handled here as
        0.0 pct / 0 secs.
        Optional fields are omitted (not nulled) when their underlying data is absent.
        The default schema is for freshly computed blocks. Cached activity callers
        pass the enclosing schema explicitly so unsupported versions fail closed.
        """
        def _band_pct(name):
            b = dfa_block.get(name)
            return b["pct"] if b else 0.0

        def _band_secs(name):
            b = dfa_block.get(name)
            return b["secs"] if b else 0

        bands = {
            "easy": _band_pct("tiz_easy"),
            "endurance": _band_pct("tiz_endurance"),
            "tempo": _band_pct("tiz_tempo"),
            "supra": _band_pct("tiz_supra"),
        }
        # Dominant band (v3.118): most RAW SECONDS in band. Raw secs, not the one-decimal
        # `pct`, so rounding can no longer manufacture a tie. A genuine exact-second tie
        # resolves by descending intensity — the order of _DOMINANT_ORDER below — which is
        # conservative: a true tie never understates internal load. Band key NAMES cannot
        # influence the outcome; the pre-3.118 rule (max rounded pct, alphabetical key
        # tiebreak) could be moved by a rename, which is why it was replaced alongside one.
        _DOMINANT_ORDER = (("supra", "tiz_supra"), ("tempo", "tiz_tempo"),
                           ("endurance", "tiz_endurance"), ("easy", "tiz_easy"))
        dominant_band = sorted(
            _DOMINANT_ORDER,
            key=lambda b: (-_band_secs(b[1]), _DOMINANT_ORDER.index(b)),
        )[0][0]

        summary = {
            "avg": dfa_block["avg"],
            "dominant_band": dominant_band,
            "tiz_pct": bands,
            "valid_pct": dfa_block["quality"]["valid_pct"],
            "sufficient": dfa_block["quality"]["sufficient"],
            "drift_quality": dfa_block.get("drift_quality"),
            "quality": self._dfa_quality_summary(dfa_block),
        }

        drift = dfa_block.get("drift")
        if drift is not None and drift.get("delta") is not None:
            summary["drift_delta"] = drift["delta"]
            summary["drift_interpretable"] = schema_version == 2 and self._dfa_drift_eligible(dfa_block)

        # v3.122: the compact summary is the AI-facing surface, so it carries threshold
        # numbers only when the crossing is estimate-eligible. The detailed crossing block
        # retains avg_hr/avg_watts as descriptive evidence with estimate_eligible: false.
        lt1 = dfa_block.get("lt1_crossing") or {}
        if lt1.get("estimate_eligible"):
            if lt1.get("avg_watts") is not None:
                summary["lt1_watts"] = lt1["avg_watts"]
            if lt1.get("avg_hr") is not None:
                summary["lt1_hr"] = lt1["avg_hr"]

        lt2 = dfa_block.get("lt2_crossing") or {}
        if lt2.get("estimate_eligible"):
            if lt2.get("avg_watts") is not None:
                summary["lt2_watts"] = lt2["avg_watts"]
            if lt2.get("avg_hr") is not None:
                summary["lt2_hr"] = lt2["avg_hr"]

        return summary

    
    def _parse_retry_after(self, value) -> Optional[int]:
        """
        Parse an HTTP Retry-After header. Accepts both documented forms:
        delta-seconds ("120") and HTTP-date ("Wed, 21 Oct 2026 07:28:00 GMT").
        Returns non-negative seconds, or None when absent/unparseable.
        """
        if value is None:
            return None
        raw = str(value).strip()
        if not raw:
            return None
        try:
            secs = int(raw)
            return secs if secs >= 0 else None
        except ValueError:
            pass
        try:
            from email.utils import parsedate_to_datetime
            dt = parsedate_to_datetime(raw)
            if dt is None:
                return None
            ref = datetime.now(dt.tzinfo) if dt.tzinfo is not None else datetime.now()
            delta = (dt - ref).total_seconds()
            return int(delta) if delta > 0 else 0
        except Exception:
            return None

    def _activity_start_dt(self, act: Dict) -> datetime:
        """Local start datetime for an activity; falls back to now on unparseable input."""
        raw = (act.get("start_date_local") or "")
        for cut, fmt in ((19, "%Y-%m-%dT%H:%M:%S"), (10, "%Y-%m-%d")):
            try:
                return datetime.strptime(raw[:cut], fmt)
            except (ValueError, TypeError):
                continue
        return datetime.now()

    def _build_pairing_map(self, events: Optional[List[Dict]],
                           activities: List[Dict]) -> set:
        """
        Activity IDs (as strings) EXACTLY paired to a planned event that carries a
        non-empty workout_doc.steps. Strict ID join in both documented directions —
        activity.paired_event_id <-> event.id and event.paired_activity_id <->
        activity.id. Never date+sport: a wrong match would extend the retry window
        for the wrong activity.

        Used ONLY to extend the interval retry window. It never gates emission and
        never classifies structure — the classifier remains out of scope.
        """
        paired = set()
        event_has_steps = {}
        for evt in (events or []):
            doc = evt.get("workout_doc")
            has_steps = bool(isinstance(doc, dict) and doc.get("steps"))
            eid = evt.get("id")
            if eid is not None:
                event_has_steps[str(eid)] = has_steps
            aid = evt.get("paired_activity_id")
            if has_steps and aid is not None:
                paired.add(str(aid))
        for act in activities:
            eid = act.get("paired_event_id")
            if eid is not None and event_has_steps.get(str(eid)):
                paired.add(str(act.get("id")))
        return paired

    def _schedule_retry(self, endpoint: str, attempts: int, paired_planned: bool,
                        activity_start: datetime, now: datetime,
                        retry_after_secs: Optional[int] = None) -> Optional[str]:
        """
        Next retry timestamp for a pending endpoint, or None when the window has
        closed (caller writes a retry_expired tombstone).

        The deadline derives from activity_start, NOT from first_seen: a first-run
        backfill of a week-old activity must not open a fresh 72h window. Only
        intervals on an exactly-paired planned workout get the extended daily tier.
        """
        extended = (endpoint == "intervals" and paired_planned)
        if extended:
            deadline = activity_start + timedelta(days=self.INTERVAL_PAIRED_RETRY_DAYS)
        else:
            deadline = activity_start + timedelta(hours=self.INTERVAL_RETRY_WINDOW_HOURS)
        if now >= deadline:
            return None

        delay = self.INTERVAL_RETRY_LADDER[-1][1]
        for through, secs in self.INTERVAL_RETRY_LADDER:
            if through is None or attempts <= through:
                delay = secs
                break
        # Past the 72h ladder an extended (paired) endpoint drops to daily.
        ladder_end = activity_start + timedelta(hours=self.INTERVAL_RETRY_WINDOW_HOURS)
        if extended and now >= ladder_end:
            delay = max(delay, self.INTERVAL_PAIRED_RETRY_DELAY_SECS)
        if retry_after_secs is not None:
            delay = max(delay, int(retry_after_secs))

        nxt = now + timedelta(seconds=delay)
        if nxt >= deadline:
            return None
        return nxt.isoformat()

    def _schedule_refresh(self, attempts: int, now: datetime,
                          retry_after_secs: Optional[int] = None) -> str:
        """
        Next attempt timestamp for an outstanding interval refresh.

        Distinct from _schedule_retry: the clock is the refresh attempt, never
        activity_start. An edit lands days after the ride, so an activity_start
        deadline would expire the refresh before its first retry and tombstone an
        endpoint whose cached payload is still good. There is no deadline here —
        past the fast ladder a due refresh continues at the maximum delay until
        retention pruning removes the activity, so an outage self-heals without
        polling every sync.
        """
        delay = self.INTERVAL_RETRY_LADDER[-1][1]
        for through, secs in self.INTERVAL_RETRY_LADDER:
            if through is None or attempts <= through:
                delay = secs
                break
        if retry_after_secs is not None:
            delay = max(delay, int(retry_after_secs))
        return (now + timedelta(seconds=delay)).isoformat()

    def _advance_endpoint_state(self, prev: Optional[Dict], endpoint: str, outcome: str,
                                reason: str, now: datetime, activity_start: datetime,
                                paired_planned: bool,
                                retry_after_secs: Optional[int] = None) -> Dict:
        """
        One endpoint's state transition. outcome is "ok" | "tombstone" | "pending".
        A pending outcome whose retry window has closed becomes a retry_expired
        tombstone here, so expiry is decided in exactly one place.
        """
        attempts = int((prev or {}).get("attempts", 0)) + 1
        state = {
            "attempts": attempts,
            "first_seen": (prev or {}).get("first_seen") or now.isoformat(),
            "last_attempt": now.isoformat(),
        }
        if outcome == "ok":
            state["status"] = "ok"
            state["reason"] = "ok"
            return state
        if outcome == "tombstone":
            state["status"] = "tombstone"
            state["reason"] = reason
            return state
        nxt = self._schedule_retry(endpoint, attempts, paired_planned,
                                   activity_start, now, retry_after_secs)
        if nxt is None:
            state["status"] = "tombstone"
            state["reason"] = "retry_expired"
        else:
            state["status"] = "pending"
            state["reason"] = reason
            state["next_retry_at"] = nxt
        return state

    def _format_interval_segments(self, raw_intervals: List[Dict], act: Dict) -> tuple:
        """
        Map raw icu_intervals to Section 11 segments and resolve activity-level
        zone_basis. Returns (segments, zone_basis) where zone_basis may be None.
        Extracted from _generate_intervals in v3.121 — logic unchanged from v3.120.
        """
        segments = []
        for iv in raw_intervals:
            segment = {
                "type": iv.get("type"),
                "label": iv.get("group_id"),
                "duration_secs": iv.get("elapsed_time"),
                "moving_secs": iv.get("moving_time"),
                "start_secs": iv.get("start_time"),
                "end_secs": iv.get("end_time"),
                "avg_power": iv.get("average_watts"),
                "max_power": iv.get("max_watts"),
                "avg_hr": iv.get("average_heartrate"),
                "max_hr": iv.get("max_heartrate"),
                "min_hr": iv.get("min_heartrate"),
                "avg_cadence": iv.get("average_cadence"),
                "zone": iv.get("zone"),
                "w_bal_start": iv.get("wbal_start"),
                "w_bal_end": iv.get("wbal_end"),
                "training_load": iv.get("training_load"),
            }
            segments.append({k: v for k, v in segment.items() if v is not None})

        has_zone = any(iv.get("zone") is not None for iv in raw_intervals)
        has_power_bounds = any(
            iv.get("zone_min_watts") is not None or iv.get("zone_max_watts") is not None
            for iv in raw_intervals
        )
        has_hr_zones = bool(act.get("icu_hr_zone_times"))
        has_pace_zones = bool(act.get("pace_zone_times")) or bool(act.get("gap_zone_times"))

        zone_basis = None
        if has_zone:
            if has_power_bounds:
                zone_basis = "power"
            elif has_hr_zones and not has_pace_zones:
                zone_basis = "hr"
            elif has_pace_zones and not has_hr_zones:
                zone_basis = "pace"
        return segments, zone_basis

    def _generate_intervals(self, activities: List[Dict], present_activity_ids: set = None,
                            events: List[Dict] = None) -> set:
        """
        Generate intervals.json with incremental caching and per-endpoint retry state.

        First run (no cache): scans full retention window (14 days) to backfill.
        Subsequent runs: scans recent activities (72h) for NEW sessions, and
        independently re-attempts any activity carrying pending fetch state whose
        next_retry_at has come due — that retry path deliberately ignores the 72h
        scan window, because upstream interval analysis can complete days after
        upload and was otherwise unrecoverable.

        v3.113: callers pass the 28d extended activity set as `activities` so the
        first-run backfill genuinely reaches the full 14d retention window.
        `present_activity_ids` prunes entries AND fetch_state whose activity no
        longer exists.

        v3.121 fetch_state (root-level, internal — NOT part of the activities[]
        consumer contract): per activity, per endpoint (`intervals`, `streams`),
        one of status ok / pending / tombstone. The two endpoints advance
        independently, so a stream failure no longer discards a successful interval
        fetch, and a retry that succeeds replaces only its own sibling payload.
        Streams count as `ok` only when a usable dfa_a1 block was computed: an HTTP
        200 carrying only heartrate/watts is `pending`/`no_data`, and a computation
        failure is `pending`/`compute_error` — absence and failure stay distinct.

        `events` (v3.121) is used only to build the exact planned-workout pairing
        map that extends the interval retry window. It never gates emission.

        Returns set of activity IDs that have interval data (for has_intervals flag).
        """
        now = datetime.now()
        now_iso = now.isoformat()
        retention_cutoff = (now - timedelta(days=self.INTERVAL_RETENTION_DAYS)).strftime("%Y-%m-%d")

        # Load existing cache
        intervals_path = self.data_dir / self.INTERVALS_FILE
        cached = {"activities": [], "fetch_state": {}}
        first_run = not intervals_path.exists()
        if not first_run:
            try:
                with open(intervals_path, 'r') as f:
                    cached = json.load(f)
                # Invalidate cache if sync.py changed. fetch_state is wiped with it:
                # a schema change can alter what a completed fetch even means.
                if cached.get("script_hash") != self.script_hash:
                    if self.debug:
                        print(f"    🔄 intervals.json stale (sync.py changed), re-scanning all")
                    cached = {"activities": [], "fetch_state": {}}
                    first_run = True
            except Exception as e:
                if self.debug:
                    print(f"    ⚠️  Could not read intervals.json: {e}")
                cached = {"activities": [], "fetch_state": {}}
                first_run = True

        # All fetch_state keys are strings; activity ids arrive as both int and str
        # from different endpoints, so normalize on load rather than at every lookup.
        fetch_state = {}
        for k, v in (cached.get("fetch_state") or {}).items():
            if isinstance(v, dict):
                fetch_state[str(k)] = v

        # First run: backfill full retention window (14 days). Subsequent: scan 72h only.
        if first_run:
            scan_cutoff = retention_cutoff
            print("    First run — scanning 14 days for interval data...")
        else:
            scan_cutoff = (now - timedelta(hours=self.INTERVAL_SCAN_HOURS)).strftime("%Y-%m-%d")

        cached_ids = {str(a.get("activity_id")) for a in cached.get("activities", [])
                      if a.get("intervals") or a.get("dfa")}
        paired_ids = self._build_pairing_map(events, activities)

        # Candidate selection. Two independent arms:
        #   NEW   — no fetch_state record at all; the 72h scan window applies.
        #   RETRY — pending endpoint(s) now due; the scan window does NOT apply,
        #           only retention. Only the due endpoints are fetched; a sibling
        #           that is ok, tombstoned, or not yet due is left untouched.
        candidates = []
        for act in activities:
            date_str = act.get("start_date_local", "")[:10]
            if date_str < retention_cutoff:
                continue
            family = self.SPORT_FAMILIES.get(act.get("type", ""))
            if family not in self.INTERVAL_SPORT_FAMILIES:
                continue
            act_id = str(act.get("id"))
            state = fetch_state.get(act_id)
            if state is None:
                if date_str < scan_cutoff or act_id in cached_ids:
                    continue
                candidates.append((act, {"intervals": True, "streams": True}, False))
                continue
            due = {}
            for endpoint in ("intervals", "streams"):
                ep_state = state.get(endpoint) or {}
                if ep_state.get("status") != "pending":
                    continue
                nxt = ep_state.get("next_retry_at")
                if nxt is None or str(nxt) <= now_iso:
                    due[endpoint] = True
            # REFRESH — a completed interval fetch is only settled until the athlete
            # edits the activity. icu_sync_date is observed to advance on controlled
            # repeated edits, so it serves as the invalidation token; icu_intervals_edited
            # gates the check to activities that carry custom intervals at all. Scan
            # window does not apply (an edit arrives long after the ride); retention and
            # present_activity_ids still do, both already applied above. Intervals only —
            # stream availability is a property of the recording, which editing cannot
            # change.
            refresh = False
            ep_state = state.get("intervals") or {}
            if ep_state.get("status") == "ok" and act.get("icu_intervals_edited") is True:
                token = act.get("icu_sync_date")
                # Absent token: no basis for comparison, and re-fetching on absence
                # would loop forever. Fail closed to current behaviour.
                if token and token != ep_state.get("source_icu_sync_date"):
                    ref = ep_state.get("refresh") or {}
                    if ref.get("target_sync_date") != token:
                        refresh = True          # new token supersedes any prior chase
                    elif ref.get("status") != "exhausted":
                        nxt = ref.get("next_retry_at")
                        if nxt is None or str(nxt) <= now_iso:
                            refresh = True
                    if refresh:
                        due["intervals"] = True
            if due:
                candidates.append((act, due, refresh))

        # Fetch due endpoints. Payload updates are collected per activity and applied
        # sibling-by-sibling during the merge — never as a whole-record replacement.
        updates = {}
        fetched_any = 0
        for act, due, refresh in candidates:
            act_id = str(act.get("id"))
            act_start = self._activity_start_dt(act)
            paired = act_id in paired_ids
            state = fetch_state.setdefault(act_id, {})
            state["date"] = act.get("start_date_local", "")[:10]
            if paired:
                state["paired_planned"] = True
            else:
                state.pop("paired_planned", None)

            print(f"    Fetching {'+'.join(sorted(due))} for {act.get('name', act_id)}...")
            upd = updates.setdefault(act_id, {"act": act})

            if due.get("intervals"):
                status, payload = self._fetch_activity_intervals(act_id)
                retry_after = self._last_retry_after_secs
                token = act.get("icu_sync_date")
                if status == "deferred":
                    pass
                elif status == "ok":
                    segments, zone_basis = self._format_interval_segments(payload, act)
                    upd["intervals"] = segments
                    upd["zone_basis"] = zone_basis
                    state["intervals"] = self._advance_endpoint_state(
                        state.get("intervals"), "intervals", "ok", "ok",
                        now, act_start, paired)
                    # _advance_endpoint_state rebuilds the dict from a fixed key set, so
                    # the token is written here rather than carried through it. Dropping
                    # `refresh` on success is the intended effect of that rebuild.
                    if token:
                        state["intervals"]["source_icu_sync_date"] = token
                    fetched_any += 1
                elif refresh:
                    # A failed refresh must not cost the cached payload. Endpoint status,
                    # attempts, first_seen and the last successful token are all left
                    # standing; only the refresh sub-object advances. A terminal 404/410
                    # exhausts this target alone — a later, different token re-arms it.
                    ep = state.get("intervals") or {}
                    prev_ref = ep.get("refresh") or {}
                    attempts = (int(prev_ref.get("attempts", 0)) + 1
                                if prev_ref.get("target_sync_date") == token else 1)
                    ref = {"target_sync_date": token, "attempts": attempts}
                    if status == "terminal_error":
                        ref["status"] = "exhausted"
                        ref["reason"] = "terminal_error"
                    else:
                        ref["reason"] = "no_data" if status == "no_data" else "transient"
                        ref["next_retry_at"] = self._schedule_refresh(
                            attempts, now, retry_after)
                    ep["refresh"] = ref
                    # An endpoint request did occur. status, reason, attempts, first_seen
                    # and source_icu_sync_date stay put; retry counting lives in refresh.
                    ep["last_attempt"] = now.isoformat()
                    state["intervals"] = ep
                    if self.debug:
                        print(f"    ⚠️  interval refresh {ref['reason']} for {act_id} "
                              f"(cached payload retained)")
                elif status == "terminal_error":
                    state["intervals"] = self._advance_endpoint_state(
                        state.get("intervals"), "intervals", "tombstone", "terminal_error",
                        now, act_start, paired)
                else:
                    # no_data (200, analysis not ready) is retryable, exactly like a
                    # transient failure — it is the shape late analysis actually takes.
                    reason = "no_data" if status == "no_data" else "transient"
                    state["intervals"] = self._advance_endpoint_state(
                        state.get("intervals"), "intervals", "pending", reason,
                        now, act_start, paired, retry_after)
                    if self.debug:
                        print(f"    ⚠️  intervals {reason} for {act_id} "
                              f"(status={state['intervals']['status']})")

            if due.get("streams"):
                status, payload = self._fetch_activity_streams(
                    act_id, ["dfa_a1", "artifacts", "heartrate", "watts", "time"])
                retry_after = self._last_retry_after_secs
                if status == "deferred":
                    pass
                elif status == "terminal_error":
                    state["streams"] = self._advance_endpoint_state(
                        state.get("streams"), "streams", "tombstone", "terminal_error",
                        now, act_start, paired)
                elif status == "transient":
                    state["streams"] = self._advance_endpoint_state(
                        state.get("streams"), "streams", "pending", "transient",
                        now, act_start, paired, retry_after)
                elif status == "no_data" or not payload.get("dfa_a1"):
                    # An HTTP 200 carrying only heartrate/watts is NOT success for this
                    # pipeline — the streams fetcher returns ok when ANY requested
                    # stream exists, so only a usable dfa_a1 counts.
                    state["streams"] = self._advance_endpoint_state(
                        state.get("streams"), "streams", "pending", "no_data",
                        now, act_start, paired)
                else:
                    try:
                        dfa_block = self._compute_dfa_block(payload)
                    except Exception as e:
                        if self.debug:
                            print(f"    ⚠️  DFA a1 computation failed for {act_id}: {e}")
                        state["streams"] = self._advance_endpoint_state(
                            state.get("streams"), "streams", "pending", "compute_error",
                            now, act_start, paired)
                    else:
                        if dfa_block is None:
                            state["streams"] = self._advance_endpoint_state(
                                state.get("streams"), "streams", "pending", "no_data",
                                now, act_start, paired)
                        else:
                            upd["dfa"] = dfa_block
                            state["streams"] = self._advance_endpoint_state(
                                state.get("streams"), "streams", "ok", "ok",
                                now, act_start, paired)
                            fetched_any += 1

        if fetched_any:
            print(f"    ✅ {fetched_any} endpoint payload{'s' if fetched_any != 1 else ''} fetched")

        # Merge. Retain cached entries within retention that still exist upstream,
        # then apply per-sibling updates keyed by activity_id — newest wins for the
        # sibling that was refetched, and only for that sibling.
        by_id = {}
        dropped = 0
        for entry in cached.get("activities", []):
            if entry.get("date", "") < retention_cutoff:
                continue
            eid = str(entry.get("activity_id"))
            if present_activity_ids is not None and eid not in present_activity_ids:
                dropped += 1
                continue
            by_id[eid] = entry
        if dropped and self.debug:
            print(f"    🧹 Pruned {dropped} stale cached interval/DFA entr"
                  f"{'y' if dropped == 1 else 'ies'} (activity no longer present)")

        for act_id, upd in updates.items():
            act = upd["act"]
            entry = by_id.get(act_id)
            if entry is None:
                entry = {
                    "activity_id": act.get("id"),
                    "date": act.get("start_date_local", "")[:10],
                    "start_datetime": act.get("start_date_local", ""),
                    "type": act.get("type", "Unknown"),
                    "name": act.get("name", ""),
                    "interval_summary": act.get("interval_summary"),
                    "intervals": [],
                }
                by_id[act_id] = entry
            if "intervals" in upd:
                entry["intervals"] = upd["intervals"]
                entry["interval_summary"] = act.get("interval_summary")
                if upd.get("zone_basis") is not None:
                    entry["zone_basis"] = upd["zone_basis"]
                else:
                    # A replacement payload that no longer resolves a basis must not
                    # leave the previous one standing.
                    entry.pop("zone_basis", None)
            if "dfa" in upd:
                entry["dfa"] = upd["dfa"]

        # Structure is an independent payload; retain it without fabricating
        # interval or DFA availability. Empty entries still rely on fetch_state.
        all_entries = [e for e in by_id.values()
                       if e.get("intervals") or e.get("dfa") or e.get("session_structure")]

        # Prune fetch_state on the same two axes as the entries.
        pruned_state = {}
        for act_id, state in fetch_state.items():
            if state.get("date", "") < retention_cutoff:
                continue
            if present_activity_ids is not None and act_id not in present_activity_ids:
                continue
            pruned_state[act_id] = state

        # Terminal endpoint tombstones are settled even without a payload row.
        for aid, state in pruned_state.items():
            for endpoint, group in (("intervals", "activity_details"), ("streams", "activity_streams")):
                ep = state.get(endpoint, {})
                refresh = ep.get("refresh") or {}
                if ((ep.get("status") == "tombstone" and ep.get("reason") == "terminal_error")
                        or (ep.get("status") == "ok" and refresh.get("status") == "exhausted"
                            and refresh.get("reason") == "terminal_error")):
                    self._adopt_native_cache(group, aid, True, "resource_gone")

        # Build intervals.json
        # Only settled, retained payloads qualify. Pending refreshes and newly
        # fetched payloads keep their real observation or existing failure state.
        for entry in all_entries:
            aid = str(entry.get("activity_id"))
            state = pruned_state.get(aid, {})
            for endpoint, group, payload in (("intervals", "activity_details", entry.get("intervals")),
                                             ("streams", "activity_streams", entry.get("dfa"))):
                ep = state.get(endpoint, {})
                if not payload or endpoint in updates.get(aid, {}) or (endpoint == "streams" and "dfa" in updates.get(aid, {})):
                    continue
                if ep.get("status", "ok") != "ok" or ep.get("refresh"):
                    continue
                valid = (isinstance(payload, list) and all(isinstance(v, dict) for v in payload)
                         if endpoint == "intervals" else isinstance(payload, dict)
                         and isinstance(payload.get("quality"), dict)
                         and type(payload.get("quality", {}).get("sufficient")) is bool)
                self._adopt_native_cache(group, aid, valid)
        self._intervals_data = {
            "generated_at": now_iso,
            "interval_data_note": self.INTERVAL_DATA_NOTE,
            "schema_version": 2,
            "version": self.VERSION,
            "script_hash": self.script_hash,
            "scan_hours": self.INTERVAL_SCAN_HOURS,
            "retention_days": self.INTERVAL_RETENTION_DAYS,
            "activities": all_entries,
            "fetch_state": pruned_state,
        }

        # Return all activity IDs that have interval data
        return {a["activity_id"] for a in all_entries if a.get("intervals") or a.get("dfa")}
    
    # ── Route & Terrain Intelligence (v3.93) ─────────────────────────────
    
    # ==================== SAVED WORKOUTS MIRROR (v3.132) ====================
    # A read-only mirror of the user's saved workouts from Intervals.icu.
    #
    # Intervals.icu exposes no change-detection mechanism on the library endpoints:
    # no ETag, no Last-Modified, no "changed since" filter, and Folder objects carry
    # no timestamp at all. Change detection therefore compares a content digest of a
    # full snapshot; the upstream `updated` field is mirrored for the reader but is
    # never an input to any freshness or skip decision.

    def _sw_now(self) -> datetime:
        """Timezone-aware UTC now. The mirror is the only output using aware timestamps."""
        return datetime.now(timezone.utc)

    @staticmethod
    def _sw_iso(dt: datetime) -> str:
        return dt.isoformat()

    @staticmethod
    def _sw_sort_key(value):
        """
        Total order over ids. Integers (and integer-valued strings) sort numerically
        and ahead of everything else; anything else sorts by string. Never raises on
        a mixed-type collection.
        """
        if isinstance(value, bool):
            return (1, str(value))
        if isinstance(value, int):
            return (0, value, "")
        try:
            return (0, int(str(value).strip()), "")
        except (TypeError, ValueError):
            return (1, 0, str(value))

    @staticmethod
    def _sw_canonical_id(value):
        """
        Strict canonical id, or SW_ID_INVALID.

        One helper serves endpoint validation, cache validation and reconciliation, so
        the collision rule and the dictionary key are the same value. Accepts only a
        non-boolean int, or a string that normalizes to an int or a non-empty string.
        Booleans, floats, None, lists and dicts are invalid: a float would collide with
        an int under equality, a bool hashes equal to 0/1, and an unhashable value
        cannot key reconciliation at all.
        """
        if isinstance(value, bool) or value is None:
            return IntervalsSync.SW_ID_INVALID
        if isinstance(value, int):
            return value
        if isinstance(value, str):
            text = value.strip()
            if not text:
                return IntervalsSync.SW_ID_INVALID
            try:
                return int(text)
            except ValueError:
                return text
        return IntervalsSync.SW_ID_INVALID

    @staticmethod
    def _sw_canonical_ref(value):
        """Canonical id for an optional reference (a workout's folder_id). None is valid."""
        if value is None:
            return None
        return IntervalsSync._sw_canonical_id(value)

    @classmethod
    def _sw_id_ok(cls, value) -> bool:
        return cls._sw_canonical_id(value) is not cls.SW_ID_INVALID

    @classmethod
    def _sw_ref_ok(cls, value) -> bool:
        return value is None or cls._sw_id_ok(value)

    def _sw_digest(self, folders: List[Dict], workouts: List[Dict]) -> str:
        """
        Content digest over the reconciled snapshot only — mirror metadata excluded.
        Object keys are sorted for the digest; array order is preserved everywhere,
        so workout_doc step order participates in the digest exactly as ordered.
        """
        payload = json.dumps({"folders": folders, "workouts": workouts},
                             sort_keys=True, separators=(",", ":"),
                             ensure_ascii=False, default=str)
        return "sha256:" + hashlib.sha256(payload.encode("utf-8")).hexdigest()

    def _sw_backoff_secs(self, attempts: int, retry_after_secs: Optional[int] = None) -> int:
        """Failure backoff, same shape as _schedule_refresh: no deadline, self-heals."""
        delay = self.SAVED_WORKOUTS_RETRY_LADDER[-1][1]
        for through, secs in self.SAVED_WORKOUTS_RETRY_LADDER:
            if through is None or attempts <= through:
                delay = secs
                break
        if retry_after_secs is not None:
            delay = max(delay, int(retry_after_secs))
        return delay

    def _sw_normalize_set_like(self, value):
        """
        Deterministic normalization for set-like fields. Applied identically to output
        and to endpoint comparison, so an order-only difference in tags or targets is
        not a disagreement. Never applied inside workout_doc, where order is semantic.
        """
        if isinstance(value, list):
            return sorted(value, key=self._sw_sort_key)
        return value

    def _sw_fields_differ(self, primary: Dict, child: Dict) -> bool:
        """True when any mirrored field disagrees between the two endpoints."""
        for key in self.SAVED_WORKOUTS_WORKOUT_FIELDS:
            a, b = primary.get(key), child.get(key)
            if key in self.SAVED_WORKOUTS_SET_LIKE_FIELDS:
                a, b = self._sw_normalize_set_like(a), self._sw_normalize_set_like(b)
            if a != b:
                return True
        for key in ("updated", "workout_doc"):
            if primary.get(key) != child.get(key):
                return True
        if self._sw_canonical_ref(primary.get("folder_id")) != self._sw_canonical_ref(child.get("folder_id")):
            return True
        return False

    def _sw_reconcile(self, folders_raw: List[Dict], workouts_raw: List[Dict]) -> Tuple[List[Dict], List[Dict], int, List]:
        """
        Build the output snapshot from one canonical membership model.

        /workouts is the primary source of workout objects; /folders supplies folder
        metadata and is the fallback source for a workout /workouts omits. Canonical
        membership is the /workouts object's own folder_id, or — for a folder-child-only
        fallback — the containing folder. folder_id, folder_name, folder.workout_ids and
        folder.num_workouts are all derived from that single value, so they can never
        contradict one another even when the endpoints disagree. Raw children are used
        only for comparison and fallback, never as a competing output relationship.

        Returns (folders, workouts, findings, flagged_workout_ids). findings counts every
        disagreement, workout-level and folder-level; flagged ids are workout ids only.

        Every id reaching this method has already passed _sw_validate_payloads, so it is
        a hashable canonical id and no collision is possible.
        """
        findings = 0
        flagged = []

        def flag(wid):
            nonlocal findings
            findings += 1
            if wid is not None and wid not in flagged:
                flagged.append(wid)

        folder_meta = {}
        folder_children = {}
        for f in (folders_raw or []):
            if not isinstance(f, dict) or f.get("id") is None:
                continue
            fid = self._sw_canonical_id(f.get("id"))
            meta = {"id": fid}
            for src_key, out_key in self.SAVED_WORKOUTS_FOLDER_FIELDS:
                meta[out_key] = f.get(src_key)
            folder_meta[fid] = meta
            kids = {}
            for child in (f.get("children") or []):
                if isinstance(child, dict) and child.get("id") is not None:
                    kids[self._sw_canonical_id(child.get("id"))] = child
            folder_children[fid] = kids

        child_folders = {}
        child_objects = {}
        for fid, kids in folder_children.items():
            for wid, obj in kids.items():
                child_folders.setdefault(wid, []).append(fid)
                child_objects[(fid, wid)] = obj

        primary = {}
        for w in (workouts_raw or []):
            if isinstance(w, dict) and w.get("id") is not None:
                primary[self._sw_canonical_id(w.get("id"))] = w

        canonical = {}
        source = {}
        objects = {}
        upstream_folder_id = {}

        for wid, w in primary.items():
            objects[wid] = w
            source[wid] = "workouts"
            canonical[wid] = self._sw_canonical_ref(w.get("folder_id"))

        for wid, fids in child_folders.items():
            if wid in primary:
                continue
            ordered = sorted(fids, key=self._sw_sort_key)
            chosen = ordered[0]
            obj = child_objects[(chosen, wid)]
            objects[wid] = obj
            source[wid] = "folders"
            canonical[wid] = chosen
            raw_fid = self._sw_canonical_ref(obj.get("folder_id"))
            if raw_fid is not None and raw_fid != chosen:
                upstream_folder_id[wid] = raw_fid
            flag(wid)                                   # trigger 4: fallback required
            if len(ordered) > 1:
                flag(wid)                               # trigger 3: several folders

        for wid, w in primary.items():
            fid = canonical[wid]
            appears = child_folders.get(wid, [])
            if fid is not None and fid not in appears:
                flag(wid)                               # trigger 1: absent from its folder
            if any(a != fid for a in appears):
                flag(wid)                               # trigger 2: under a different folder
            if len(appears) > 1:
                flag(wid)                               # trigger 3: several folders
            for a in appears:
                if self._sw_fields_differ(w, child_objects[(a, wid)]):
                    flag(wid)                           # trigger 5: field conflict
                    break

        membership = {}
        for wid, fid in canonical.items():
            if fid is not None:
                membership.setdefault(fid, []).append(wid)

        folders_out = []
        for fid in sorted(folder_meta, key=self._sw_sort_key):
            meta = dict(folder_meta[fid])
            ids = sorted(membership.get(fid, []), key=self._sw_sort_key)
            meta["num_workouts"] = len(ids)
            meta["workout_ids"] = ids
            upstream_count = meta.get("upstream_num_workouts")
            raw_count = len(folder_children.get(fid, {}))
            if isinstance(upstream_count, int) and not isinstance(upstream_count, bool):
                if upstream_count != raw_count or upstream_count != len(ids):
                    flag(None)                          # trigger 6: folder count divergence
            folders_out.append(meta)

        workouts_out = []
        for wid in sorted(objects, key=self._sw_sort_key):
            src = objects[wid]
            fid = canonical[wid]
            entry = {"id": wid}
            for key in self.SAVED_WORKOUTS_WORKOUT_FIELDS:
                value = src.get(key)
                if key in self.SAVED_WORKOUTS_SET_LIKE_FIELDS:
                    value = self._sw_normalize_set_like(value)
                entry[key] = value
            entry["folder_id"] = fid
            entry["folder_name"] = (folder_meta.get(fid) or {}).get("name") if fid is not None else None
            if wid in upstream_folder_id:
                entry["upstream_folder_id"] = upstream_folder_id[wid]
            entry["updated"] = src.get("updated")
            entry["source_endpoint"] = source[wid]
            doc = src.get("workout_doc")
            entry["has_workout_doc"] = bool(isinstance(doc, dict) and doc)
            entry["workout_doc"] = doc
            workouts_out.append(entry)

        return folders_out, workouts_out, findings, flagged

    def _fetch_saved_workouts(self) -> Tuple[bool, Optional[List], Optional[List], Optional[Dict]]:
        """
        One refresh = both library endpoints, both of which must succeed and decode to
        a list. A partial success is a failed refresh: there is no partial merge.

        Deliberately not routed through _intervals_get, which passes no timeout.
        Returns (ok, folders, workouts, error). The error dict carries retry_after for
        scheduling; only endpoint/kind/status are ever written to the file.
        """
        headers = {
            "Authorization": f"Basic {self.intervals_auth}",
            "Accept": "application/json"
        }
        payloads = {}
        for endpoint in ("folders", "workouts"):
            url = f"{self.INTERVALS_BASE_URL}/athlete/{self.athlete_id}/{endpoint}"
            try:
                response = self._intervals_request(url, headers=headers,
                                        timeout=self.SAVED_WORKOUTS_TIMEOUT_SECS)
            except RequestBudgetRefused:
                raise
            except requests.exceptions.Timeout:
                return False, None, None, {"endpoint": endpoint, "kind": "timeout",
                                           "status": None, "retry_after": None}
            except requests.exceptions.RequestException:
                return False, None, None, {"endpoint": endpoint, "kind": "connection",
                                           "status": None, "retry_after": None}
            if response.status_code != 200:
                retry_after = None
                if response.status_code in (429, 503):
                    retry_after = self._parse_retry_after(response.headers.get("Retry-After"))
                return False, None, None, {"endpoint": endpoint, "kind": "http_status",
                                           "status": response.status_code,
                                           "retry_after": retry_after}
            try:
                payload = response.json()
            except ValueError:
                return False, None, None, {"endpoint": endpoint, "kind": "decode",
                                           "status": response.status_code, "retry_after": None}
            if not isinstance(payload, list):
                return False, None, None, {"endpoint": endpoint, "kind": "schema",
                                           "status": response.status_code, "retry_after": None}
            payloads[endpoint] = payload
        return True, payloads["folders"], payloads["workouts"], None

    def _sw_validate_payloads(self, folders_raw, workouts_raw) -> Optional[Dict]:
        """
        Structural validation of a complete successful response, run before any
        reconciliation. Returns a sanitized error dict on failure, or None.

        Reconciliation silently ignores entries it cannot key and would raise on an
        unhashable one, so without this a malformed HTTP 200 could overwrite a valid
        cache with an apparently successful smaller library, or surface as an internal
        error rather than the schema error it is. Ids are compared as canonical values,
        never as strings: `1`, `"1"`, `1.0` and `True` must not slip past each other.
        """
        def bad(endpoint):
            return {"endpoint": endpoint, "kind": "schema", "status": 200, "retry_after": None}

        def check_entry(item, seen):
            if not isinstance(item, dict):
                return False
            cid = self._sw_canonical_id(item.get("id"))
            if cid is self.SW_ID_INVALID or cid in seen:
                return False
            seen.add(cid)
            return True

        for endpoint, payload in (("folders", folders_raw), ("workouts", workouts_raw)):
            if not isinstance(payload, list):
                return bad(endpoint)
            seen = set()
            for item in payload:
                if not check_entry(item, seen):
                    return bad(endpoint)
                if endpoint == "workouts" and not self._sw_ref_ok(item.get("folder_id")):
                    return bad(endpoint)
            if endpoint == "folders":
                for folder in payload:
                    children = folder.get("children")
                    if children is None:
                        continue
                    if not isinstance(children, list):
                        return bad(endpoint)
                    child_seen = set()
                    for child in children:
                        if not check_entry(child, child_seen):
                            return bad(endpoint)
                        if not self._sw_ref_ok(child.get("folder_id")):
                            return bad(endpoint)
        return None

    SAVED_WORKOUTS_ROOT_KEYS = ("generated_at", "schema_version", "version", "script_hash",
                                "source", "target_resolution", "refresh", "counts",
                                "folders", "workouts", "fetch_state")
    SAVED_WORKOUTS_REFRESH_KEYS = ("status", "consistency", "last_success_at",
                                   "last_content_change_at", "refresh_interval_secs")
    SAVED_WORKOUTS_STATE_KEYS = ("last_attempt_at", "consecutive_failures", "next_attempt_after",
                                 "last_error", "content_digest", "endpoint_mismatch_count",
                                 "endpoint_mismatch_ids")
    SAVED_WORKOUTS_ERROR_KINDS = ("http_status", "timeout", "connection", "decode",
                                  "schema", "internal")

    @staticmethod
    def _sw_is_utc_stamp(value) -> bool:
        """A producer timestamp: parseable ISO-8601, timezone-aware, zero UTC offset."""
        if not isinstance(value, str) or not value:
            return False
        try:
            parsed = datetime.fromisoformat(value)
        except (TypeError, ValueError):
            return False
        return parsed.tzinfo is not None and parsed.utcoffset() == timedelta(0)

    @staticmethod
    def _sw_is_digest(value) -> bool:
        if not isinstance(value, str) or not value.startswith("sha256:"):
            return False
        body = value[7:]
        return len(body) == 64 and all(c in "0123456789abcdef" for c in body)

    def _sw_cache_is_valid(self, data) -> bool:
        """
        A cached mirror is accepted only when it could have been emitted by this
        producer at this schema version.

        Its own next_attempt_after decides whether a refresh runs at all, so anything
        this method waves through stays consumable, and stays retained as last-good,
        until the throttle expires. Presence-and-type checking is not enough for that:
        the file has to be internally coherent too, which is why folder_name is checked
        against the canonical folder, has_workout_doc against the document, the status
        against the failure counters, and content_digest by recomputation.

        Producer version and script_hash are deliberately NOT pinned. A snapshot written
        by an earlier sync.py is still valid data; _sw_refresh_due already forces a
        refresh when script_hash moves, while keeping that snapshot as last-good. Pinning
        here would throw away a good snapshot on every upgrade. schema_version IS pinned,
        because a different contract version is not something this code can read.
        """
        def nonneg_int(value):
            return isinstance(value, int) and not isinstance(value, bool) and value >= 0

        def opt(value, *types):
            return value is None or isinstance(value, types)

        if not isinstance(data, dict) or set(data) != set(self.SAVED_WORKOUTS_ROOT_KEYS):
            return False
        if data.get("schema_version") != self.SAVED_WORKOUTS_SCHEMA_VERSION:
            return False
        if data.get("source") != "intervals.icu" or data.get("target_resolution") != "as_stored":
            return False
        if not isinstance(data.get("version"), str) or not data["version"]:
            return False
        if not isinstance(data.get("script_hash"), str) or not data["script_hash"]:
            return False
        if not self._sw_is_utc_stamp(data.get("generated_at")):
            return False

        refresh, state = data.get("refresh"), data.get("fetch_state")
        if not isinstance(refresh, dict) or set(refresh) != set(self.SAVED_WORKOUTS_REFRESH_KEYS):
            return False
        if not isinstance(state, dict) or set(state) != set(self.SAVED_WORKOUTS_STATE_KEYS):
            return False

        status = refresh.get("status")
        if status not in ("ok", "stale", "unavailable"):
            return False
        if refresh.get("refresh_interval_secs") != self.SAVED_WORKOUTS_REFRESH_INTERVAL_SECS:
            return False
        if not self._sw_is_utc_stamp(state.get("last_attempt_at")):
            return False
        if not self._sw_is_utc_stamp(state.get("next_attempt_after")):
            return False

        failures = state.get("consecutive_failures")
        if not nonneg_int(failures):
            return False
        last_error = state.get("last_error")
        if status == "ok":
            if failures != 0 or last_error is not None:
                return False
        else:
            if failures < 1:
                return False
            if not isinstance(last_error, dict) or set(last_error) != {"endpoint", "kind", "status"}:
                return False
            if last_error.get("endpoint") not in (None, "folders", "workouts"):
                return False
            if last_error.get("kind") not in self.SAVED_WORKOUTS_ERROR_KINDS:
                return False
            if not opt(last_error.get("status"), int) or isinstance(last_error.get("status"), bool):
                return False

        mismatch_count = state.get("endpoint_mismatch_count")
        mismatch_ids = state.get("endpoint_mismatch_ids")
        if not nonneg_int(mismatch_count):
            return False
        if not isinstance(mismatch_ids, list) or len(mismatch_ids) > self.SAVED_WORKOUTS_MISMATCH_ID_CAP:
            return False
        canonical_mismatch = []
        for value in mismatch_ids:
            cid = self._sw_canonical_id(value)
            if cid is self.SW_ID_INVALID or cid in canonical_mismatch:
                return False
            canonical_mismatch.append(cid)
        if mismatch_count < len(canonical_mismatch):
            return False

        folders, workouts, counts = data.get("folders"), data.get("workouts"), data.get("counts")

        if status == "unavailable":
            return (folders is None and workouts is None and counts is None
                    and refresh.get("last_success_at") is None
                    and refresh.get("last_content_change_at") is None
                    and refresh.get("consistency") is None
                    and state.get("content_digest") is None
                    and mismatch_count == 0 and mismatch_ids == [])

        # ok / stale: a real snapshot, coherent with its own metadata.
        if not isinstance(folders, list) or not isinstance(workouts, list) or not isinstance(counts, dict):
            return False
        if set(counts) != {"folders", "workouts"}:
            return False
        if not self._sw_is_utc_stamp(refresh.get("last_success_at")):
            return False
        if not self._sw_is_utc_stamp(refresh.get("last_content_change_at")):
            return False
        consistency = refresh.get("consistency")
        if consistency not in ("consistent", "endpoints_disagree"):
            return False
        if consistency == "consistent" and mismatch_count != 0:
            return False
        if consistency == "endpoints_disagree" and mismatch_count < 1:
            return False
        if not self._sw_is_digest(state.get("content_digest")):
            return False
        if not nonneg_int(counts.get("folders")) or not nonneg_int(counts.get("workouts")):
            return False
        if counts["folders"] != len(folders) or counts["workouts"] != len(workouts):
            return False

        folder_keys = {"id", "num_workouts", "workout_ids"} | {out for _, out in self.SAVED_WORKOUTS_FOLDER_FIELDS}
        folder_ids = {}
        folder_names = {}
        for folder in folders:
            if not isinstance(folder, dict) or set(folder) != folder_keys:
                return False
            fid = self._sw_canonical_id(folder.get("id"))
            if fid is self.SW_ID_INVALID or fid in folder_ids:
                return False
            if not opt(folder.get("type"), str) or not opt(folder.get("name"), str):
                return False
            if not opt(folder.get("description"), str) or not opt(folder.get("visibility"), str):
                return False
            if not opt(folder.get("read_only_workouts"), bool) or not opt(folder.get("can_edit"), bool):
                return False
            if not opt(folder.get("start_date_local"), str) or not opt(folder.get("activity_types"), list):
                return False
            upstream = folder.get("upstream_num_workouts")
            if upstream is not None and not nonneg_int(upstream):
                return False
            member_ids = folder.get("workout_ids")
            if not isinstance(member_ids, list):
                return False
            members = []
            for value in member_ids:
                cid = self._sw_canonical_id(value)
                if cid is self.SW_ID_INVALID or cid in members:
                    return False
                members.append(cid)
            if not nonneg_int(folder.get("num_workouts")) or folder["num_workouts"] != len(members):
                return False
            folder_ids[fid] = members
            folder_names[fid] = folder.get("name")

        workout_keys = ({"id", "folder_id", "folder_name", "updated", "source_endpoint",
                         "has_workout_doc", "workout_doc"} | set(self.SAVED_WORKOUTS_WORKOUT_FIELDS))
        workout_refs = {}
        for workout in workouts:
            if not isinstance(workout, dict):
                return False
            extra = set(workout) - workout_keys
            if extra - {"upstream_folder_id"} or not workout_keys <= set(workout):
                return False
            wid = self._sw_canonical_id(workout.get("id"))
            if wid is self.SW_ID_INVALID or wid in workout_refs:
                return False
            if workout.get("source_endpoint") not in ("workouts", "folders"):
                return False
            if not opt(workout.get("updated"), str):
                return False
            for key in ("name", "type", "sub_type", "description", "target"):
                if not opt(workout.get(key), str):
                    return False
            for key in ("indoor", "for_week", "hide_from_athlete"):
                if not opt(workout.get(key), bool):
                    return False
            for key in ("moving_time", "distance", "icu_training_load", "icu_intensity", "carbs_per_hour"):
                value = workout.get(key)
                if not opt(value, int, float) or isinstance(value, bool):
                    return False
            for key in ("targets", "tags"):
                value = workout.get(key)
                if not opt(value, list):
                    return False
                if isinstance(value, list) and value != self._sw_normalize_set_like(value):
                    return False
            doc = workout.get("workout_doc")
            if not opt(doc, dict):
                return False
            if workout.get("has_workout_doc") is not bool(isinstance(doc, dict) and doc):
                return False
            if not self._sw_ref_ok(workout.get("folder_id")):
                return False
            fid = self._sw_canonical_ref(workout.get("folder_id"))
            if "upstream_folder_id" in workout:
                upstream_ref = self._sw_canonical_id(workout["upstream_folder_id"])
                if (upstream_ref is self.SW_ID_INVALID
                        or workout.get("source_endpoint") != "folders"
                        or upstream_ref == fid):
                    return False
            expected_name = folder_names.get(fid) if fid is not None and fid in folder_ids else None
            if workout.get("folder_name") != expected_name:
                return False
            workout_refs[wid] = fid

        # Canonical membership invariant, the same five clauses the producer guarantees.
        for wid, fid in workout_refs.items():
            holders = [f for f, members in folder_ids.items() if wid in members]
            if fid is None:
                if holders:
                    return False
            elif fid in folder_ids:
                if holders != [fid]:
                    return False
            elif holders:
                return False
        for fid, members in folder_ids.items():
            for wid in members:
                if wid not in workout_refs or workout_refs[wid] != fid:
                    return False

        # Mismatch ids must reference workouts actually present in this snapshot.
        if any(cid not in workout_refs for cid in canonical_mismatch):
            return False

        # Finally: the digest must be the one this snapshot actually produces. Altered
        # content with a carried-over digest is the case presence checks cannot catch.
        return self._sw_digest(folders, workouts) == state.get("content_digest")

    def _sw_load_existing(self) -> Optional[Dict]:
        """Previous mirror, or None when absent, unreadable or unparseable (treated as absent)."""
        path = self.data_dir / self.SAVED_WORKOUTS_FILE
        try:
            with open(path, "r", encoding="utf-8") as f:
                data = json.load(f)
        except (OSError, ValueError):
            return None
        if not self._sw_cache_is_valid(data):
            return None
        return data

    def _sw_refresh_due(self, prev: Optional[Dict], now: datetime) -> bool:
        """
        A refresh is attempted when the file is absent or unparseable, the script hash
        differs, or the scheduled attempt time has arrived. A script-hash change forces
        a refresh but never discards the retained snapshot.
        """
        if prev is None:
            return True
        if prev.get("script_hash") != self.script_hash:
            return True
        state = prev.get("fetch_state") or {}
        nxt = state.get("next_attempt_after")
        if not nxt:
            return True
        try:
            due = datetime.fromisoformat(str(nxt))
        except (TypeError, ValueError):
            return True
        if due.tzinfo is None:
            due = due.replace(tzinfo=timezone.utc)
        return now >= due

    def _sw_build_success(self, prev: Optional[Dict], folders_raw, workouts_raw,
                          now: datetime) -> Dict:
        """Snapshot from a complete, structurally validated response."""
        prev_refresh = (prev or {}).get("refresh") or {}
        prev_state = (prev or {}).get("fetch_state") or {}
        folders, workouts, findings, flagged = self._sw_reconcile(folders_raw, workouts_raw)
        digest = self._sw_digest(folders, workouts)
        prev_change = prev_refresh.get("last_content_change_at")
        changed = (digest != prev_state.get("content_digest")) or not prev_change
        data = self._sw_envelope(now)
        data["refresh"] = {
            "status": "ok",
            "consistency": "endpoints_disagree" if findings else "consistent",
            "last_success_at": self._sw_iso(now),
            "last_content_change_at": self._sw_iso(now) if changed else prev_change,
            "refresh_interval_secs": self.SAVED_WORKOUTS_REFRESH_INTERVAL_SECS,
        }
        data["counts"] = {"folders": len(folders), "workouts": len(workouts)}
        data["folders"] = folders
        data["workouts"] = workouts
        data["fetch_state"] = {
            "last_attempt_at": self._sw_iso(now),
            "consecutive_failures": 0,
            "next_attempt_after": self._sw_iso(
                now + timedelta(seconds=self.SAVED_WORKOUTS_REFRESH_INTERVAL_SECS)),
            "last_error": None,
            "content_digest": digest,
            "endpoint_mismatch_count": findings,
            "endpoint_mismatch_ids": flagged[:self.SAVED_WORKOUTS_MISMATCH_ID_CAP],
        }
        return data

    def _sw_build_failure(self, prev: Optional[Dict], error: Dict, now: datetime) -> Dict:
        """
        Failure state. Every refresh failure lands here, whatever its cause: an HTTP
        or transport error, a structurally invalid response, or an unexpected internal
        exception. The last good snapshot is preserved whole and reported as stale;
        with no valid previous snapshot the collections are null and the status is
        unavailable. A retained snapshot is never presented as freshly verified.
        """
        prev_refresh = (prev or {}).get("refresh") or {}
        prev_state = (prev or {}).get("fetch_state") or {}
        if not isinstance(prev_refresh, dict):
            prev_refresh = {}
        if not isinstance(prev_state, dict):
            prev_state = {}
        has_snapshot = bool(prev_refresh.get("last_success_at")) and isinstance((prev or {}).get("workouts"), list)

        # Defensive coercion. _sw_load_existing already rejects a malformed cache, but
        # this is also the recovery path for an unexpected exception, so it must not be
        # the thing that raises: a bad retained counter degrades to a safe default.
        def safe_count(value, default=0):
            return value if isinstance(value, int) and not isinstance(value, bool) and value >= 0 else default

        attempts = safe_count(prev_state.get("consecutive_failures")) + 1
        retry_after = error.get("retry_after")
        if not (isinstance(retry_after, int) and not isinstance(retry_after, bool) and retry_after >= 0):
            retry_after = None
        delay = self._sw_backoff_secs(attempts, retry_after)
        prev_ids = prev_state.get("endpoint_mismatch_ids")
        if not isinstance(prev_ids, list):
            prev_ids = []
        data = self._sw_envelope(now)
        data["refresh"] = {
            "status": "stale" if has_snapshot else "unavailable",
            "consistency": prev_refresh.get("consistency") if has_snapshot else None,
            "last_success_at": prev_refresh.get("last_success_at") if has_snapshot else None,
            "last_content_change_at": prev_refresh.get("last_content_change_at") if has_snapshot else None,
            "refresh_interval_secs": self.SAVED_WORKOUTS_REFRESH_INTERVAL_SECS,
        }
        data["counts"] = prev.get("counts") if has_snapshot else None
        data["folders"] = prev.get("folders") if has_snapshot else None
        data["workouts"] = prev.get("workouts") if has_snapshot else None
        data["fetch_state"] = {
            "last_attempt_at": self._sw_iso(now),
            "consecutive_failures": attempts,
            "next_attempt_after": self._sw_iso(now + timedelta(seconds=delay)),
            "last_error": {"endpoint": error.get("endpoint"),
                           "kind": error.get("kind"),
                           "status": error.get("status")},
            "content_digest": prev_state.get("content_digest") if has_snapshot else None,
            "endpoint_mismatch_count": safe_count(prev_state.get("endpoint_mismatch_count")) if has_snapshot else 0,
            "endpoint_mismatch_ids": prev_ids[:self.SAVED_WORKOUTS_MISMATCH_ID_CAP] if has_snapshot else [],
        }
        return data

    def _sw_envelope(self, now: datetime) -> Dict:
        """Producer identity block shared by every mirror write."""
        return {
            "generated_at": self._sw_iso(now),
            "schema_version": self.SAVED_WORKOUTS_SCHEMA_VERSION,
            "version": self.VERSION,
            "script_hash": self.script_hash,
            "source": "intervals.icu",
            "target_resolution": "as_stored",
        }

    def _generate_saved_workouts(self, force: bool = False) -> Optional[Dict]:
        """
        Build saved_workouts.json, or return None when the throttle window has not
        expired (in which case the file is left untouched and no request is made).

        Every failure path - transport, HTTP status, malformed payload, unreadable or
        structurally invalid cache, or an unexpected exception anywhere in fetch,
        validation or reconciliation - resolves to _sw_build_failure, so the file
        never keeps claiming that the most recent attempt succeeded. Failure never
        removes cached entries.
        """
        now = self._sw_now()
        prev = None
        try:
            prev = self._sw_load_existing()
            if not force and not self._sw_refresh_due(prev, now):
                self._saved_workouts_data = None
                return None
            ok, folders_raw, workouts_raw, error = self._fetch_saved_workouts()
            if ok:
                error = self._sw_validate_payloads(folders_raw, workouts_raw)
                ok = error is None
            if ok:
                data = self._sw_build_success(prev, folders_raw, workouts_raw, now)
                if getattr(self, "_acquisition", None) is not None:
                    self._acquisition.companion_success["saved_workouts"] = now.timestamp()
            else:
                data = self._sw_build_failure(prev, error, now)
        except RequestBudgetRefused:
            self._saved_workouts_data = None
            return None
        except Exception:
            # Bounded, sanitized classification only: no exception text, which could
            # carry a URL, a token or athlete data.
            data = self._sw_build_failure(
                prev, {"endpoint": None, "kind": "internal", "status": None,
                       "retry_after": None}, now)
        self._saved_workouts_data = data
        return data

    def _sw_write(self, data: Dict) -> Path:
        """Atomic same-directory write: temp file plus os.replace."""
        path = self.data_dir / self.SAVED_WORKOUTS_FILE
        tmp = path.with_name(path.name + ".tmp")
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(data, f, indent=2, default=str)
        os.replace(tmp, path)
        return path

    @staticmethod
    def _sw_status_line(data: Dict) -> str:
        """One-line console summary of a mirror write."""
        refresh = data.get("refresh") or {}
        counts = data.get("counts") or {}
        status = refresh.get("status")
        if status == "unavailable":
            return "unavailable (no snapshot yet)"
        detail = f"{counts.get('workouts')} workout(s), {counts.get('folders')} folder(s)"
        if refresh.get("consistency") == "endpoints_disagree":
            detail += ", endpoints disagree"
        return f"{status} - {detail}"

    @staticmethod
    def _event_start_fields(evt: Dict) -> Dict:
        """Upstream midnight is an unset-time placeholder, not a known start."""
        raw = evt.get("start_date_local")
        if isinstance(raw, str) and "T" in raw:
            try:
                parsed = datetime.fromisoformat(raw)
                if (parsed.hour, parsed.minute, parsed.second, parsed.microsecond) == (0, 0, 0, 0):
                    return {"start_time_status": "midnight_treated_as_unset"}
                return {"start_time": parsed.strftime("%H:%M"),
                        "start_time_status": "provided"}
            except ValueError:
                pass
        return {"start_time_status": "missing"}

    @staticmethod
    def _select_route_attachment(attachments: List[Dict]) -> Optional[Dict]:
        """GPX before TCX before FIT, then lexical ID, filename and URL."""
        priority = {"gpx": 0, "tcx": 1, "fit": 2}
        candidates = []
        for att in attachments or []:
            if not isinstance(att, dict):
                continue
            filename = str(att.get("filename") or "")
            ext = filename.lower().rsplit(".", 1)[-1]
            if ext in priority:
                candidates.append((priority[ext], str(att.get("id") or ""),
                                   filename, str(att.get("url") or ""), att))
        return min(candidates, key=lambda item: item[:4])[-1] if candidates else None

    def _planned_route_fields(self, evt: Dict) -> Dict:
        """Compact state shared by planned_workouts and race_calendar."""
        route = getattr(self, "_planned_routes", {}).get(evt.get("id"))
        if route is None:
            return {"has_terrain": False, "route_status": "absent"}
        fields = {"has_terrain": route["route_status"] == "ok",
                "route_status": route["route_status"],
                "route_ref": route["route_ref"]}
        brief = route.get("route_weather")
        if isinstance(brief, dict):
            fields["route_weather_summary"] = {
                key: brief[key] for key in ("event_id", "route_ref", "brief_id", "cache_key", "status", "tier",
                                            "reason_codes", "departure", "expires_at", "summary") if key in brief}
            fields["route_weather_summary"]["detail_file"] = "routes.json"
        return fields

    def _generate_route_weather(self, events, activities, previous, athlete, power_inputs=None):
        self._overview_events = events
        self._overview_athlete = athlete
        """Optional enrichment; never let a weather failure stop the training output."""
        try:
            RouteWeather(self).generate(events, activities, previous, athlete, power_inputs)
        except Exception:
            for row in getattr(self, "_routes_data", {}).get("events", []):
                if row.get("route_status") == "ok":
                    row["route_weather"] = {"schema_version": RouteWeather.VERSION,
                                            "event_id": row.get("event_id"), "route_ref": row.get("route_ref"),
                                            "status": "unavailable", "brief_id": None,
                                            "reason_codes": ["weather_processing_failed"]}
        try:
            RouteWeatherMap.generate(self, events, athlete)
        except Exception:
            for row in getattr(self, "_routes_data", {}).get("events", []):
                row.pop("route_weather_map", None)
                row["route_weather_map_status"] = "image_processing_failed"

    def _update_route_eta_history(self, activities, previous=None, full_history=False, now=None):
        """Non-critical local record; no additional API calls or training payload changes."""
        try:
            return RouteWeather.update_history(self, activities, previous or {}, full_history, now)
        except Exception:
            return {"activities": [], "last_full_fetch_at": None, "persistence_status": "record_unavailable"}

    def _generate_terrain(self, events: List[Dict],
                          athlete_units: Optional[Dict[str, str]] = None) -> set:
        """Reuse unchanged immutable attachments without HTTP; back off failed reads."""
        routes_path = self.data_dir / self.ROUTES_FILE
        cached = {}
        if routes_path.exists():
            try:
                with open(routes_path, "r") as f:
                    data = json.load(f)
                if data.get("script_hash") == self.script_hash:
                    for entry in data.get("events", []):
                        if isinstance(entry, dict):
                            cached[(entry.get("event_id"), entry.get("attachment_id"))] = entry
            except (OSError, ValueError, TypeError, AttributeError):
                cached = {}

        new_entries = []
        self._planned_routes = {}
        self._route_source_ids = set()
        for evt in events:
            att = self._select_route_attachment(evt.get("attachments"))
            if att is None:
                continue
            self._route_source_ids.add(hashlib.sha256(str(att.get("url")).encode()).hexdigest())
            evt_id, att_id = evt.get("id"), att.get("id")
            filename = str(att.get("filename") or "")
            # Detect filename replacement; potentially rotating URLs are not identity.
            source_hash = hashlib.sha256(json.dumps(
                [filename], separators=(",", ":")
            ).encode("utf-8")).hexdigest()
            now = datetime.now(timezone.utc)
            result = self._cached_route_result(
                cached.get((evt_id, att_id)), filename, source_hash, now, athlete_units)
            if result is None:
                if evt_id is None or att_id is None:
                    result = {"route_status": "failed", "route_error": "missing_identity"}
                else:
                    result = self._download_and_parse_route(
                        att.get("url"), filename, athlete_units=athlete_units)
                result = self._validated_route_result(result)
                result.update(last_attempt_at=now.isoformat(), checked_at=now.isoformat(),
                              cache_hit=False)
            # A legacy error dictionary or an incomplete parser result is never terrain.
            result = self._validated_route_result(result)
            if result.get("cache_hit") and result["route_status"] == "ok":
                # A prior capacity refusal can leave valid native terrain without
                # private provenance. Reuse remains valid; its acquisition age is unknown.
                self._adopt_native_cache("route_attachments",
                    hashlib.sha256(str(att.get("url")).encode()).hexdigest(), True)
            if result["route_status"] in ("unsupported_format", "no_elevation"):
                self._adopt_native_cache("route_attachments",
                    hashlib.sha256(str(att.get("url")).encode()).hexdigest(), True, result["route_status"])
            revision = result.pop("revision", None)
            entry = {
                "event_id": evt_id,
                "event_name": evt.get("name", "Unnamed"),
                "event_date": (evt.get("start_date_local") or "")[:10],
                "category": evt.get("category", ""),
                "attachment_id": att_id,
                "filename": filename,
                "attachment_source_hash": source_hash,
                "route_ref": {
                    "route_id": (f"intervals:{evt_id}:attachment:{att_id}"
                                 if evt_id is not None and att_id is not None else None),
                    "revision": revision,
                    "attachment_id": att_id,
                    "terrain_version": self.ROUTE_TERRAIN_VERSION,
                },
                **result,
                **self._event_start_fields(evt),
            }
            new_entries.append(entry)
            if evt_id is not None:
                self._planned_routes[evt_id] = entry

        self._routes_data = {
            "generated_at": datetime.now(timezone.utc).isoformat(),
            "sync_version": self.VERSION,
            "script_hash": self.script_hash,
            "events": new_entries,
        }
        return {e["event_id"] for e in new_entries if e["route_status"] == "ok"}

    def _cached_route_result(self, cached: Optional[Dict], filename: str,
                             source_hash: str, now: datetime,
                             athlete_units: Optional[Dict[str, str]] = None) -> Optional[Dict]:
        """Reuse matching analysis or a not-yet-due failure before any HTTP call.

        Intervals attachment IDs are assumed immutable. A changed ID or filename
        is a new attachment version; a changed URL is not. The caller checked event/attachment
        IDs and script hash; content revisions remain the hashes recorded at parse.
        """
        if not isinstance(cached, dict):
            return None
        ref = cached.get("route_ref")
        if (not isinstance(ref, dict)
                or ref.get("terrain_version") != self.ROUTE_TERRAIN_VERSION
                or cached.get("filename") != filename
                or cached.get("attachment_source_hash") != source_hash):
            return None
        previous = self._validated_route_result(cached)
        status = previous["route_status"]
        revision = ref.get("revision")
        if status in ("ok", "no_elevation"):
            if (not isinstance(revision, str) or len(revision) != 64
                    or any(c not in "0123456789abcdef" for c in revision)
                    or not previous.get("analyzed_at")):
                return None
        elif status == "unsupported_format" or previous.get("route_error") == "missing_identity":
            pass  # Terminal for this unchanged attachment; no repeated request.
        else:
            try:
                last_attempt = datetime.fromisoformat(previous["last_attempt_at"])
                if last_attempt.tzinfo is None:
                    last_attempt = last_attempt.replace(tzinfo=timezone.utc)
            except (KeyError, TypeError, ValueError):
                return None
            if (now - last_attempt).total_seconds() >= self.ROUTE_RETRY_BACKOFF_SECONDS:
                return None
        result = {key: previous[key] for key in (
            "route_status", "route_error", "terrain_summary", "route_geometry",
            "analyzed_at", "last_attempt_at", "checked_at") if key in previous}
        if status == "ok":
            result["terrain_summary"] = self._refresh_terrain_display(
                result["terrain_summary"], athlete_units)
        elif status == "no_elevation":
            geometry = dict(result["route_geometry"])
            geometry["display"] = {"total_distance": self._to_display(
                geometry["total_distance_km"], "distance", athlete_units)}
            result["route_geometry"] = geometry
        return {**result, "revision": revision, "cache_hit": True}

    @staticmethod
    def _validated_route_result(result: Dict) -> Dict:
        """Fail closed at the parser/cache boundary, independent of truthiness."""
        if not isinstance(result, dict) or "error" in result:
            return {"route_status": "failed", "route_error": "invalid_parse_result"}
        status = result.get("route_status")
        if status == "ok":
            terrain = result.get("terrain_summary")
            if (not isinstance(terrain, dict) or "error" in terrain
                    or terrain.get("course_character") not in ("flat", "rolling", "hilly", "mountain")
                    or not isinstance(terrain.get("polyline"), list)
                    or len(terrain["polyline"]) < 2
                    or not isinstance(terrain.get("total_elevation_m"), (int, float))
                    or not math.isfinite(terrain["total_elevation_m"])):
                return {"route_status": "failed", "route_error": "invalid_terrain_result"}
        elif status == "no_elevation":
            geometry = result.get("route_geometry")
            if (not isinstance(geometry, dict)
                    or not isinstance(geometry.get("polyline"), list)
                    or len(geometry["polyline"]) < 2):
                return {"route_status": "failed", "route_error": "invalid_geometry_result"}
        elif status not in ("failed", "unsupported_format", "no_gps"):
            return {"route_status": "failed", "route_error": "invalid_route_status"}
        out = dict(result)
        if status != "ok":
            out.pop("terrain_summary", None)
        if status != "no_elevation":
            out.pop("route_geometry", None)
        return out

    @observe_source("route_attachments")
    def _download_and_parse_route(self, url: str, filename: str,
                                  athlete_units: Optional[Dict[str, str]] = None) -> Dict:
        """Download and analyze a new or retry-due attachment, recording its hash."""
        if filename.lower().endswith(".fit"):
            return {"route_status": "unsupported_format", "route_error": "FIT is not supported"}
        if not url:
            return {"route_status": "failed", "route_error": "missing_url"}
        try:
            seen = set()
            for hop in range(6):  # Initial download plus at most five redirects.
                target = urlsplit(url)
                if target.scheme not in ("http", "https") or not target.hostname:
                    raise requests.exceptions.RequestException("invalid attachment URL")
                # Preserve signed query parameters, but never send URL userinfo.
                url = target._replace(netloc=target.netloc.rsplit("@", 1)[-1],
                                      fragment="").geturl()
                if url in seen:
                    raise requests.exceptions.TooManyRedirects("attachment redirect loop")
                seen.add(url)
                response = self._intervals_request(url, timeout=30, budget_attachment=True)
                if response.status_code not in (301, 302, 303, 307, 308):
                    break
                location = response.headers.get("Location")
                response.close()
                if not isinstance(location, str) or not location.strip() or hop == 5:
                    raise requests.exceptions.RequestException("invalid attachment redirect")
                url = urljoin(url, location.strip())
            if response.status_code != 200:
                return {"route_status": "failed",
                        "route_error": f"download failed (HTTP {response.status_code})"}
            content = response.content
        except (requests.exceptions.RequestException, ValueError):
            return {"route_status": "failed", "route_error": "download failed"}
        if not content:
            return {"route_status": "failed", "route_error": "empty_file"}

        revision = hashlib.sha256(content).hexdigest()
        result = self._validated_route_result(
            self._parse_route_file(content, filename, athlete_units=athlete_units))
        result.update(revision=revision, cache_hit=False)
        if result["route_status"] in ("ok", "no_elevation"):
            result["analyzed_at"] = datetime.now(timezone.utc).isoformat()
        return result

    def _parse_route_file(self, content: bytes, filename: str,
                          athlete_units: Optional[Dict[str, str]] = None) -> Dict:
        """Dispatch on the XML root, never on the shared XML declaration."""
        if filename.lower().endswith(".fit") or content[8:12] == b".FIT":
            return {"route_status": "unsupported_format", "route_error": "FIT is not supported"}
        try:
            root = ET.fromstring(content)
        except (ET.ParseError, LookupError, ValueError):
            return {"route_status": "failed", "route_error": "invalid_xml"}
        tag = root.tag.rsplit("}", 1)[-1]
        if tag == "gpx":
            return self._parse_gpx(content, athlete_units=athlete_units)
        if tag == "TrainingCenterDatabase":
            return self._parse_tcx(content, athlete_units=athlete_units)
        return {"route_status": "unsupported_format", "route_error": "unrecognized XML root"}

    @staticmethod
    def _route_point(lat, lon, ele=None) -> Optional[Dict]:
        """Keep valid GPS when altitude is missing; reject non-finite coordinates."""
        try:
            lat, lon = float(lat), float(lon)
        except (ValueError, TypeError):
            return None
        if not (math.isfinite(lat) and math.isfinite(lon) and -90 <= lat <= 90 and -180 <= lon <= 180):
            return None
        point = {"lat": lat, "lon": lon}
        try:
            altitude = float(ele)
            if math.isfinite(altitude):
                point["ele"] = altitude
        except (ValueError, TypeError):
            pass
        return point

    def _route_from_trackpoints(self, trackpoints: List[Dict],
                                athlete_units: Optional[Dict[str, str]] = None) -> Dict:
        if len(trackpoints) < 2:
            return {"route_status": "no_gps", "route_error": "insufficient_trackpoints"}
        # Incomplete altitude coverage must not enter the detector as synthetic zero.
        if not all("ele" in point for point in trackpoints):
            distance = 0.0
            next_threshold = 0.0
            polyline = []
            for i, point in enumerate(trackpoints):
                if i:
                    prev = trackpoints[i - 1]
                    distance += self._haversine(prev["lat"], prev["lon"], point["lat"], point["lon"])
                if distance >= next_threshold or i == len(trackpoints) - 1:
                    polyline.append([round(distance / 1000, 1),
                                     round(point["lat"], 5), round(point["lon"], 5)])
                    next_threshold = distance + 500.0
            km = round(distance / 1000, 1)
            return {"route_status": "no_elevation", "route_geometry": {
                "total_distance_km": km,
                "start_coords": [round(trackpoints[0]["lat"], 5), round(trackpoints[0]["lon"], 5)],
                "polyline": polyline,
                "display": {"total_distance": self._to_display(km, "distance", athlete_units)},
            }}
        summary = self._analyze_terrain(trackpoints, athlete_units=athlete_units)
        if not isinstance(summary, dict) or "error" in summary:
            return {"route_status": "failed", "route_error": "terrain_analysis_unavailable"}
        return {"route_status": "ok", "terrain_summary": summary}

    def _parse_gpx(self, content: bytes,
                   athlete_units: Optional[Dict[str, str]] = None) -> Dict:
        """Parse GPX trackpoints without inventing missing altitude."""
        try:
            root = ET.fromstring(content)
        except ET.ParseError:
            return {"route_status": "failed", "route_error": "invalid_gpx"}
        ns = root.tag[:root.tag.index("}") + 1] if "}" in root.tag else ""
        trackpoints = []
        for trkpt in root.iter(f"{ns}trkpt"):
            point = self._route_point(trkpt.get("lat"), trkpt.get("lon"),
                                      trkpt.findtext(f"{ns}ele"))
            if point is not None:
                trackpoints.append(point)
        return self._route_from_trackpoints(trackpoints, athlete_units)

    def _parse_tcx(self, content: bytes,
                   athlete_units: Optional[Dict[str, str]] = None) -> Dict:
        """Parse TCX positions, retaining GPS if altitude is absent or malformed."""
        try:
            root = ET.fromstring(content)
        except ET.ParseError:
            return {"route_status": "failed", "route_error": "invalid_tcx"}
        ns = root.tag[:root.tag.index("}") + 1] if "}" in root.tag else ""
        trackpoints = []
        for tp_elem in root.iter(f"{ns}Trackpoint"):
            pos = tp_elem.find(f"{ns}Position")
            if pos is None:
                continue
            point = self._route_point(pos.findtext(f"{ns}LatitudeDegrees"),
                                      pos.findtext(f"{ns}LongitudeDegrees"),
                                      tp_elem.findtext(f"{ns}AltitudeMeters"))
            if point is not None:
                trackpoints.append(point)
        return self._route_from_trackpoints(trackpoints, athlete_units)
    
    @staticmethod
    def _haversine(lat1: float, lon1: float, lat2: float, lon2: float) -> float:
        """Haversine distance in meters between two GPS coordinates."""
        R = 6371000  # Earth radius in meters
        phi1, phi2 = math.radians(lat1), math.radians(lat2)
        dphi = math.radians(lat2 - lat1)
        dlam = math.radians(lon2 - lon1)
        a = math.sin(dphi / 2) ** 2 + math.cos(phi1) * math.cos(phi2) * math.sin(dlam / 2) ** 2
        return R * 2 * math.atan2(math.sqrt(a), math.sqrt(1 - a))
    
    def _analyze_terrain(self, trackpoints: List[Dict],
                         source: str = "gpx_attachment",
                         include_polyline: bool = True,
                         athlete_units: Optional[Dict[str, str]] = None) -> Dict:
        """
        Analyze trackpoints into terrain_summary.
        
        Computes: total distance, total elevation gain, climb/descent detection,
        course character, elevation_per_km. Elevation smoothed with rolling
        window (~50m) before gradient calculation to reduce GPS jitter.
        
        Parameters:
            trackpoints: list of {lat, lon, ele?} dicts.
            source: tag stored in output. "gpx_attachment" for route attachments
                (default, preserves existing routes.json behavior). "activity_streams"
                for completed activities pulled from Intervals streams API.
            include_polyline: emit downsampled polyline (500m intervals). True for
                routes.json (used for map rendering). False for activity terrain
                (raw streams available on demand via pull.py).
            athlete_units: six-key prefs map ({distance, weight, height, ...}). When
                provided, terrain_summary and each climb/descent get a `display`
                block alongside canonical metric fields. None preserves the
                metric-only output for any caller not yet plumbed (v3.109).
        """
        has_elevation = any("ele" in tp for tp in trackpoints)
        
        # Compute cumulative distance and collect elevation
        cum_dist = [0.0]  # cumulative distance in meters
        for i in range(1, len(trackpoints)):
            d = self._haversine(
                trackpoints[i - 1]["lat"], trackpoints[i - 1]["lon"],
                trackpoints[i]["lat"], trackpoints[i]["lon"]
            )
            cum_dist.append(cum_dist[-1] + d)
        
        total_distance_m = cum_dist[-1]
        total_distance_km = round(total_distance_m / 1000, 1)
        
        if not has_elevation or total_distance_m < 100:
            return {
                "source": source if has_elevation else f"{source}_no_elevation",
                "total_distance_km": total_distance_km,
                "total_elevation_m": 0,
                "elevation_per_km": 0.0,
                "course_character": "flat",
                "climbs": [],
                "descents": [],
                "display": {
                    "total_distance": self._to_display(total_distance_km, "distance", athlete_units),
                    "total_elevation": self._to_display(0, "elevation", athlete_units),
                    "elevation_per_distance": self._to_display(0.0, "elevation_per_distance", athlete_units),
                }
            } if not has_elevation else None
        
        # Smooth elevation: rolling window ~50m of distance
        raw_ele = [tp.get("ele", 0.0) for tp in trackpoints]
        smoothed_ele = list(raw_ele)  # copy
        SMOOTH_WINDOW_M = 50.0
        
        for i in range(len(trackpoints)):
            # Find indices within ±SMOOTH_WINDOW_M/2 of current point
            lo, hi = i, i
            while lo > 0 and cum_dist[i] - cum_dist[lo - 1] < SMOOTH_WINDOW_M / 2:
                lo -= 1
            while hi < len(trackpoints) - 1 and cum_dist[hi + 1] - cum_dist[i] < SMOOTH_WINDOW_M / 2:
                hi += 1
            if lo < hi:
                smoothed_ele[i] = sum(raw_ele[lo:hi + 1]) / (hi - lo + 1)
        
        # Total elevation gain (from smoothed)
        total_gain = 0.0
        for i in range(1, len(smoothed_ele)):
            diff = smoothed_ele[i] - smoothed_ele[i - 1]
            if diff > 0:
                total_gain += diff
        total_elevation_m = round(total_gain)
        
        elevation_per_km = round(total_elevation_m / total_distance_km, 1) if total_distance_km > 0 else 0.0
        
        # Detect climbs and descents
        # Native segment boundaries use the existing 50m-smoothed elevations.
        # After raw distance/gradient admission, retain rounded gain >=100m OR
        # rounded absolute average >=3%; this applies symmetrically to descents.
        raw_climbs = self._detect_segments(trackpoints, cum_dist, smoothed_ele, min_gradient=1.5, min_distance=500.0, ascending=True, athlete_units=athlete_units)
        climbs = [c for c in raw_climbs if c["elevation_m"] >= 100 or c["avg_gradient_pct"] >= 3.0]
        raw_descents = self._detect_segments(trackpoints, cum_dist, smoothed_ele, min_gradient=1.5, min_distance=500.0, ascending=False, athlete_units=athlete_units)
        descents = [d for d in raw_descents if abs(d["elevation_m"]) >= 100 or abs(d["avg_gradient_pct"]) >= 3.0]
        
        # Course character — elevation density (m/km) only.
        # Total elevation is distance-blind: 2000m over 300km is rolling,
        # not hilly. Climb category upgrades handle "flat with one big climb."
        if elevation_per_km >= 30:
            course_character = "mountain"
        elif elevation_per_km >= 20:
            course_character = "hilly"
        elif elevation_per_km >= 5:
            course_character = "rolling"
        else:
            course_character = "flat"
        
        # Upgrade based on climb severity
        max_category = None
        for c in climbs:
            cat = c.get("category")
            if cat in ("HC", "Cat 1", "Cat 2"):
                max_category = "hilly"
                break
        if max_category == "hilly" and course_character in ("flat", "rolling"):
            course_character = "hilly"
        
        # Downsample trackpoints at 500m intervals for polyline (when requested).
        # Activities skip the polyline since the raw streams are available on demand
        # via pull.py — saves ~1-3 KB per activity in latest.json.
        polyline = None
        if include_polyline:
            POLYLINE_INTERVAL_M = 500.0
            polyline = []
            next_threshold = 0.0
            for i, tp in enumerate(trackpoints):
                if cum_dist[i] >= next_threshold or i == 0 or i == len(trackpoints) - 1:
                    km = round(cum_dist[i] / 1000, 1)
                    pt = [km, round(tp["lat"], 5), round(tp["lon"], 5)]
                    if has_elevation:
                        pt.append(round(smoothed_ele[i]))
                    polyline.append(pt)
                    if i == 0:
                        next_threshold = POLYLINE_INTERVAL_M
                    else:
                        next_threshold = cum_dist[i] + POLYLINE_INTERVAL_M
        
        # Start coordinates — first valid trackpoint. Useful for "where did this
        # ride happen" without needing to read the full polyline.
        start_coords = [round(trackpoints[0]["lat"], 5), round(trackpoints[0]["lon"], 5)]
        
        # Grade distribution + max grade — both derived from the same 200m chunked
        # walk over smoothed elevation. max_grade_pct captures the steepest
        # 200m anywhere on the route (including short pitches that don't
        # form sustained climbs and therefore aren't in climbs[]).
        grade_distribution, max_grade_pct = self._compute_grade_distribution(cum_dist, smoothed_ele)
        
        result = {
            "source": source,
            "total_distance_km": total_distance_km,
            "total_elevation_m": total_elevation_m,
            "elevation_per_km": elevation_per_km,
            "course_character": course_character,
            "max_grade_pct": max_grade_pct,
            "grade_distribution": grade_distribution,
            "start_coords": start_coords,
            "climbs": climbs,
            "descents": descents,
            "display": {
                "total_distance": self._to_display(total_distance_km, "distance", athlete_units),
                "total_elevation": self._to_display(total_elevation_m, "elevation", athlete_units),
                "elevation_per_distance": self._to_display(elevation_per_km, "elevation_per_distance", athlete_units),
            }
        }
        if include_polyline:
            result["polyline"] = polyline
        return result
    
    def _compute_grade_distribution(self, cum_dist: List[float],
                                    smoothed_ele: List[float]) -> Tuple[Dict[str, float], float]:
        """
        Compute time-in-grade distribution + max absolute grade.
        
        Walks the route in 200m chunks. For each chunk, computes the gradient
        and assigns it to a bucket. Returns (distribution, max_abs_grade_pct).
        
        Buckets (absolute gradient — descents and climbs both count toward
        the same bucket since coaching-relevant grade impact is symmetric):
            flat:     |grade| < 1%
            gentle:   1-3%
            moderate: 3-6%
            steep:    >= 6%
        
        First return value is a dict with keys flat_pct, gentle_pct,
        moderate_pct, steep_pct (sums to ~100, rounding residual possible).
        
        Second return value is the steepest 200m chunk encountered anywhere
        on the route, NOT just inside detected climbs. This catches short
        steep pitches on otherwise rolling routes that don't form sustained
        climbs (and therefore don't appear in the climbs[] array). Coach
        protocol uses max_grade_pct ≥ 10 as a "surface terrain" trigger;
        gating that on detected-climb max would miss exactly the rides
        where a single short kicker mattered.
        """
        CHUNK_M = 200.0
        total_dist = cum_dist[-1] if cum_dist else 0.0
        if total_dist < CHUNK_M:
            return ({"flat_pct": 100.0, "gentle_pct": 0.0, "moderate_pct": 0.0, "steep_pct": 0.0}, 0.0)
        
        buckets = {"flat": 0.0, "gentle": 0.0, "moderate": 0.0, "steep": 0.0}
        max_grade = 0.0
        n = len(cum_dist)
        i = 0
        chunk_start_dist = 0.0
        while i < n - 1:
            # Advance j until chunk_distance >= CHUNK_M or end of track
            j = i
            while j < n - 1 and cum_dist[j] - chunk_start_dist < CHUNK_M:
                j += 1
            chunk_dist = cum_dist[j] - chunk_start_dist
            if chunk_dist <= 0:
                break
            ele_change = smoothed_ele[j] - smoothed_ele[i]
            grade_pct = abs(ele_change / chunk_dist * 100.0)
            if grade_pct > max_grade:
                max_grade = grade_pct
            if grade_pct < 1.0:
                buckets["flat"] += chunk_dist
            elif grade_pct < 3.0:
                buckets["gentle"] += chunk_dist
            elif grade_pct < 6.0:
                buckets["moderate"] += chunk_dist
            else:
                buckets["steep"] += chunk_dist
            chunk_start_dist = cum_dist[j]
            i = j
        
        return ({
            "flat_pct": round(buckets["flat"] / total_dist * 100, 1),
            "gentle_pct": round(buckets["gentle"] / total_dist * 100, 1),
            "moderate_pct": round(buckets["moderate"] / total_dist * 100, 1),
            "steep_pct": round(buckets["steep"] / total_dist * 100, 1),
        }, round(max_grade, 1))
    
    def _streams_to_trackpoints(self, streams: List[Dict]) -> List[Dict]:
        """
        Convert Intervals.icu streams response into trackpoint dicts compatible
        with _analyze_terrain.
        
        Intervals stores latlng as a single stream object with two parallel
        arrays: `data` holds latitudes, `data2` holds longitudes (NOT the Strava
        paired-array convention). Altitude is its own stream with a `data` array.
        
        Skips trackpoints where either lat or lng is None (GPS dropout). Altitude
        is included when present and non-None at the same index.
        """
        latlng_stream = next((s for s in streams if s.get("type") == "latlng"), None)
        altitude_stream = next((s for s in streams if s.get("type") == "altitude"), None)
        if not latlng_stream:
            return []
        
        lat_arr = latlng_stream.get("data") or []
        lng_arr = latlng_stream.get("data2") or []
        ele_arr = (altitude_stream.get("data") if altitude_stream else None) or []
        
        n = min(len(lat_arr), len(lng_arr))
        trackpoints = []
        for i in range(n):
            lat, lng = lat_arr[i], lng_arr[i]
            if lat is None or lng is None:
                continue
            tp = {"lat": float(lat), "lon": float(lng)}
            if i < len(ele_arr) and ele_arr[i] is not None:
                tp["ele"] = float(ele_arr[i])
            trackpoints.append(tp)
        return trackpoints
    
    @staticmethod
    def _terrain_native_boundaries(cum_dist, smoothed_ele, ascending):
        """Native relative-dip parents and all positive 1.5% excess cores."""
        n = len(cum_dist)
        if n < 2:
            return []
        sign = 1 if ascending else -1
        y = [sign * value for value in smoothed_ele]
        d = cum_dist
        reference = 1.5 / 100
        spans = []
        i = 0
        while i < n - 1:
            length = d[i + 1] - d[i]
            if length <= 0 or (y[i + 1] - y[i]) / length < reference:
                i += 1
                continue
            peak = i
            j = i + 1
            while j < n:
                if y[j] > y[peak]:
                    peak = j
                allowance = max(2.5, 0.05 * (y[peak] - y[i]))
                if y[peak] - y[j] > allowance:
                    break
                j += 1
            pending = [(i, peak)]
            while pending:
                lo, hi = pending.pop()
                low = start = end = lo
                best = 0.0
                for k in range(lo + 1, hi + 1):
                    value = y[k] - y[low] - reference * (d[k] - d[low])
                    if value > best:
                        start, end, best = low, k, value
                    if y[k] - reference * d[k] < y[low] - reference * d[low]:
                        low = k
                if end > start:
                    spans.append((start, end))
                    if lo < start:
                        pending.append((lo, start))
                    if end < hi:
                        pending.append((end, hi))
            i = max(peak, i + 1)
        return sorted(spans)

    @staticmethod
    def _terrain_rolling_gradient(d, y):
        """Centered native secant within a fixed 200 m window."""
        from bisect import bisect_left, bisect_right
        window = 200
        result = []
        for i, x in enumerate(d):
            lo = bisect_left(d, x - window / 2, 0, i + 1)
            hi = max(i, bisect_right(d, x + window / 2, i) - 1)
            result.append(100 * (y[hi] - y[lo]) / (d[hi] - d[lo])
                          if d[hi] > d[lo] else 0)
        return result

    @staticmethod
    def _terrain_valley_splits(spans, d, y, g):
        """Split persistent valleys at a shared native saddle; protect 100 m gain."""
        from bisect import bisect_left, bisect_right
        window, fraction = 200, 0.25
        out, pending = [], list(spans)
        while pending:
            a, b = pending.pop()
            if y[b] - y[a] >= 100:
                out.append((a, b))
                continue
            lo = bisect_left(d, d[a] + window, a, b + 1)
            hi = bisect_right(d, d[b] - window, lo, b + 1) - 1
            if hi < lo:
                out.append((a, b))
                continue
            k = min(range(lo, hi + 1), key=lambda j: g[j])
            threshold = fraction * min(max(g[a:k]), max(g[k + 1:b + 1]))
            left = right = k
            if g[k] < threshold:
                while left > a and g[left - 1] < threshold:
                    left -= 1
                while right < b and g[right + 1] < threshold:
                    right += 1
            if g[k] >= threshold or d[right] - d[left] < window / 4:
                out.append((a, b))
                continue
            pending.extend(((a, k), (k, b)))
        return sorted(out)

    @staticmethod
    def _terrain_bounded_ends(spans, d, g):
        """Extend supported ends by at most 100 m and a fixed neighbor midpoint."""
        from bisect import bisect_left
        window, fraction = 200, 0.25
        out = []
        for i, (a, b) in enumerate(spans):
            hi = (bisect_left(d, (d[b] + d[spans[i + 1][0]]) / 2)
                  if i + 1 < len(spans) else len(d) - 1)
            end = b
            threshold = fraction / 2 * max(g[a:b + 1])
            while b < hi and g[b + 1] > threshold and d[b + 1] - d[end] <= window / 2:
                b += 1
            out.append((a, b))
        return out

    @staticmethod
    def _terrain_boundaries(cum_dist, smoothed_ele, ascending):
        """Fixed segmentation composition on original 50 m-smoothed native samples.

        Six fixed constants: 1.5%, 2.5 m, 5%, 200 m, one quarter, 100 m.
        Dwell, exit support and extension are derived from window/fraction.
        Explicit stacks avoid recursion limits; worst-case searches are not linear.
        """
        if len(cum_dist) < 2:
            return []
        y = [value if ascending else -value for value in smoothed_ele]
        g = IntervalsSync._terrain_rolling_gradient(cum_dist, y)
        spans = IntervalsSync._terrain_native_boundaries(cum_dist, smoothed_ele, ascending)
        spans = IntervalsSync._terrain_valley_splits(spans, cum_dist, y, g)
        return IntervalsSync._terrain_bounded_ends(spans, cum_dist, g)

    def _detect_segments(self, trackpoints: List[Dict], cum_dist: List[float],
                         smoothed_ele: List[float], min_gradient: float,
                         min_distance: float, ascending: bool,
                         athlete_units: Optional[Dict[str, str]] = None) -> List[Dict]:
        """
        Detect native climb/descent spans with fixed native boundaries.
        Admission and formatting measure the original smoothed profile.
        athlete_units adds the existing preferred-unit display block.
        """
        segments = []
        for seg_start_idx, seg_end_idx in self._terrain_boundaries(cum_dist, smoothed_ele, ascending):
            seg_dist = cum_dist[seg_end_idx] - cum_dist[seg_start_idx]
            seg_ele = smoothed_ele[seg_end_idx] - smoothed_ele[seg_start_idx]
            
            # Check minimum criteria
            if seg_dist >= min_distance:
                avg_gradient = (seg_ele / seg_dist) * 100 if seg_dist > 0 else 0
                
                if (ascending and avg_gradient >= min_gradient) or \
                   (not ascending and avg_gradient <= -min_gradient):
                    
                    position_km = round(cum_dist[seg_start_idx] / 1000, 1)
                    distance_km = round(seg_dist / 1000, 1)
                    elevation_m = round(abs(seg_ele))
                    signed_elevation_m = elevation_m if ascending else -elevation_m
                    
                    segment = {
                        "position_km": position_km,
                        "distance_km": distance_km,
                        "elevation_m": signed_elevation_m,
                        "avg_gradient_pct": round(abs(avg_gradient), 1),
                        "start_coords": [round(trackpoints[seg_start_idx]["lat"], 5),
                                         round(trackpoints[seg_start_idx]["lon"], 5)],
                        "end_coords": [round(trackpoints[seg_end_idx]["lat"], 5),
                                       round(trackpoints[seg_end_idx]["lon"], 5)],
                        "display": {
                            "position": self._to_display(position_km, "distance", athlete_units),
                            "distance": self._to_display(distance_km, "distance", athlete_units),
                            "elevation": self._to_display(signed_elevation_m, "elevation", athlete_units),
                        }
                    }
                    
                    if ascending:
                        # Max gradient over 200m subsections
                        max_grad = 0.0
                        for k in range(seg_start_idx, seg_end_idx):
                            for m in range(k + 1, seg_end_idx + 1):
                                sub_dist = cum_dist[m] - cum_dist[k]
                                if sub_dist >= 200:
                                    sub_grad = abs((smoothed_ele[m] - smoothed_ele[k]) / sub_dist * 100)
                                    max_grad = max(max_grad, sub_grad)
                                    break
                        segment["max_gradient_pct"] = round(max_grad, 1) if max_grad > 0 else segment["avg_gradient_pct"]
                        
                        # UCI-derived climb category
                        if elevation_m >= 1000:
                            segment["category"] = "HC"
                        elif elevation_m >= 650:
                            segment["category"] = "Cat 1"
                        elif elevation_m >= 400:
                            segment["category"] = "Cat 2"
                        elif elevation_m >= 200:
                            segment["category"] = "Cat 3"
                        elif elevation_m >= 100:
                            segment["category"] = "Cat 4"
                        else:
                            segment["category"] = None  # uncategorized — below Cat 4 threshold
                    else:
                        segment["avg_gradient_pct"] = -segment["avg_gradient_pct"]
                    
                    segments.append(segment)
            
        return segments
    
    def _fetch_today_wellness(self) -> Dict:
        """
        Fetch today's wellness data which contains:
        - CTL, ATL, rampRate (but these include planned workouts!)
        - sportInfo with eFTP, W', P-max (accurate live estimates)
        - VO2max, sleep quality/hours, etc.
        """
        today = datetime.now().strftime("%Y-%m-%d")
        if hasattr(self, "_wellness_union") and not getattr(self, "_wellness_separate", False):
            row = next((w for w in self._wellness_union if w.get("id") == today), None)
            if row is not None:
                return AcquisitionStore.clone(row)
            # A missing list row cannot prove that the day object is absent.
            # Preserve its direct-read fallback, including generated-only fields.
        try:
            data = self._intervals_get(f"wellness/{today}")
            return data
        except Exception as e:
            if self.debug:
                print(f"  Could not fetch today's wellness: {e}")
            return {}
    
    def _extract_power_model_from_wellness(self, wellness_data: Dict) -> Dict:
        """
        Extract eFTP, W', P-max from wellness.sportInfo.
        These are the accurate live estimates that match the Intervals.icu UI.
        """
        # v3.124: sportInfo arrives present-but-null from third-party wellness clients,
        # so the [] default never applies. Same for the reads below.
        sport_info = wellness_data.get("sportInfo") or []
        
        # Find cycling sport info
        cycling_info = None
        for sport in sport_info:
            if sport.get("type") == "Ride":
                cycling_info = sport
                break
        
        if not cycling_info:
            return {
                "eftp": None,
                "w_prime": None,
                "w_prime_kj": None,
                "p_max": None,
                "source": "unavailable"
            }
        
        eftp = cycling_info.get("eftp")
        w_prime = cycling_info.get("wPrime")
        p_max = cycling_info.get("pMax")
        
        if self.debug and eftp:
            print(f"  eFTP: {round(eftp)}W, W': {round(w_prime) if w_prime else 'N/A'}J, P-max: {round(p_max) if p_max else 'N/A'}W")
        
        return {
            "eftp": round(eftp, 1) if eftp else None,
            "w_prime": round(w_prime) if w_prime else None,
            "w_prime_kj": round(w_prime / 1000, 1) if w_prime else None,
            "p_max": round(p_max) if p_max else None,
            "source": "wellness.sportInfo"
        }
    
    def _load_ftp_history(self) -> Dict[str, Dict[str, int]]:
        """
        Load FTP history from local JSON file.
        
        Returns dict with structure:
        {
            "indoor": {"2026-01-01": 270, "2026-02-01": 275},
            "outdoor": {"2026-01-01": 280, "2026-02-01": 287}
        }
        """
        ftp_history_path = self.data_dir / self.FTP_HISTORY_FILE
        
        if ftp_history_path.exists():
            try:
                with open(ftp_history_path, 'r') as f:
                    data = json.load(f)
                    # Handle legacy format (flat dict) -> convert to new format
                    if data and not ("indoor" in data or "outdoor" in data):
                        if self.debug:
                            print(f"  Converting legacy FTP history format...")
                        return {"indoor": {}, "outdoor": data}
                    return data
            except Exception as e:
                if self.debug:
                    print(f"  Could not load FTP history: {e}")
                return {"indoor": {}, "outdoor": {}}
        return {"indoor": {}, "outdoor": {}}
    
    def _save_ftp_history(self, history: Dict[str, Dict[str, int]], 
                          current_ftp_indoor: int, current_ftp_outdoor: int) -> Dict[str, Dict[str, int]]:
        """
        Save current FTPs to history file.
        Tracks indoor and outdoor FTP separately.
        Only adds entry if FTP changed from most recent entry.
        """
        today = datetime.now().strftime("%Y-%m-%d")
        
        # Ensure structure exists
        if "indoor" not in history:
            history["indoor"] = {}
        if "outdoor" not in history:
            history["outdoor"] = {}
        
        # Update indoor FTP if changed
        if current_ftp_indoor:
            indoor_history = history["indoor"]
            if indoor_history:
                sorted_dates = sorted(indoor_history.keys(), reverse=True)
                most_recent = indoor_history[sorted_dates[0]]
                if current_ftp_indoor != most_recent:
                    history["indoor"][today] = current_ftp_indoor
                    if self.debug:
                        print(f"  Indoor FTP changed: {most_recent} → {current_ftp_indoor}")
            else:
                history["indoor"][today] = current_ftp_indoor
                if self.debug:
                    print(f"  Indoor FTP recorded: {current_ftp_indoor}")
        
        # Update outdoor FTP if changed
        if current_ftp_outdoor:
            outdoor_history = history["outdoor"]
            if outdoor_history:
                sorted_dates = sorted(outdoor_history.keys(), reverse=True)
                most_recent = outdoor_history[sorted_dates[0]]
                if current_ftp_outdoor != most_recent:
                    history["outdoor"][today] = current_ftp_outdoor
                    if self.debug:
                        print(f"  Outdoor FTP changed: {most_recent} → {current_ftp_outdoor}")
            else:
                history["outdoor"][today] = current_ftp_outdoor
                if self.debug:
                    print(f"  Outdoor FTP recorded: {current_ftp_outdoor}")
        
        # Save to file
        ftp_history_path = self.data_dir / self.FTP_HISTORY_FILE
        try:
            with open(ftp_history_path, 'w') as f:
                json.dump(history, f, indent=2, sort_keys=True)
            if self.debug:
                print(f"  FTP history saved to {ftp_history_path}")
        except Exception as e:
            if self.debug:
                print(f"  Could not save FTP history: {e}")
        
        return history
    
    def _calculate_benchmark_index(self, current_ftp: int, ftp_history: Dict[str, int], 
                                    ftp_type: str = "indoor") -> Tuple[Optional[float], Optional[int]]:
        """
        Calculate Benchmark Index = (FTP_current / FTP_8_weeks_ago) - 1
        
        Returns (benchmark_index, ftp_8_weeks_ago)
        """
        if not current_ftp or not ftp_history:
            return None, None
        
        # Find FTP from ~8 weeks ago (56 days, with ±7 day tolerance)
        target_date = datetime.now() - timedelta(days=56)
        earliest_acceptable = target_date - timedelta(days=7)
        latest_acceptable = target_date + timedelta(days=7)
        
        # Find the closest FTP entry to 8 weeks ago
        best_match_date = None
        best_match_diff = float('inf')
        
        for date_str, ftp in ftp_history.items():
            try:
                entry_date = datetime.strptime(date_str, "%Y-%m-%d")
                
                if earliest_acceptable <= entry_date <= latest_acceptable:
                    diff = abs((entry_date - target_date).days)
                    if diff < best_match_diff:
                        best_match_diff = diff
                        best_match_date = date_str
            except:
                continue
        
        if best_match_date:
            ftp_8_weeks_ago = ftp_history[best_match_date]
            benchmark_index = round((current_ftp / ftp_8_weeks_ago) - 1, 3)
            
            if self.debug:
                print(f"  Benchmark Index ({ftp_type}): {benchmark_index:+.1%} (FTP {ftp_8_weeks_ago} → {current_ftp})")
            
            return benchmark_index, ftp_8_weeks_ago
        
        # No data from 8 weeks ago
        if self.debug:
            sorted_dates = sorted(ftp_history.keys())
            if sorted_dates:
                oldest_date = datetime.strptime(sorted_dates[0], "%Y-%m-%d")
                days_of_history = (datetime.now() - oldest_date).days
                print(f"  Benchmark Index ({ftp_type}) unavailable: only {days_of_history} days of history (need ~56)")
        
        return None, None
    
    def _years_since(self, date_str: Optional[str]) -> Optional[int]:
        """Compute complete years between an ISO YYYY-MM-DD date and today.
        Returns None if missing/malformed. Used for both age (from DOB) and
        platform tenure (from activation date)."""
        if not date_str:
            return None
        try:
            d = datetime.strptime(date_str, "%Y-%m-%d")
            today = datetime.now()
            return today.year - d.year - ((today.month, today.day) < (d.month, d.day))
        except (ValueError, TypeError):
            return None
    
    def _compose_location(self, city: Optional[str], state: Optional[str],
                          country: Optional[str]) -> Optional[str]:
        """Join city/state/country into a display string, stripping trailing spaces
        (Intervals.icu returns 'Aalborg ' / 'Nordjylland ' with trailing whitespace).
        Returns None if all parts are empty/None."""
        parts = [p.strip() for p in (city, state, country) if p and p.strip()]
        return ", ".join(parts) if parts else None
    
    @preserve_budget_outputs
    def collect_training_data(self, days_back: int = 7) -> Dict:
        """Collect all training data for LLM analysis"""
        self._hosted_generation = None
        if not self.begin_tick():
            raise RequestBudgetRefused("top-level tick is not due")
        # v3.157: stream responses are reused only within this sync run.
        self._stream_responses = {}
        # Extended range for ACWR calculation (need 28 days minimum)
        days_for_acwr = self.ACTIVITY_WINDOW_DAYS
        oldest_extended = (datetime.now() - timedelta(days=days_for_acwr - 1)).strftime("%Y-%m-%d")
        oldest_display = (datetime.now() - timedelta(days=days_back - 1)).strftime("%Y-%m-%d")
        newest = datetime.now().strftime("%Y-%m-%d")
        today = datetime.now().strftime("%Y-%m-%d")
        
        print("Fetching athlete data...")
        athlete = self._intervals_get("")
        
        # Athlete profile (stable identity fields from athlete endpoint) — v3.103
        # SECURITY: explicit-allow only. Never serialize the raw athlete dict —
        # it contains icu_api_key, icu_friend_invite_token, and other secrets.
        dob = athlete.get("icu_date_of_birth")
        platform_activated_raw = athlete.get("icu_activated")  # ISO 8601 with time
        platform_activated = platform_activated_raw[:10] if platform_activated_raw else None
        years_on_platform = self._years_since(platform_activated)
        # Normalized unit dict — source of truth for display conversions across
        # all narrative-bearing fields (v3.109). Built before athlete_profile so
        # it can populate athlete_profile.display_preferences and feed
        # _to_display() at every emission site below.
        athlete_units = self._athlete_units_from_dict(athlete)
        
        height_m = athlete.get("height")
        athlete_profile = {
            "date_of_birth": dob,
            "age": self._years_since(dob),
            "height_m": height_m,
            "display": {
                "height": self._to_display(height_m, "height", athlete_units),
            },
            "display_preferences": athlete_units,
            "sex": athlete.get("sex"),
            "location": self._compose_location(
                athlete.get("city"), athlete.get("state"), athlete.get("country")
            ),
            "timezone": athlete.get("timezone"),
            "platform_activated": platform_activated,
            "years_on_platform": years_on_platform,
        }
        athlete_notes = athlete.get("icu_notes")  # raw string passthrough; mini-dossier later
        
        # Per-field unit labels for recent_activities (v3.103)
        # Temp/wind: API returns values in athlete's account unit — label reflects that.
        # Speed: sync.py force-converts m/s → km/h at format time → always "KPH".
        # avg_speed_unit/max_speed_unit retained for backward compatibility; the new
        # display.speed block (v3.109) is the authoritative narration source.
        temp_unit = "F" if athlete.get("fahrenheit") else "C"
        wind_unit = athlete.get("wind_speed") or "MPS"
        speed_unit = "KPH"
        
        # Load previous latest.json — used as persistent state for terrain &
        # weather copy-forward. Empty dict on first sync / fresh data dir.
        previous_latest_lookup = self._load_previous_latest()
        
        # Extract per-sport-family thesholds from user settings
        sport_settings = self._build_sport_thresholds(athlete)
        
        # One 56-date listing supports new curve attribution. Preserve the old
        # sustainability and 28-day slices, including source order and duplicates.
        oldest_sustainability = (datetime.now() - timedelta(
            days=self.SUSTAINABILITY_WINDOW_DAYS - 1)).strftime("%Y-%m-%d")
        print("Fetching activities (ACWR + sustainability window)...")
        oldest_curves = (datetime.strptime(today, "%Y-%m-%d") - timedelta(days=55)).strftime("%Y-%m-%d")
        activities_curves = self._intervals_get("activities", {
            "oldest": min(oldest_extended, oldest_sustainability, oldest_curves), "newest": newest})
        activities_sustainability = [a for a in activities_curves
            if a.get("start_date_local", "")[:10] >= min(oldest_extended, oldest_sustainability)]
        activities_extended = [a for a in activities_sustainability
                               if a.get("start_date_local", "")[:10] >= oldest_extended]
        
        # Filter to display range for recent_activities
        activities_display = [a for a in activities_extended 
                             if a.get("start_date_local", "")[:10] >= oldest_display]
        
        print("Fetching wellness data...")
        oldest_sleep = (datetime.strptime(today, "%Y-%m-%d") - timedelta(days=34)).strftime("%Y-%m-%d")
        self._wellness_union = self._intervals_get("wellness", {
            "oldest": min(oldest_display, oldest_sleep), "newest": newest})
        union_oldest = min(oldest_display, oldest_sleep)
        wellness_status = self._acquisition.source_status("wellness")
        current_wellness = wellness_status is None or wellness_status["status"] == "fresh"
        self._wellness_separate = current_wellness and any(not isinstance(w.get("id"), str)
            or not re.fullmatch(r"\d{4}-\d{2}-\d{2}", w["id"])
            or not union_oldest <= w["id"] <= newest for w in self._wellness_union)
        def wellness_slice(oldest, newest):
            # A malformed or out-of-range row cannot safely be assigned to a
            # narrower endpoint. Preserve the original endpoint's raw response.
            if self._wellness_separate:
                if oldest == union_oldest:
                    return AcquisitionStore.clone(self._wellness_union)
                return self._intervals_get("wellness", {"oldest": oldest, "newest": newest})
            return [AcquisitionStore.clone(w) for w in self._wellness_union
                    if isinstance(w.get("id"), str) and oldest <= w["id"] <= newest]
        wellness = wellness_slice(oldest_display, newest)
        wellness_sleep = wellness_slice(oldest_sleep, newest)
        acquired = wellness_status["source_acquired_at"] if wellness_status else None
        sleep_context = self._build_sleep_context(
            wellness_sleep, today, athlete.get("timezone"),
            datetime.fromisoformat(acquired.replace("Z", "+00:00")) if acquired else datetime.now(timezone.utc))
        wellness_extended = [w for w in wellness_sleep if isinstance(w, dict)
                             and isinstance(w.get("id"), str)
                             and oldest_extended <= w["id"] <= newest]
        
        # Fetch today's wellness for live estimates (eFTP, W', P-max, VO2max, etc.)
        print("Fetching today's wellness (eFTP, W', P-max, VO2max)...")
        today_wellness = self._fetch_today_wellness()
        
        # Extract power model from wellness (accurate live estimates)
        power_model = self._extract_power_model_from_wellness(today_wellness)
        
        # Extract additional metrics from today's wellness
        vo2max = today_wellness.get("vo2max")
        
        # Get API values for fitness metrics (these include planned workouts!)
        api_ctl = today_wellness.get("ctl")
        api_atl = today_wellness.get("atl")
        api_ramp_rate = today_wellness.get("rampRate")
        
        # Fetch yesterday's wellness for decay fallback
        print("Fetching fitness metrics...")
        try:
            yesterday = (datetime.now() - timedelta(days=1)).strftime("%Y-%m-%d")
            yesterday_wellness = wellness_slice(yesterday, yesterday)
            yesterday_data = yesterday_wellness[0] if yesterday_wellness else {}
            
            # PMC decay constants
            ctl_decay = math.exp(-1/42)  # ~0.9765
            atl_decay = math.exp(-1/7)   # ~0.8668
            
            yesterday_ctl = yesterday_data.get("ctl")
            yesterday_atl = yesterday_data.get("atl")
            yesterday_ramp = yesterday_data.get("rampRate")
            
            # Decayed values = what fitness looks like with zero training today
            decayed_ctl = round(yesterday_ctl * ctl_decay, 2) if yesterday_ctl else None
            decayed_atl = round(yesterday_atl * atl_decay, 2) if yesterday_atl else None
            decayed_ramp = round(yesterday_ramp * ctl_decay, 2) if yesterday_ramp else None
        except:
            decayed_ctl = None
            decayed_atl = None
            decayed_ramp = None
            yesterday_ramp = None
        
        latest_wellness = wellness[-1] if wellness else {}
        
        # Fetch planned workouts (EXTENDED: include past 7 days for Consistency Index, 90 days ahead for race calendar)
        print("Fetching planned workouts (past + future for Consistency Index + race calendar)...")
        # Current identity spans 28 days; step/stream retention remains 14 days.
        # past_events keeps its original days_back slice — the Consistency Index
        # denominator must not move as a side effect of widening this fetch.
        past_events_cutoff = (datetime.now() - timedelta(days=days_back - 1)).strftime("%Y-%m-%d")
        oldest_events = (datetime.now() - timedelta(
            days=max(days_back - 1, days_for_acwr - 1, self.INTERVAL_RETENTION_DAYS))).strftime("%Y-%m-%d")
        newest_ahead = (datetime.now() + timedelta(days=90)).strftime("%Y-%m-%d")
        events = self._intervals_get("events", {"oldest": oldest_events, "newest": newest_ahead, "resolve": "true"})
        
        # Split events into past (for consistency), near future (for planned workouts display), and all future (for race calendar)
        past_events = [e for e in events
                       if past_events_cutoff <= e.get("start_date_local", "")[:10] <= today]
        # Full-depth past slice for the interval pairing map only. past_events above
        # stays at days_back for the Consistency Index; this one reaches retention.
        pairing_events = [e for e in events if e.get("start_date_local", "")[:10] <= today]
        future_events = [e for e in events if e.get("start_date_local", "")[:10] >= today]
        planned_cutoff = (datetime.now() + timedelta(days=42)).strftime("%Y-%m-%d")
        near_future_events = [e for e in events
                              if (e.get("start_date_local") or "")[:10]
                              and e["start_date_local"][:10] <= planned_cutoff
                              and self._calendar_end_date(e) >= today]
        
        # Health context (v3.128, issue #27). Calendar SICK / INJURED markers reach
        # planned_workouts now retains returned in-progress spans, but cannot see
        # markers whose start precedes the main events request's lookback floor.
        # The builder runs its own filtered fetch with a year-long lookback; `events` is
        # passed as the degraded fallback if that fetch fails.
        print("Building health context...")
        health_context = self._build_health_context(
            fallback_events=events, latest_wellness=latest_wellness,
            today=today, fallback_oldest=oldest_events
        )
        
        # Smart fitness metrics: same logic for CTL, ATL, TSB, and ramp rate
        # API values include planned workouts → inflated if not yet completed
        # Decayed values = yesterday × decay → accurate baseline before any training today
        # v3.128: only load-bearing categories inflate the API's CTL/ATL. A SICK,
        # INJURED, NOTE or HOLIDAY marker dated today carries no planned load, so it
        # must not select the decayed branch or make fitness_source claim that planned
        # workouts are not yet completed. No fitness figure moves: with no planned load
        # today the decayed and API branches produce the same values.
        todays_planned = [e for e in events
                          if e.get("start_date_local", "")[:10] == today
                          and e.get("category", "") in self.TRAINING_EVENT_CATEGORIES]
        todays_activities = [a for a in activities_display if a.get("start_date_local", "")[:10] == today]
        
        if todays_planned and not todays_activities:
            # Planned workouts exist but nothing completed → decay (API values are inflated)
            ctl = decayed_ctl
            atl = decayed_atl
            smart_ramp_rate = decayed_ramp if decayed_ramp else api_ramp_rate
            fitness_source = "Decayed from yesterday (today's planned workouts not yet completed)"
        else:
            # No planned workouts OR workouts completed → API values are accurate
            ctl = round(api_ctl, 2) if api_ctl else decayed_ctl
            atl = round(api_atl, 2) if api_atl else decayed_atl
            smart_ramp_rate = round(api_ramp_rate, 2) if api_ramp_rate else decayed_ramp
            fitness_source = "From Intervals.icu API (reflects completed workouts)"
        
        tsb = round(ctl - atl, 2) if (ctl is not None and atl is not None) else None
        
        # Get both FTP values for cycling (user-set, not estimated)
        cycling = sport_settings.get("cycling", {})
        current_ftp_indoor = cycling.get("ftp_indoor")
        current_ftp_outdoor = cycling.get("ftp")
        
        # Load and update FTP history (tracks both indoor and outdoor)
        print("Updating FTP history...")
        ftp_history = self._load_ftp_history()
        ftp_history = self._save_ftp_history(ftp_history, current_ftp_indoor, current_ftp_outdoor)
        
        # Calculate Benchmark Index for both
        benchmark_index_indoor, ftp_8_weeks_ago_indoor = self._calculate_benchmark_index(
            current_ftp_indoor, ftp_history.get("indoor", {}), "indoor"
        )
        benchmark_index_outdoor, ftp_8_weeks_ago_outdoor = self._calculate_benchmark_index(
            current_ftp_outdoor, ftp_history.get("outdoor", {}), "outdoor"
        )
        
        # Generate routes.json from GPX/TCX attachments (v3.93)
        print("Scanning events for route attachments...")
        terrain_event_ids = self._generate_terrain(events, athlete_units=athlete_units)
        self._terrain_event_ids = terrain_event_ids
        self._generate_route_weather(events, activities_extended, previous_latest_lookup, athlete,
                                     RouteWeather.eta_inputs(cycling, latest_wellness, athlete))
        if terrain_event_ids:
            print(f"   🗺️  Route data for {len(terrain_event_ids)} event(s)")

        # Saved Workouts Mirror (v3.132) - read-only, independently throttled.
        # Non-critical: a mirror problem must never abort a sync whose training data
        # is sound, and the last good snapshot is retained on any failure.
        try:
            saved_workouts = self._generate_saved_workouts(
                force=getattr(self, "_force_saved_workouts", False))
            if saved_workouts is not None:
                print(f"   📑 Saved workouts: {self._sw_status_line(saved_workouts)}")
        except Exception as e:
            # _generate_saved_workouts already persists a stale/unavailable state for
            # any internal failure. This guard only keeps a mirror problem from
            # aborting a sync whose training data is sound; it must not discard the
            # state that was built, or the previous file would keep claiming ok.
            print(f"   ⚠️ Saved workouts refresh failed (non-critical): {e}")
        
        # Build race calendar (v3.5.0) — moved before derived metrics for phase detection
        print("Building race calendar...")
        race_calendar = self._build_race_calendar(
            future_events=future_events,
            current_ctl=ctl,
            current_atl=atl,
            current_tsb=tsb,
            activities_7d=activities_display,
            today=today,
            athlete_units=athlete_units
        )
        
        # Format planned workouts — used by both phase detection and output
        formatted_planned_workouts = self._format_events(near_future_events, today=today)
        
        # Fetch power curves for delta analysis (two 28-day windows)
        print("Fetching power curves...")
        power_curve_data = None
        pc_dates = None
        try:
            pc_end1 = today
            pc_start1 = (datetime.now() - timedelta(days=27)).strftime("%Y-%m-%d")
            pc_end2 = (datetime.now() - timedelta(days=28)).strftime("%Y-%m-%d")
            pc_start2 = (datetime.now() - timedelta(days=55)).strftime("%Y-%m-%d")
            pc_dates = (pc_start1, pc_end1, pc_start2, pc_end2)
            power_curve_data = self._intervals_get("power-curves", {
                "type": "Ride",
                "curves": f"r.{pc_start1}.{pc_end1},r.{pc_start2}.{pc_end2}"
            })
        except Exception as e:
            if self.debug:
                print(f"  ⚠️  Power curve fetch failed: {e}")
        
        # Fetch HR curves for delta analysis (same windows, no sport filter)
        print("Fetching HR curves...")
        hr_curve_data = None
        try:
            hr_curve_data = self._intervals_get("hr-curves", {
                "curves": f"r.{pc_dates[0]}.{pc_dates[1]},r.{pc_dates[2]}.{pc_dates[3]}"
            }) if pc_dates else None
        except Exception as e:
            if self.debug:
                print(f"  ⚠️  HR curve fetch failed: {e}")
        
        # Fetch sustainability curves (v3.91) — sport-filtered power + HR, single 42d window
        print("Fetching sustainability curves...")
        sustainability_curves = {}
        sus_end = today
        sus_start = (datetime.now() - timedelta(days=self.SUSTAINABILITY_WINDOW_DAYS - 1)).strftime("%Y-%m-%d")
        sus_window = (sus_start, sus_end)
        
        # Determine which sport families have recent activity data
        active_sport_families = set()
        for a in activities_extended:
            sf = self.SPORT_FAMILIES.get(a.get("type", ""), None)
            if sf and sf in self.SUSTAINABILITY_ANCHORS:
                active_sport_families.add(sf)
        
        for sport_family in active_sport_families:
            sport_curves = {"power": {}, "hr": {}}
            
            # Power curves — one fetch per activity type (cycling: Ride + VirtualRide)
            power_types = self.SUSTAINABILITY_POWER_TYPES.get(sport_family, [])
            for ptype in power_types:
                try:
                    data = self._intervals_get("power-curves", {
                        "type": ptype,
                        "curves": f"r.{sus_start}.{sus_end}"
                    })
                    sport_curves["power"][ptype] = data
                except Exception as e:
                    if self.debug:
                        print(f"  ⚠️  Sustainability power-curves ({ptype}) failed: {e}")
            
            # HR curves — one fetch per activity type
            hr_types = self.SUSTAINABILITY_HR_TYPES.get(sport_family, [])
            for htype in hr_types:
                try:
                    data = self._intervals_get("hr-curves", {
                        "type": htype,
                        "curves": f"r.{sus_start}.{sus_end}"
                    })
                    sport_curves["hr"][htype] = data
                except Exception as e:
                    if self.debug:
                        print(f"  ⚠️  Sustainability hr-curves ({htype}) failed: {e}")
            
            sustainability_curves[sport_family] = sport_curves
        
        if sustainability_curves:
            print(f"  📊 Sustainability curves fetched for: {', '.join(sorted(sustainability_curves.keys()))}")
        else:
            print("  📊 No sport families with sustainability data")
        
        # Generate interval-level data (v3.82, expanded v3.99)
        # Uses the already-fetched activity list — no extra listing API calls.
        # Pre-filters by sport family whitelist; no longer requires interval_summary.
        # Incremental: only fetches intervals for new qualifying activities.
        # MUST run before _calculate_derived_metrics so self._intervals_data is
        # populated when _calculate_dfa_a1_profile reads it (v3.99 fix).
        print("Checking for interval data...")
        # v3.113: pass the 28d extended set (not the 7d display set) so first-run backfill
        # reaches the full 14d retention window, and supply the present-ID set for stale-entry
        # pruning. Scan cutoff inside _generate_intervals still limits what actually gets fetched.
        present_ids = {str(a.get("id")) for a in activities_extended if a.get("id")}
        interval_activity_ids = self._generate_intervals(
            activities_extended, present_activity_ids=present_ids, events=pairing_events)
        if interval_activity_ids:
            print(f"  📊 {len(interval_activity_ids)} activit{'y' if len(interval_activity_ids) == 1 else 'ies'} with interval data")

        self._prepare_session_structures(
            activities_extended, events, previous_latest_lookup)
        
        # Calculate derived metrics for Section 11 compliance
        print("Calculating derived metrics...")
        derived_metrics = self._calculate_derived_metrics(
            activities_7d=activities_display,
            activities_28d=activities_extended,
            wellness_7d=wellness,
            wellness_extended=wellness_extended,
            current_ctl=ctl,
            current_atl=atl,
            current_tsb=tsb,
            past_events=past_events,
            activities_for_consistency=activities_display,
            power_model=power_model,
            benchmark_indoor=(benchmark_index_indoor, ftp_8_weeks_ago_indoor, current_ftp_indoor),
            benchmark_outdoor=(benchmark_index_outdoor, ftp_8_weeks_ago_outdoor, current_ftp_outdoor),
            vo2max=vo2max,
            formatted_planned_workouts=formatted_planned_workouts,
            race_calendar=race_calendar,
            power_curve_data=power_curve_data,
            power_curve_dates=pc_dates,
            hr_curve_data=hr_curve_data,
            sustainability_curves=sustainability_curves,
            sustainability_window=sus_window,
            sport_settings=sport_settings,
            icu_weight=athlete.get("icu_weight")
        )
        
        # New requests follow the existing data reads and share their retry budget.
        derived_metrics["capability"]["curve_deltas_by_sport"] = self._sport_curve_deltas(
            activities_curves, derived_metrics["report_intensity_28d"]["selected"], pc_dates)

        # Generate alerts array (v3.3.0)
        print("Evaluating alert thresholds...")
        alerts = self._generate_alerts(
            derived_metrics=derived_metrics,
            wellness_7d=wellness,
            tss_7d_total=derived_metrics.get("tss_7d_total", 0),
            tss_28d_total=derived_metrics.get("tss_28d_total", 0)
        )
        
        if alerts:
            alarm_count = sum(1 for a in alerts if a["severity"] == "alarm")
            warning_count = sum(1 for a in alerts if a["severity"] == "warning")
            print(f"  ⚠️  {len(alerts)} alerts: {alarm_count} alarm, {warning_count} warning")
        else:
            print("  ✅ No alerts — green light")
        
        # Add race-specific alerts
        race_alerts = self._generate_race_alerts(race_calendar)
        if race_alerts:
            alerts.extend(race_alerts)
            print(f"  🏁 {len(race_alerts)} race alert(s) added")
        
        if race_calendar.get("race_week", {}).get("active"):
            rw = race_calendar["race_week"]
            print(f"  🏁 Race week ACTIVE: {rw['current_day']} of '{rw['event_name']}'")
        elif race_calendar.get("taper_alert", {}).get("active"):
            nr = race_calendar.get("next_race", {})
            print(f"  🏁 Taper alert: '{nr.get('name', '?')}' in {nr.get('days_until', '?')} days")
        elif race_calendar.get("next_race"):
            nr = race_calendar["next_race"]
            print(f"  🏁 Next race: '{nr.get('name', '?')}' in {nr.get('days_until', '?')} days")
        else:
            print("  🏁 No races in 90-day window")
        
        # Compute readiness decision (v3.72)
        print("Computing readiness decision...")
        readiness_decision = self._compute_readiness_decision(
            derived_metrics=derived_metrics,
            alerts=alerts,
            latest_wellness=latest_wellness,
            activities=activities_extended,
            race_calendar=race_calendar,
            current_tsb=tsb
        )
        rd_rec = readiness_decision["recommendation"].upper()
        rd_pri = readiness_decision["priority"]
        print(f"  {'🟢' if rd_rec == 'GO' else '🟡' if rd_rec == 'MODIFY' else '🔴'} Readiness: {rd_rec} (P{rd_pri})")
        
        # History confidence (v3.3.0)
        history_info = self._get_history_confidence()
        
        data = {
            "report_intensity_schema": self._report_intensity_schema(),
            "READ_THIS_FIRST": {
                "state_note": DataOverview.STATE_NOTE,
                "interval_data_note": self.INTERVAL_DATA_NOTE,
                "report_intensity_note": self.REPORT_INTENSITY_NOTE,
                "instruction_for_ai": "DO NOT calculate totals from individual activities. Use the pre-calculated values in 'summary', 'weekly_summary', and 'derived_metrics' sections below. These are already computed accurately from the API data.",
                "display_formatting": "For durations and sleep, always display the '_formatted' fields (e.g., sleep_formatted, duration_formatted, total_training_formatted) instead of converting decimal '_hours' values. The formatted fields are pre-calculated from raw seconds and avoid rounding errors.",
                "data_period": f"Last {days_back} days (including today)",
                "extended_data_note": f"ACWR and baselines calculated from {days_for_acwr} days of data",
                "sleep_context_note": (
                    "Read top-level sleep_context for descriptive multi-night sleep context. "
                    "Fresh 35-date wellness read; disjoint 28-night median plus seven dated nights. "
                    "repeat_context requires the latest three nights each strictly below that median "
                    "and their combined difference >=3600 seconds. Read status, reason, dates, "
                    "coverage and source_updated_at; unknown timezone or date mismatch is unavailable. "
                    "Use supplied formatted durations. Low confidence, not sleep debt or a readiness "
                    "signal; never add it to counts, P0/P1 or Go/Modify/Skip. Fragmentation comes only "
                    "from explicit dated athlete statements in the current conversation, never sync."
                ),
                "dfa_drift_note": (
                    "DFA drift uses original_index_thirds_v1 in intervals schema 2. Read drift_quality "
                    "and quality.coverage_by_third in detailed blocks, summaries and latest_session. "
                    "Only sufficient data with the recognized method, eligible status, empty reasons, "
                    "verified_1hz timing and interpretable=true licenses an eligible endpoint contrast. "
                    "A numeric delta may be descriptive only; null is unavailable, not zero. Name the "
                    "supplied reasons, which need not imply structural intervals. TIZ percentages and "
                    "dominant band describe retained samples; valid_secs/total_secs are sample counts. "
                    "Unknown artifacts are gaps for drift only. Inspect temporal and artifact coverage "
                    "before whole-session claims. The latest-seven-sufficient-session window's drift "
                    "mean uses only eligible contrasts; drift_sessions is its denominator. Eligibility "
                    "does not prove steady workload or eliminate bias from missing data. A physiological "
                    "drift flag additionally requires steady easy/endurance cycling context and delta "
                    "strictly below -0.2; without that context use descriptive wording. DFA remains "
                    "Tier 2 and never changes readiness, phase progression or configured thresholds."
                ),
                "capability_metrics_note": "The 'capability' block in derived_metrics contains durability trend (aggregate decoupling 7d/28d), efficiency factor trend (aggregate EF 7d/28d), HRRc trend (heart rate recovery 7d/28d), TID comparison (7d vs 28d distribution drift), power curve delta (MMP shift at anchor durations across 28d windows — energy system adaptation direction), HR curve delta (max sustained HR shift at anchor durations — cardiac adaptation, cross-sport), sustainability profile (per-sport power/HR sustainability table for race estimation — 42d window, sport-filtered), and DFA a1 profile (per-session non-linear HRV index from AlphaHRV Connect IQ field — latest_session + trailing_by_sport with crossing-band easy_guard / LT1 / LT2 estimates). These measure HOW the athlete expresses fitness, not just load. Use these for coaching context alongside traditional load metrics. Durability and EF trend direction matters more than absolute values. HRRc is display only — higher = better parasympathetic recovery. Power curve delta rotation_index reveals whether gains are sprint-biased (positive) or endurance-biased (negative). HR curve delta is ambiguous — rising max sustained HR may indicate fitness or fatigue; cross-reference with resting HRV/HR and RPE. Sustainability profile provides race estimation lookup: actual MMP, Coggan predicted (cycling only), CP/W' model (cycling only), model_divergence_pct (actual vs CP — divergence IS the coaching signal). CP/W' is primary for durations ≤20min; Coggan duration factors are the established reference for ≥60min. Source flag (observed_outdoor/observed_indoor) matters for cycling race estimation — indoor MMP is typically 3-5% lower. DFA a1 profile: three self-describing markers (each estimate + crossing block carries marker_dfa_a1) — easy_guard (a1 1.0, a conservative easy-state guard, NOT a threshold), lt1 (a1 0.75, HRVT1 / aerobic threshold), lt2 (a1 0.5, HRVT2 / anaerobic threshold). The literature threshold markers (0.75 / 0.5) are cycling-validated only - non-cycling sports get rollups but validated=False. Every estimate requires a SUSTAINED contiguous crossing: each session's easy_guard_crossing / lt1_crossing / lt2_crossing carries a reason (ok / no_samples_in_band / insufficient_total_dwell / no_contiguous_dwell); scattered in-band time does not produce an estimate. v3.122: dwell is not sufficient. Each crossing also carries estimate_eligible / estimate_reason / n_eligible_segments - a1 reflects the prior 200 beats while watts is instantaneous, so a crossing recorded across varying power blends work and recovery into a number that is not usable as a threshold estimate. avg_hr / avg_watts stay populated on a dwell-qualified but estimate-ineligible crossing as descriptive evidence (a dwell-failed crossing has null averages as before); read estimate_eligible, never infer from absence. Compact lt1_/lt2_ summary fields and all trailing rollups consume eligible crossings only. HR is pooled across sessions; watts are split by environment for cycling (watts_outdoor, watts_indoor with per-environment n_sessions) - only lt2 is ever measured against a configured threshold: lt2_estimate.watts_outdoor against current_status.thresholds.sports.cycling.ftp, lt2_estimate.watts_indoor against current_status.thresholds.sports.cycling.ftp_indoor, and pooled lt2_estimate.hr against current_status.thresholds.sports.cycling.lthr. Non-cycling sports keep pooled watts. easy_guard_estimate, lt1_estimate and lt2_estimate are each gated INDEPENDENTLY - null when that marker has fewer than 3 estimate-ELIGIBLE marker-sessions (v3.122 - not merely dwell-qualified; see easy_guard_eligible_sessions / lt1_eligible_sessions / lt2_eligible_sessions alongside the *_crossing_sessions counts, and note that any gap between them means at least one dwell-qualified marker-session was estimate-rejected). An estimate is null whenever minimum estimate-eligible session depth is not met. If at least one eligible session exists, trailing_by_sport.{sport}.easy_guard_reason / lt1_reason / lt2_reason is insufficient_sessions. If none exists, the staged reason identifies the dominant blocker: dwell failure, incomplete coverage, excessive artifacts, non-positive mean power, or non-stationary power. Do NOT read a null estimate as 'the athlete did not sustain that marker' - read the reason. IMPORTANT: easy_guard is a conservative easy-state compliance guard, NOT an LT1/aerobic-threshold estimate - never compare it to the athlete's configured thresholds and never treat it as a calibration or staleness signal. Only lt2 (0.5) has a configured counterpart and can therefore produce a threshold-comparison coaching observation. lt1 (0.75) is descriptive only: no configured LT1 threshold exists to measure it against, so it never produces a delta, though it may motivate a formal retest. lt1 (0.75) populates only on rides that sustain aerobic-threshold intensity, so it is often null on easy/deload riding - that is expected, not a data gap. Sport-level confidence is a coarse orientation string derived from the maximum eligible-session depth across the THRESHOLD markers lt1 and lt2, with easy_guard excluded - it is orientation only and MUST NOT gate any LT2 comparison, which gates on lt2's own eligible-session depth; per-marker estimate presence + reason are authoritative. DFA a1 is a Tier-2 interpretive signal - does NOT enter the readiness P0-P3 ladder, does NOT classify training phase or establish phase progression, and never auto-updates the configured thresholds; it surfaces a threshold comparison only from lt2, never from lt1 or easy_guard. Quality gate: refuse to interpret any DFA output when latest_session.sufficient=false. Each lt2 comparison is independently complete only with all three of a non-null estimate value, its own matching depth of at least 4, and a non-null configured comparator: lt2_estimate.hr with lt2_estimate.n_sessions and current_status.thresholds.sports.cycling.lthr; lt2_estimate.watts_outdoor with lt2_estimate.n_sessions_outdoor and .ftp; lt2_estimate.watts_indoor with lt2_estimate.n_sessions_indoor and .ftp_indoor. A missing cycling entry and a null comparator fail completeness identically. Depth in one environment never licenses a comparison in the other. Surface a delta only where a complete comparison differs by more than 5%; otherwise report the empirical estimate descriptively. Report no notable delta only when at least one lt2 comparison is complete and every complete difference is 5% or less. Where no comparison is complete, omit the comparison entirely; never use no notable delta as a substitute for the absence of a valid comparison. easy_guard is NOT gated on confidence (it is excluded from it) - interpret easy_guard_estimate from its own reason / n_sessions / quality when present, but never as a calibration signal. See SECTION_11.md DFA a1 Protocol for full interpretation rules.",
                "readiness_decision_note": "The 'readiness_decision' block contains a pre-computed go/modify/skip recommendation with priority level (P0=safety, P1=overload, P2=fatigue, P3=green), individual signal statuses, phase-adjusted thresholds, and structured modification guidance. Use this as the baseline for pre-workout recommendations. Override only under the override rules in SECTION_11.md (Feel/RPE Override): athlete-reported state escalates unconditionally, de-escalation is P2-only, P0/P1 are not overridable. signals.acwr is the START-OF-DAY value from derived_metrics.acwr_start_of_day - the same 7d/28d windows with today's activities excluded - so it does not move when a workout is completed today. derived_metrics.acwr stays live and today-inclusive: retrospective load context only (acwr_readiness_eligible false), never used to approve, modify or veto a later same-day session or tomorrow's. Tomorrow is decided from tomorrow morning's readiness output, whose start-of-day value will include today's training. ACWR alone no longer forces P1 - a Skip needs start-of-day ACWR >= 1.5 plus a corroborating Tier-1 signal, and uncorroborated ACWR counts as an ordinary P2 amber/red. signals.hrv may carry an optional reason: 'rmssd_missing_sdnn_available' means the latest wellness record has no usable rMSSD but does carry SDNN. SDNN is a different metric and is explanatory metadata only - never a readiness input, never treated as HRV. Report HRV as unavailable and name the cause.",
                "health_context_note": "The 'health_context' block carries athlete-reported illness and injury markers. It is CONTEXT, NOT a readiness input - readiness_decision is physiological only and can legitimately read 'go' while clarification_required is true. Calendar markers are matched on the canonical Intervals.icu category (SICK / INJURED), never on the event title. end_date is already converted to the INCLUSIVE last CALENDAR-MARKED day (not the last day the athlete was unwell); Intervals stores an exclusive end. IMPORTANT: end_date_local is the end of the calendar MARKING, not evidence that the illness or injury ended - illness is normally marked for the current day because recovery cannot be predicted. There is deliberately no 'active' field, because a false value would read as 'recovered'. Read marker_active (a marker spans today), recent_marker (a marker ended within recent_window_days and none spans today - recovery status UNKNOWN), and clarification_required. When clarification_required is true, do not give an unqualified full-program recommendation: acknowledge a current marker and establish severity; after a recent marker, ask whether the athlete has recovered rather than assuming it; this escalates only and is never grounds to relax an existing Skip, and never by itself an automatic Skip. wellness_injury is the CURRENT value only (the full series is in wellness_data[].injury and history.json daily_90d[].injury) and contributes to clarification_required only when freshness is 'current' and value >= 3; a 'stale' value is visible context that triggers nothing. source_status 'partial' means the dedicated health fetch failed and the block was built from the narrower main event fetch - marker_active and recent_marker are OMITTED in that case because they were not established, an empty current/recent list is NOT evidence of no marker, and clarification_required stays true. A span beginning before lookback_days is not visible; absence is never proof of no illness.",
                "zone_preference": self.zone_preference if self.zone_preference else "default (power preferred, HR fallback)",
                "wellness_field_scales": {
                    "note": "All categorical wellness fields use a 1-4 positional scale where 1 = best state, 4 = worst state. Labels differ per field but direction is consistent. Fields are null when not reported.",
                    "sleep_quality": {"1": "GREAT", "2": "GOOD", "3": "AVERAGE", "4": "POOR"},
                    "fatigue": {"1": "None", "2": "Some", "3": "High", "4": "Extreme", "ui_note": "Labeled 'Pre training' in Intervals.icu"},
                    "soreness": {"1": "None", "2": "Some", "3": "High", "4": "Extreme", "ui_note": "Labeled 'Pre training' in Intervals.icu"},
                    "stress": {"1": "LOW", "2": "AVG", "3": "HIGH", "4": "EXTREME"},
                    "mood": {"1": "GREAT", "2": "GOOD", "3": "OK", "4": "GRUMPY"},
                    "motivation": {"1": "EXTREME", "2": "HIGH", "3": "AVG", "4": "LOW"},
                    "injury": {"1": "NONE", "2": "NIGGLE", "3": "POOR", "4": "INJURED"},
                    "hydration": {"1": "GOOD", "2": "OK", "3": "POOR", "4": "BAD"},
                    "menstrual": "menstrual_phase and menstrual_phase_predicted are not on the 1-4 scale. Values: PERIOD, FOLLICULAR, OVULATION, LUTEAL, etc."
                },
                "quick_stats": {
                    "total_training_hours": round(sum(act.get("moving_time", 0) for act in activities_display) / 3600, 2),
                    "total_training_formatted": self._format_duration(int(sum(act.get("moving_time", 0) for act in activities_display)) // 60 * 60),
                    "total_activities": len(activities_display),
                    "total_tss": round(sum(act.get("icu_training_load", 0) for act in activities_display if act.get("icu_training_load")), 0)
                }
            },
            "metadata": {
                "athlete_id": "REDACTED",
                "last_updated": None,  # Filled once the coherent training generation is complete.
                "data_range_days": days_back,
                "extended_range_days": days_for_acwr,
                "version": self.VERSION
            },
            "athlete_profile": athlete_profile,
            "athlete_notes": athlete_notes,
            "alerts": alerts,
            "readiness_decision": readiness_decision,
            "sleep_context": sleep_context,
            "health_context": health_context,
            "history": history_info,
            "summary": self._compute_activity_summary(activities_display, days_back, athlete_units),
            "current_status": {
                "fitness": {
                    "ctl": ctl,
                    "atl": atl,
                    "tsb": tsb,
                    "ramp_rate": smart_ramp_rate,
                    "fitness_source": fitness_source
                },
                "thresholds": {
                    "eftp": power_model.get("eftp"),
                    "w_prime": power_model.get("w_prime"),
                    "w_prime_kj": power_model.get("w_prime_kj"),
                    "p_max": power_model.get("p_max"),
                    "vo2max": vo2max,                    
                    "sports": sport_settings
                },
                "current_metrics": {
                    "weight_kg": latest_wellness.get("weight") or athlete.get("icu_weight"),
                    "display": {
                        "weight": self._to_display(
                            latest_wellness.get("weight") or athlete.get("icu_weight"),
                            "weight", athlete_units
                        ),
                    },
                    "resting_hr": latest_wellness.get("restingHR") or athlete.get("icu_resting_hr"),
                    "hrv": latest_wellness.get("hrv"),
                    "sleep_quality": latest_wellness.get("sleepQuality"),
                    "sleep_hours": round(latest_wellness.get("sleepSecs", 0) / 3600, 2) if latest_wellness.get("sleepSecs") else None,
                    "sleep_formatted": self._format_duration(int(latest_wellness.get("sleepSecs", 0)) // 60 * 60) if latest_wellness.get("sleepSecs") else None,
                    "sleep_score": latest_wellness.get("sleepScore"),
                    # Subjective state (categorical 1-4, see wellness_field_scales in READ_THIS_FIRST)
                    "fatigue": latest_wellness.get("fatigue"),
                    "soreness": latest_wellness.get("soreness"),
                    "stress": latest_wellness.get("stress"),
                    "mood": latest_wellness.get("mood"),
                    "motivation": latest_wellness.get("motivation"),
                    "injury": latest_wellness.get("injury"),
                    "hydration": latest_wellness.get("hydration"),
                    # Vitals
                    "spO2": latest_wellness.get("spO2"),
                    "blood_glucose": latest_wellness.get("bloodGlucose"),
                    "systolic": latest_wellness.get("systolic"),
                    "diastolic": latest_wellness.get("diastolic"),
                    "baevsky_si": latest_wellness.get("baevskySI"),
                    "lactate": latest_wellness.get("lactate"),
                    "respiration": latest_wellness.get("respiration"),
                    # Body composition
                    "body_fat_pct": latest_wellness.get("bodyFat"),
                    "abdomen_cm": latest_wellness.get("abdomen"),
                    # Lifestyle / nutrition
                    "steps": latest_wellness.get("steps"),
                    "hydration_volume_l": latest_wellness.get("hydrationVolume"),
                    "kcal_consumed": latest_wellness.get("kcalConsumed"),
                    "carbohydrates_g": latest_wellness.get("carbohydrates"),
                    "protein_g": latest_wellness.get("protein"),
                    "fat_g": latest_wellness.get("fatTotal"),
                    # Cycle
                    "menstrual_phase": latest_wellness.get("menstrualPhase"),
                    "menstrual_phase_predicted": latest_wellness.get("menstrualPhasePredicted"),
                    # Platform
                    "readiness": latest_wellness.get("readiness")
                }
            },
            "derived_metrics": derived_metrics,
            "recent_activities": self._format_activities(
                activities_extended, interval_activity_ids,
                temp_unit=temp_unit, wind_unit=wind_unit, speed_unit=speed_unit,
                previous_latest_lookup=previous_latest_lookup,
                athlete_units=athlete_units, paired_events=events
            ),
            "wellness_data": self._format_wellness(wellness, athlete_units),
            "planned_workouts": formatted_planned_workouts,
            "workout_summary_stats": getattr(self, '_summary_stats', {}),
            "weekly_summary": self._compute_weekly_summary(activities_display, wellness),
            "race_calendar": race_calendar
        }

        data["rolling_7d_chunks"] = self._rolling_7d_chunks(
            activities_extended, wellness_extended, data["recent_activities"], today, ctl,
            data["derived_metrics"]["primary_sport"])
        report_start = (datetime.strptime(today, "%Y-%m-%d") - timedelta(days=27)).strftime("%Y-%m-%d")
        data["wellness_28d"] = self._report_wellness(wellness_extended, report_start, today, athlete_units)
        data["derived_metrics"]["capability"]["dfa_a1_profile_28d"] = self._dfa_28d_profile(
            data["recent_activities"], report_start, today)
        activity_curves = {str(row["id"]): row.get("power_curve") for row in data["recent_activities"]}
        data["derived_metrics"]["capability"]["sustainability_profile"] = self._calculate_sustainability_profile(
            sustainability_curves, sus_window, power_model, sport_settings,
            wellness, wellness_extended, athlete.get("icu_weight"),
            activities=[dict(raw, date=raw.get("start_date_local", ""),
                             power_curve=activity_curves.get(str(raw.get("id"))))
                        for raw in activities_sustainability],
            activities_window=(min(oldest_extended, oldest_sustainability), newest))
        data["fun_facts"] = {"scope": "cycling", "sport_identity_rule": self.SPORT_IDENTITY_RULE,
            "rolling_7d": data["rolling_7d_chunks"][0]["fun_facts"],
            "rolling_28d": self._build_fun_facts(
            data["recent_activities"], (datetime.strptime(today, "%Y-%m-%d") - timedelta(days=27)).strftime("%Y-%m-%d"),
            today, formatted=True, include_week=True, raw_activities=activities_extended)}

        sport_facts = self._build_sport_fun_facts(activities_extended, {
            "rolling_7d": data["derived_metrics"]["report_intensity_7d"],
            "rolling_28d": data["derived_metrics"]["report_intensity_28d"]})
        if sport_facts is not None:
            data["sport_fun_facts"] = sport_facts

        # Body weight signal (v3.112) — gated W/kg + weekly weight trend.
        # None when no field qualifies; AI omits the report section silently.
        weight_signal = self._build_weight_signal(
            wellness_extended, sport_settings, power_model, athlete_units
        )
        if weight_signal:
            data["current_status"]["weight"] = weight_signal

        data["source_freshness"] = self._source_freshness(data)
        self._acquisition.prune(data)
        # Capture once, after the complete training body and source evaluation.
        generated = datetime.now(timezone.utc)
        data["metadata"]["last_updated"] = ExportFreshness.stamp(generated)
        data["export_freshness"] = ExportFreshness.build(
            data["metadata"]["last_updated"], ExportFreshness.context(os.environ),
            data["source_freshness"], generated)
        self._hosted_generation = data
        return data

    def _build_sleep_context(self, wellness, as_of_date, timezone_name, source_updated_at):
        """Bounded context from raw wellness seconds; never a readiness input.

        Keep original wellness date labels. The existing sync clock supplies D;
        withhold comparison if its date is not current in the athlete's zone.
        No history/latest carry-forward, imputation, or fragmentation inference.
        """
        day = datetime.strptime(as_of_date, "%Y-%m-%d")
        dates = [(day - timedelta(days=i)).strftime("%Y-%m-%d")
                 for i in range(34, -1, -1)]
        alignment_reason = None
        zone = None
        try:
            if not isinstance(timezone_name, str) or not timezone_name:
                raise ValueError("missing timezone")
            zone = ZoneInfo(timezone_name)
        except (ValueError, ZoneInfoNotFoundError):
            alignment_reason = "unknown_timezone"
        if source_updated_at.tzinfo is None or source_updated_at.utcoffset() is None:
            alignment_reason = alignment_reason or "unknown_date_alignment"
        elif zone is not None and source_updated_at.astimezone(zone).strftime("%Y-%m-%d") != as_of_date:
            alignment_reason = "current_date_mismatch"

        rows = defaultdict(list)
        input_reason = None
        if not isinstance(wellness, list):
            input_reason = "source_unavailable" if wellness is None else "invalid_input"
            wellness = []
        for row in wellness:
            date = row.get("id") if isinstance(row, dict) else None
            try:
                if not isinstance(date, str) or datetime.strptime(date, "%Y-%m-%d").strftime("%Y-%m-%d") != date:
                    raise ValueError("invalid wellness date")
            except ValueError:
                input_reason = "invalid_input"
                continue
            if dates[0] <= date <= dates[-1]:
                rows[date].append(row)

        def duration_fields(seconds, prefix):
            return {prefix + "_seconds": seconds,
                    prefix + "_hours": round(seconds / 3600, 2) if seconds is not None else None,
                    prefix + "_formatted": self._format_duration(int(seconds) // 60 * 60)
                    if seconds is not None else None}

        nights = []
        for date in dates:
            matches = rows[date]
            seconds, reason = None, None
            if len(matches) > 1:
                reason = "ambiguous_duplicate"
            elif matches:
                value = matches[0].get("sleepSecs")
                if value is None:
                    reason = "missing_duration"
                elif type(value) not in (int, float):
                    reason = "nonnumeric_duration"
                elif type(value) is float and not math.isfinite(value):
                    reason = "nonfinite_duration"
                elif not 0 < value <= 86400:
                    reason = "out_of_range_duration"
                else:
                    seconds = value
            nights.append({"date": date, **duration_fields(seconds, "sleep"),
                           "status": "invalid" if reason else "observed" if matches else "missing",
                           "reason": reason})

        def coverage(part):
            return {"start": part[0]["date"], "end": part[-1]["date"],
                    "observed_nights": sum(n["status"] == "observed" for n in part),
                    "expected_nights": len(part),
                    "missing_dates": [n["date"] for n in part if n["status"] == "missing"],
                    "invalid_dates": [{"date": n["date"], "reason": n["reason"]}
                                      for n in part if n["status"] == "invalid"]}

        reference_nights, recent_nights = nights[:28], nights[28:]
        reference, recent = coverage(reference_nights), coverage(recent_nights)
        median = (statistics.median(n["sleep_seconds"] for n in reference_nights)
                  if reference["observed_nights"] == 28 else None)
        reference.update(duration_fields(median, "median"))
        comparable = median is not None and not (alignment_reason or input_reason)
        for night in recent_nights:
            night["below_reference"] = (night["sleep_seconds"] < median
                if comparable and night["status"] == "observed" else None)
        recent["nights"] = recent_nights
        recent["below_reference_nights"] = (sum(n["below_reference"] is True for n in recent_nights)
                                             if comparable else None)
        mean = (statistics.mean(n["sleep_seconds"] for n in recent_nights)
                if recent["observed_nights"] == 7 else None)
        recent.update(duration_fields(mean, "mean"))
        latest_three = recent_nights[-3:]
        latest_complete = all(n["status"] == "observed" for n in latest_three)
        repeat, run, boundary, difference = None, None, None, None
        run_dates = []
        if comparable and latest_complete:
            difference = sum(median - n["sleep_seconds"] for n in latest_three)
            repeat = all(n["below_reference"] for n in latest_three) and difference >= 3600
            run = 0
            for night in reversed(recent_nights):
                if night["status"] != "observed":
                    boundary = night["status"]
                    break
                if not night["below_reference"]:
                    boundary = "observed_not_below"
                    break
                run += 1
                run_dates.insert(0, night["date"])
            if run == 7:
                boundary = "window_start"
        recent.update({"latest_three_difference_sum_seconds": difference,
                       "consecutive_observed_below_reference": run,
                       "run_formatted": "at least 7" if run == 7 else str(run) if run is not None else None,
                       "run_dates": run_dates, "run_boundary": boundary})
        reason = alignment_reason or input_reason
        if reason is None and median is None:
            reason = "incomplete_reference"
        if reason is None and not latest_complete:
            reason = "incomplete_latest_three"
        status = "not_assessed" if reason else "assessed"
        if reason is None and recent["observed_nights"] < 7:
            status, reason = "partial_recent", "partial_recent_window"
        return {"schema_version": 1,
                "calculation_version": "disjoint_28d_median_latest3_3600s_v1",
                "as_of_date": as_of_date,
                "timezone": {"value": timezone_name if isinstance(timezone_name, str) else None,
                             "source": "athlete_timezone" if zone is not None else "unknown"},
                "source_updated_at": source_updated_at.isoformat(),
                "source": "Intervals.icu wellness.sleepSecs",
                "status": status, "reason": reason, "confidence": "low",
                "readiness_eligible": False, "reference": reference,
                "recent": recent, "repeat_context": repeat}

    def _build_sport_thresholds(self, athlete: dict) -> dict:
        """
        Build per-sport-family threshold map from athlete sportSettings.
        Returns a dict keyed by sport family (e.g. {"cycling": {...}, "run": {...}})
        """
        candidates: dict[str, tuple[dict, int, str]] = {}

        for sport in athlete.get("sportSettings") or []:          # v3.124: present-but-null
            for sport_type in sport.get("types") or []:           # v3.124: present-but-null
                family = self.SPORT_FAMILIES.get(sport_type)
                if not family:
                    continue

                raw_pace = sport.get("threshold_pace")
                threshold_pace = raw_pace if (raw_pace is not None and raw_pace != 0) else None
                pace_units = sport.get("pace_units") if threshold_pace is not None else None

                entry = {
                    "lthr": sport.get("lthr"),
                    "max_hr": sport.get("max_hr"),
                    "threshold_pace": threshold_pace,
                    "pace_units": pace_units,
                    "ftp": sport.get("ftp") or None,
                    "ftp_indoor": sport.get("indoor_ftp") or None,
                }

                populated = sum(1 for v in entry.values() if v is not None)

                if family not in candidates or populated > candidates[family][1] or \
                   (populated == candidates[family][1] and sport_type < candidates[family][2]):
                    candidates[family] = (entry, populated, sport_type)

        return {family: data for family, (data, _, _) in candidates.items()}

    def _build_weight_signal(self, wellness_extended: List[Dict],
                              sport_settings: Dict, power_model: Dict,
                              athlete_units: Optional[Dict[str, str]] = None) -> Optional[Dict]:
        """
        Build current_status.weight block — gated weight signals for block
        (W/kg) and weekly (trend) reports. (v3.112)

        Architecture: every metric below is computed here; the AI layer
        interprets only. Failed-gate fields are ABSENT from the dict (not
        null) so the AI can treat absence as the "omit section" signal —
        no "insufficient data" boilerplate.

        Display fields (per Display Unit Semantics): narrated weights ship
        with a `display` sub-dict carrying {value, unit} pairs in the
        athlete's preferred unit. W/kg stays unit-universal — no display
        block on wkg_* fields. Slope display preserves 3dp precision and
        emits a unit code suffixed with "/week".

        Gates:
          - weight_latest_kg / weight_latest_date:
              latest weigh-in age <= 14 days
          - wkg_current + wkg_ftp_source [+ ftp_setting_date]:
              weight_latest present + FTP source available.
              Tested cycling FTP from sportSettings preferred, eFTP fallback.
              eFTP is not suppressed for stale tested FTP — staleness rides
              on the source tag via ftp_setting_date. The date reflects the
              FTP setting change recorded in ftp_history.json (Intervals
              does not expose a formal test date).
          - wkg_block_start / wkg_block_end / wkg_block_delta:
              >=1 weigh-in within the FIRST 4 days of the trailing 28d
              window (days [today-27, today-24]) AND >=1 weigh-in within
              the LAST 4 days (days [today-3, today]). v1 block-window
              proxy — Section 11 does not yet track explicit block
              boundaries. Both endpoints use the current FTP, so the delta
              reflects weight change across the window only.
          - weight_7d_avg_kg:
              >= 4 weigh-ins in trailing 7d
          - weight_28d_slope_kg_per_week:
              >= 14 weigh-ins in trailing 28d (linear slope)

        Returns None when no field qualifies — caller omits the `weight`
        key from current_status entirely.
        """
        BLOCK_WINDOW_DAYS = 28
        BOUNDARY_WIDTH_DAYS = 4
        today = datetime.now().date()
        block: Dict = {}
        display: Dict = {}

        # --- Collect dated weight entries (newest-first) ---
        entries: List[Tuple] = []
        for w in (wellness_extended or []):
            wt = w.get("weight")
            if wt is None or wt == 0:
                continue
            date_str = w.get("id", "")
            if not date_str:
                continue
            try:
                d = datetime.strptime(date_str[:10], "%Y-%m-%d").date()
            except Exception:
                continue
            entries.append((d, float(wt)))

        if not entries:
            return None

        entries.sort(key=lambda x: x[0], reverse=True)

        # --- weight_latest_kg / weight_latest_date (gate: <=14d age) ---
        latest_date, latest_weight = entries[0]
        latest_age_days = (today - latest_date).days
        if 0 <= latest_age_days <= 14:
            block["weight_latest_kg"] = round(latest_weight, 1)
            block["weight_latest_date"] = latest_date.isoformat()
            display["weight_latest"] = self._to_display(
                latest_weight, "weight", athlete_units
            )

        # --- Resolve FTP source (tested preferred, eFTP fallback) ---
        cycling = (sport_settings or {}).get("cycling", {})
        tested_ftp = cycling.get("ftp")
        eftp = (power_model or {}).get("eftp")

        ftp_used: Optional[float] = None
        ftp_source: Optional[str] = None
        ftp_setting_date: Optional[str] = None

        if tested_ftp:
            ftp_used = float(tested_ftp)
            ftp_source = "tested"
            try:
                ftp_history = self._load_ftp_history()
                outdoor_dates = sorted(ftp_history.get("outdoor", {}).keys(), reverse=True)
                indoor_dates = sorted(ftp_history.get("indoor", {}).keys(), reverse=True)
                if outdoor_dates:
                    ftp_setting_date = outdoor_dates[0]
                elif indoor_dates:
                    ftp_setting_date = indoor_dates[0]
            except Exception:
                ftp_setting_date = None
        elif eftp:
            ftp_used = float(eftp)
            ftp_source = "eftp"

        # --- wkg_current (depends on weight_latest_kg + FTP source) ---
        if "weight_latest_kg" in block and ftp_used and block["weight_latest_kg"] > 0:
            block["wkg_current"] = round(ftp_used / block["weight_latest_kg"], 2)
            block["wkg_ftp_source"] = ftp_source
            if ftp_setting_date:
                block["ftp_setting_date"] = ftp_setting_date

        # --- Block trajectory: first-4 / last-4 boundary windows ---
        # First 4 days of trailing 28d window: [today-27, today-24]
        # Last 4 days of trailing 28d window:  [today-3,  today]
        first4_high = today - timedelta(days=BLOCK_WINDOW_DAYS - BOUNDARY_WIDTH_DAYS)  # today-24
        first4_low = today - timedelta(days=BLOCK_WINDOW_DAYS - 1)                     # today-27
        last4_low = today - timedelta(days=BOUNDARY_WIDTH_DAYS - 1)                    # today-3
        last4_high = today                                                              # today

        def _nearest_in_range(low, high, anchor):
            """Pick the weigh-in within [low, high] closest to anchor."""
            best = None
            best_dist = None
            for d, w in entries:
                if low <= d <= high:
                    dist = abs((d - anchor).days)
                    if best_dist is None or dist < best_dist:
                        best = w
                        best_dist = dist
            return best

        block_start_anchor = first4_low                # day -27
        block_end_anchor = today                       # day 0
        weight_at_start = _nearest_in_range(first4_low, first4_high, block_start_anchor)
        weight_at_end = _nearest_in_range(last4_low, last4_high, block_end_anchor)

        if weight_at_start and weight_at_end and ftp_used:
            block["wkg_block_start"] = round(ftp_used / weight_at_start, 2)
            block["wkg_block_end"] = round(ftp_used / weight_at_end, 2)
            block["wkg_block_delta"] = round(
                block["wkg_block_end"] - block["wkg_block_start"], 2
            )

        # --- weight_7d_avg_kg (gate: >=4 entries in trailing 7d) ---
        seven_d_cutoff = today - timedelta(days=6)
        seven_d_weights = [w for d, w in entries if d >= seven_d_cutoff]
        if len(seven_d_weights) >= 4:
            avg_kg = sum(seven_d_weights) / len(seven_d_weights)
            block["weight_7d_avg_kg"] = round(avg_kg, 1)
            display["weight_7d_avg"] = self._to_display(avg_kg, "weight", athlete_units)

        # --- weight_28d_slope_kg_per_week (gate: >=14 entries in trailing 28d) ---
        twenty_eight_d_cutoff = today - timedelta(days=BLOCK_WINDOW_DAYS - 1)
        slope_pairs = [(d, w) for d, w in entries if d >= twenty_eight_d_cutoff]
        if len(slope_pairs) >= 14:
            xs = [(d - twenty_eight_d_cutoff).days for d, _ in slope_pairs]
            ys = [w for _, w in slope_pairs]
            n = len(xs)
            mean_x = sum(xs) / n
            mean_y = sum(ys) / n
            num = sum((xs[i] - mean_x) * (ys[i] - mean_y) for i in range(n))
            den = sum((xs[i] - mean_x) ** 2 for i in range(n))
            if den > 0:
                slope_kg_per_week = (num / den) * 7
                block["weight_28d_slope_kg_per_week"] = round(slope_kg_per_week, 3)
                # Manual display build: preserves 3dp + appends "/week" to unit code.
                # _to_display rounds to 1dp (correct for absolute weights, too coarse
                # for slopes) — we mirror its conversion logic here instead.
                weight_pref = (athlete_units or {}).get("weight")
                if weight_pref == "lb":
                    slope_display_value = round(slope_kg_per_week * 2.20462, 3)
                    slope_display_unit = "lb/week"
                else:
                    slope_display_value = round(slope_kg_per_week, 3)
                    slope_display_unit = "kg/week"
                display["weight_28d_slope_per_week"] = {
                    "value": slope_display_value,
                    "unit": slope_display_unit,
                }

        if not block:
            return None
        if display:
            block["display"] = display
        return block

    def _calculate_derived_metrics(self, activities_7d: List[Dict], activities_28d: List[Dict],
                                    wellness_7d: List[Dict], wellness_extended: List[Dict],
                                    current_ctl: float, current_atl: float, current_tsb: float,
                                    past_events: List[Dict], activities_for_consistency: List[Dict],
                                    power_model: Dict,
                                    benchmark_indoor: Tuple[Optional[float], Optional[int], Optional[int]],
                                    benchmark_outdoor: Tuple[Optional[float], Optional[int], Optional[int]],
                                    vo2max: float,
                                    formatted_planned_workouts: List[Dict] = None,
                                    race_calendar: Dict = None,
                                    power_curve_data: Dict = None,
                                    power_curve_dates: Tuple = None,
                                    hr_curve_data: Dict = None,
                                    sustainability_curves: Dict = None,
                                    sustainability_window: Tuple = None,
                                    sport_settings: Dict = None,
                                    icu_weight: float = None) -> Dict:
        """
        Calculate Section 11 derived metrics.
        
        Tier 1 (Primary): RI, baselines
        Tier 2 (Secondary): ACWR, Monotony, Strain, Stress Tolerance, Load-Recovery Ratio
        Tier 3 (Tertiary): Zone distribution, Polarisation, Phase Detection, Consistency, Benchmark
        
        Args:
            benchmark_indoor: (benchmark_index, ftp_8_weeks_ago, current_ftp) for indoor
            benchmark_outdoor: (benchmark_index, ftp_8_weeks_ago, current_ftp) for outdoor
        """
        
        # Defaults for phase detection inputs
        if race_calendar is None:
            race_calendar = {"next_race": None, "all_races": [], "taper_alert": {"active": False}, "race_week": {"active": False}}
        
        # Unpack benchmark tuples
        benchmark_index_indoor, ftp_8_weeks_ago_indoor, current_ftp_indoor = benchmark_indoor
        benchmark_index_outdoor, ftp_8_weeks_ago_outdoor, current_ftp_outdoor = benchmark_outdoor
        
        # === DAILY TSS AGGREGATION ===
        daily_tss_7d = self._get_daily_tss(activities_7d, days=7)
        daily_tss_28d = self._get_daily_tss(activities_28d, days=28)
        
        tss_7d_total = sum(daily_tss_7d)
        tss_28d_total = sum(daily_tss_28d)
        
        # === ACWR (Acute:Chronic Workload Ratio) ===
        # Formula: (7-day avg TSS) / (28-day avg TSS)
        # Reference: Gabbett (2016) - "sweet spot" is 0.8-1.3
        acute_load = tss_7d_total / 7 if tss_7d_total else 0
        chronic_load = tss_28d_total / 28 if tss_28d_total else 0
        acwr = round(acute_load / chronic_load, 2) if chronic_load > 0 else None

        # === START-OF-DAY ACWR (readiness basis, v3.127) ===
        # Same windows, same divisors, same source lists - only today's activities are
        # excluded, leaving today's bucket empty. Not a midnight snapshot: recomputed
        # from current source data on every sync with activities dated as_of_date
        # excluded. readiness_decision consumes this; `acwr` above stays live.
        # Deliberately mirrors the live source lists (activities_7d for the acute window,
        # activities_28d for the chronic) rather than "correcting" either, so the two
        # values are the same metric read at two moments. With no activity dated today
        # they are identical.
        # Not a persisted snapshot: recomputed every sync, so a corrected earlier-day
        # activity still moves it while a workout completed today cannot.
        # The empty today bucket is intentional and inherited, not a defect - the
        # 1.3/1.5 thresholds have only ever been applied to a today-inclusive window
        # with a partly-empty current day. Do not "fix" it by shifting the windows back.
        today_str = datetime.now().strftime("%Y-%m-%d")
        activities_7d_sod = [a for a in activities_7d
                             if a.get("start_date_local", "")[:10] != today_str]
        activities_28d_sod = [a for a in activities_28d
                              if a.get("start_date_local", "")[:10] != today_str]
        sod_7d_total = sum(self._get_daily_tss(activities_7d_sod, days=7))
        sod_28d_total = sum(self._get_daily_tss(activities_28d_sod, days=28))
        sod_acute = sod_7d_total / 7 if sod_7d_total else 0
        sod_chronic = sod_28d_total / 28 if sod_28d_total else 0
        acwr_start_of_day = round(sod_acute / sod_chronic, 2) if sod_chronic > 0 else None
        
        # === MONOTONY (Total) ===
        # Formula: mean(daily_tss) / stdev(daily_tss)
        # Reference: Foster (1998) - values >2.0 indicate increased illness risk
        if len(daily_tss_7d) > 1 and any(daily_tss_7d):
            mean_tss = statistics.mean(daily_tss_7d)
            try:
                stdev_tss = statistics.stdev(daily_tss_7d)
                monotony = round(mean_tss / stdev_tss, 2) if stdev_tss > 0 else None
            except:
                monotony = None
        else:
            monotony = None
            mean_tss = 0

        # === PRIMARY SPORT MONOTONY (v3.3.3) ===
        # Multi-sport athletes get inflated total monotony when cross-training
        # adds a consistent TSS floor across days. Per-sport monotony isolates
        # the actual load variation within each modality.
        daily_tss_by_sport = self._get_daily_tss_by_sport(activities_7d, days=7)
        primary_sport = None
        primary_sport_monotony = None
        primary_sport_tss_7d = None

        if daily_tss_by_sport:
            # Primary sport = highest 7-day TSS total
            sport_totals = {sport: sum(days) for sport, days in daily_tss_by_sport.items()}
            primary_sport = max(sport_totals, key=sport_totals.get) if sport_totals else None

            if primary_sport:
                primary_days = daily_tss_by_sport[primary_sport]
                primary_sport_tss_7d = round(sum(primary_days), 0)
                # Require ≥3 active days for meaningful monotony
                active_days = sum(1 for d in primary_days if d > 0)
                if active_days >= 3 and len(primary_days) > 1:
                    try:
                        ps_mean = statistics.mean(primary_days)
                        ps_stdev = statistics.stdev(primary_days)
                        primary_sport_monotony = round(ps_mean / ps_stdev, 2) if ps_stdev > 0 else None
                    except:
                        primary_sport_monotony = None

                if self.debug:
                    print(f"  Primary sport: {primary_sport} (TSS: {primary_sport_tss_7d})")
                    print(f"  Primary sport monotony: {primary_sport_monotony}")
                    print(f"  Total monotony: {monotony}")
                    if primary_sport_monotony and monotony and primary_sport_monotony < monotony:
                        print(f"  → Multi-sport inflation detected ({monotony} total vs {primary_sport_monotony} primary)")

        # Determine effective monotony for alerts:
        # Use primary sport monotony when available and multi-sport detected,
        # fall back to total monotony otherwise
        is_multi_sport = len(daily_tss_by_sport) > 1
        effective_monotony = primary_sport_monotony if (is_multi_sport and primary_sport_monotony is not None) else monotony

        # === STRAIN ===
        # Formula: 7-day total TSS × Monotony
        # Reference: Foster (1998) - values >3500-4000 associated with overtraining
        strain = round(tss_7d_total * monotony, 0) if monotony else None
        
        # === BASELINES (7-day and extended) ===
        hrv_values_7d = [w.get("hrv") for w in wellness_7d if self._is_valid_hrv(w.get("hrv"))]
        rhr_values_7d = [w.get("restingHR") for w in wellness_7d if w.get("restingHR")]
        
        hrv_baseline_7d = round(statistics.mean(hrv_values_7d), 1) if hrv_values_7d else None
        rhr_baseline_7d = round(statistics.mean(rhr_values_7d), 1) if rhr_values_7d else None
        
        # Extended baselines (for more stable reference)
        hrv_values_ext = [w.get("hrv") for w in wellness_extended if self._is_valid_hrv(w.get("hrv"))]
        rhr_values_ext = [w.get("restingHR") for w in wellness_extended if w.get("restingHR")]
        
        hrv_baseline_28d = round(statistics.mean(hrv_values_ext), 1) if hrv_values_ext else None
        rhr_baseline_28d = round(statistics.mean(rhr_values_ext), 1) if rhr_values_ext else None
        
        # === RECOVERY INDEX (RI) ===
        # Formula: (HRV_today / HRV_baseline) ÷ (RHR_today / RHR_baseline)
        # Interpretation: >1.0 = good recovery, <1.0 = poor recovery
        latest_hrv_raw = wellness_7d[-1].get("hrv") if wellness_7d else None
        latest_hrv = latest_hrv_raw if self._is_valid_hrv(latest_hrv_raw) else None
        latest_rhr = wellness_7d[-1].get("restingHR") if wellness_7d else None
        
        if latest_hrv and latest_rhr and hrv_baseline_7d and rhr_baseline_7d:
            hrv_ratio = latest_hrv / hrv_baseline_7d
            rhr_ratio = latest_rhr / rhr_baseline_7d
            ri = round(hrv_ratio / rhr_ratio, 2) if rhr_ratio > 0 else None
        else:
            ri = None

        # Yesterday's RI — same formula, wellness_7d[-2] against same 7d baseline.
        # Used for RI amber persistence check in readiness_decision (2-day rule).
        ri_yesterday = None
        if len(wellness_7d) >= 2:
            y_hrv_raw = wellness_7d[-2].get("hrv")
            y_hrv = y_hrv_raw if self._is_valid_hrv(y_hrv_raw) else None
            y_rhr = wellness_7d[-2].get("restingHR")
            if y_hrv and y_rhr and hrv_baseline_7d and rhr_baseline_7d:
                y_hrv_ratio = y_hrv / hrv_baseline_7d
                y_rhr_ratio = y_rhr / rhr_baseline_7d
                ri_yesterday = round(y_hrv_ratio / y_rhr_ratio, 2) if y_rhr_ratio > 0 else None
        
        # === STRESS TOLERANCE ===
        # Formula: (Strain ÷ Monotony) ÷ 100
        stress_tolerance = round((strain / monotony) / 100, 1) if strain and monotony else None
        
        # === LOAD-RECOVERY RATIO ===
        # Formula: 7-day Load ÷ (RI × 100)
        load_recovery_ratio = round(tss_7d_total / (ri * 100), 1) if ri and ri > 0 else None
        
        # === ZONE AGGREGATION ===
        zone_totals = self._aggregate_zones(activities_7d)
        
        total_zone_time = zone_totals["total_time"]
        z1_time = zone_totals["z1_time"]
        z2_time = zone_totals["z2_time"]
        z3_time = zone_totals["z3_time"]
        z4_plus_time = zone_totals["z4_plus_time"]
        zone_basis_7d = zone_totals["zone_basis"]
        
        # === GREY ZONE PERCENTAGE (Z3 - to be minimized in polarized training) ===
        # Reference: Seiler - "too much pain for too little gain"
        grey_zone_percentage = round((z3_time / total_zone_time) * 100, 1) if total_zone_time > 0 else None
        
        # === QUALITY INTENSITY PERCENTAGE (Z4+ per Seiler's model) ===
        # Reference: Seiler's Zone 3 = above LT2 = Z4+ in 7-zone model
        # This is the "hard" work that should be ~20% in polarized training
        quality_intensity_percentage = round((z4_plus_time / total_zone_time) * 100, 1) if total_zone_time > 0 else None
        
        # === EASY TIME RATIO ===
        # Formula: (Z1 + Z2) / Total - measures how much time is "easy"
        # Target: ~80% for polarized training
        easy_time_ratio = round((z1_time + z2_time) / total_zone_time, 2) if total_zone_time > 0 else None
        
        # === SEILER TID (Training Intensity Distribution) ===
        # Dual calculation: all-sport and primary-sport (like monotony)
        # Uses correct 7→3 zone mapping per Treff et al. 2019
        seiler_tid_all = self._build_seiler_tid(activities_7d)

        seiler_tid_primary = None
        if primary_sport:
            seiler_tid_primary = self._build_seiler_tid(
                activities_7d, sport_family_filter=primary_sport
            )
            seiler_tid_primary["sport"] = primary_sport

        if self.debug:
            pi_all = seiler_tid_all.get("polarization_index")
            cls_all = seiler_tid_all.get("classification")
            print(f"  Seiler TID (all): {cls_all}, PI={pi_all}")
            if seiler_tid_primary:
                pi_ps = seiler_tid_primary.get("polarization_index")
                cls_ps = seiler_tid_primary.get("classification")
                print(f"  Seiler TID ({primary_sport}): {cls_ps}, PI={pi_ps}")

        # === SEILER TID 28d (Chronic Training Intensity Distribution) ===
        # Same method, wider window — for acute vs chronic TID comparison
        seiler_tid_28d_all = self._build_seiler_tid(activities_28d)

        seiler_tid_28d_primary = None
        if primary_sport:
            seiler_tid_28d_primary = self._build_seiler_tid(
                activities_28d, sport_family_filter=primary_sport
            )
            seiler_tid_28d_primary["sport"] = primary_sport

        if self.debug:
            pi_28d = seiler_tid_28d_all.get("polarization_index")
            cls_28d = seiler_tid_28d_all.get("classification")
            print(f"  Seiler TID 28d (all): {cls_28d}, PI={pi_28d}")

        # === TID COMPARISON (7d vs 28d drift detection) ===
        tid_comparison = self._calculate_tid_comparison(seiler_tid_all, seiler_tid_28d_all)
        tid_comparison_primary = self._calculate_tid_comparison(
            seiler_tid_primary or {}, seiler_tid_28d_primary or {})
        tid_comparison_primary["sport"] = primary_sport

        report_end = datetime.strptime(today_str, "%Y-%m-%d")
        report_intensity_7d = self._report_intensity(
            activities_28d, (report_end - timedelta(days=6)).strftime("%Y-%m-%d"),
            today_str, week_mode="rolling", as_of=today_str)
        report_intensity_28d = self._report_intensity(
            activities_28d, (report_end - timedelta(days=27)).strftime("%Y-%m-%d"),
            today_str, week_mode="rolling", weekly_rescue=True, as_of=today_str)
        main_monotony = self._main_monotony(
            activities_28d, (report_end - timedelta(days=6)).strftime("%Y-%m-%d"), today_str,
            report=report_intensity_7d, chronic=True)

        # === DURABILITY TREND (aggregate decoupling) ===
        durability = self._calculate_durability(activities_7d, activities_28d)
        efficiency_factor = self._calculate_efficiency_factor(activities_7d, activities_28d)
        hrrc_trend = self._calculate_hrrc_trend(activities_7d, activities_28d)

        # === POWER CURVE DELTA (energy system adaptation trend) ===
        power_curve_delta = self._calculate_power_curve_delta(power_curve_data, power_curve_dates)

        # === HR CURVE DELTA (cardiac adaptation trend) ===
        hr_curve_delta = self._calculate_hr_curve_delta(hr_curve_data, power_curve_dates)

        # === SUSTAINABILITY PROFILE (race estimation lookup table, v3.91) ===
        sustainability_profile = self._calculate_sustainability_profile(
            sustainability_curves=sustainability_curves or {},
            sustainability_window=sustainability_window,
            power_model=power_model,
            sport_settings=sport_settings or {},
            wellness_7d=wellness_7d,
            wellness_extended=wellness_extended,
            icu_weight=icu_weight
        )

        # === DFA a1 PROFILE (v3.99) ===
        # Reads from self._intervals_data populated by _generate_intervals().
        # Returns None when no AlphaHRV-equipped sessions exist in the 14d window.
        dfa_a1_profile = self._calculate_dfa_a1_profile()

        # === CONSISTENCY INDEX ===
        consistency_index, consistency_details = self._calculate_consistency_index(
            activities_for_consistency, past_events
        )
        
        # === PHASE DETECTION v2 (dual-stream) ===
        today = datetime.now().strftime("%Y-%m-%d")
        
        # === LIVE WEEKLY ROWS FROM activities_28d (v3.94) ===
        # Replaces v3.89 single-week overlay. Computes all 4 weekly rows
        # (TSS, primary_sport_tss, hard_days) live from activities_28d,
        # eliminating the entire class of stale-row bugs. CTL/ATL enriched
        # from history.json where available (stable background data).
        now_dt = datetime.now()
        days_since_ws = (now_dt.weekday() - self.week_start_day) % 7
        current_ws_dt = now_dt - timedelta(days=days_since_ws)
        
        # Build 4 week boundaries (newest first, then reversed to chronological)
        week_boundaries = []
        for i in range(4):
            ws_dt = current_ws_dt - timedelta(weeks=i)
            we_dt = ws_dt + timedelta(days=6)
            week_boundaries.append((ws_dt.strftime("%Y-%m-%d"), we_dt.strftime("%Y-%m-%d")))
        week_boundaries.reverse()  # chronological: oldest first
        
        # Bucket activities_28d by week and compute TSS + hard_days per week
        weekly_rows = []
        for ws, we in week_boundaries:
            week_acts = [a for a in activities_28d
                         if ws <= (a.get("start_date_local", "")[:10]) <= min(we, today)]
            
            w_tss = sum((a.get("icu_training_load", 0) or 0) for a in week_acts)
            w_primary_tss = sum(
                (a.get("icu_training_load", 0) or 0) for a in week_acts
                if self.SPORT_FAMILIES.get(a.get("type", ""), None) == primary_sport
            )
            
            # Hard days: group by date, classify each day
            acts_by_date = {}
            for a in week_acts:
                a_date = a.get("start_date_local", "")[:10]
                if a_date not in acts_by_date:
                    acts_by_date[a_date] = []
                acts_by_date[a_date].append(a)
            
            w_hard_days = 0
            for date_str, day_acts in acts_by_date.items():
                day_zones_by_basis = {}
                for a in day_acts:
                    sf = self.SPORT_FAMILIES.get(a.get("type", ""), None)
                    zones, basis = self._get_activity_zones(a, sport_family=sf)
                    if zones and basis:
                        if basis not in day_zones_by_basis:
                            day_zones_by_basis[basis] = {}
                        for zid, secs in zones.items():
                            day_zones_by_basis[basis][zid] = day_zones_by_basis[basis].get(zid, 0) + secs
                is_hard, _basis = self._classify_hard_day(day_zones_by_basis)
                if is_hard:
                    w_hard_days += 1
            
            weekly_rows.append({
                "week_start": ws,
                "total_tss": round(w_tss, 0),
                "primary_sport_tss": round(w_primary_tss, 0),
                "primary_sport": primary_sport,
                "hard_days": w_hard_days,
                "hard_days_coverage": self._hard_days_coverage(week_acts),
                "monotony_main_sports": self._main_monotony(
                    activities_28d, ws, min(we, today), weekly=True),
                "activity_count": len(week_acts),
            })
        
        # Current week gets live CTL/ATL/ACWR/monotony (already computed this run)
        weekly_rows[-1]["ctl_end"] = round(current_ctl, 1) if current_ctl else None
        weekly_rows[-1]["atl_end"] = round(current_atl, 1) if current_atl else None
        weekly_rows[-1]["acwr"] = acwr
        weekly_rows[-1]["monotony"] = monotony
        
        # Enrich older weeks with CTL/ATL from history.json (stable background)
        history_rows = self._load_weekly_rows_for_phase()
        history_by_ws = {r.get("week_start"): r for r in history_rows}
        for row in weekly_rows[:-1]:  # skip current week (already enriched)
            hist = history_by_ws.get(row["week_start"])
            if hist:
                for field in ("ctl_end", "atl_end", "acwr", "monotony"):
                    if field not in row or row[field] is None:
                        row[field] = hist.get(field)
        
        # hard_days_this_week: current week's value (used in return dict)
        hard_days_this_week = weekly_rows[-1]["hard_days"]
        
        # previous_phase from [-2] (last completed week).
        # History rows may have phase_detected; fresh rows won't.
        # Enrich completed rows with phase_detected from history where available.
        for row in weekly_rows[:-1]:
            hist = history_by_ws.get(row["week_start"])
            if hist and hist.get("_phase_load_compatible") and "phase_detected" in hist:
                row["phase_detected"] = hist["phase_detected"]
                row["phase_load_basis"] = hist.get("phase_load_basis")
                row["_phase_load_compatible"] = True
        
        previous_phase = None
        if len(weekly_rows) >= 2:
            previous_phase = weekly_rows[-2].get("phase_detected")
        
        # Exact current-snapshot pairing only. A calendar edit is not evidence
        # of the prescription at completion; use identity solely to exclude
        # already-executed events from prospective phase features.
        observed_acts = [a for a in activities_28d
                         if week_boundaries[0][0] <= (a.get("start_date_local") or "")[:10] <= today]
        observed_ids = {str(a["id"]) for a in observed_acts if a.get("id") is not None}
        completed_event_ids = {str(a["paired_event_id"]) for a in observed_acts
                               if a.get("paired_event_id") is not None}
        completed_event_ids.update(
            str(e["id"]) for e in (past_events or [])
            if e.get("id") is not None and e.get("paired_activity_id") is not None
            and str(e["paired_activity_id"]) in observed_ids
        )
        phase_result = self._detect_phase_v2(
            weekly_rows=weekly_rows,
            planned_workouts=formatted_planned_workouts,
            race_calendar=race_calendar,
            previous_phase=previous_phase,
            today=today,
            primary_sport=primary_sport,
            completed_event_ids=completed_event_ids,
            completed_activities=observed_acts,
            current_week_events=past_events,
            load_activities=activities_28d
        )
        phase_detected = phase_result["phase"]
        
        # Legacy compatibility: extract trigger-style info for existing consumers
        phase_triggers = phase_result["reason_codes"]
        
        # === SEASONAL CONTEXT ===
        seasonal_context = self._determine_seasonal_context()
        
        # === BENCHMARK SEASONAL EXPECTATION ===
        benchmark_expected_indoor = self._is_benchmark_expected(benchmark_index_indoor, seasonal_context)
        benchmark_expected_outdoor = self._is_benchmark_expected(benchmark_index_outdoor, seasonal_context)
        
        return {
            # Tier 1: Primary Readiness
            "recovery_index": ri,
            "recovery_index_yesterday": ri_yesterday,
            "hrv_baseline_7d": hrv_baseline_7d,
            "rhr_baseline_7d": rhr_baseline_7d,
            "hrv_baseline_28d": hrv_baseline_28d,
            "rhr_baseline_28d": rhr_baseline_28d,
            "latest_hrv": latest_hrv,
            "latest_rhr": latest_rhr,
            
            # Tier 2: Secondary Load Metrics
            "acwr": acwr,
            "acwr_interpretation": self._interpret_acwr(acwr),
            # v3.127: the live field is retrospective load reporting. Readiness reads
            # acwr_start_of_day below; these two keys close the raw-field back door.
            "acwr_scope": "live_retrospective",
            "acwr_readiness_eligible": False,
            "acwr_start_of_day": {
                "value": acwr_start_of_day,
                "interpretation": self._interpret_acwr(acwr_start_of_day),
                "scope": "start_of_day",
                "as_of_date": today_str,
                "current_day_load_included": False,
                "acute_days": 7,
                "chronic_days": 28
            },
            "monotony": monotony,
            "monotony_main_sports": main_monotony,
            "strain_main_sports": self._main_strain(main_monotony),
            "monotony_interpretation": self._interpret_monotony(monotony, effective_monotony, is_multi_sport),
            "primary_sport": primary_sport,
            "primary_sport_monotony": primary_sport_monotony,
            "primary_sport_tss_7d": primary_sport_tss_7d,
            "effective_monotony": effective_monotony,
            "multi_sport_detected": is_multi_sport,
            "strain": strain,
            "stress_tolerance": stress_tolerance,
            "load_recovery_ratio": load_recovery_ratio,
            "tss_7d_total": round(tss_7d_total, 0),
            "tss_28d_total": round(tss_28d_total, 0),
            
            # Tier 3: Zone Distribution (Seiler's Polarized Model)
            "zone_distribution_7d": {
                "z1_hours": round(z1_time / 3600, 2),
                "z2_hours": round(z2_time / 3600, 2),
                "z3_hours": round(z3_time / 3600, 2),
                "z4_plus_hours": round(z4_plus_time / 3600, 2),
                "total_hours": round(total_zone_time / 3600, 2),
                "zone_basis": zone_basis_7d
            },
            "grey_zone_percentage": grey_zone_percentage,
            "grey_zone_note": "Gray Zone % (Z3/tempo) - minimize in polarized training",
            "quality_intensity_percentage": quality_intensity_percentage,
            "quality_intensity_note": "Quality Intensity % (Z4+/threshold+) - target ~20% in polarized training",
            "easy_time_ratio": easy_time_ratio,
            "easy_time_ratio_note": "Easy time (Z1+Z2) / Total - target ~80% in polarized training",
            "hard_days_this_week": hard_days_this_week,
            "hard_days_coverage": weekly_rows[-1]["hard_days_coverage"],
            "hard_days_note": "Power ladder: z3+ >= 30min, z4+ >= 10min, z5+ >= 5min, z6+ >= 2min, z7 >= 1min. HR fallback (when no power): z4+ >= 10min, z5+ >= 5min. Per Seiler 3-zone model + Foster. HR-based days flagged with intensity_basis: hr",
            
            # Tier 3: Seiler TID (Training Intensity Distribution)
            "seiler_tid_7d": seiler_tid_all,
            "seiler_tid_7d_primary": seiler_tid_primary,
            "seiler_tid_28d": seiler_tid_28d_all,
            "seiler_tid_28d_primary": seiler_tid_28d_primary,
            "report_intensity_7d": self._report_pack(report_intensity_7d, ready=True),
            "report_intensity_28d": self._report_pack(report_intensity_28d, ready=True),
            
            # Capability metrics (how fitness is expressed, not just load)
            "capability": {
                "durability": durability,
                "efficiency_factor": efficiency_factor,
                "hrrc": hrrc_trend,
                "tid_comparison": tid_comparison,
                "tid_comparison_primary": tid_comparison_primary,
                "report_intensity_comparison": self._report_pack_comparison(
                    self._report_intensity_comparison(report_intensity_7d, report_intensity_28d)),
                "power_curve_delta": power_curve_delta,
                "hr_curve_delta": hr_curve_delta,
                "sustainability_profile": sustainability_profile,
                "dfa_a1_profile": dfa_a1_profile,
            },
            
            # Tier 3: Consistency & Compliance
            "consistency_index": consistency_index,
            "consistency_details": consistency_details,
            
            # Phase & Context
            "phase_detection": phase_result,
            "phase_detected": phase_detected,  # top-level shortcut for backward compat
            "phase_triggers": phase_triggers,   # backward compat
            "seasonal_context": seasonal_context,
            
            # Benchmark & FTP Progression (Indoor)
            "benchmark_indoor": {
                "current_ftp": current_ftp_indoor,
                "ftp_8_weeks_ago": ftp_8_weeks_ago_indoor,
                "benchmark_index": benchmark_index_indoor,
                "benchmark_percentage": f"{benchmark_index_indoor:+.1%}" if benchmark_index_indoor is not None else None,
                "seasonal_expected": benchmark_expected_indoor
            },
            # Benchmark & FTP Progression (Outdoor)
            "benchmark_outdoor": {
                "current_ftp": current_ftp_outdoor,
                "ftp_8_weeks_ago": ftp_8_weeks_ago_outdoor,
                "benchmark_index": benchmark_index_outdoor,
                "benchmark_percentage": f"{benchmark_index_outdoor:+.1%}" if benchmark_index_outdoor is not None else None,
                "seasonal_expected": benchmark_expected_outdoor
            },
            
            # Power Model (from API - accurate live estimates)
            "eftp": power_model.get("eftp"),
            "w_prime": power_model.get("w_prime"),
            "w_prime_kj": power_model.get("w_prime_kj"),
            "p_max": power_model.get("p_max"),
            "power_model_source": power_model.get("source"),
            
            # Additional wellness metrics (from API)
            "vo2max": vo2max,
            
            # Validation metadata
            "calculation_timestamp": datetime.now(timezone.utc).isoformat().replace("+00:00", "Z"),
            "data_quality": {
                "hrv_data_points": len(hrv_values_7d),
                "rhr_data_points": len(rhr_values_7d),
                "activities_7d": len(activities_7d),
                "activities_28d": len(activities_28d),
                # v3.128: past_events is every calendar entry in the window. Only
                # training entries are planned workouts - counting SICK / INJURED /
                # NOTE / HOLIDAY markers overstated this quality figure. Matches the
                # filter _calculate_consistency_index already applies to the same list.
                "planned_workouts_7d": sum(
                    1 for e in past_events
                    if e.get("category", "") in self.TRAINING_EVENT_CATEGORIES
                ),
                "ftp_history_days": self._get_ftp_history_span()
            }
        }
    
    def _interpret_acwr(self, acwr: float) -> Optional[str]:
        """Interpret ACWR value per Gabbett guidelines"""
        if acwr is None:
            return None
        if acwr < 0.8:
            return "undertraining"
        elif acwr < 1.3:
            return "optimal"
        elif acwr < 1.5:
            return "caution"
        else:
            return "danger"

    def _interpret_monotony(self, total_monotony: float, effective_monotony: float, is_multi_sport: bool) -> Optional[str]:
        """
        Interpret monotony with multi-sport awareness.
        When multi-sport training inflates total monotony, the interpretation
        reflects the effective (primary sport) value instead.
        """
        if effective_monotony is None:
            return None
        if is_multi_sport and total_monotony and effective_monotony < total_monotony:
            # Multi-sport inflation detected
            if effective_monotony > 2.0:
                return f"elevated (primary sport {effective_monotony}, total {total_monotony} inflated by multi-sport)"
            else:
                return f"normal (primary sport {effective_monotony}, total {total_monotony} inflated by multi-sport)"
        else:
            if effective_monotony > 2.0:
                return "elevated"
            else:
                return "normal"

    def _classify_effort_response(self, if_value: Optional[float],
                                    rpe: Optional[float]) -> Optional[str]:
        """
        Classify effort response per the v11.34 RPE Expectation Bands.

        Reads session IF (icu_intensity, stored as percentage 0-100+) and reported RPE
        (icu_rpe, 1-10). Normalizes IF to decimal at entry to match the canonical band
        table in SECTION_11.md §RPE Expectation Bands.

        Returns:
            "positive" - RPE below the expected band (fitness/freshness tell)
            "neutral"  - RPE within the expected band
            "negative" - RPE above the expected band (fatigue/under-recovery tell)
            None       - IF absent, RPE absent or <= 0, or IF < 0.65 (out of coverage)

        The IF < 0.65 null is a deliberate design gap, not missing data — recovery rides
        and aborted sessions fall outside the bands' calibration range, and fabricating a
        band there would produce noise on the sessions least worth flagging.

        Interpretive overlay only. Does NOT alter Feel/RPE Override rules (v11.14) and
        does NOT enter the readiness P0-P3 ladder.
        """
        if if_value is None or rpe is None or rpe <= 0:
            return None
        if_decimal = if_value / 100.0
        if if_decimal < 0.65:
            return None
        if if_decimal < 0.75:
            band_low, band_high = 2, 4
        elif if_decimal < 0.85:
            band_low, band_high = 4, 6
        elif if_decimal < 0.95:
            band_low, band_high = 6, 8
        elif if_decimal < 1.05:
            band_low, band_high = 8, 9
        else:
            band_low, band_high = 9, 10
        if rpe < band_low:
            return "positive"
        if rpe > band_high:
            return "negative"
        return "neutral"

    def _calculate_consistency_index(self, activities: List[Dict], 
                                      past_events: List[Dict]) -> Tuple[Optional[float], Dict]:
        """
        Calculate Consistency Index = Completed Workout Days / Planned Workout Days
        
        Matches by date (not individual workouts) since multiple workouts can be planned per day.
        """
        # Get unique dates with planned workouts (only WORKOUT type)
        planned_dates = set()
        for event in past_events:
            if event.get("category") == "WORKOUT":
                date_str = event.get("start_date_local", "")[:10]
                if date_str:
                    planned_dates.add(date_str)
        
        # Get unique dates with completed activities (any sport type)
        completed_dates = set()
        
        for activity in activities:
            date_str = (activity.get("date") or activity.get("start_date_local") or "")[:10]
            if date_str:
                completed_dates.add(date_str)
        
        # Calculate overlap
        matched_dates = planned_dates & completed_dates
        
        if not planned_dates:
            return None, {
                "planned_days": 0,
                "completed_days": len(completed_dates),
                "matched_days": 0,
                "note": "No planned workouts in period"
            }
        
        consistency_index = round(len(matched_dates) / len(planned_dates), 2)
        
        return consistency_index, {
            "planned_days": len(planned_dates),
            "completed_days": len(completed_dates),
            "matched_days": len(matched_dates),
            "planned_dates": sorted(list(planned_dates)),
            "completed_dates": sorted(list(completed_dates))
        }
    
    def _is_benchmark_expected(self, benchmark_index: Optional[float], 
                                seasonal_context: str) -> Optional[bool]:
        """
        Determine if the benchmark index is within expected range for the season.
        """
        if benchmark_index is None:
            return None
        
        expectations = {
            "Off-season / Transition": (-0.05, -0.02),
            "Early Base": (-0.02, 0.01),
            "Late Base / Build": (0.02, 0.05),
            "Build / Early Race Season": (0.01, 0.04),
            "Peak Race Season": (0.01, 0.03),
            "Late Season / Transition": (-0.03, 0.00),
        }
        
        if seasonal_context in expectations:
            low, high = expectations[seasonal_context]
            return low <= benchmark_index <= high
        
        return None
    
    def _get_ftp_history_span(self) -> Dict[str, int]:
        """Get the number of days of FTP history available for indoor and outdoor"""
        ftp_history = self._load_ftp_history()
        
        result = {"indoor": 0, "outdoor": 0}
        
        for ftp_type in ["indoor", "outdoor"]:
            history = ftp_history.get(ftp_type, {})
            if not history:
                continue
            
            sorted_dates = sorted(history.keys())
            if len(sorted_dates) < 2:
                continue
            
            try:
                oldest = datetime.strptime(sorted_dates[0], "%Y-%m-%d")
                newest = datetime.strptime(sorted_dates[-1], "%Y-%m-%d")
                result[ftp_type] = (newest - oldest).days
            except:
                continue
        
        return result
    
    def _get_daily_tss(self, activities: List[Dict], days: int) -> List[float]:
        """Aggregate TSS by day for the specified number of days"""
        daily_tss = defaultdict(float)
        
        for act in activities:
            date_str = act.get("start_date_local", "")[:10]
            tss = act.get("icu_training_load") or 0
            daily_tss[date_str] += tss
        
        # Create array for last N days (including days with 0 TSS)
        result = []
        for i in range(days - 1, -1, -1):
            date = (datetime.now() - timedelta(days=i)).strftime("%Y-%m-%d")
            result.append(daily_tss.get(date, 0))
        
        return result

    def _get_daily_tss_by_sport(self, activities: List[Dict], days: int) -> Dict[str, List[float]]:
        """
        Aggregate TSS by day AND sport family for per-sport monotony calculation.
        Returns dict of sport_family → [daily_tss_day1, daily_tss_day2, ...] (N elements).
        Only includes sport families that have at least one activity with TSS > 0.
        Sport families are mapped via SPORT_FAMILIES class constant.
        Unmapped activity types are grouped as "other".
        """
        # Collect all sport families present and their daily TSS
        sport_daily_tss = defaultdict(lambda: defaultdict(float))

        for act in activities:
            date_str = act.get("start_date_local", "")[:10]
            tss = act.get("icu_training_load") or 0
            if tss <= 0:
                continue
            activity_type = act.get("type", "Unknown")
            sport_family = self.SPORT_FAMILIES.get(activity_type, "other")
            sport_daily_tss[sport_family][date_str] += tss

        # Build daily arrays for each sport family (including 0 days)
        result = {}
        for sport_family, daily_dict in sport_daily_tss.items():
            daily_array = []
            for i in range(days - 1, -1, -1):
                date = (datetime.now() - timedelta(days=i)).strftime("%Y-%m-%d")
                daily_array.append(daily_dict.get(date, 0))
            result[sport_family] = daily_array

        return result

    def _report_primary_sport(self, activities):
        """Use the existing latest-seven-day highest-TSS rule for report history."""
        today = datetime.now().strftime("%Y-%m-%d")
        start = (datetime.now() - timedelta(days=6)).strftime("%Y-%m-%d")
        current = [a for a in activities if start <= a.get("start_date_local", "")[:10] <= today]
        totals = {sport: sum(days) for sport, days in
                  self._get_daily_tss_by_sport(current, days=7).items()}
        return max(totals, key=totals.get) if totals else None

    @classmethod
    def _parse_report_main_sports(cls, value):
        """Explicit report IDs only; an absent override selects nothing extra."""
        if value is None or value == "":
            return []
        values = value.split(",") if isinstance(value, str) else value
        if not isinstance(values, (list, tuple)) or any(not isinstance(v, str) for v in values):
            raise ValueError("report_main_sports must be comma-separated report sport IDs")
        sports = sorted({"nordic_skiing" if v.strip() == "skiing" else v.strip()
                         for v in values if v.strip()})
        if any(s not in cls.REPORT_SPORTS.values() for s in sports):
            raise ValueError("Unknown report_main_sports ID; use " +
                             ", ".join(sorted(set(cls.REPORT_SPORTS.values()))))
        return sports

    @classmethod
    def _report_observations(cls, activities, start, end):
        """Deduplicate before windowing; conflicting IDs cannot supply intensity."""
        by_id, anonymous = defaultdict(list), []
        invalid_dates = 0
        # Only relevant fields decide a duplicate conflict; names cannot select sports.
        fields = ("type", "start_date_local", "icu_training_load", "moving_time",
                  "icu_zone_times", "icu_hr_zone_times", "trainer", "indoor")
        for act in activities:
            if not isinstance(act, dict):
                continue
            date = act.get("start_date_local")
            try:
                parsed = datetime.strptime(date[:10], "%Y-%m-%d")
                if parsed.strftime("%Y-%m-%d") != date[:10]:
                    raise ValueError("Noncanonical activity date")
            except (TypeError, ValueError):
                invalid_dates += 1
                continue
            aid = act.get("id")
            if aid is None or aid == "":
                anonymous.append(act)
            else:
                by_id[str(aid)].append(act)
        rows, duplicates, conflicts = [], 0, 0
        for group in list(by_id.values()) + [[a] for a in anonymous]:
            signatures = {json.dumps({k: a.get(k) for k in fields}, sort_keys=True,
                                     separators=(",", ":")): a for a in group}
            relevant = [a for a in group if isinstance(a.get("start_date_local"), str)
                        and start <= a["start_date_local"][:10] <= end]
            if not relevant:
                continue
            duplicates += len(group) - 1
            if len(signatures) > 1:
                # Preserve every possible in-window sport as indeterminate, without
                # choosing a contradictory payload or counting its load as zero.
                conflicts += 1
                for sport in sorted({cls._report_sport(a.get("type")) for a in relevant}
                                    - {None}):
                    act = min((a for a in relevant if cls._report_sport(a.get("type")) == sport),
                              key=lambda a: (a["type"], a["start_date_local"]))
                    rows.append({"type": act["type"], "start_date_local": min(
                        a["start_date_local"] for a in relevant
                        if cls._report_sport(a.get("type")) == sport), "_report_conflict": True})
            else:
                rows.append(next(iter(signatures.values())))
        rows.sort(key=lambda a: (a.get("start_date_local", ""), str(a.get("id", "")),
                                json.dumps(a, sort_keys=True, separators=(",", ":"))))
        return rows, {"duplicate_records": duplicates, "conflicting_ids": conflicts,
                      "invalid_date_records": invalid_dates,
                      "missing_ids": sum(a.get("id") in (None, "") for a in rows
                                         if not a.get("_report_conflict"))}

    @classmethod
    def _report_totals(cls, activities):
        """Raw observed sums, explicit missingness, and a deterministic winner."""
        groups = defaultdict(list)
        for act in activities:
            sport = cls._report_sport(act.get("type"))
            if sport in cls.LOAD_SPORTS:
                groups[sport].append(act)
        totals = {}
        for sport, acts in sorted(groups.items()):
            loads = [cls._fact_number(a.get("icu_training_load")) for a in acts]
            times = [cls._fact_number(a.get("moving_time")) for a in acts]
            loads = [v for v in loads if v is not None and v >= 0]
            times = [v for v in times if v is not None and v >= 0]
            totals[sport] = {"sessions": len(acts), "known_tss": math.fsum(loads),
                             "known_moving_seconds": math.fsum(times),
                             "missing_load": len(acts) - len(loads),
                             "missing_time": len(acts) - len(times)}
        denominator = {k: sum(t[k] for t in totals.values()) for k in
                       ("sessions", "missing_load", "missing_time")}
        for k in ("known_tss", "known_moving_seconds"):
            denominator[k] = math.fsum(t[k] for t in totals.values())
        for t in [denominator, *totals.values()]:
            t["tss"] = None if t["missing_load"] else t["known_tss"]
            t["moving_seconds"] = None if t["missing_time"] else t["known_moving_seconds"]
        load_ok = not denominator["missing_load"] and denominator["known_tss"] > 0
        time_ok = not denominator["missing_time"] and denominator["known_moving_seconds"] > 0
        primary, basis = None, None
        if load_ok or time_ok:
            basis = "tss" if load_ok else "moving_time"
            primary = min(totals, key=lambda s: (
                -totals[s]["known_tss"] if load_ok else -totals[s]["known_moving_seconds"],
                -totals[s]["known_moving_seconds"] if load_ok and time_ok else 0, s))
        return totals, denominator, primary, basis

    def _report_weeks(self, start, end, mode, as_of):
        """Disjoint rolling chunks or configured weeks, retaining clipped edges."""
        first, last = (datetime.strptime(d, "%Y-%m-%d") for d in (start, end))
        current = first
        if mode == "calendar":
            current -= timedelta(days=(first.weekday() - self.week_start_day) % 7)
        elif mode != "rolling":
            raise ValueError("Unknown report week mode")
        weeks = []
        while current <= last:
            finish = current + timedelta(days=6)
            lo, hi = max(first, current), min(last, finish)
            full = lo == current and hi == finish
            weeks.append({"start": lo.strftime("%Y-%m-%d"), "end": hi.strftime("%Y-%m-%d"),
                          "full": full, "winner_eligible": full and
                          (mode == "rolling" or finish.strftime("%Y-%m-%d") < as_of)})
            current += timedelta(days=7)
        return weeks

    def _report_zone_source(self, activity):
        """Report-only power/HR validation. Never mutate the shared zone path."""
        candidates = {}
        power = activity.get("icu_zone_times")
        if isinstance(power, list) and power:
            zones = {}
            seen = set()
            for row in power:
                if not isinstance(row, dict):
                    break
                key, seconds = row.get("id"), self._fact_number(row.get("secs"))
                if key not in ("Z1", "Z2", "Z3", "Z4", "Z5", "Z6", "Z7", "SS") or key in seen:
                    break
                if seconds is None or seconds < 0:
                    break
                seen.add(key)
                # Sweet-spot seconds overlap the numbered zones; validate but
                # never count this recognised overlay as another zone.
                if key == "SS":
                    continue
                zones[key] = seconds
            else:
                if math.fsum(zones.values()) > 0:
                    candidates["power"] = (zones, "power_7to3_v1", "icu_zone_times")
        hr = activity.get("icu_hr_zone_times")
        if isinstance(hr, list) and len(hr) in (5, 7):
            seconds = [self._fact_number(v) for v in hr]
            if all(v is not None and v >= 0 for v in seconds) and math.fsum(seconds) > 0:
                candidates["hr"] = ({"Z" + str(i + 1): v for i, v in enumerate(seconds)},
                                    "hr_" + str(len(hr)) + "to3_v1", "icu_hr_zone_times")
        family = self.SPORT_FAMILIES.get(activity.get("type"))
        order = ("hr", "power") if self.zone_preference.get(family) == "hr" else ("power", "hr")
        for basis in order:
            if basis in candidates:
                zones, mapping, field = candidates[basis]
                return basis, mapping, field, [zones.get("Z1", 0) + zones.get("Z2", 0),
                    zones.get("Z3", 0), math.fsum(zones.get("Z" + str(i), 0) for i in range(4, 8))]
        return None

    @staticmethod
    def _report_date_ranges(dates):
        ranges = []
        for day in sorted(set(dates)):
            if ranges and (datetime.strptime(day, "%Y-%m-%d") -
                           datetime.strptime(ranges[-1][1], "%Y-%m-%d")).days == 1:
                ranges[-1][1] = day
            else:
                ranges.append([day, day])
        return ranges

    def _report_intensity(self, activities, start, end, week_mode="calendar",
                          weekly_rescue=False, as_of=None, classify=True):
        """Period-local report contract; selection precedes zone availability."""
        as_of = as_of or datetime.now().strftime("%Y-%m-%d")
        acts, identity = self._report_observations(activities, start, end)
        totals, denominator, primary, primary_basis = self._report_totals(acts)
        weeks = self._report_weeks(start, end, week_mode, as_of)
        weekly, known_weeks = [], []
        for week in weeks:
            wacts = [a for a in acts if week["start"] <= a["start_date_local"][:10] <= week["end"]]
            wt, wd, winner, basis = self._report_totals(wacts)
            if week["winner_eligible"] and wd["sessions"] and not wd["missing_time"]:
                known_weeks.append(wd["known_moving_seconds"])
            weekly.append((wt, wd, winner, basis))
        median = statistics.median(known_weeks) if weekly_rescue and len(known_weeks) >= 2 else None
        floor = median * 0.5 if median is not None else None
        winners = defaultdict(list)
        for i, (week, (wt, wd, winner, basis)) in enumerate(zip(weeks, weekly)):
            qualifies = (weekly_rescue and floor is not None and week["winner_eligible"]
                         and not wd["missing_time"] and winner is not None
                         and wt[winner]["known_moving_seconds"] >= floor)
            week.update({"primary_sport": winner, "primary_basis": basis,
                         "known_moving_seconds": wd["known_moving_seconds"],
                         "missing_time": wd["missing_time"], "sessions": wd["sessions"],
                         "guarded_winner": winner if qualifies else None})
            if qualifies:
                winners[winner].append(i)
        load_ok = denominator["tss"] is not None and denominator["tss"] > 0
        time_ok = denominator["moving_seconds"] is not None and denominator["moving_seconds"] > 0
        main_sports = getattr(self, "report_main_sports", [])
        sports = {}
        for sport, total in totals.items():
            reasons = []
            load_share = total["known_tss"] / denominator["tss"] if load_ok else None
            time_share = total["known_moving_seconds"] / denominator["moving_seconds"] if time_ok else None
            if sport == primary:
                reasons.append("period_primary")
            if load_ok and total["known_tss"] >= 0.10 * denominator["tss"]:
                reasons.append("load_share_10pct")
            if time_ok and total["known_moving_seconds"] >= 0.50 * denominator["moving_seconds"]:
                reasons.append("time_share_50pct")
            if winners[sport]:
                reasons.append("guarded_week_winner")
            if sport in main_sports:
                reasons.append("explicit_main_sport")
            sacts = [a for a in acts if self._report_sport(a.get("type")) == sport]
            active = [i for i, w in enumerate(weeks) if any(
                w["start"] <= a["start_date_local"][:10] <= w["end"] for a in sacts)]
            buckets = defaultdict(list)
            for act in sacts:
                source = self._report_zone_source(act)
                if source:
                    basis, mapping, field, seconds = source
                    buckets[(basis, mapping, field)].append((act, seconds))
            by_basis = []
            for (basis, mapping, field), contributions in sorted(buckets.items()):
                seconds = [math.fsum(s[i] for _, s in contributions) for i in range(3)]
                zone_total = math.fsum(seconds)
                fractions = [s / zone_total for s in seconds]
                pi = self._calculate_polarization_index(*fractions) if classify else None
                dates = sorted({a["start_date_local"][:10] for a, _ in contributions})
                covered = [i for i, w in enumerate(weeks) if any(w["start"] <= d <= w["end"] for d in dates)]
                moving = [self._fact_number(a.get("moving_time")) for a, _ in contributions]
                known_moving = math.fsum(v for v in moving if v is not None and v >= 0)
                aligned = all(v is not None and v >= 0 and v == math.fsum(s)
                              for v, (_, s) in zip(moving, contributions))
                environments = defaultdict(int)
                for a, _ in contributions:
                    flags = [a.get(k) for k in ("indoor", "trainer")]
                    env = ("indoor" if a["type"].startswith("Virtual") or any(v is True for v in flags)
                           else "unknown" if any(v is not None and not isinstance(v, bool) for v in flags)
                           else "outdoor")
                    environments[env] += 1
                by_basis.append({"zone_basis": basis, "mapping_version": mapping, "source_field": field,
                    "activity_types": sorted({a["type"] for a, _ in contributions}),
                    "environments": dict(sorted(environments.items())),
                    "threshold_scope": "activity_relative",
                    **{"z" + str(i + 1) + "_seconds": s for i, s in enumerate(seconds)},
                    **{"z" + str(i + 1) + "_pct": round(f * 100, 1) for i, f in enumerate(fractions)},
                    "total_seconds": zone_total, "polarization_index": pi,
                    "classification": self._classify_tid(*fractions, pi) if classify else None,
                    "coverage": {"sessions": len(contributions), "sport_sessions": len(sacts),
                        "covered_weeks": covered, "covered_ranges": self._report_date_ranges(dates),
                        "known_moving_seconds": known_moving,
                        "missing_time": sum(v is None or v < 0 for v in moving),
                        "sport_known_moving_seconds": total["known_moving_seconds"],
                        "zone_seconds": zone_total, "moving_ratio": None,
                        "ratio_status": "clocks_not_established",
                        "status": "complete_observed_sessions" if aligned and len(contributions) == len(sacts)
                                  else "partial"}})
            unknown = bool(denominator["missing_load"] or denominator["missing_time"])
            covered_sessions = sum(b["coverage"]["sessions"] for b in by_basis)
            sports[sport] = {**total, "selected": bool(reasons), "selection_reasons": reasons,
                "qualification": "selected" if reasons else "indeterminate" if unknown else "not_selected",
                "load_share": load_share, "time_share": time_share,
                "winner_weeks": winners[sport], "active_weeks": active,
                "activity_types": sorted({a["type"] for a in sacts}),
                "zone_sessions": covered_sessions, "unavailable_zone_sessions": len(sacts) - covered_sessions,
                "zone_status": "zones_unavailable" if not by_basis else "observed",
                "by_basis": by_basis}
        return {"schema_version": 1, "rule_version": self.REPORT_INTENSITY_RULE,
            "start": start, "end": end, "as_of": as_of, "week_mode": week_mode,
            "week_start_day": self.week_start_day if week_mode == "calendar" else None,
            "selection_config": {"main_sports": list(main_sports),
                                 "zone_preference": dict(sorted(self.zone_preference.items()))},
            "activity_fetch_coverage": "unknown", "identity": identity,
            "denominator": denominator, "primary_sport": primary, "primary_basis": primary_basis,
            "weekly_guard": {"enabled": weekly_rescue, "known_nonempty_full_weeks": len(known_weeks),
                "median_moving_seconds": median, "minimum_winner_seconds": floor},
            "weeks": weeks, "selected_sports": [s for s in sports if sports[s]["selected"]],
            "sports": sports}

    def _phase_load_schema(self):
        """Current-run settings, not historical athlete preferences."""
        return {"rule": self.PHASE_LOAD_RULE, "eligible_sports": sorted(self.LOAD_SPORTS),
                "selection_rule": self.REPORT_INTENSITY_RULE,
                "week_start_day": self.week_start_day,
                "selection_config_ref": "report_intensity_schema.selection_config",
                "selection": "sports,status; rolling_28d then four configured weeks oldest first",
                "week": "week_start,known_tss,missing_tss,tss,status",
                "week_end": "minimum of week_start plus 6 days and observation_cutoff",
                "monotony_rule": "selected_s7_combined_load_v1",
                "activity_fetch_coverage": "unknown"}

    @staticmethod
    def _pack_phase_load(basis):
        """History keeps target evidence once, decoded by phase_load_schema."""
        return {**{k: basis[k] for k in ("rule", "sports", "status", "selection_status",
                                        "window_28d", "observation_cutoff")},
                "selections": [[s["sports"], s["status"]] for s in basis["selections"]],
                "weeks": [[w[k] for k in ("week_start", "known_tss", "missing_tss", "tss", "status")]
                          for w in basis["weeks"]]}

    def _weekly_main_monotony(self, activities, start, end):
        result = self._main_monotony(activities, start, end, weekly=True)
        return {k: result[k] for k in ("sports", "selection_status", "status", "value",
                "active_days", "elapsed_days", "known_tss", "tss", "missing_tss")}

    @staticmethod
    def _load_cutoff(activities, cutoff):
        # Filter before identity reconciliation: future duplicates cannot poison
        # an earlier target. Retain malformed dates for explicit missingness.
        result = []
        for act in activities or []:
            date = act.get("start_date_local") if isinstance(act, dict) else None
            try:
                parsed = datetime.strptime(date[:10], "%Y-%m-%d")
                valid = parsed.strftime("%Y-%m-%d") == date[:10]
            except (TypeError, ValueError):
                valid = False
            if isinstance(act, dict) and (not valid or date[:10] <= cutoff):
                result.append(act)
        return result

    def _load_selection(self, activities, start, end, report=None, rolling=False, rescue=False):
        if activities is None:
            return {"start": start, "end": end, "sports": [], "status": "unavailable"}
        block = report if report is not None else self._report_intensity(
            activities, start, end, week_mode="rolling" if rolling else "calendar",
            weekly_rescue=rescue, as_of=end)
        if block.get("schema_version") != 1 or block.get("rule_version") != self.REPORT_INTENSITY_RULE:
            return {"start": start, "end": end, "sports": [], "status": "unavailable"}
        sports = sorted(set(block["selected_sports"]) & self.LOAD_SPORTS)
        uncertain = any(s in self.LOAD_SPORTS and v["qualification"] == "indeterminate"
                        for s, v in block["sports"].items())
        # An undated eligible observation cannot be assigned to a complete period.
        _, identity = self._report_observations(
            [a for a in activities if self._report_sport(a.get("type")) in self.LOAD_SPORTS],
            start, end)
        status = "partial" if uncertain or identity["invalid_date_records"] else "complete"
        return {"start": start, "end": end, "sports": sports,
                "status": status if sports or status != "complete" else "empty"}

    def _main_load_days(self, activities, sports, start, end):
        first, last = (datetime.strptime(d, "%Y-%m-%d") for d in (start, end))
        daily = {(first + timedelta(days=i)).strftime("%Y-%m-%d"): []
                 for i in range((last - first).days + 1)}
        acts, identity = self._report_observations(activities or [], start, end)
        _, selected_identity = self._report_observations(
            [a for a in activities or [] if self._report_sport(a.get("type")) in sports], start, end)
        missing = selected_identity["invalid_date_records"]
        for act in acts:
            if self._report_sport(act.get("type")) not in sports:
                continue
            value = self._fact_number(act.get("icu_training_load"))
            if value is None or value < 0:
                missing += 1
            else:
                daily[act["start_date_local"][:10]].append(value)
        values = [math.fsum(v) for v in daily.values()]
        return values, {"known_tss": math.fsum(values), "missing_tss": missing,
                        "status": "unavailable" if activities is None else
                        "partial" if missing else "complete"}

    def _main_monotony(self, activities, start, end, report=None, weekly=False, chronic=False):
        bounded = None if activities is None else self._load_cutoff(activities, end)
        # Reuse a ready selection only when its input had no future observations.
        if bounded != activities:
            report = None
        selection = self._load_selection(bounded, start, end, report, rolling=not weekly)
        values, load = self._main_load_days(bounded, selection["sports"], start, end)
        status = selection["status"]
        value = None
        active = sum(v > 0 for v in values)
        if status == "complete":
            status = load["status"]
            if status == "complete":
                if weekly and (len(values) < 5 or active < 3):
                    status = "insufficient_days"
                elif not active:
                    status = "zero_load"
                else:
                    sd = statistics.stdev(values) if len(values) > 1 else 0
                    status = "available" if sd > 0 else "zero_variance"
                    value = round(statistics.mean(values) / sd, 2) if sd > 0 else None
        status = {"empty": "no_main_sports", "partial": "missing_load" if selection["status"] == "complete"
                  else "incomplete_selection"}.get(status, status)
        result = {**selection, **load, "rule": "selected_s7_combined_load_v1",
                  "selection_source": "configured_week" if weekly else "report_intensity_7d",
                  "selection_status": selection["status"], "status": status, "value": value,
                  "interpretation": self._interpret_monotony(value, value, False),
                  "tss": load["known_tss"] if selection["status"] == "complete" and load["status"] == "complete" else None,
                  "active_days": active, "elapsed_days": len(values), "activity_fetch_coverage": "unknown"}
        if chronic:
            first = (datetime.strptime(end, "%Y-%m-%d") - timedelta(days=27)).strftime("%Y-%m-%d")
            _, chronic_load = self._main_load_days(bounded, selection["sports"], first, end)
            result["reference_28d"] = {"start": first, "end": end, **chronic_load}
            result["deload_context"] = (self._detect_deload_context(load["known_tss"], chronic_load["known_tss"])
                if value is not None and chronic_load["status"] == "complete" else None)
            result["reference_28d"].update(
                tss=chronic_load["known_tss"] if chronic_load["status"] == "complete" else None,
                deload_context=result["deload_context"])
        return result

    @classmethod
    def _main_strain(cls, source):
        """Use the exact seven-day selected set already used for monotony."""
        tss, monotony = source.get("tss"), source.get("value")
        valid = (source.get("status") == "available" and cls._fact_number(tss) is not None
                 and cls._fact_number(monotony) is not None and tss >= 0 and monotony >= 0)
        return {"rule": "selected_s7_strain_v1",
                "source_ref": "derived_metrics.monotony_main_sports",
                "sports": list(source.get("sports", [])), "start": source.get("start"),
                "end": source.get("end"), "status": source.get("status", "unavailable"),
                "tss": tss, "monotony": monotony,
                "value": round(tss * monotony, 0) if valid else None}

    def _main_phase_load(self, activities, weekly_rows, cutoff):
        """One target-local union; never sum locally selected weekly totals."""
        bounded = None if activities is None else self._load_cutoff(activities, cutoff)
        end = datetime.strptime(cutoff, "%Y-%m-%d")
        start28 = (end - timedelta(days=27)).strftime("%Y-%m-%d")
        selections = [self._load_selection(bounded, start28, cutoff, rolling=True, rescue=True)]
        target = datetime.strptime(weekly_rows[-1]["week_start"], "%Y-%m-%d") if weekly_rows else end
        starts = [(target - timedelta(weeks=i)).strftime("%Y-%m-%d") for i in (3, 2, 1, 0)]
        for start in starts:
            finish = min(cutoff, (datetime.strptime(start, "%Y-%m-%d") + timedelta(days=6)).strftime("%Y-%m-%d"))
            selections.append(self._load_selection(bounded, start, finish))
        sports = sorted({s for selection in selections for s in selection["sports"]})
        status = ("unavailable" if any(s["status"] == "unavailable" for s in selections) else
                  "partial" if any(s["status"] == "partial" for s in selections) else
                  "complete" if sports else "empty")
        rows = []
        supplied = {r.get("week_start") for r in weekly_rows}
        for selection in selections[1:]:
            _, load = self._main_load_days(bounded, sports, selection["start"], selection["end"])
            if selection["start"] not in supplied:
                load["status"] = "unavailable"
            rows.append({"week_start": selection["start"], "end": selection["end"], **load,
                         "tss": round(load["known_tss"], 0) if status == "complete" and load["status"] == "complete" else None})
        selection_status = status
        if status == "complete" and any(r["status"] != "complete" for r in rows):
            status = "partial"
        return {"rule": self.PHASE_LOAD_RULE, "sports": sports, "status": status,
                "selection_status": selection_status, "window_28d": {"start": start28, "end": cutoff},
                "observation_cutoff": cutoff, "selections": selections, "weeks": rows,
                "activity_fetch_coverage": "unknown"}

    def _main_phase_features(self, activities, rows, plans, events, completed_ids,
                             today, is_backfill, legacy_s2):
        cutoff = ((datetime.strptime(rows[-1]["week_start"], "%Y-%m-%d") + timedelta(days=6)).strftime("%Y-%m-%d")
                  if is_backfill and rows else today)
        basis = self._main_phase_load(activities, rows, cutoff)
        bounded = None if activities is None else self._load_cutoff(activities, cutoff)
        loads = {r["week_start"]: r for r in basis["weeks"]}
        decision_rows = []
        for row in rows:
            start = row["week_start"]
            load = loads.get(start, {"tss": None, "end": min(cutoff,
                (datetime.strptime(start, "%Y-%m-%d") + timedelta(days=6)).strftime("%Y-%m-%d"))})
            mono = self._main_monotony(bounded, start, load["end"], weekly=True)
            if start in loads:
                loads[start]["monotony_main_sports"] = mono
            decision_rows.append({**row, "total_tss": load["tss"],
                                  "monotony": mono["value"]})
        s1 = self._phase_stream1_features(decision_rows, is_backfill=is_backfill)
        available = basis["status"] == "complete"
        if not available:
            s1["tss_values"] = []
        s1["primary_tss_values"] = []
        # Missing newest monotony must not promote an older elevated value.
        finalized = decision_rows if is_backfill else decision_rows[:-1]
        if not finalized or finalized[-1]["monotony"] is None:
            s1["monotony_trend"] = None
            s1["suggested_phase"] = self._phase_from_stream1(s1, finalized)
        s2 = dict(legacy_s2)
        evidence = dict(legacy_s2["load_evidence"])
        s2["load_evidence"] = evidence
        s2["load_basis_available"] = available
        reference = statistics.mean(s1["tss_values"][-3:]) if s1["tss_values"] else None
        completed = loads[rows[-1]["week_start"]]["tss"] if rows and available else None
        evidence.update(sport_scope=basis["sports"], reference_week_tss=reference,
                        completed_tss=completed, completed_tss_delta=(completed / reference
                            if completed is not None and reference and reference > 0 else None),
                        full_week_reduction="unverified", next_week_rebound="unverified")
        if evidence["completed_tss_delta"] is not None and evidence["completed_tss_delta"] > 0.80:
            evidence["full_week_reduction"] = "contradicted"
        as_of = datetime.strptime(today, "%Y-%m-%d")
        week_end = as_of + timedelta(days=((self.week_start_day - 1) - as_of.weekday()) % 7)
        for key, lo, hi, ratio_key in (
                ("remaining", today, week_end.strftime("%Y-%m-%d"), "planned_tss_delta"),
                ("next_week", (week_end + timedelta(days=1)).strftime("%Y-%m-%d"),
                 (week_end + timedelta(days=7)).strftime("%Y-%m-%d"), "next_week_tss_delta")):
            detail = dict(evidence[key], known_tss=0, missing_tss=0, excluded_sports=[])
            for pw in plans or []:
                date = (pw.get("date") or "")[:10]
                if (pw.get("type") not in self.TRAINING_EVENT_CATEGORIES or not lo <= date <= hi
                        or (pw.get("id") is not None and str(pw["id"]) in (completed_ids or set()))):
                    continue
                sport = self._report_sport(pw.get("sport_type"))
                value = self._fact_number(pw.get("planned_tss"))
                if sport in basis["sports"]:
                    if value is None or value < 0:
                        detail["missing_tss"] += 1
                    else:
                        detail["known_tss"] += value
                elif sport is None:
                    detail["missing_tss"] += 1
                elif sport not in detail["excluded_sports"]:
                    detail["excluded_sports"].append(sport)
            detail["excluded_sports"].sort()
            detail["status"] = ("unavailable" if plans is None or not available else
                                "partial" if detail["missing_tss"] else "complete")
            evidence[key] = detail
            factor = 7 / ((week_end - as_of).days + 1) if key == "remaining" else 1
            # Preserve the legacy positive-plan projection gate, including zero.
            s2[ratio_key] = (round(detail["known_tss"] * factor / reference, 2)
                if detail["status"] == "complete" and reference and reference > 0
                and detail["known_tss"] > 0 else None)
        if not is_backfill:
            clean, _ = self._report_observations(bounded or [], basis["selections"][1]["start"], cutoff)
            aligned = self._phase_current_evidence(clean if bounded is not None else None,
                events, plans, rows, today, None, load_sports=basis["sports"])
            if not available:
                aligned.update(status="unavailable", tss_delta=None)
            evidence["day_aligned"] = aligned
            if aligned["status"] == "reduced" and s2["next_week_tss_delta"] is not None and s2["next_week_tss_delta"] >= 0.80:
                evidence["next_week_rebound"] = "confirmed"
        s2["suggested_phase"] = self._phase_from_stream2(s2)
        evidence["sports"] = evidence.pop("sport_scope")
        if "day_aligned" in evidence:
            evidence["day_aligned"]["sports"] = evidence["day_aligned"].pop("sport_scope")
        basis.update(load_evidence=evidence, planned_tss_delta=s2["planned_tss_delta"],
                     next_week_tss_delta=s2["next_week_tss_delta"], monotony_trend=s1["monotony_trend"],
                     selection_config=self._report_intensity_schema()["selection_config"],
                     week_start_day=self.week_start_day)
        return s1, s2, basis

    def _hard_days_coverage(self, activities):
        """Day-level zone presence only; counts and ladders remain independent."""
        days = {}
        for act in activities:
            date = (act.get("start_date_local") or "")[:10]
            zones, basis = self._get_activity_zones(act,
                sport_family=self.SPORT_FAMILIES.get(act.get("type")))
            days[date] = days.get(date, False) or bool(zones and basis)
        missing = sum(not present for present in days.values())
        return {"days_with_activity": len(days), "days_without_zone_data": missing,
                "status": "no_activities" if not days else "unknown" if missing == len(days)
                else "partial" if missing else "complete"}

    def _report_intensity_schema(self):
        """One file-level decoder for compact report-only observations."""
        return {"schema_version": 2, "rule_version": self.REPORT_INTENSITY_RULE,
            "eligible_sports": sorted(self.LOAD_SPORTS),
            "sport_labels": dict(self.SPORT_LABELS),
            "selection_config": {"main_sports": list(getattr(self, "report_main_sports", [])),
                "zone_preference": dict(sorted(self.zone_preference.items()))},
            "week_start_day": self.week_start_day,
            "mappings": {"p7": "power/power_7to3_v1",
                         "h5": "hr/hr_5to3_v1", "h7": "hr/hr_7to3_v1"},
            "reasons": dict(zip("pltwe", ("period_primary", "load_share_10pct",
                "time_share_50pct", "guarded_week_winner", "explicit_main_sport"))),
            "sport": "sessions,known_tss,known_moving_seconds,active_weeks,zones,exceptions?",
            "zones": "z1_seconds,z2_seconds,z3_seconds,sessions,covered_weeks",
            "tid": "z1_pct,z2_pct,z3_pct,polarization_index?,classification?",
            "guard": "known_nonempty_full_weeks,median_moving_seconds",
            "coverage": "Observed sessions only; fetch completeness and moving-time ratio unknown."}

    def _report_pack(self, block, ready=False):
        """Compact serialization only; preserve every sport, reason and raw sum."""
        if block is None:
            return None
        reasons = self._report_intensity_schema()["reasons"]
        mappings = {"power_7to3_v1": "p7", "hr_5to3_v1": "h5", "hr_7to3_v1": "h7"}
        def number(value):
            return int(value) if isinstance(value, float) and value.is_integer() else value
        result = {"selected": {s: "".join(k for k, v in reasons.items()
                      if v in block["sports"][s]["selection_reasons"])
                      for s in block["selected_sports"]},
                  "sports": {}}
        if ready:
            result.update({"start": block["start"], "end": block["end"],
                           "week_mode": block["week_mode"], "weeks": len(block["weeks"])})
        identity = {k: v for k, v in block["identity"].items() if v}
        if identity:
            result["identity"] = identity
        guard = block["weekly_guard"]
        if guard["enabled"] and (ready or "w" in result["selected"].values()):
            result["guard"] = [guard["known_nonempty_full_weeks"], number(guard["median_moving_seconds"])]
        for sport, source in block["sports"].items():
            value = [number(source[k]) for k in ("sessions", "known_tss", "known_moving_seconds")]
            value += [len(source["active_weeks"]), {}]
            exceptions = {}
            if source["missing_load"] or source["missing_time"]:
                exceptions["missing"] = [source["missing_load"], source["missing_time"]]
            if source["qualification"] == "indeterminate":
                exceptions["indeterminate"] = True
            for basis in source["by_basis"]:
                key = mappings[basis["mapping_version"]]
                coverage = basis["coverage"]
                value[4][key] = [number(basis["z" + str(i) + "_seconds"])
                    for i in (1, 2, 3)] + [coverage["sessions"], len(coverage["covered_weeks"])]
                if coverage["status"] == "partial" and coverage["sessions"] == source["sessions"]:
                    exceptions.setdefault("unaligned", []).append(key)
                if ready and source["selected"]:
                    tid = [basis["z" + str(i) + "_pct"] for i in (1, 2, 3)]
                    if basis["classification"] is not None:
                        tid += [basis["polarization_index"], basis["classification"]]
                    result.setdefault("tid", {}).setdefault(sport, {})[key] = tid
            if exceptions:
                value.append(exceptions)
            result["sports"][sport] = value
        return result

    @staticmethod
    def _report_pack_comparison(comparison):
        """Coverage is read from the two ready blocks, not copied per line."""
        if comparison["status"] != "available":
            return comparison
        mappings = {"power_7to3_v1": "p7", "hr_5to3_v1": "h5", "hr_7to3_v1": "h7"}
        return {"status": "available", "rule_version": comparison["rule_version"], "lines": [
            {"sport": line["sport"], "mapping": mappings.get(line["mapping_version"]),
             "status": line["status"], "pi_delta": line["pi_delta"], "drift": line["drift"]}
            for line in comparison["lines"]]}

    def _report_intensity_comparison(self, acute, chronic):
        """Match selected sport/basis/mapping only; absent blocks never fall back."""
        if not isinstance(acute, dict) or not isinstance(chronic, dict):
            return {"status": "unavailable", "reason": "missing_report_intensity", "lines": []}
        if any(b.get("schema_version") != 1 or b.get("rule_version") != self.REPORT_INTENSITY_RULE
               for b in (acute, chronic)):
            return {"status": "unavailable", "reason": "unsupported_report_intensity", "lines": []}
        for key in ("schema_version", "rule_version", "selection_config"):
            if acute.get(key) != chronic.get(key) or key not in acute:
                return {"status": "unavailable", "reason": "incompatible_" + key, "lines": []}
        lines = []
        for sport in sorted(set(acute["selected_sports"]) | set(chronic["selected_sports"])):
            sides = [block["sports"].get(sport, {}) for block in (acute, chronic)]
            maps = [{(b["zone_basis"], b["mapping_version"]): b for b in s.get("by_basis", [])}
                    for s in sides]
            keys = sorted(set(maps[0]) | set(maps[1])) or [(None, None)]
            for key in keys:
                a, c = (m.get(key) for m in maps)
                complete = all(s.get("selected") and not s.get("missing_load") and not s.get("missing_time")
                               for s in sides) and all(b and b["coverage"]["status"] == "complete_observed_sessions"
                                                      for b in (a, c))
                comparison = self._calculate_tid_comparison(a or {}, c or {})
                if not complete:
                    comparison.update({"pi_delta": None, "drift": None})
                lines.append({"sport": sport, "zone_basis": key[0], "mapping_version": key[1],
                    "status": "complete_observed_sessions" if complete else "unavailable_or_partial",
                    **comparison, "coverage_7d": a.get("coverage") if a else None,
                    "coverage_28d": c.get("coverage") if c else None,
                    "note": "Observed sessions only; activity-fetch completeness is unknown."})
        return {"status": "available", "rule_version": self.REPORT_INTENSITY_RULE,
                "start_7d": acute["start"], "end_7d": acute["end"],
                "start_28d": chronic["start"], "end_28d": chronic["end"], "lines": lines}

    def _report_tid_alerts(self, metrics):
        comparison = (metrics.get("capability") or {}).get("report_intensity_comparison") or {}
        if (comparison.get("status") != "available"
                or comparison.get("rule_version") != self.REPORT_INTENSITY_RULE):
            return []
        blocks = [metrics.get("report_intensity_" + period) or {} for period in ("7d", "28d")]
        alerts, seen = [], set()
        for line in comparison.get("lines", []):
            sport, mapping = line.get("sport"), line.get("mapping")
            if (line.get("status") != "complete_observed_sessions" or sport not in self.LOAD_SPORTS
                    or mapping not in ("p7", "h5", "h7") or (sport, mapping) in seen):
                continue
            sides = []
            for block in blocks:
                row = block.get("sports", {}).get(sport)
                tid = block.get("tid", {}).get(sport, {}).get(mapping)
                if not isinstance(row, list) or len(row) < 5 or not isinstance(tid, list) or len(tid) != 5:
                    break
                exceptions = row[5] if len(row) > 5 else {}
                bucket = row[4].get(mapping)
                if (sport not in block.get("selected", {}) or not bucket or len(bucket) != 5
                        or bucket[3] != row[0] or any(exceptions.get("missing", []))
                        or mapping in exceptions.get("unaligned", [])):
                    break
                sides.append({"polarization_index": tid[3], "classification": tid[4]})
            if len(sides) != 2:
                continue
            actual = self._calculate_tid_comparison(*sides)
            drift = actual.get("drift")
            if drift != line.get("drift") or drift not in ("acute_depolarization", "shifting"):
                continue
            seen.add((sport, mapping))
            acute = drift == "acute_depolarization"
            label = self.SPORT_LABELS[sport] + " (" + ("power" if mapping == "p7" else "HR") + ", " + mapping + ")"
            a, c = (s["polarization_index" if acute else "classification"] for s in sides)
            alerts.append({"metric": "tid_distribution", "value": a, "severity": "warning",
                "threshold": "7d PI < 2.0, 28d PI >= 2.0" if acute else "7d/28d classification mismatch",
                "context": f"{label}: {drift}, 7d {a} vs 28d {c}. Observed sessions only; fetch completeness unknown.",
                "persistence_days": None, "tier": 3, "basis": "main_sports", "sport": sport,
                "mapping": mapping, "scope": "reporting", "readiness_eligible": False})
        return alerts

    @classmethod
    def _longest_session_schema(cls):
        return {"schema_version": 1, "rule_version": "report_sport_longest_v1",
                "sport_identity_rule": cls.SPORT_IDENTITY_RULE, "units": "seconds",
                "scope": "observed_eligible_sports",
                "columns": ["moving_time_s", "date", "activity_id", "activity_type", "status"],
                "tie_break": "moving_time_desc,date_asc,activity_id_asc,activity_type_asc"}

    @classmethod
    def _longest_sessions(cls, activities, start="0001-01-01", end="9999-12-31"):
        # Reconcile IDs against the full supplied history before the row window.
        rows, _ = cls._report_observations(activities, start, end)
        groups = defaultdict(list)
        for act in rows:
            sport = cls._report_sport(act.get("type"))
            if sport in cls.LOAD_SPORTS:
                groups[sport].append(act)
        result = {}
        for sport, group in sorted(groups.items()):
            valid = [a for a in group if cls._fact_number(a.get("moving_time")) is not None
                     and a["moving_time"] >= 0 and not a.get("_report_conflict")]
            if not valid:
                result[sport] = [None, None, None, None, "no_valid_duration"]
                continue
            best = min(valid, key=lambda a: (-a["moving_time"], a["start_date_local"][:10],
                                            str(a.get("id") or ""), a["type"]))
            result[sport] = [best["moving_time"], best["start_date_local"][:10],
                             str(best["id"]) if best.get("id") is not None else None,
                             best["type"], "available" if len(valid) == len(group) else "partial"]
        return result

    def _report_season_intensity(self, activities, weekly_rows, as_of):
        completed = weekly_rows[:-1]
        if not completed:
            return None
        start = completed[0]["week_start"]
        end = (datetime.strptime(completed[-1]["week_start"], "%Y-%m-%d") +
               timedelta(days=6)).strftime("%Y-%m-%d")
        return self._report_intensity(activities, start, end, weekly_rescue=True,
                                      as_of=as_of, classify=False)

    def _report_seiler_tid(self, activities, primary_sport):
        """One supplied main sport across report windows; no all-sport fallback."""
        if not primary_sport:
            return None
        return {**self._build_seiler_tid(activities, sport_family_filter=primary_sport),
                "sport": primary_sport}

    def _zone_reference(self, activity):
        """Provenance only: retain upstream zones and their selected basis."""
        _, basis = self._get_activity_zones(
            activity, sport_family=self.SPORT_FAMILIES.get(activity.get("type"), "other"))
        ftp = self._fact_number(activity.get("icu_ftp")) if basis == "power" else None
        flags = [activity.get(key) for key in ("indoor", "trainer")]
        activity_type = activity.get("type")
        virtual = isinstance(activity_type, str) and activity_type.startswith("Virtual")
        environment = ("indoor" if virtual or any(v is True for v in flags) else
                       "unknown" if any(v is not None and not isinstance(v, bool) for v in flags) else
                       "outdoor")
        return {"basis": basis, "ftp_w": ftp if ftp and ftp > 0 else None,
                "environment": environment}

    # === ZONE EXTRACTION & HARD DAY CLASSIFICATION ===
    # Shared helpers used by _aggregate_zones, derived metrics, and all tier builders.
    # Power zones (icu_zone_times) preferred; HR zones (icu_hr_zone_times) as fallback.
    # HR and power zones are NOT interchangeable — different widths, lag characteristics,
    # and physiological meaning. They are kept in separate accumulators.

    def _get_activity_zones(self, activity: Dict, sport_family: str = None) -> tuple:
        """
        Extract zone times from a single activity.
        
        Returns (zones_dict, basis) where:
        - zones_dict: {"z1": secs, "z2": secs, ...} 
        - basis: "power" | "hr" | None
        
        Power zones (icu_zone_times): list of {"id": "Z3", "secs": 600}
        HR zones (icu_hr_zone_times): flat array of seconds [0, 120, 300, 180, 60]
        
        Default: power preferred, HR fallback.
        When zone_preference is configured for the sport_family, respects that
        preference (e.g. run:hr → HR preferred for running, power fallback).
        HR zones typically 5-zone (indices 0-4 → z1-z5), sometimes 7.
        """
        # Determine preference for this sport family
        prefer_hr = (sport_family and 
                     self.zone_preference.get(sport_family) == "hr")
        
        # Extract both zone sets
        power_zones = None
        icu_zone_times = activity.get("icu_zone_times", [])
        if icu_zone_times:
            pz = {}
            for zone in icu_zone_times:
                zone_id = zone.get("id", "").lower()
                secs = zone.get("secs", 0)
                if zone_id in ("z1", "z2", "z3", "z4", "z5", "z6", "z7"):
                    pz[zone_id] = secs
            if pz:
                power_zones = pz
        
        hr_zones = None
        icu_hr_zone_times = activity.get("icu_hr_zone_times", [])
        if icu_hr_zone_times:
            zone_labels = ("z1", "z2", "z3", "z4", "z5", "z6", "z7")
            hz = {}
            for idx, secs in enumerate(icu_hr_zone_times):
                if idx < len(zone_labels) and secs:
                    hz[zone_labels[idx]] = secs
            if hz:
                hr_zones = hz
        
        # Return based on preference
        if prefer_hr:
            if hr_zones:
                return (hr_zones, "hr")
            if power_zones:
                return (power_zones, "power")
        else:
            if power_zones:
                return (power_zones, "power")
            if hr_zones:
                return (hr_zones, "hr")
        
        return ({}, None)

    @staticmethod
    def _classify_hard_day(day_zones_by_basis: Dict) -> tuple:
        """
        Classify whether a day is hard based on accumulated zone times.
        
        Args:
            day_zones_by_basis: {"power": {"z3": N, "z4": N, ...}, "hr": {"z4": N, "z5": N, ...}}
                Power and HR zones accumulated SEPARATELY across the day's activities.
        
        Returns (is_hard, basis) where:
        - is_hard: True | False | None (None = no zone data, unknown)
        - basis: "power" | "hr" | "mixed" | None
        
        Power ladder (5 rungs, per Seiler/Foster):
            z3+ >= 1800s, z4+ >= 600s, z5+ >= 300s, z6+ >= 120s, z7 >= 60s
        
        HR ladder (2 rungs, conservative — per Seiler 3-zone model):
            z4+ >= 600s (sustained above LT2)
            z5+ >= 300s (VO2max)
        
        HR zones are too wide and lagged for fine-grained classification.
        Short-duration rungs (z6+/z7) invalid for HR due to cardiac lag.
        Z3 skipped for HR to avoid false positives on steady-state runs.
        """
        pz = day_zones_by_basis.get("power", {})
        hz = day_zones_by_basis.get("hr", {})
        
        has_power = bool(pz)
        has_hr = bool(hz)
        
        if not has_power and not has_hr:
            return (None, None)
        
        # Power ladder (unchanged)
        power_hard = False
        if has_power:
            p_z3 = pz.get("z3", 0)
            p_z4 = pz.get("z4", 0)
            p_z5 = pz.get("z5", 0)
            p_z6 = pz.get("z6", 0)
            p_z7 = pz.get("z7", 0)
            power_hard = (
                (p_z3 + p_z4 + p_z5 + p_z6 + p_z7) >= 1800 or  # z3+: 30 min tempo+
                (p_z4 + p_z5 + p_z6 + p_z7) >= 600 or            # z4+: 10 min threshold+
                (p_z5 + p_z6 + p_z7) >= 300 or                    # z5+: 5 min VO2max+
                (p_z6 + p_z7) >= 120 or                            # z6+: 2 min anaerobic+
                p_z7 >= 60                                          # z7:  1 min neuromuscular
            )
        
        # HR ladder (conservative fallback)
        hr_hard = False
        if has_hr:
            h_z4 = hz.get("z4", 0)
            h_z5 = hz.get("z5", 0)
            h_z6 = hz.get("z6", 0)
            h_z7 = hz.get("z7", 0)
            hr_hard = (
                (h_z4 + h_z5 + h_z6 + h_z7) >= 600 or  # z4+: 10 min above LT2
                (h_z5 + h_z6 + h_z7) >= 300              # z5+: 5 min VO2max
            )
        
        is_hard = power_hard or hr_hard
        
        # Determine basis
        if has_power and has_hr:
            basis = "mixed"
        elif has_power:
            basis = "power"
        else:
            basis = "hr"
        
        return (is_hard, basis)

    def _aggregate_zones(self, activities: List[Dict]) -> Dict:
        """
        Aggregate zone times across all activities.
        
        Returns separate Z1, Z2, Z3, and Z4+ times for proper polarization analysis.
        Per Seiler's model:
        - Z1-Z2: Easy (below LT1)
        - Z3: Grey zone / Tempo (between LT1 and LT2) - to be minimized
        - Z4+: Hard / Quality (above LT2) - ~20% target
        
        Uses _get_activity_zones() for consistent zone preference support.
        """
        z1_time = 0
        z2_time = 0
        z3_time = 0
        z4_plus_time = 0
        total_time = 0
        basis_set = set()
        
        for act in activities:
            sf = self.SPORT_FAMILIES.get(act.get("type", ""), None)
            zones, basis = self._get_activity_zones(act, sport_family=sf)
            
            if zones:
                if basis:
                    basis_set.add(basis)
                z1_time += zones.get("z1", 0)
                z2_time += zones.get("z2", 0)
                z3_time += zones.get("z3", 0)
                z4_plus_time += (zones.get("z4", 0) + zones.get("z5", 0) + 
                               zones.get("z6", 0) + zones.get("z7", 0))
                total_time += sum(zones.values())
        
        # Determine aggregate zone basis
        if len(basis_set) > 1:
            zone_basis = "mixed"
        elif len(basis_set) == 1:
            zone_basis = next(iter(basis_set))
        else:
            zone_basis = None
        
        return {
            "z1_time": z1_time,
            "z2_time": z2_time,
            "z3_time": z3_time,
            "z4_plus_time": z4_plus_time,
            "total_time": total_time,
            "zone_basis": zone_basis
        }
    
    # === SEILER TID (Training Intensity Distribution) v3.4.0 ===

    def _aggregate_seiler_zones(self, activities: List[Dict],
                                sport_family_filter: str = None) -> Dict:
        """
        Aggregate 7-zone times into Seiler 3-zone model.

        Mapping (per Treff et al. 2019):
            Seiler Z1 = z1 + z2  (below LT1)
            Seiler Z2 = z3       (between LT1 and LT2)
            Seiler Z3 = z4 + z5 + z6 + z7  (above LT2)

        Uses _get_activity_zones() for consistent zone preference support.

        Args:
            activities: List of activity dicts with zone data
            sport_family_filter: If set, only include activities matching
                                 this sport family (from SPORT_FAMILIES).
                                 Note: this controls which activities enter
                                 the aggregation; zone preference uses each
                                 activity's own sport family (separate lookup).

        Returns dict with z1_seconds, z2_seconds, z3_seconds, total_seconds, zone_basis
        """
        sz1 = 0
        sz2 = 0
        sz3 = 0
        basis_set = set()

        for act in activities:
            # Apply sport family filter if specified (controls inclusion)
            activity_type = act.get("type", "Unknown")
            act_sport_family = self.SPORT_FAMILIES.get(activity_type, "other")
            if sport_family_filter:
                if act_sport_family != sport_family_filter:
                    continue

            # Zone preference uses each activity's own sport family
            zones, basis = self._get_activity_zones(act, sport_family=act_sport_family)

            if zones:
                if basis:
                    basis_set.add(basis)
                sz1 += zones.get("z1", 0) + zones.get("z2", 0)
                sz2 += zones.get("z3", 0)
                sz3 += (zones.get("z4", 0) + zones.get("z5", 0) +
                        zones.get("z6", 0) + zones.get("z7", 0))

        total = sz1 + sz2 + sz3
        
        # Determine aggregate zone basis
        if len(basis_set) > 1:
            zone_basis = "mixed"
        elif len(basis_set) == 1:
            zone_basis = next(iter(basis_set))
        else:
            zone_basis = None
        
        return {
            "z1_seconds": sz1,
            "z2_seconds": sz2,
            "z3_seconds": sz3,
            "total_seconds": total,
            "zone_basis": zone_basis
        }

    def _calculate_polarization_index(self, z1_frac: float, z2_frac: float,
                                       z3_frac: float) -> Optional[float]:
        """
        Calculate Treff Polarization Index.

        Formula: PI = log10((Z1 / Z2) × Z3 × 100)

        Rules (per Treff et al. 2019 + updated literature):
        - Only compute when Z1 > Z3 > Z2 and Z3 >= 0.01
        - If Z2 = 0 but structure is polarized: substitute Z2 = 0.01
        - Otherwise: return None (not a polarization score)
        """
        if z3_frac < 0.01:
            return None
        if not (z1_frac > z3_frac > z2_frac):
            return None

        # Handle Z2 = 0 with substitution (per updated PI formulation)
        effective_z2 = z2_frac if z2_frac > 0 else 0.01

        try:
            raw = (z1_frac / effective_z2) * z3_frac * 100
            if raw <= 0:
                return None
            return round(math.log10(raw), 2)
        except (ValueError, ZeroDivisionError):
            return None

    def _classify_tid(self, z1_frac: float, z2_frac: float,
                      z3_frac: float, pi: Optional[float]) -> str:
        """
        Classify Training Intensity Distribution.

        Explicit priority order (to avoid overlaps):
        1. Z3 < 0.01 and Z1 largest → Base
        2. Z1 > Z3 > Z2 and PI > 2.0 → Polarized
        3. Z1 > Z2 > Z3 → Pyramidal
        4. Z2 largest → Threshold
        5. Z3 largest → High Intensity
        """
        # 1. Base: Z3 near zero, Z1 dominant
        if z3_frac < 0.01 and z1_frac >= z2_frac and z1_frac >= z3_frac:
            return "Base"

        # 2. Polarized: Z1 > Z3 > Z2 and PI > 2.0
        if z1_frac > z3_frac > z2_frac and pi is not None and pi > 2.0:
            return "Polarized"

        # 3. Pyramidal: Z1 > Z2 > Z3
        if z1_frac > z2_frac > z3_frac:
            return "Pyramidal"

        # 4. Threshold: Z2 dominant
        if z2_frac >= z1_frac and z2_frac >= z3_frac:
            return "Threshold"

        # 5. High Intensity: Z3 dominant
        if z3_frac >= z1_frac and z3_frac >= z2_frac:
            return "High Intensity"

        # Fallback: polarized structure but PI <= 2.0
        return "Pyramidal"

    def _build_seiler_tid(self, activities: List[Dict],
                          sport_family_filter: str = None) -> Dict:
        """
        Build complete Seiler TID structure for given activities.

        Returns dict with:
            z1_seconds, z2_seconds, z3_seconds
            z1_pct, z2_pct, z3_pct
            polarization_index (float or null)
            classification (string)
            zone_basis ("power" | "hr" | "mixed" | null)
        """
        zones = self._aggregate_seiler_zones(activities, sport_family_filter)
        total = zones["total_seconds"]
        zone_basis = zones["zone_basis"]

        if total == 0:
            return {
                "z1_seconds": 0,
                "z2_seconds": 0,
                "z3_seconds": 0,
                "z1_pct": None,
                "z2_pct": None,
                "z3_pct": None,
                "polarization_index": None,
                "classification": None,
                "zone_basis": None
            }

        z1_frac = zones["z1_seconds"] / total
        z2_frac = zones["z2_seconds"] / total
        z3_frac = zones["z3_seconds"] / total

        pi = self._calculate_polarization_index(z1_frac, z2_frac, z3_frac)
        classification = self._classify_tid(z1_frac, z2_frac, z3_frac, pi)

        return {
            "z1_seconds": zones["z1_seconds"],
            "z2_seconds": zones["z2_seconds"],
            "z3_seconds": zones["z3_seconds"],
            "z1_pct": round(z1_frac * 100, 1),
            "z2_pct": round(z2_frac * 100, 1),
            "z3_pct": round(z3_frac * 100, 1),
            "polarization_index": pi,
            "classification": classification,
            "zone_basis": zone_basis
        }

    @classmethod
    def _cycling_durability_values(cls, activities):
        values = []
        for act in activities:
            if cls._report_sport(act.get("type")) != "cycling":
                continue
            dec, vi = act.get("decoupling"), act.get("icu_variability_index")
            mt = act.get("moving_time", 0) or 0
            if dec is not None and vi is not None and 0 < vi <= 1.05 and mt >= 5400:
                values.append(dec)
        return values

    def _calculate_durability(self, activities_7d: List[Dict],
                               activities_28d: List[Dict]) -> Dict:
        """
        Calculate aggregate decoupling as a durability trend.

        Filters to cycling steady-state power sessions only:
        - decoupling is not None
        - variability_index is not None and > 0 and <= 1.05
        - moving_time >= 5400 (90 minutes)

        Per Maunder et al. (2021), Rothschild et al. (2025): meaningful
        cardiac drift requires prolonged exercise. 90 min is the practical
        field floor where drift becomes detectable.

        Negative decoupling is included — it indicates HR drifted down
        relative to power (strong durability or cooling conditions).

        Returns dict with 7d/28d means, high-drift counts, qualifying
        session counts, and trend direction.
        """
        vals_7d = self._cycling_durability_values(activities_7d)
        vals_28d = self._cycling_durability_values(activities_28d)

        # Compute means (need >= 2 qualifying sessions)
        mean_7d = round(statistics.mean(vals_7d), 2) if len(vals_7d) >= 2 else None
        mean_28d = round(statistics.mean(vals_28d), 2) if len(vals_28d) >= 2 else None

        # High drift counts (> 5%)
        high_drift_7d = sum(1 for v in vals_7d if v > 5.0)
        high_drift_28d = sum(1 for v in vals_28d if v > 5.0)

        # Trend (requires both windows)
        trend = None
        if mean_7d is not None and mean_28d is not None:
            delta = mean_7d - mean_28d
            if delta < -1.0:
                trend = "improving"
            elif delta > 1.0:
                trend = "declining"
            else:
                trend = "stable"

        # Reliability gate: alarm needs N28>=5; declining warning needs N7>=3 AND N28>=5.
        # Flag set whenever either gate would suppress an alert if one were to fire.
        # The mean itself is still computed at N>=2 for situational awareness.
        n7 = len(vals_7d)
        n28 = len(vals_28d)
        reliability_limited = (n28 < 5) or (n7 < 3)
        reliability_note = None
        if reliability_limited:
            reliability_note = (
                f"insufficient qualifying sessions for alert evaluation: "
                f"7d N={n7} (min 3), 28d N={n28} (min 5)"
            )

        if self.debug:
            print(f"  Durability: 7d={mean_7d} ({n7} sessions), "
                  f"28d={mean_28d} ({n28} sessions), trend={trend}, "
                  f"reliability_limited={reliability_limited}")

        return {
            "mean_decoupling_7d": mean_7d,
            "sport": "cycling",
            "sport_identity_rule": self.SPORT_IDENTITY_RULE,
            "mean_decoupling_28d": mean_28d,
            "high_drift_count_7d": high_drift_7d,
            "high_drift_count_28d": high_drift_28d,
            "qualifying_sessions_7d": n7,
            "qualifying_sessions_28d": n28,
            "trend": trend,
            "reliability_limited": reliability_limited,
            "reliability_note": reliability_note,
            "note": ("Cycling steady-state power sessions only (VI <= 1.05, VI > 0, "
                     ">= 90min, power data). Negative decoupling = strong "
                     "durability. Trend compares 7d vs 28d mean "
                     "(+/-1% = stable). Alerts require N28>=5 (alarm) "
                     "or N7>=3 AND N28>=5 (declining warning) for "
                     "statistical reliability.")
        }

    def _calculate_efficiency_factor(self, activities_7d: List[Dict],
                                      activities_28d: List[Dict]) -> Dict:
        """
        Calculate aggregate Efficiency Factor (EF) as an aerobic fitness trend.

        EF = Normalized Power / Average HR (Coggan). Intervals.icu provides
        this as icu_efficiency_factor per activity.

        Filters to qualifying sessions only:
        - icu_efficiency_factor is not None
        - Cycling types (Ride, VirtualRide, MountainBikeRide, GravelRide)
        - icu_variability_index is not None and > 0 and <= 1.05 (steady-state)
        - moving_time >= 1200 (20 minutes)

        Per TrainingPeaks / Coggan: EF is only valid for aerobic, steady-state
        efforts. Values under 20 minutes are not reliable. Low VI ensures
        steady pacing for meaningful HR-power relationship.

        Rising EF at the same intensity = improving aerobic fitness.
        Compare like-for-like sessions only — EF varies with intensity.

        Returns dict with 7d/28d means, qualifying session counts, and trend.
        """
        CYCLING_TYPES = {"Ride", "VirtualRide", "MountainBikeRide", "GravelRide"}

        def _filter_qualifying(activities: List[Dict]) -> List[float]:
            """Return EF values from qualifying sessions."""
            qualifying = []
            for act in activities:
                ef = act.get("icu_efficiency_factor")
                vi = act.get("icu_variability_index")
                mt = act.get("moving_time", 0) or 0
                act_type = act.get("type", "")

                if (ef is not None
                        and act_type in CYCLING_TYPES
                        and vi is not None
                        and vi > 0
                        and vi <= 1.05
                        and mt >= 1200):
                    qualifying.append(ef)
            return qualifying

        vals_7d = _filter_qualifying(activities_7d)
        vals_28d = _filter_qualifying(activities_28d)

        # Compute means (need >= 2 qualifying sessions)
        mean_7d = round(statistics.mean(vals_7d), 2) if len(vals_7d) >= 2 else None
        mean_28d = round(statistics.mean(vals_28d), 2) if len(vals_28d) >= 2 else None

        # Trend (requires both windows)
        trend = None
        if mean_7d is not None and mean_28d is not None:
            delta = mean_7d - mean_28d
            if delta > 0.03:
                trend = "improving"
            elif delta < -0.03:
                trend = "declining"
            else:
                trend = "stable"

        if self.debug:
            print(f"  Efficiency Factor: 7d={mean_7d} ({len(vals_7d)} sessions), "
                  f"28d={mean_28d} ({len(vals_28d)} sessions), trend={trend}")

        return {
            "mean_ef_7d": mean_7d,
            "mean_ef_28d": mean_28d,
            "qualifying_sessions_7d": len(vals_7d),
            "qualifying_sessions_28d": len(vals_28d),
            "trend": trend,
            "note": ("Steady-state cycling sessions only (VI <= 1.05, VI > 0, "
                     ">= 20min, power+HR data). Rising EF = improving aerobic "
                     "efficiency. Compare like-for-like sessions only — "
                     "EF varies with intensity. Trend compares 7d vs 28d mean "
                     "(+/-0.03 = stable).")
        }

    def _calculate_hrrc_trend(self, activities_7d: List[Dict],
                               activities_28d: List[Dict]) -> Dict:
        """
        Calculate aggregate HRRc (heart rate recovery) as a recovery quality trend.

        HRRc = largest 60-second HR drop (bpm) after exceeding configured
        threshold HR for >1 minute. Intervals.icu API field: icu_hrr,
        displayed as HRRc. Higher = faster parasympathetic recovery.

        Qualifying criteria: icu_hrr is not None (self-selects — only fires
        when threshold HR held >1min and cooldown recorded).

        Window minimums: 7d >= 1 session, 28d >= 3 sessions.
        Trend: 7d mean vs 28d mean, >10% difference = meaningful
        (conservative threshold for noisy field metric; lab CV ~4% but
        field CV likely 10-15% due to variable workout type, intensity,
        and recording conditions).

        References:
        - Fecchio et al. (2019) systematic review: HRR60s exhibits high
          reliability (ICC up to 0.99, CV 3.4-13.5% across protocols)
        - Lamberts et al. (2024): HRR60s ICC=0.97, TEM=4.3% in cyclists
        - Buchheit (2006): HRR associated with training loads, not VO2max
        - Intervals.icu: renamed HRR to HRRc to avoid confusion with
          Heart Rate Reserve (Tinker, 2019)
        """
        def _filter_qualifying(activities: List[Dict]) -> List[float]:
            """Return HRRc values from sessions where it was recorded."""
            qualifying = []
            for act in activities:
                hrrc = act.get("icu_hrr")
                if hrrc is None:
                    continue
                # API may return a dict (e.g. {"value": 34}) or a plain number
                if isinstance(hrrc, dict):
                    _v = hrrc.get("value")
                    if _v is None:
                        _v = hrrc.get("hrr")
                    hrrc = _v
                if isinstance(hrrc, (int, float)) and hrrc > 0:
                    qualifying.append(float(hrrc))
            return qualifying

        vals_7d = _filter_qualifying(activities_7d)
        vals_28d = _filter_qualifying(activities_28d)

        # 7d: >= 1 session (report value or mean)
        mean_7d = round(statistics.mean(vals_7d), 1) if len(vals_7d) >= 1 else None
        # 28d: >= 3 sessions (noise dampening for field metric)
        mean_28d = round(statistics.mean(vals_28d), 1) if len(vals_28d) >= 3 else None

        # Trend: >10% difference = meaningful (conservative for field noise)
        trend = None
        if mean_7d is not None and mean_28d is not None and mean_28d > 0:
            pct_change = (mean_7d - mean_28d) / mean_28d
            if pct_change > 0.10:
                trend = "improving"
            elif pct_change < -0.10:
                trend = "declining"
            else:
                trend = "stable"

        if self.debug:
            print(f"  HRRc: 7d={mean_7d} ({len(vals_7d)} sessions), "
                  f"28d={mean_28d} ({len(vals_28d)} sessions), trend={trend}")

        return {
            "mean_hrrc_7d": mean_7d,
            "mean_hrrc_28d": mean_28d,
            "qualifying_sessions_7d": len(vals_7d),
            "qualifying_sessions_28d": len(vals_28d),
            "trend": trend,
            "note": ("HRRc = heart rate recovery (largest 60s HR drop in bpm "
                     "after exceeding threshold HR for >1 min). Higher = "
                     "better parasympathetic recovery. Null when threshold "
                     "not reached, recording stopped before cooldown, or no "
                     "HR data. Trend: 7d mean vs 28d mean, >10% = meaningful "
                     "(min 1 session/7d, 3 sessions/28d). Display only — "
                     "not wired into readiness_decision signals.")
        }

    @classmethod
    def _curve_power_observed(cls, act):
        fields = ("average_watts", "avg_watts", "average_power", "avgWatts", "icu_average_watts",
                  "weighted_average_watts", "np", "icu_pm_np", "normalizedPower", "icu_weighted_avg_watts")
        if any(cls._fact_number(act.get(k)) is not None and act[k] > 0 for k in fields):
            return True
        if "watts" in (act.get("stream_types") or []):
            return True
        zones = act.get("icu_zone_times")
        if not isinstance(zones, list) or not zones:
            return False
        seen, total = set(), 0
        for row in zones:
            if not isinstance(row, dict) or row.get("id") not in ("Z1", "Z2", "Z3", "Z4", "Z5", "Z6", "Z7", "SS"):
                return False
            key, value = row["id"], cls._fact_number(row.get("secs"))
            if key in seen or value is None or value < 0:
                return False
            seen.add(key)
            if key != "SS":
                total += value
        return total > 0

    @classmethod
    def _curve_scope_risk(cls, sport, activities, start, end):
        # Conservative possible shared groups, not a claim about live grouping.
        groups = ({"cycling", "e_cycling", "handcycling"},
                  {"running", "walking", "hiking"}, {"nordic_skiing", "alpine_skiing"},
                  {"rowing", "paddling"})
        peers = next((g - {sport} for g in groups if sport in g), set())
        return any(cls._report_sport(a.get("type")) in peers
                   and start <= (cls._fact_date(a.get("start_date_local")) or "") <= end
                   for a in activities)

    def _sport_curve_points(self, payload, request_type, sport, metric, dates, activities, identities,
                           submax_efforts=3):
        """Validate new typed curves; a rejected maximum never gains invented provenance."""
        durations = (5, 60, 300, 1200, 3600) if metric == "power" else (60, 300, 1200, 3600)
        windows = (dates[:2], dates[2:])
        points, reasons = [{}, {}], [{}, {}]
        curves = payload.get("list") if isinstance(payload, dict) else payload
        if not isinstance(curves, list) or any(not isinstance(c, dict) for c in curves):
            raise ValueError("invalid_curve_list")
        for wi, (start, end) in enumerate(windows):
            cid = f"r.{start}.{end}"
            matches = [c for c in curves if c.get("id") == cid]
            if not matches:
                reasons[wi] = {s: "missing_window" for s in durations}
                continue
            if any(c != matches[0] for c in matches[1:]):
                raise ValueError("conflicting_window_ids")
            curve = matches[0]
            secs = curve.get("secs")
            values = curve.get("watts", curve.get("values")) if metric == "power" else curve.get("values")
            if not isinstance(secs, list) or not isinstance(values, list):
                raise ValueError("invalid_curve_arrays")
            ids_present = "activity_id" in curve
            ids = curve.get("activity_id")
            if ids_present and not isinstance(ids, list):
                raise ValueError("invalid_activity_ids")
            subs, subids = curve.get("submax_values", []), curve.get("submax_activity_id", [])
            if not isinstance(subs, list) or not isinstance(subids, list) or len(subs) != len(subids):
                raise ValueError("invalid_submax_arrays")
            if any(not isinstance(v, list) or not isinstance(i, list) or len(v) != len(i)
                   for v, i in zip(subs, subids)):
                raise ValueError("invalid_submax_arrays")
            # Rank arrays align with secs from index zero; missing tails mean
            # no effort. Retain point-major only when its shape cannot be ranks.
            rank_major = len(subs) <= submax_efforts and all(len(v) <= len(secs) for v in subs)
            point_major = (len(subs) == len(secs) and len(subs) > submax_efforts
                           and all(len(v) <= submax_efforts for v in subs))
            if not (rank_major or point_major):
                raise ValueError("invalid_submax_shape")
            for seconds in durations:
                indexes = [i for i, s in enumerate(secs) if type(s) in (int, float)
                           and math.isfinite(s) and s == seconds]
                if not indexes:
                    reasons[wi][seconds] = "missing_anchor"
                    continue
                if len(indexes) != 1:
                    raise ValueError("duplicate_anchor")
                i = indexes[0]
                efforts = [(values[i] if i < len(values) else None,
                            ids[i] if ids_present and i < len(ids) else None)]
                if rank_major:
                    efforts += [(v[i], aid[i]) for v, aid in zip(subs, subids) if i < len(v)]
                elif point_major:
                    efforts += list(zip(subs[i], subids[i]))
                winners, rejected = [], False
                for value, aid in efforts:
                    if self._fact_number(value) is None or value <= 0:
                        continue
                    if aid is None and not ids_present:
                        if self._curve_scope_risk(sport, activities, start, end):
                            rejected = True
                            continue
                        source = {"request_type": request_type, "activity_id": None, "date": None}
                    else:
                        identity = identities.get(str(aid)) if aid is not None else None
                        if (identity is None or self._report_sport(identity[0]) != sport
                                or not start <= identity[1] <= end):
                            rejected = True
                            continue
                        source = {"request_type": request_type, "activity_id": str(aid), "date": identity[1]}
                    winners.append((value, source))
                if winners:
                    points[wi][seconds] = min(winners, key=self._curve_winner_key)
                else:
                    reasons[wi][seconds] = "no_eligible_attributed_effort" if rejected else "missing_anchor"
        return points, reasons

    @staticmethod
    def _curve_winner_key(point):
        value, source = point
        return (-value, source["activity_id"] is None, source["date"] or "",
                source["activity_id"] or "", source["request_type"])

    def _sport_curve_deltas(self, activities, selected, dates):
        """One typed request per observed type/metric, max merge, no legacy fallback."""
        result = {"schema_version": 1, "rule_version": self.REPORT_INTENSITY_RULE,
                  "selection_ref": "derived_metrics.report_intensity_28d", "window_days": 28,
                  "sports": {}}
        if not dates:
            result["status"] = "unavailable"
            return result
        result.update(current_window={"start": dates[0], "end": dates[1]},
                      previous_window={"start": dates[2], "end": dates[3]})
        acts = [a for a in activities if dates[2] <= (self._fact_date(a.get("start_date_local")) or "") <= dates[1]]
        identities = {}
        for a in activities:
            if a.get("id") in (None, ""):
                continue
            key = str(a["id"])
            identity = (a.get("type"), self._fact_date(a.get("start_date_local")))
            if key not in identities:
                identities[key] = identity if identity[1] is not None else None
            elif identities[key] != identity:
                identities[key] = None
        for sport in sorted(set(selected) & self.LOAD_SPORTS):
            types = sorted({a["type"] for a in acts if self._report_sport(a.get("type")) == sport})
            sport_result = result["sports"][sport] = {"activity_types": types}
            for metric in ("power", "hr"):
                requested = [t for t in types if metric == "hr" or any(
                    a.get("type") == t and self._curve_power_observed(a) for a in acts)]
                durations = (5, 60, 300, 1200, 3600) if metric == "power" else (60, 300, 1200, 3600)
                merged, reasons, failed = [{}, {}], [{}, {}], []
                partial = False
                submax_efforts = 3
                for typ in requested:
                    try:
                        payload = self._intervals_get(metric + "-curves", {"type": typ,
                            "curves": f"r.{dates[0]}.{dates[1]},r.{dates[2]}.{dates[3]}",
                            "subMaxEfforts": submax_efforts})
                        points, issues = self._sport_curve_points(
                            payload, typ, sport, metric, dates, acts, identities, submax_efforts)
                    except (requests.exceptions.RequestException, ValueError, TypeError, KeyError):
                        failed.append(typ)
                        partial = True
                        continue
                    for wi in (0, 1):
                        for sec, point in points[wi].items():
                            if sec not in merged[wi] or self._curve_winner_key(point) < self._curve_winner_key(merged[wi][sec]):
                                merged[wi][sec] = point
                        for sec, reason in issues[wi].items():
                            reasons[wi].setdefault(sec, reason)
                            if reason == "no_eligible_attributed_effort":
                                partial = True
                counts = [len(v) for v in merged]
                status = ("no_power_observed" if metric == "power" and not requested else
                          "partial" if partial else "available" if min(counts) >= 3 else
                          "one_window_only" if (counts[0] > 0) != (counts[1] > 0) else
                          "insufficient_data" if max(counts) else "unavailable")
                key = "watts" if metric == "power" else "bpm"
                anchors = {}
                for sec in durations:
                    row = {}
                    for wi, side in enumerate(("current", "previous")):
                        value, source = merged[wi].get(sec, (None, None))
                        row[side + "_" + key], row[side + "_source"] = value, source
                        if value is None:
                            row[side + "_reason"] = reasons[wi].get(sec, "fetch_failed" if failed else "missing_anchor")
                    row["pct_change"] = None
                    anchors[str(sec) + "s"] = row
                rotation = None
                if status == "available":
                    payload = {"list": [{"id": f"r.{start}.{end}", "secs": list(durations),
                        "watts" if metric == "power" else "values": [merged[wi].get(s, (None,))[0] for s in durations]}
                        for wi, (start, end) in enumerate((dates[:2], dates[2:]))]}
                    calculate = self._calculate_power_curve_delta if metric == "power" else self._calculate_hr_curve_delta
                    delta = calculate(payload, dates)
                    for label, row in (delta.get("anchors") or {}).items():
                        anchors[label]["pct_change"] = row["pct_change"]
                    rotation = delta["rotation_index"]
                sport_result[metric] = {"status": status, "requested_types": requested,
                    "failed_types": failed, "current_valid_anchors": counts[0], "previous_valid_anchors": counts[1],
                    "anchors": anchors if requested else None, "rotation_index": rotation}
        return result

    def _calculate_power_curve_delta(self, power_curve_data: Dict = None,
                                      power_curve_dates: Tuple = None) -> Dict:
        """
        Calculate power curve delta across two 28-day windows.
        
        Extracts MMP at five anchor durations (5s, 60s, 300s, 1200s, 3600s)
        from each window. Computes % change per anchor and rotation_index.
        
        Rotation index = mean(short-anchor changes) - mean(long-anchor changes)
        where short = 5s, 60s and long = 1200s, 3600s. 300s excluded (transitional).
        Positive = sprint-biased gains, negative = endurance-biased gains.
        
        Curve matching by response ID field, not list index — handles empty
        windows gracefully (API omits curves with no data).
        
        Guards:
        - Per-anchor: null if duration not in secs array or watts is 0/None
        - pct_change: null if either window's anchor watts is 0/None
        - Block-level: null if either window has < 3 non-null anchors
        - Rotation: null if any of the 4 component anchors has null pct_change
        
        References:
        - Pinot & Grappe (2011): power-duration profiling across durations
        - Quod et al. (2010): MMP tracking for training monitoring
        - Intervals.icu API: GET /api/v1/athlete/{id}/power-curves
        """
        ANCHORS = {"5s": 5, "60s": 60, "300s": 300, "1200s": 1200, "3600s": 3600}
        
        # Build null block (reused for all early returns)
        def _null_block(note="Insufficient power data in one or both windows."):
            dates = {}
            if power_curve_dates:
                dates = {
                    "current_window": {"start": power_curve_dates[0], "end": power_curve_dates[1]},
                    "previous_window": {"start": power_curve_dates[2], "end": power_curve_dates[3]},
                }
            return {
                "window_days": 28,
                **dates,
                "anchors": None,
                "rotation_index": None,
                "note": note
            }
        
        # Guard: no data or no dates
        if not power_curve_data or not power_curve_dates:
            return _null_block()
        
        curves_list = power_curve_data.get("list", [])
        if not curves_list:
            return _null_block()
        
        # Match curves by ID, not list index
        pc_start1, pc_end1, pc_start2, pc_end2 = power_curve_dates
        current_id = f"r.{pc_start1}.{pc_end1}"
        previous_id = f"r.{pc_start2}.{pc_end2}"
        
        curves_by_id = {c["id"]: c for c in curves_list if "id" in c}
        current_curve = curves_by_id.get(current_id)
        previous_curve = curves_by_id.get(previous_id)
        
        if not current_curve or not previous_curve:
            missing = []
            if not current_curve:
                missing.append("current")
            if not previous_curve:
                missing.append("previous")
            return _null_block(f"No power data in {' and '.join(missing)} window(s).")
        
        # Extract anchor values from both curves
        anchors = {}
        for label, duration_secs in ANCHORS.items():
            cur_secs = current_curve.get("secs", [])
            cur_watts = current_curve.get("watts", [])
            prev_secs = previous_curve.get("secs", [])
            prev_watts = previous_curve.get("watts", [])
            
            # Current window anchor
            cur_w = None
            if duration_secs in cur_secs:
                idx = cur_secs.index(duration_secs)
                val = cur_watts[idx] if idx < len(cur_watts) else None
                if val is not None and val > 0:
                    cur_w = val
            
            # Previous window anchor
            prev_w = None
            if duration_secs in prev_secs:
                idx = prev_secs.index(duration_secs)
                val = prev_watts[idx] if idx < len(prev_watts) else None
                if val is not None and val > 0:
                    prev_w = val
            
            # Compute pct_change (null if either side is null)
            pct_change = None
            if cur_w is not None and prev_w is not None:
                pct_change = round((cur_w - prev_w) / prev_w * 100, 1)
            
            anchors[label] = {
                "current_watts": cur_w,
                "previous_watts": prev_w,
                "pct_change": pct_change
            }
        
        # Block-level guard: need >= 3 non-null anchors in EACH window
        current_valid = sum(1 for a in anchors.values() if a["current_watts"] is not None)
        previous_valid = sum(1 for a in anchors.values() if a["previous_watts"] is not None)
        
        if current_valid < 3 or previous_valid < 3:
            return _null_block(f"Too few valid anchors (current: {current_valid}, previous: {previous_valid}, need 3+).")
        
        # Rotation index: mean(5s, 60s) - mean(1200s, 3600s), 300s excluded
        short_changes = [anchors["5s"]["pct_change"], anchors["60s"]["pct_change"]]
        long_changes = [anchors["1200s"]["pct_change"], anchors["3600s"]["pct_change"]]
        
        rotation_index = None
        if all(v is not None for v in short_changes + long_changes):
            short_mean = sum(short_changes) / len(short_changes)
            long_mean = sum(long_changes) / len(long_changes)
            rotation_index = round(short_mean - long_mean, 1)
        
        if self.debug:
            if rotation_index is not None:
                print(f"  📈 Power curve delta: rotation={rotation_index:+.1f}")
            else:
                print(f"  📈 Power curve delta: rotation unavailable (missing anchor data)")
            for label, vals in anchors.items():
                if vals["pct_change"] is not None:
                    print(f"      {label}: {vals['current_watts']}W vs {vals['previous_watts']}W ({vals['pct_change']:+.1f}%)")
        
        return {
            "window_days": 28,
            "current_window": {"start": pc_start1, "end": pc_end1},
            "previous_window": {"start": pc_start2, "end": pc_end2},
            "anchors": anchors,
            "rotation_index": rotation_index,
            "note": ("Compares MMP at 5 anchor durations (5s neuromuscular, 60s anaerobic, "
                     "300s MAP, 1200s threshold, 3600s endurance) across two 28d windows. "
                     "rotation_index = mean(5s,60s pct_change) - mean(1200s,3600s pct_change). "
                     "Positive = sprint-biased gains, negative = endurance-biased. "
                     "300s excluded from rotation (transitional). "
                     "Null when either window has fewer than 3 valid anchor durations.")
        }

    def _calculate_hr_curve_delta(self, hr_curve_data: Dict = None,
                                   curve_dates: Tuple = None) -> Dict:
        """
        Calculate HR curve delta across two 28-day windows.
        
        Extracts max sustained HR at four anchor durations (60s, 300s, 1200s, 3600s)
        from each window. Computes % change per anchor and rotation_index.
        
        No 5s anchor — peak HR at 5s is just max HR, not an energy system signal.
        
        Rotation index = mean(short-anchor changes) - mean(long-anchor changes)
        where short = 60s, 300s and long = 1200s, 3600s.
        Positive = intensity-biased HR shift, negative = endurance-biased shift.
        
        IMPORTANT: Unlike power where higher is always better, rising max sustained HR
        is ambiguous — could indicate improved cardiac output (fitness gain) or
        accumulated fatigue / dehydration / heat. The AI coach must cross-reference
        with resting HRV, resting HR, RPE trends, and environmental context.
        
        No sport filter on the API call — HR is physiological, not sport-specific.
        Max sustained HR at 300s is max sustained HR at 300s whether from cycling,
        running, or SkiErg. The curve is naturally dominated by the hardest efforts.
        
        Data key is 'values' (not 'watts' as in power curves).
        
        Guards: same as power_curve_delta — per-anchor null, div-by-zero, block-level <3.
        """
        ANCHORS = {"60s": 60, "300s": 300, "1200s": 1200, "3600s": 3600}
        
        def _null_block(note="Insufficient HR data in one or both windows."):
            dates = {}
            if curve_dates:
                dates = {
                    "current_window": {"start": curve_dates[0], "end": curve_dates[1]},
                    "previous_window": {"start": curve_dates[2], "end": curve_dates[3]},
                }
            return {
                "window_days": 28,
                **dates,
                "anchors": None,
                "rotation_index": None,
                "note": note
            }
        
        # Guard: no data or no dates
        if not hr_curve_data or not curve_dates:
            return _null_block()
        
        curves_list = hr_curve_data.get("list", [])
        if not curves_list:
            return _null_block()
        
        # Match curves by ID, not list index
        pc_start1, pc_end1, pc_start2, pc_end2 = curve_dates
        current_id = f"r.{pc_start1}.{pc_end1}"
        previous_id = f"r.{pc_start2}.{pc_end2}"
        
        curves_by_id = {c["id"]: c for c in curves_list if "id" in c}
        current_curve = curves_by_id.get(current_id)
        previous_curve = curves_by_id.get(previous_id)
        
        if not current_curve or not previous_curve:
            missing = []
            if not current_curve:
                missing.append("current")
            if not previous_curve:
                missing.append("previous")
            return _null_block(f"No HR data in {' and '.join(missing)} window(s).")
        
        # Extract anchor values — HR curves use 'values' key, not 'watts'
        anchors = {}
        for label, duration_secs in ANCHORS.items():
            cur_secs = current_curve.get("secs", [])
            cur_values = current_curve.get("values", [])
            prev_secs = previous_curve.get("secs", [])
            prev_values = previous_curve.get("values", [])
            
            # Current window anchor
            cur_v = None
            if duration_secs in cur_secs:
                idx = cur_secs.index(duration_secs)
                val = cur_values[idx] if idx < len(cur_values) else None
                if val is not None and val > 0:
                    cur_v = val
            
            # Previous window anchor
            prev_v = None
            if duration_secs in prev_secs:
                idx = prev_secs.index(duration_secs)
                val = prev_values[idx] if idx < len(prev_values) else None
                if val is not None and val > 0:
                    prev_v = val
            
            # Compute pct_change (null if either side is null)
            pct_change = None
            if cur_v is not None and prev_v is not None:
                pct_change = round((cur_v - prev_v) / prev_v * 100, 1)
            
            anchors[label] = {
                "current_bpm": cur_v,
                "previous_bpm": prev_v,
                "pct_change": pct_change
            }
        
        # Block-level guard: need >= 3 non-null anchors in EACH window
        current_valid = sum(1 for a in anchors.values() if a["current_bpm"] is not None)
        previous_valid = sum(1 for a in anchors.values() if a["previous_bpm"] is not None)
        
        if current_valid < 3 or previous_valid < 3:
            return _null_block(f"Too few valid anchors (current: {current_valid}, previous: {previous_valid}, need 3+).")
        
        # Rotation index: mean(60s, 300s) - mean(1200s, 3600s)
        short_changes = [anchors["60s"]["pct_change"], anchors["300s"]["pct_change"]]
        long_changes = [anchors["1200s"]["pct_change"], anchors["3600s"]["pct_change"]]
        
        rotation_index = None
        if all(v is not None for v in short_changes + long_changes):
            short_mean = sum(short_changes) / len(short_changes)
            long_mean = sum(long_changes) / len(long_changes)
            rotation_index = round(short_mean - long_mean, 1)
        
        if self.debug:
            if rotation_index is not None:
                print(f"  📈 HR curve delta: rotation={rotation_index:+.1f}")
            else:
                print(f"  📈 HR curve delta: rotation unavailable (missing anchor data)")
            for label, vals in anchors.items():
                if vals["pct_change"] is not None:
                    print(f"      {label}: {vals['current_bpm']}bpm vs {vals['previous_bpm']}bpm ({vals['pct_change']:+.1f}%)")
        
        return {
            "window_days": 28,
            "current_window": {"start": pc_start1, "end": pc_end1},
            "previous_window": {"start": pc_start2, "end": pc_end2},
            "anchors": anchors,
            "rotation_index": rotation_index,
            "note": ("Compares max sustained HR at 4 anchor durations (60s anaerobic ceiling, "
                     "300s VO2max HR, 1200s threshold HR, 3600s endurance HR) across two 28d windows. "
                     "rotation_index = mean(60s,300s pct_change) - mean(1200s,3600s pct_change). "
                     "Positive = intensity-biased HR shift, negative = endurance-biased. "
                     "No sport filter — HR is cross-sport physiological (dominated by hardest efforts). "
                     "IMPORTANT: rising max sustained HR is ambiguous — may indicate improved cardiac "
                     "output (good) or accumulated fatigue/dehydration/heat (bad). Cross-reference with "
                     "resting HRV, resting HR, RPE, and environmental context before interpreting. "
                     "Null when either window has fewer than 3 valid anchor durations.")
        }

    def _calculate_dfa_a1_profile(self, intervals_data=None, all_sessions=False) -> Optional[Dict]:
        """
        Build dfa_a1_profile for latest.json capability block.

        Reads from self._intervals_data (must be set first by _generate_intervals).
        Returns:
          - latest_session: most recent activity with a sufficient dfa block (any sport)
          - trailing_by_sport: per sport family, aggregated rollups across the latest
            DFA_TRAILING_WINDOW_N sessions, with confidence + validated flags

        Returns None if no intervals data or no DFA-equipped sessions exist.
        """
        if intervals_data is None:
            intervals_data = getattr(self, "_intervals_data", None)
        if not intervals_data:
            return None
        activities = intervals_data.get("activities", [])
        drift_schema_supported = intervals_data.get("schema_version") == 2
        # Keep only activities with a dfa block (i.e. AlphaHRV recorded), most recent first
        dfa_activities = [a for a in activities if a.get("dfa") is not None]
        if not dfa_activities:
            return None
        # v3.113: sort by full start_datetime (ISO strings sort chronologically) with day-only
        # date as fallback, so two genuine same-day DFA rides (e.g. indoor AM + outdoor PM)
        # resolve by actual time rather than arbitrary cache order for latest_session/window.
        dfa_activities.sort(key=lambda a: (a.get("start_datetime") or a.get("date", "")), reverse=True)

        # --- latest_session: most recent SUFFICIENT session ---
        latest_session = None
        for a in dfa_activities:
            block = a["dfa"]
            quality = block.get("quality") or {}
            if quality.get("sufficient"):
                tiz_split = {}
                for key, label in [
                    ("tiz_easy", "easy"),
                    ("tiz_endurance", "endurance"),
                    ("tiz_tempo", "tempo"),
                    ("tiz_supra", "supra"),
                ]:
                    band = block.get(key)
                    tiz_split[label] = band["pct"] if band else 0.0
                drift = block.get("drift") or {}
                latest_session = {
                    "activity_id": a.get("activity_id"),
                    "date": a.get("date"),
                    "name": a.get("name"),
                    "sport": a.get("type"),
                    "validated": self.SPORT_FAMILIES.get(a.get("type", "")) in self.DFA_VALIDATED_SPORTS,
                    "avg": block.get("avg"),
                    "tiz_split_pct": tiz_split,
                    "drift_delta": drift.get("delta"),
                    "drift_interpretable": (
                        drift_schema_supported and self._dfa_drift_eligible(block)
                    ) if drift else None,
                    "drift_quality": block.get("drift_quality"),
                    "quality": self._dfa_quality_summary(block),
                    "quality_pct": quality.get("valid_pct"),
                    "sufficient": True,
                }
                break

        # If no sufficient session, surface the most recent insufficient one so the AI
        # can see "AlphaHRV ran but unusable" instead of "no data".
        if latest_session is None:
            a = dfa_activities[0]
            latest_session = {
                "activity_id": a.get("activity_id"),
                "date": a.get("date"),
                "name": a.get("name"),
                "sport": a.get("type"),
                "validated": self.SPORT_FAMILIES.get(a.get("type", "")) in self.DFA_VALIDATED_SPORTS,
                "avg": None,
                "tiz_split_pct": None,
                "drift_delta": None,
                "drift_interpretable": None,
                "drift_quality": a["dfa"].get("drift_quality"),
                "quality": self._dfa_quality_summary(a["dfa"]),
                "quality_pct": (a["dfa"].get("quality") or {}).get("valid_pct"),
                "sufficient": False,
            }

        # --- trailing_by_sport: per-sport aggregation across last N sufficient sessions ---
        trailing_by_sport = {}
        # Group dfa activities by sport family
        by_family = {}
        for a in dfa_activities:
            if not (a["dfa"].get("quality") or {}).get("sufficient"):
                continue
            family = self.SPORT_FAMILIES.get(a.get("type", ""), "other")
            by_family.setdefault(family, []).append(a)

        for family, acts in by_family.items():
            window = acts if all_sessions else acts[: self.DFA_TRAILING_WINDOW_N]
            n = len(window)
            if n == 0:
                continue
            avg_dfa_values = [a["dfa"]["avg"] for a in window if a["dfa"].get("avg") is not None]
            avg_dfa = round(sum(avg_dfa_values) / len(avg_dfa_values), 3) if avg_dfa_values else None
            drift_values = [
                a["dfa"]["drift"]["delta"]
                for a in window
                if drift_schema_supported and self._dfa_drift_eligible(a["dfa"])
            ]
            drift_mean = round(sum(drift_values) / len(drift_values), 3) if drift_values else None

            # Threshold estimates from crossing bands — only sessions with a qualifying
            # contiguous crossing (v3.113: reason=="ok"; secs_in_band alone no longer qualifies).
            def _avg_crossing(key, field, subset=None):
                source = subset if subset is not None else window
                vals = []
                for a in source:
                    cb = a["dfa"].get(key)
                    # v3.122: dwell qualification AND estimate eligibility.
                    if cb and cb.get("reason") == "ok" and cb.get("estimate_eligible"):
                        v = cb.get(field)
                        if v is not None:
                            vals.append(v)
                if not vals:
                    return None, 0
                return round(sum(vals) / len(vals)), len(vals)

            # Watts subsets for cycling (environment split); HR is always pooled.
            is_cycling = (family == "cycling")
            if is_cycling:
                indoor = [a for a in window if self._is_indoor_cycling(a.get("type", ""))]
                outdoor = [a for a in window if not self._is_indoor_cycling(a.get("type", ""))]

            def _threshold_reason(key, eligible_n):
                # v3.122 staged. A flat modal count across the whole window lets a majority of
                # no_samples_in_band sessions bury the dwell-qualified crossings that were
                # rejected for stationarity - the blocker the athlete can actually act on.
                if eligible_n >= self.DFA_MIN_CROSSING_SESSIONS_N:
                    return "ok"
                if eligible_n >= 1:
                    return "insufficient_sessions"
                blocks = [(a["dfa"].get(key) or {}) for a in window]
                # Zero eligible, but crossings did sustain dwell: report why THOSE were
                # rejected, modal among them, tiebroken by ESTIMATE_REASON_PRIORITY then name.
                dwell_ok = [b for b in blocks if b.get("reason") == "ok"]
                if dwell_ok:
                    counts = {}
                    for b in dwell_ok:
                        r = b.get("estimate_reason")
                        if r and r != "ok":
                            counts[r] = counts.get(r, 0) + 1
                    if counts:
                        order = {r: i for i, r in enumerate(self.ESTIMATE_REASON_PRIORITY)}
                        return sorted(counts.items(),
                                      key=lambda kv: (-kv[1], order.get(kv[0], len(order)), kv[0]))[0][0]
                # No dwell-qualified crossings at all: modal dwell blocker, tiebreak toward the
                # more-blocking reason (no_samples > insufficient_total > no_contiguous).
                counts = {}
                for b in blocks:
                    r = b.get("reason")
                    if r and r != "ok":
                        counts[r] = counts.get(r, 0) + 1
                if not counts:
                    return "no_samples_in_band"
                severity = {"no_samples_in_band": 0, "insufficient_total_dwell": 1, "no_contiguous_dwell": 2}
                return sorted(counts.items(),
                              key=lambda kv: (-kv[1], severity.get(kv[0], len(severity)), kv[0]))[0][0]

            # Per-marker estimate builder (v3.114): generalizes the v3.113 per-threshold
            # gating/reason logic across all three markers (easy_guard 1.0, lt1 0.75, lt2 0.5).
            # HR pooled; watts split by environment for cycling. Each estimate carries
            # marker_dfa_a1 so the JSON is self-describing. Gated on its own estimate-eligible
            # marker-session count.
            def _build_marker(key, marker_value):
                hr, n_hr = _avg_crossing(key, "avg_hr")
                if is_cycling:
                    w_out, n_w_out = _avg_crossing(key, "avg_watts", outdoor)
                    w_in, n_w_in = _avg_crossing(key, "avg_watts", indoor)
                    n_w = n_w_out + n_w_in
                else:
                    watts, n_w = _avg_crossing(key, "avg_watts")
                # v3.122: two distinct counts, never one field reinterpreted by context.
                # crossing_sessions = marker-sessions that sustained a contiguous dwell.
                # eligible_sessions = those that were ALSO usable as a threshold estimate.
                # Gating, n_sessions and confidence all key on eligible_sessions - max(n_hr,
                # n_w) inferred the count from whichever HR/watts values happened to populate,
                # which is not the same thing. n_hr / n_w survive only for the environment
                # subcounts below.
                crossing_sessions = sum(
                    1 for a in window if (a["dfa"].get(key) or {}).get("reason") == "ok"
                )
                eligible_sessions = sum(
                    1 for a in window
                    if (a["dfa"].get(key) or {}).get("reason") == "ok"
                    and (a["dfa"].get(key) or {}).get("estimate_eligible")
                )
                n_marker = eligible_sessions
                reason = _threshold_reason(key, eligible_sessions)
                if eligible_sessions < self.DFA_MIN_CROSSING_SESSIONS_N:
                    return None, reason, crossing_sessions, eligible_sessions
                if is_cycling:
                    est = {
                        "marker_dfa_a1": marker_value,
                        "hr": hr,
                        "watts_outdoor": w_out,
                        "watts_indoor": w_in,
                        "n_sessions": n_marker,
                        "n_sessions_outdoor": n_w_out,
                        "n_sessions_indoor": n_w_in,
                    }
                else:
                    est = {
                        "marker_dfa_a1": marker_value,
                        "hr": hr,
                        "watts": watts,
                        "n_sessions": n_marker,
                    }
                return est, reason, crossing_sessions, n_marker

            easy_guard_est, easy_guard_reason, easy_guard_crossing_sessions, easy_guard_eligible = \
                _build_marker("easy_guard_crossing", self.DFA_EASY_GUARD)
            lt1_est, lt1_reason, lt1_crossing_sessions, lt1_eligible = \
                _build_marker("lt1_crossing", self.DFA_LT1)
            lt2_est, lt2_reason, lt2_crossing_sessions, lt2_eligible = \
                _build_marker("lt2_crossing", self.DFA_LT2)

            # Sport-level confidence: coarse, max across THRESHOLD markers only (lt1, lt2).
            # easy_guard is a compliance guard, deliberately EXCLUDED — it populates on easy
            # rides and would inflate threshold-calibration confidence (v3.114). Consumed by the
            # agent + 28_DAY_REPORT gate; per-marker estimate presence + reason are authoritative.
            # v3.122: these are ELIGIBLE-session counts, not dwell counts.
            crossing_n = max(lt1_eligible, lt2_eligible)
            if crossing_n >= 6:
                confidence = "high"
            elif crossing_n >= 4:
                confidence = "moderate"
            elif crossing_n >= self.DFA_MIN_CROSSING_SESSIONS_N:
                confidence = "low"
            else:
                confidence = None  # not enough sessions for any threshold estimate

            quality_avg = round(
                sum(a["dfa"]["quality"]["valid_pct"] for a in window) / n, 1
            )
            validated = family in self.DFA_VALIDATED_SPORTS

            sport_block = {
                "n_sessions": n,
                "date_range": [window[-1].get("date"), window[0].get("date")],
                "avg_dfa_a1": avg_dfa,
                "drift_delta_mean": drift_mean,
                "drift_method": self.DFA_DRIFT_METHOD,
                "drift_sessions": len(drift_values),
                "easy_guard_crossing_sessions": easy_guard_crossing_sessions,
                "lt1_crossing_sessions": lt1_crossing_sessions,
                "lt2_crossing_sessions": lt2_crossing_sessions,
                "easy_guard_eligible_sessions": easy_guard_eligible,
                "lt1_eligible_sessions": lt1_eligible,
                "lt2_eligible_sessions": lt2_eligible,
                "easy_guard_estimate": easy_guard_est,
                "easy_guard_reason": easy_guard_reason,
                "lt1_estimate": lt1_est,
                "lt1_reason": lt1_reason,
                "lt2_estimate": lt2_est,
                "lt2_reason": lt2_reason,
                "quality_avg_pct": quality_avg,
                "validated": validated,
                "confidence": confidence,
            }
            if not validated:
                sport_block["note"] = (
                    f"DFA a1 threshold mapping (LT1 0.75 / LT2 0.5) is cycling-validated. "
                    f"{family} thresholds may differ — treat estimates as informational only."
                )
            trailing_by_sport[family] = sport_block

        return {
            "latest_session": latest_session,
            "trailing_by_sport": trailing_by_sport,
        }

    def _dfa_28d_profile(self, activities, start, end):
        rows = []
        for activity in activities:
            retained = activity.get("dfa_rollup") or {}
            if (start <= activity.get("date", "")[:10] <= end
                    and retained.get("schema_version") == 2 and retained.get("dfa")
                    and retained.get("date") == activity.get("date")):
                rows.append({"activity_id": activity.get("id"), "date": activity["date"][:10],
                             "start_datetime": activity["date"],
                             "name": activity.get("name"), "type": activity.get("type"),
                             "dfa": retained["dfa"]})
        profile = self._calculate_dfa_a1_profile(
            {"schema_version": 2, "activities": rows}, all_sessions=True)
        if profile:
            profile["window"] = {"start": start, "end": end, "days": 28}
            profile["recorded_sessions"] = len(rows)
            profile["coverage_note"] = "Available retained DFA summaries only; no historical backfill."
        return profile

    def _calculate_sustainability_profile(self, sustainability_curves: Dict,
                                           sustainability_window: Tuple,
                                           power_model: Dict,
                                           sport_settings: Dict,
                                           wellness_7d: List[Dict],
                                           wellness_extended: List[Dict],
                                           icu_weight: float = None,
                                           activities: List[Dict] = None,
                                           activities_window: Tuple = None) -> Dict:
        """
        Build per-sport sustainability profile for race estimation (v3.91).
        
        For each active sport family, extracts MMP and max sustained HR at
        sport-specific anchor durations from a single wider window (42d default).
        
        Three model layers for cycling:
        1. Actual MMP — observed from training data
        2. Coggan predicted — FTP × duration factor (Allen & Coggan, 3rd ed.)
        3. CP/W' predicted — P = CP + W'/t (Skiba critical power model)
        
        Non-cycling power sports get actual MMP only (no published duration
        factors, no sport-specific CP/W' values).
        
        Indoor/outdoor handling (cycling only): max across fetched curves,
        attributed through activity identity and the shared _fact_indoor classifier,
        never the request type. Without identity, a complete homogeneous cycling
        window can establish environment only; unknown/mixed results withhold FTP models.
        
        Weight fallback chain: today's wellness → most recent in wellness
        history → athlete.icu_weight → null (all W/kg fields null).
        
        References:
        - Allen & Coggan, Training and Racing with a Power Meter (3rd ed.)
        - Skiba et al. (2012): CP/W' model for performance prediction
        - Pinot & Grappe (2011): power-duration profiling
        """
        # Null block for early returns
        def _null_profile(note="No sustainability data available."):
            result = {"note": note}
            if sustainability_window:
                result["window"] = {
                    "days": self.SUSTAINABILITY_WINDOW_DAYS,
                    "start": sustainability_window[0],
                    "end": sustainability_window[1]
                }
            return result
        
        if not sustainability_curves or not sustainability_window:
            return _null_profile()
        
        # --- Weight fallback chain ---
        weight_kg = None
        weight_source = None
        
        # 1. Today's wellness (last entry in 7d)
        if wellness_7d:
            for w in reversed(wellness_7d):
                if w.get("weight"):
                    weight_kg = round(w["weight"], 1)
                    weight_source = "wellness_recent"
                    break
        
        # 2. Extended wellness history
        if weight_kg is None and wellness_extended:
            for w in reversed(wellness_extended):
                if w.get("weight"):
                    weight_kg = round(w["weight"], 1)
                    weight_source = "wellness_extended"
                    break
        
        # 3. Athlete profile weight (icu_weight)
        if weight_kg is None and icu_weight is not None:
            weight_kg = round(icu_weight, 1)
            weight_source = "athlete_profile"
        
        if self.debug:
            if weight_kg:
                print(f"  ⚖️  Sustainability weight: {weight_kg}kg ({weight_source})")
            else:
                print(f"  ⚖️  Sustainability weight: unavailable (W/kg will be null)")
        
        # --- FTP staleness (cycling only) ---
        ftp_staleness_days = None
        try:
            ftp_history = self._load_ftp_history()
            all_dates = []
            for ftp_type in ["indoor", "outdoor"]:
                dates = list(ftp_history.get(ftp_type, {}).keys())
                all_dates.extend(dates)
            if all_dates:
                most_recent = max(all_dates)
                most_recent_date = datetime.strptime(most_recent, "%Y-%m-%d")
                ftp_staleness_days = (datetime.now() - most_recent_date).days
        except Exception:
            pass
        
        # --- Cycling model inputs ---
        cycling_ftp = None
        cycling_w_prime = None
        cycling_settings = sport_settings.get("cycling", {})
        
        # Use athlete-set FTP from sportSettings (not eFTP)
        activity_by_id = {str(a["id"]): a for a in (activities or []) if a.get("id") is not None}
        window_indoor = None
        if (activities_window and activities_window[0] <= sustainability_window[0]
                and activities_window[1] >= sustainability_window[1]):
            cycling_activities = [a for a in (activities or [])
                                  if self.SPORT_FAMILIES.get(a.get("type", "")) == "cycling"
                                  and (not a.get("date") or
                                       sustainability_window[0] <= a["date"][:10] <= sustainability_window[1])]
            if cycling_activities and all(a.get("date") for a in cycling_activities):
                flags = {self._fact_indoor(a) for a in cycling_activities}
                if len(flags) == 1 and None not in flags:
                    window_indoor = next(iter(flags))
        
        cycling_w_prime = power_model.get("w_prime")  # In joules from API
        
        # --- Build per-sport blocks ---
        profile = {
            "window": {
                "days": self.SUSTAINABILITY_WINDOW_DAYS,
                "start": sustainability_window[0],
                "end": sustainability_window[1]
            },
            "weight_kg": weight_kg,
            "weight_source": weight_source,
        }
        
        for sport_family, sport_data in sustainability_curves.items():
            anchors_map = self.SUSTAINABILITY_ANCHORS.get(sport_family)
            if not anchors_map:
                continue
            
            sport_lthr = sport_settings.get(sport_family, {}).get("lthr")
            power_curves_by_type = sport_data.get("power", {})
            hr_curves_by_type = sport_data.get("hr", {})
            
            is_cycling = (sport_family == "cycling")
            
            # --- Extract MMP per anchor (power) ---
            # For cycling: max(Ride, VirtualRide) at each anchor with source tracking
            anchors = {}
            curve_id = f"r.{sustainability_window[0]}.{sustainability_window[1]}"
            
            for label, duration_secs in anchors_map.items():
                best_watts = None
                best_source = None
                best_activity = None
                
                for ptype, pdata in power_curves_by_type.items():
                    curves_list = pdata.get("list", []) if isinstance(pdata, dict) else []
                    curves_by_id = {c["id"]: c for c in curves_list if "id" in c}
                    curve = curves_by_id.get(curve_id)
                    if not curve:
                        continue
                    
                    secs = curve.get("secs", [])
                    watts = curve.get("watts", [])
                    
                    if duration_secs in secs:
                        idx = secs.index(duration_secs)
                        val = watts[idx] if idx < len(watts) else None
                        if val is not None and val > 0:
                            ids = curve.get("activity_ids") or curve.get("activity_id") or []
                            identity = ids[idx] if isinstance(ids, list) and idx < len(ids) else None
                            observed = activity_by_id.get(str(identity)) if identity is not None else None
                            if observed is None:
                                # Exact cached per-activity observations can identify a tied
                                # maximum without trusting the aggregate request's type label.
                                matches = [a for a in (activities or [])
                                           if sustainability_window[0] <= a.get("date", "")[:10] <= sustainability_window[1]
                                           and self.SPORT_FAMILIES.get(a.get("type", "")) == sport_family
                                           and (a.get("power_curve") or {}).get(str(duration_secs)) == val]
                                observed = min(matches, key=lambda a: str(a["id"])) if matches else None
                            if best_watts is None or val > best_watts:
                                best_watts = val
                                best_activity = observed
                            elif val == best_watts and observed is not None:
                                if best_activity is None or str(observed["id"]) < str(best_activity["id"]):
                                    best_activity = observed
                indoor = self._fact_indoor(best_activity or {})
                if is_cycling and best_activity is None and best_watts is not None:
                    indoor = window_indoor
                best_source = ("observed_indoor" if indoor is True else "observed_outdoor"
                               if indoor is False else "observed_unknown") if is_cycling else "observed"
                if best_watts is None:
                    best_source = None
                cycling_ftp = (cycling_settings.get("ftp_indoor") if indoor is True else
                               cycling_settings.get("ftp") if indoor is False else None)
                
                # --- Extract max sustained HR at this anchor ---
                best_hr = None
                
                for htype, hdata in hr_curves_by_type.items():
                    curves_list = hdata.get("list", []) if isinstance(hdata, dict) else []
                    curves_by_id = {c["id"]: c for c in curves_list if "id" in c}
                    curve = curves_by_id.get(curve_id)
                    if not curve:
                        continue
                    
                    secs = curve.get("secs", [])
                    values = curve.get("values", [])
                    
                    if duration_secs in secs:
                        idx = secs.index(duration_secs)
                        val = values[idx] if idx < len(values) else None
                        if val is not None and val > 0:
                            if best_hr is None or val > best_hr:
                                best_hr = round(val)
                
                # --- Compute W/kg ---
                actual_wpkg = None
                if best_watts is not None and weight_kg is not None and weight_kg > 0:
                    actual_wpkg = round(best_watts / weight_kg, 2)
                
                # --- Compute %LTHR ---
                pct_lthr = None
                if best_hr is not None and sport_lthr is not None and sport_lthr > 0:
                    pct_lthr = round(best_hr / sport_lthr * 100, 1)
                
                # --- Coggan model (cycling only) ---
                coggan_watts = None
                coggan_wpkg = None
                if is_cycling and cycling_ftp and duration_secs in self.COGGAN_DURATION_FACTORS:
                    coggan_watts = round(cycling_ftp * self.COGGAN_DURATION_FACTORS[duration_secs])
                    if weight_kg and weight_kg > 0:
                        coggan_wpkg = round(coggan_watts / weight_kg, 2)
                
                # --- CP/W' model (cycling only) ---
                cp_model_watts = None
                cp_model_wpkg = None
                if is_cycling and cycling_ftp and cycling_w_prime and duration_secs > 0:
                    # P = CP + W'/t  (CP approximated by FTP for this model)
                    cp_model_watts = round(cycling_ftp + cycling_w_prime / duration_secs)
                    if weight_kg and weight_kg > 0:
                        cp_model_wpkg = round(cp_model_watts / weight_kg, 2)
                
                # --- Model divergence (actual vs CP model) ---
                model_divergence_pct = None
                if best_watts is not None and cp_model_watts is not None and cp_model_watts > 0:
                    model_divergence_pct = round((best_watts - cp_model_watts) / cp_model_watts * 100, 1)
                
                # A homogeneous window establishes environment, never an anchor's
                # identity/date. Aggregate request types establish neither.
                
                anchor_data = {
                    "actual_watts": best_watts,
                    "actual_wpkg": actual_wpkg,
                    "actual_hr": best_hr,
                    "pct_lthr": pct_lthr,
                    "source": best_source,
                    "activity_id": (best_activity or {}).get("id"),
                    "date": (best_activity or {}).get("date", "")[:10] or None,
                }
                
                # Cycling gets model layers
                if is_cycling:
                    anchor_data["ftp_used"] = cycling_ftp
                    anchor_data["coggan_watts"] = coggan_watts
                    anchor_data["coggan_wpkg"] = coggan_wpkg
                    anchor_data["cp_model_watts"] = cp_model_watts
                    anchor_data["cp_model_wpkg"] = cp_model_wpkg
                    anchor_data["model_divergence_pct"] = model_divergence_pct
                
                anchors[label] = anchor_data
            
            # --- Coverage ratio ---
            total_anchors = len(anchors)
            observed_anchors = sum(1 for a in anchors.values() if a.get("actual_watts") is not None)
            coverage_ratio = round(observed_anchors / total_anchors, 2) if total_anchors > 0 else 0
            
            # Block-level guard: need >= 2 non-null anchors
            if observed_anchors < 2:
                profile[sport_family] = {
                    "anchors": None,
                    "coverage_ratio": coverage_ratio,
                    "note": f"Too few observed anchors ({observed_anchors}, need 2+)."
                }
                continue
            
            sport_block = {
                "anchors": anchors,
                "coverage_ratio": coverage_ratio,
            }
            
            # Cycling-only fields at sport block level
            if is_cycling:
                used = {a["ftp_used"] for a in anchors.values() if a.get("actual_watts") is not None}
                sport_block["ftp_used"] = next(iter(used)) if len(used) == 1 else None
                sport_block["w_prime_used"] = cycling_w_prime
                sport_block["ftp_staleness_days"] = ftp_staleness_days
                sport_block["model_trust_note"] = (
                    "CP/W' model (P=CP+W'/t) is primary for durations ≤20min where W' contribution "
                    "is meaningful. Coggan duration factors (Allen & Coggan, 3rd ed.) are the established "
                    "reference for ≥60min. 30min is the crossover zone where both apply. "
                    "model_divergence_pct = (actual - CP_model) / CP_model × 100. "
                    "Positive divergence at short durations may indicate strong anaerobic capacity "
                    "or stale W' value. Indoor MMP is typically 3-5% lower than outdoor (cooling, "
                    "motivation) — source flag indicates which environment produced each anchor."
                )
            
            profile[sport_family] = sport_block
            
            if self.debug:
                print(f"  📊 Sustainability {sport_family}: {observed_anchors}/{total_anchors} anchors observed")
                for label, vals in anchors.items():
                    w = vals.get("actual_watts")
                    hr = vals.get("actual_hr")
                    src = vals.get("source", "")
                    if w is not None:
                        div = vals.get("model_divergence_pct")
                        div_str = f", div={div:+.1f}%" if div is not None else ""
                        print(f"      {label}: {w}W ({src}), HR={hr}{div_str}")
        
        # If no sport blocks were added beyond the header
        has_sport_data = any(k not in ("window", "weight_kg", "weight_source", "note") for k in profile)
        if not has_sport_data:
            return _null_profile("No sport families produced valid sustainability data.")
        
        return profile

    def _calculate_tid_comparison(self, seiler_tid_7d: Dict,
                                   seiler_tid_28d: Dict) -> Dict:
        """
        Compare 7d vs 28d Seiler TID to detect distribution drift.

        Drift categories:
        - consistent: 7d and 28d classification match
        - shifting: 7d and 28d classification differ
        - acute_depolarization: 7d PI < 2.0 AND 28d PI >= 2.0

        Returns dict with classifications, PI values, delta, and drift.
        """
        cls_7d = seiler_tid_7d.get("classification")
        cls_28d = seiler_tid_28d.get("classification")
        pi_7d = seiler_tid_7d.get("polarization_index")
        pi_28d = seiler_tid_28d.get("polarization_index")

        # Null handling: if either window has no data, no comparison
        if cls_7d is None or cls_28d is None:
            return {
                "classification_7d": cls_7d,
                "classification_28d": cls_28d,
                "pi_7d": pi_7d,
                "pi_28d": pi_28d,
                "pi_delta": None,
                "drift": None,
                "note": ("Compares 7d vs 28d Seiler TID to detect "
                         "distribution shifts. Insufficient data in "
                         "one or both windows.")
            }

        # PI delta (positive = more polarized acutely)
        pi_delta = None
        if pi_7d is not None and pi_28d is not None:
            pi_delta = round(pi_7d - pi_28d, 2)

        # Drift classification
        # Check acute_depolarization first (more specific than shifting)
        if (pi_7d is not None and pi_28d is not None
                and pi_7d < 2.0 and pi_28d >= 2.0):
            drift = "acute_depolarization"
        elif cls_7d != cls_28d:
            drift = "shifting"
        else:
            drift = "consistent"

        if self.debug:
            print(f"  TID comparison: 7d={cls_7d} (PI={pi_7d}), "
                  f"28d={cls_28d} (PI={pi_28d}), drift={drift}")

        return {
            "classification_7d": cls_7d,
            "classification_28d": cls_28d,
            "pi_7d": pi_7d,
            "pi_28d": pi_28d,
            "pi_delta": pi_delta,
            "drift": drift,
            "note": ("Compares 7d vs 28d Seiler TID to detect "
                     "distribution shifts. pi_delta positive = "
                     "more polarized acutely.")
        }

    # === PHASE DETECTION v2 (dual-stream, spec-driven) ===

    # Two inclusive local dates are the earliest useful span in the supplied
    # daily replay. This is an EOD calibration, not an intraday completeness claim.
    PHASE_MIN_ELAPSED_DAYS = 2

    def _phase_current_evidence(self, activities, events, plans, weekly_rows,
                                today, primary_sport, load_sports=None):
        """Matched-sport execution over equal weekday spans; names support only."""
        as_of = datetime.strptime(today, "%Y-%m-%d")
        start = as_of - timedelta(days=(as_of.weekday() - self.week_start_day) % 7)
        span = (as_of - start).days + 1
        start_str = start.strftime("%Y-%m-%d")
        end_str = (start + timedelta(days=6)).strftime("%Y-%m-%d")
        prior_starts = [(start - timedelta(weeks=i)).strftime("%Y-%m-%d") for i in (1, 2, 3)]
        result = {
            "sport_scope": primary_sport if load_sports is None else load_sports,
            "elapsed_days": span,
            "minimum_elapsed_days": self.PHASE_MIN_ELAPSED_DAYS,
            "observation_cutoff": today,
            "reference_weeks": list(reversed(prior_starts)),
            "completed_tss": None,
            "reference_tss_mean": None,
            "tss_delta": None,
            "missing_tss": 0,
            "status": "unavailable",
            "name_support": {"keyword": "deload",
                             "week_phrases": ["recovery week", "rest week", "deload week"],
                             "planned_events": 0, "completed_activities": 0},
        }
        # Generic English whole-word/phrase intent, not an intensity classifier.
        # Deload week is covered by deload; recovery alone names isolated easy rides.
        name_pattern = re.compile(r"\b(?:deload|recovery week|rest week)\b", re.IGNORECASE)
        def matches(sport):
            if load_sports is not None:
                return self._report_sport(sport) in load_sports
            return not primary_sport or self.SPORT_FAMILIES.get(sport) == primary_sport
        named_events = set()
        for index, event in enumerate(list(events or []) + list(plans or [])):
            date = (event.get("date") or event.get("start_date_local") or "")[:10]
            category = event.get("category") or event.get("type")
            sport = event.get("sport_type") if "sport_type" in event else event.get("type")
            if (start_str <= date <= end_str and category in self.TRAINING_EVENT_CATEGORIES
                    and matches(sport)
                    and name_pattern.search(event.get("name") or "")):
                named_events.add(str(event["id"]) if event.get("id") is not None else (date, index))
        result["name_support"]["planned_events"] = len(named_events)
        for act in activities or []:
            date = (act.get("start_date_local") or "")[:10]
            if (start_str <= date <= today
                    and matches(act.get("type"))
                    and name_pattern.search(act.get("name") or "")):
                result["name_support"]["completed_activities"] += 1
        # The normal caller supplies the full fetched activity window. A missing
        # list, unknown sport or missing finalized week cannot establish reduction.
        finalized = {row.get("week_start") for row in (weekly_rows or [])[:-1]}
        if activities is None or not (primary_sport or load_sports) or not set(prior_starts) <= finalized:
            return result
        totals = []
        for offset in (0, 1, 2, 3):
            first = start - timedelta(weeks=offset)
            last = first + timedelta(days=span - 1)
            first_str, last_str = first.strftime("%Y-%m-%d"), last.strftime("%Y-%m-%d")
            subtotal = 0
            for act in activities:
                date = (act.get("start_date_local") or "")[:10]
                if not (first_str <= date <= last_str and date <= today
                        and matches(act.get("type"))):
                    continue
                tss = act.get("icu_training_load")
                if isinstance(tss, (int, float)) and not isinstance(tss, bool) and math.isfinite(tss) and tss >= 0:
                    subtotal += tss
                else:
                    result["missing_tss"] += 1
            totals.append(subtotal)
        result["completed_tss"] = totals[0]
        result["reference_tss_mean"] = statistics.mean(totals[1:])
        if result["missing_tss"] or result["reference_tss_mean"] <= 0:
            return result
        ratio = totals[0] / result["reference_tss_mean"]
        result["tss_delta"] = ratio
        if span < self.PHASE_MIN_ELAPSED_DAYS:
            result["status"] = "insufficient_elapsed"
        else:
            result["status"] = "reduced" if ratio <= 0.80 else "not_reduced"
        return result
    
    def _detect_phase_v2(self, weekly_rows: List[Dict], planned_workouts: List[Dict],
                          race_calendar: Dict, previous_phase: Optional[str] = None,
                          today: str = None, dossier_declared: Optional[str] = None,
                          primary_sport: Optional[str] = None,
                          is_backfill: bool = False,
                          completed_event_ids: Optional[set] = None,
                          completed_activities: Optional[List[Dict]] = None,
                          current_week_events: Optional[List[Dict]] = None,
                          load_activities: Optional[List[Dict]] = None) -> Dict:
        """
        Dual-stream phase detection (v2).
        
        Stream 1: Completed history — rolling 4-week lookback from weekly_180d rows.
        Stream 2: Planned calendar — next 7-14 days of planned workouts + race calendar.
        
        Returns full phase output structure with confidence and reason_codes.
        
        Phase states: Build, Base, Peak, Taper, Deload, Recovery, Overreached, null.

        is_backfill: forwarded to _phase_stream1_features. Set True only when
        called from history regeneration (each historical week's classifier
        needs to see its own row at weekly_rows[-1]).
        """
        if today is None:
            today = datetime.now().strftime("%Y-%m-%d")
        
        reason_codes = []
        
        # Compute features from both streams
        s1 = self._phase_stream1_features(weekly_rows, is_backfill=is_backfill)
        s2 = self._phase_stream2_features(planned_workouts, race_calendar, s1, today, primary_sport,
                                          weekly_rows=weekly_rows,
                                          completed_event_ids=completed_event_ids)

        if not is_backfill:
            current_evidence = self._phase_current_evidence(
                completed_activities, current_week_events, planned_workouts,
                weekly_rows, today, primary_sport)
            s2["load_evidence"]["day_aligned"] = current_evidence
            if current_evidence["status"] == "reduced":
                rebound = s2.get("next_week_tss_delta")
                s2["load_evidence"]["next_week_rebound"] = (
                    "confirmed" if rebound is not None and rebound >= 0.80 else "unverified")
            s2["suggested_phase"] = self._phase_from_stream2(s2)
        
        # Data quality assessment
        data_quality = self._phase_data_quality(weekly_rows, s1, reason_codes)

        # Keep the legacy streams above byte-compatible; only this explicit view
        # supplies load to classification. Missing raw observations never fall back.
        decision_s1, decision_s2, main_load = self._main_phase_features(
            load_activities if load_activities is not None else completed_activities,
            weekly_rows, planned_workouts, current_week_events, completed_event_ids,
            today, is_backfill, s2)
        prior = weekly_rows[-2] if len(weekly_rows) >= 2 else {}
        prior_basis = prior.get("phase_load_basis") or {}
        expected_prior = ((datetime.strptime(weekly_rows[-1]["week_start"], "%Y-%m-%d")
                           - timedelta(weeks=1)).strftime("%Y-%m-%d") if weekly_rows else None)
        compatible_previous = (prior.get("week_start") == expected_prior
                               and (is_backfill or prior.get("_phase_load_compatible"))
                               and prior_basis.get("rule") == self.PHASE_LOAD_RULE
                               and prior_basis.get("status") == "complete"
                               and prior_basis.get("observation_cutoff") == (
                                   datetime.strptime(expected_prior, "%Y-%m-%d") + timedelta(days=6)).strftime("%Y-%m-%d"))
        if not compatible_previous:
            previous_phase = None
        
        # Classification
        phase, confidence, extra_reasons = self._phase_classify(
            decision_s1, decision_s2, previous_phase, data_quality
        )
        reason_codes.extend(extra_reasons)
        if main_load["status"] != "complete":
            reason_codes.append("MAIN_SPORT_LOAD_UNAVAILABLE")
            if phase not in ("Taper", "Peak"):
                confidence = "low"
        
        # Phase duration: count consecutive weeks of same phase from history.
        # Skip weekly_rows[-1] — it's the current week (being classified now,
        # phase_detected is stale or absent). Count from [-2] backward, +1 for current.
        phase_duration = None if not compatible_previous else 0
        if phase and weekly_rows and compatible_previous:
            expected_week = expected_prior
            for row in reversed(weekly_rows[:-1]):
                if (row.get("phase_detected") == phase
                        and row.get("week_start") == expected_week
                        and (is_backfill or row.get("_phase_load_compatible"))
                        and (row.get("phase_load_basis") or {}).get("rule") == self.PHASE_LOAD_RULE
                        and (row.get("phase_load_basis") or {}).get("status") == "complete"
                        and (row.get("phase_load_basis") or {}).get("observation_cutoff") == (
                            datetime.strptime(expected_week, "%Y-%m-%d") + timedelta(days=6)).strftime("%Y-%m-%d")):
                    phase_duration += 1
                    expected_week = (datetime.strptime(expected_week, "%Y-%m-%d") - timedelta(weeks=1)).strftime("%Y-%m-%d")
                else:
                    break
            phase_duration += 1  # current week (just classified)
        
        # Dossier agreement
        dossier_agreement = None
        if dossier_declared:
            dossier_agreement = (dossier_declared == phase) if phase else None
        
        # Stream agreement
        stream_agreement = decision_s1.get("suggested_phase") == decision_s2.get("suggested_phase")
        if decision_s1.get("suggested_phase") is None or decision_s2.get("suggested_phase") is None:
            stream_agreement = None  # can't assess if one stream has no opinion
        
        # Bounded temporal provenance, not a historical knowledge-time record.
        # Backfill's legacy today argument is the target's start, not its cutoff.
        target_start = ((weekly_rows[-1].get("week_start") if weekly_rows else None)
                        if is_backfill else None)
        as_of = datetime.strptime(today, "%Y-%m-%d")
        week_start = (datetime.strptime(target_start, "%Y-%m-%d") if target_start
                      else as_of - timedelta(days=(as_of.weekday() - self.week_start_day) % 7))
        week_end = week_start + timedelta(days=6)
        finalized = weekly_rows if is_backfill else weekly_rows[:-1]
        provenance = {
            "as_of_date": ((week_end + timedelta(days=1)).strftime("%Y-%m-%d")
                           if is_backfill else today),
            "week_start": week_start.strftime("%Y-%m-%d"),
            "week_end": week_end.strftime("%Y-%m-%d"),
            "mode": "retrospective" if is_backfill else "live",
            "completed_weeks_used": [r.get("week_start") for r in finalized[-4:]],
            "observation_cutoff": week_end.strftime("%Y-%m-%d") if is_backfill else today,
            "availability": "current_snapshot_not_historical_knowledge",
        }
        return {
            "phase": phase,
            "confidence": confidence,
            "reason_codes": reason_codes,
            "basis": {
                "decision_load_source": "main_sport_load",
                "main_sport_load": main_load,
                "stream_1": {
                    "ctl_slope": s1.get("ctl_slope"),
                    "acwr_trend": s1.get("acwr_trend"),
                    "hard_day_pattern": s1.get("hard_day_avg"),
                    "weeks_available": s1.get("weeks_available", 0)
                },
                "stream_2": {
                    "planned_tss_delta": s2.get("planned_tss_delta"),
                    "hard_sessions_planned": s2.get("hard_sessions_planned"),
                    "current_week_hard_days_completed": s2.get("current_week_hard_days_completed"),
                    "current_week_hard_days_total": s2.get("current_week_hard_days_total"),
                    "race_proximity": s2.get("race_proximity"),
                    "next_week_load": s2.get("next_week_tss_delta"),
                    "plan_coverage_current_week": s2.get("plan_coverage_current_week"),
                    "plan_coverage_next_week": s2.get("plan_coverage_next_week"),
                    "load_evidence": s2.get("load_evidence")
                },
                "data_quality": data_quality,
                "stream_agreement": stream_agreement
            },
            "provenance": provenance,
            "previous_phase": previous_phase,
            "phase_duration_weeks": phase_duration,
            "dossier_declared": dossier_declared,
            "dossier_agreement": dossier_agreement
        }
    
    def _phase_stream1_features(self, weekly_rows: List[Dict],
                                is_backfill: bool = False) -> Dict:
        """
        Extract Stream 1 (retrospective) features from weekly_180d rows.
        Uses last 4 weeks for trend detection.

        is_backfill: when True, weekly_rows[-1] is the target week being
        classified retroactively (history regen); include it in the lookback so
        its own data is visible to stream1. When False (live mode),
        weekly_rows[-1] is the in-progress current week with partial mid-day
        CTL — exclude it.
        """
        result = {
            "weeks_available": len(weekly_rows),
            "ctl_slope": None,
            "ctl_values": [],
            "acwr_trend": None,
            "hard_day_avg": None,
            "hard_day_values": [],
            "monotony_trend": None,
            "tss_values": [],
            "primary_tss_values": [],
            "suggested_phase": None
        }
        
        if not weekly_rows:
            return result
        
        # Live mode: weekly_rows[-1] is the in-progress current week (partial
        # mid-day CTL); exclude it so the regression sees only finalized weeks.
        # Backfill mode: weekly_rows[-1] IS the target week being classified;
        # include it so its own data drives the classification (otherwise a
        # deload week is invisible to its own classifier).
        if is_backfill:
            finalized = weekly_rows
        else:
            finalized = weekly_rows[:-1] if len(weekly_rows) >= 2 else weekly_rows
        recent = finalized[-4:] if len(finalized) >= 4 else finalized
        
        # CTL slope: linear regression (CTL units per week) over finalized window.
        # Previous impl was a 2-point endpoint chord divided by len(values) instead
        # of (len-1), which both ignored interior points and mis-scaled the
        # denominator — producing spuriously negative slopes when a deload week
        # sat inside the lookback.
        ctl_values = [r.get("ctl_end") for r in recent if r.get("ctl_end") is not None]
        result["ctl_values"] = ctl_values
        if len(ctl_values) >= 2:
            try:
                slope, _ = statistics.linear_regression(
                    range(len(ctl_values)), ctl_values
                )
                result["ctl_slope"] = round(slope, 2)
            except (AttributeError, statistics.StatisticsError):
                # Fallback for Python <3.10: chord over (n-1) intervals
                result["ctl_slope"] = round(
                    (ctl_values[-1] - ctl_values[0]) / (len(ctl_values) - 1), 2
                )
        
        # TSS values for trend
        result["tss_values"] = [r.get("total_tss", 0) or 0 for r in recent]
        result["primary_tss_values"] = [r.get("primary_sport_tss", 0) or 0 for r in recent]
        
        # ACWR trend: direction over the window
        acwr_values = [r.get("acwr") for r in recent if r.get("acwr") is not None]
        if len(acwr_values) >= 2:
            acwr_diff = acwr_values[-1] - acwr_values[0]
            if acwr_diff > 0.1:
                result["acwr_trend"] = "rising"
            elif acwr_diff < -0.1:
                result["acwr_trend"] = "falling"
            else:
                result["acwr_trend"] = "stable"
        
        # Hard-day density
        hard_values = [r.get("hard_days", 0) or 0 for r in recent]
        result["hard_day_values"] = hard_values
        if hard_values:
            result["hard_day_avg"] = round(statistics.mean(hard_values), 1)
        
        # Monotony trend (last week vs average of prior weeks)
        mono_values = [r.get("monotony") for r in recent if r.get("monotony") is not None]
        if len(mono_values) >= 2:
            if mono_values[-1] and mono_values[-1] > 2.5:
                result["monotony_trend"] = "elevated"
            else:
                result["monotony_trend"] = "normal"
        
        # Stream 1 suggested phase (retrospective only)
        result["suggested_phase"] = self._phase_from_stream1(result, recent)
        
        return result
    
    def _phase_from_stream1(self, features: Dict, recent_rows: List[Dict]) -> Optional[str]:
        """Suggest a phase from Stream 1 features alone. Returns phase or None."""
        ctl_slope = features.get("ctl_slope")
        hard_avg = features.get("hard_day_avg")
        acwr_trend = features.get("acwr_trend")
        mono_trend = features.get("monotony_trend")
        
        # Overreached: requires convergence of multiple signals, not a single metric.
        # Both paths are gated on elevated monotony - ACWR alone never triggers this.
        # Path A: elevated monotony + ACWR >= 1.5 (acute spike, Gabbett danger zone)
        # Path B: elevated monotony + ACWR >= 1.3 with a rising ACWR trend
        if mono_trend == "elevated":
            # Most recent row of the caller's window, not the historical max - a spike
            # 3 weeks ago that has since resolved should not keep triggering Overreached.
            # NB the caller's window is finalized weeks in live mode (the in-progress
            # current week is excluded upstream) and the target week in backfill mode,
            # so this is the last completed week's coupled 7:28 ACWR.
            # Live derived_metrics.acwr uses the same definition on rolling days.
            current_acwr = recent_rows[-1].get("acwr") if recent_rows else None
            if current_acwr is not None and current_acwr >= 1.5:
                return "Overreached"
            # Sustained pattern: elevated monotony + ACWR still above normal
            if current_acwr is not None and current_acwr >= 1.3 and acwr_trend == "rising":
                return "Overreached"
        
        if ctl_slope is None:
            return None
        
        # Build: rising CTL + sustained hard days
        if ctl_slope > 1.0 and hard_avg is not None and hard_avg >= 1.5:
            return "Build"
        
        # Base: flat CTL + moderate volume
        if -1.0 <= ctl_slope <= 1.0 and hard_avg is not None and hard_avg <= 1.5:
            return "Base"
        
        # Declining CTL — could be Deload, Taper, or Recovery (need Stream 2)
        if ctl_slope < -1.0:
            return None  # ambiguous without calendar context
        
        return None
    
    def _phase_stream2_features(self, planned_workouts: List[Dict], race_calendar: Dict,
                                 stream1: Dict, today: str,
                                 primary_sport: Optional[str] = None,
                                 weekly_rows: Optional[List[Dict]] = None,
                                 completed_event_ids: Optional[set] = None) -> Dict:
        """
        Extract Stream 2 (prospective) features from planned workouts and race calendar.
        
        Windows are aligned to the training week (configurable via
        .sync_config.json, WEEK_START env var, or --week-start CLI;
        default Monday/ISO). This prevents mid-week contamination where
        a deload week's window leaks into the next build week.
        
        - Current week remainder: today → last day of training week
        - Next week: next full training week (7 days)
        
        When primary_sport is set, planned_tss_delta and next_week_tss_delta
        are filtered to primary sport only (numerator from planned workouts,
        denominator from weekly history). Falls back to all-sport when
        primary sport data is unavailable.

        weekly_rows (optional): live weekly aggregates including the in-progress
        current week at [-1]. Used to (a) compute current_week_hard_days_total
        by merging the in-progress week's completed hard_days with planned
        hard sessions remaining, and (b) derive expected_sessions for plan
        coverage from recent activity_count instead of hard-coding 5.
        """
        result = {
            "planned_tss_delta": None,
            "hard_sessions_planned": 0,
            "current_week_hard_days_completed": 0,
            "current_week_hard_days_total": 0,
            "race_proximity": None,
            "race_category": None,
            "next_week_tss_delta": None,
            "plan_coverage_current_week": 0.0,
            "plan_coverage_next_week": 0.0,
            "suggested_phase": None
        }
        
        today_date = datetime.strptime(today, "%Y-%m-%d")

        # Completed execution is independent of whether the calendar has entries.
        current = weekly_rows[-1] if weekly_rows else {}
        completed_hard_days = current.get("hard_days") or 0
        result["current_week_hard_days_completed"] = completed_hard_days
        result["current_week_hard_days_total"] = completed_hard_days
        result["next_7d_sessions"] = 0
        use_primary = bool(primary_sport and stream1.get("primary_tss_values")
                           and any(v > 0 for v in stream1["primary_tss_values"]))
        denom_values = stream1.get("primary_tss_values" if use_primary else "tss_values", [])
        reference_tss = statistics.mean(denom_values[-3:]) if denom_values else None
        completed_tss = current.get("primary_sport_tss" if use_primary else "total_tss")
        if use_primary and current.get("primary_sport") != primary_sport:
            completed_tss = None
        evidence = {
            "calendar_status": "unavailable" if planned_workouts is None else "available",
            "sport_scope": primary_sport if use_primary else "all",
            "reference_week_tss": reference_tss,
            "completed_tss": completed_tss,
            "completed_tss_delta": (completed_tss / reference_tss
                                    if completed_tss is not None and reference_tss
                                    and reference_tss > 0 else None),
            "remaining": {"sessions": 0, "known_tss": 0, "missing_tss": 0,
                          "unknown_intensity": 0, "same_day_unresolved": 0},
            "next_week": {"sessions": 0, "known_tss": 0, "missing_tss": 0,
                          "unknown_intensity": 0, "same_day_unresolved": 0},
            "completed_events_excluded": 0,
            # Listed entries, even when all numeric, do not prove calendar
            # completeness. Do not invent rest days or a full-week TSS sum.
            "full_week_reduction": "unverified",
            "next_week_rebound": "unverified",
        }
        result["load_evidence"] = evidence
        if evidence["completed_tss_delta"] is not None and evidence["completed_tss_delta"] > 0.80:
            evidence["full_week_reduction"] = "contradicted"
        
        # Race proximity from race_calendar
        next_race = race_calendar.get("next_race")
        if next_race and next_race.get("days_until") is not None:
            result["race_proximity"] = next_race["days_until"]
            result["race_category"] = next_race.get("category")
        
        if not planned_workouts:
            return result
        
        # Week-aligned boundaries (configurable via self.week_start_day)
        # week_start_day: Mon=0..Sun=6 (Python weekday convention)
        # Week end day = day before start (e.g., Sun start → Sat end, Mon start → Sun end)
        week_end_day = (self.week_start_day - 1) % 7
        today_weekday = today_date.weekday()  # Mon=0..Sun=6
        days_to_week_end = (week_end_day - today_weekday) % 7
        current_week_end = today_date + timedelta(days=days_to_week_end)
        # Next training week: day after current_week_end → 6 days later
        next_week_start = current_week_end + timedelta(days=1)
        next_week_end = next_week_start + timedelta(days=6)
        
        # Classify planned workouts into current week remainder and next full week
        current_week_workouts = []
        next_week_workouts = []
        current_week_tss = 0
        current_week_tss_primary = 0
        
        for pw in planned_workouts:
            # v3.128: planned_workouts carries every near-future calendar entry,
            # including SICK / INJURED / NOTE / HOLIDAY markers. Only training entries
            # are sessions; counting the rest inflated plan_coverage_current_week /
            # _next_week and fed a wrong session count into phase detection. Matches
            # the filter _calculate_consistency_index already applies.
            if (pw.get("type") or "") not in self.TRAINING_EVENT_CATEGORIES:
                continue
            if pw.get("id") is not None and str(pw["id"]) in (completed_event_ids or set()):
                evidence["completed_events_excluded"] += 1
                continue
            pw_date_str = (pw.get("date") or "")[:10]
            if not pw_date_str or pw_date_str == "unknown":
                continue
            try:
                pw_date = datetime.strptime(pw_date_str, "%Y-%m-%d")
            except ValueError:
                continue
            
            pw_tss = pw.get("planned_tss") or 0
            pw_sport = self.SPORT_FAMILIES.get(pw.get("sport_type", ""))
            is_primary = (pw_sport == primary_sport) if primary_sport else False
            
            # Current week remainder (today through end of training week)
            if today_date <= pw_date <= current_week_end:
                current_week_workouts.append(pw)
                current_week_tss += pw_tss
                if is_primary:
                    current_week_tss_primary += pw_tss
            # Next full training week
            elif next_week_start <= pw_date <= next_week_end:
                next_week_workouts.append(pw)
        
        # Plan coverage: sessions / expected sessions.
        # Derive expected_sessions from recent weekly history (activity_count
        # average over finalized weeks) instead of the legacy hard-coded 5.
        # Falls back to 5 when no history is available (e.g. first runs).
        tss_values = stream1.get("tss_values", [])
        primary_tss_values = stream1.get("primary_tss_values", [])
        weeks_avail = stream1.get("weeks_available", 0)
        expected_sessions = 5
        if weekly_rows:
            # Use finalized weeks only (exclude in-progress current week at [-1])
            finalized = weekly_rows[:-1] if len(weekly_rows) >= 2 else weekly_rows
            recent = finalized[-4:] if len(finalized) >= 4 else finalized
            counts = [r.get("activity_count") for r in recent
                      if r.get("activity_count") is not None]
            if counts:
                expected_sessions = max(1, round(statistics.mean(counts)))
        
        result["plan_coverage_current_week"] = round(
            len(current_week_workouts) / expected_sessions, 2
        ) if expected_sessions > 0 else 0.0
        result["plan_coverage_next_week"] = round(
            len(next_week_workouts) / expected_sessions, 2
        ) if expected_sessions > 0 else 0.0
        
        # Planned TSS delta: current week remainder planned / avg of prior 3 weeks actual
        # Use primary-sport values when available; fall back to all-sport
        use_primary = primary_sport and primary_tss_values and any(v > 0 for v in primary_tss_values)
        denom_values = primary_tss_values if use_primary else tss_values
        numer_current = current_week_tss_primary if use_primary else current_week_tss
        
        avg_tss_prev = None
        if denom_values and len(denom_values) >= 3:
            avg_tss_prev = statistics.mean(denom_values[-3:])
        elif denom_values:
            avg_tss_prev = statistics.mean(denom_values)
        
        # Scale: project current week remainder to full-week equivalent
        # so it's comparable to the historical weekly average.
        # days_remaining = days_to_week_end + 1 (inclusive of today)
        days_remaining = days_to_week_end + 1
        if avg_tss_prev and avg_tss_prev > 0 and numer_current > 0 and days_remaining > 0:
            projected_week_tss = numer_current * (7 / days_remaining)
            result["planned_tss_delta"] = round(projected_week_tss / avg_tss_prev, 2)
        
        # Next week TSS delta (for Deload confirmation: does load resume?)
        next_week_tss_all = sum(pw.get("planned_tss") or 0 for pw in next_week_workouts)
        if use_primary:
            next_week_tss = sum(
                (pw.get("planned_tss") or 0) for pw in next_week_workouts
                if self.SPORT_FAMILIES.get(pw.get("sport_type", "")) == primary_sport
            )
        else:
            next_week_tss = next_week_tss_all
        if avg_tss_prev and avg_tss_prev > 0 and next_week_tss > 0:
            result["next_week_tss_delta"] = round(next_week_tss / avg_tss_prev, 2)
        
        def heuristic_hard(pw):
            ws = pw.get("workout_summary") or ""
            cat = (pw.get("type") or "").upper()
            name = (pw.get("name") or "").lower()
            return ("×" in ws or "sets" in ws.lower() or
                    cat in ("RACE_A", "RACE_B", "RACE_C") or
                    any(kw in name for kw in ("interval", "vo2", "threshold", "sprint", "tempo",
                                               "race", "hard", "intensity", "sweet spot")))

        # Retain load presence and intensity uncertainty independently of the
        # legacy density/projection aliases. Zero TSS is explicit, null is not.
        for key, workouts in (("remaining", current_week_workouts), ("next_week", next_week_workouts)):
            details = evidence[key]
            details["sessions"] = len(workouts)
            for pw in workouts:
                sport = self.SPORT_FAMILIES.get(pw.get("sport_type", ""))
                tss = pw.get("planned_tss")
                if not use_primary or sport == primary_sport:
                    if isinstance(tss, (int, float)) and not isinstance(tss, bool) and math.isfinite(tss) and tss >= 0:
                        details["known_tss"] += tss
                    else:
                        details["missing_tss"] += 1
                elif sport is None:
                    details["missing_tss"] += 1  # cannot establish matched scope
                # A heuristic non-hard title is not positive evidence of easy intent.
                if not heuristic_hard(pw) and tss != 0:
                    details["unknown_intensity"] += 1
                if key == "remaining" and (pw.get("date") or "")[:10] == today:
                    details["same_day_unresolved"] += 1

        # Hard sessions planned (current week remainder only)
        # A planned workout is "hard" if its name or type suggests intensity
        hard_count = sum(1 for pw in current_week_workouts if heuristic_hard(pw))
        current_week_sessions = len(current_week_workouts)
        result["hard_sessions_planned"] = hard_count
        result["next_7d_sessions"] = current_week_sessions  # renamed semantically but key preserved for compat
        
        # Merge completed (so far) + planned (remaining) hard days for the
        # current week. Without this, on the first day of a new week the
        # scorer sees only N-1 planned hard sessions even though completed
        # ones already happened — biasing Build-shaped weeks toward Base.
        # The in-progress week's hard_days count lives in weekly_rows[-1]
        # (built live from activities_28d in _calculate_derived_metrics).
        result["current_week_hard_days_completed"] = completed_hard_days
        result["current_week_hard_days_total"] = completed_hard_days + hard_count
        
        # Stream 2 suggested phase
        result["suggested_phase"] = self._phase_from_stream2(result)
        
        return result
    
    def _phase_from_stream2(self, features: Dict) -> Optional[str]:
        """Suggest a phase from Stream 2 features alone. Returns phase or None."""
        race_prox = features.get("race_proximity")
        race_cat = features.get("race_category")
        tss_delta = features.get("planned_tss_delta")
        next_week_delta = features.get("next_week_tss_delta")
        
        # Taper: race within 14 days + volume reducing
        if race_prox is not None and race_prox <= 14 and race_cat in ("RACE_A", "RACE_B"):
            if tss_delta is not None and tss_delta <= 0.80:
                return "Taper"
            # Race is close but volume not yet reducing — could be Peak
            return "Taper"  # err toward Taper when race is imminent
        
        # Peak: race within 21 days + no volume reduction yet
        if race_prox is not None and race_prox <= 21 and race_cat in ("RACE_A", "RACE_B"):
            if tss_delta is not None and tss_delta > 0.80:
                return "Peak"
        
        # Live execution establishes reduction; next week only confirms rebound.
        evidence = features.get("load_evidence", {})
        aligned = evidence.get("day_aligned")
        if aligned is not None:
            return "Deload" if aligned.get("status") == "reduced" else None
        if evidence.get("full_week_reduction") in ("unverified", "contradicted"):
            return None
        if tss_delta is not None and tss_delta <= 0.80:
            if next_week_delta is not None and next_week_delta >= 0.85:
                return "Deload"
            # Next week unknown — Deload candidate (can't confirm)
            if features.get("plan_coverage_next_week", 0) < 0.3:
                return None  # ambiguous, can't confirm rebound
            return "Deload"
        
        return None
    
    def _phase_data_quality(self, weekly_rows: List[Dict], stream1: Dict,
                             reason_codes: List[str]) -> str:
        """Assess data quality and append reason codes. Returns 'good', 'mixed', or 'poor'."""
        quality = "good"
        weeks = stream1.get("weeks_available", 0)
        
        if weeks < 3:
            reason_codes.append("INSUFFICIENT_LOOKBACK")
            quality = "poor"
        
        # Check intensity basis breakdown across recent weeks
        if weekly_rows:
            recent = weekly_rows[-4:] if len(weekly_rows) >= 4 else weekly_rows
            hr_only_weeks = 0
            for row in recent:
                ibb = row.get("intensity_basis_breakdown")
                if ibb and ibb.get("hr", 0) > 0 and ibb.get("power", 0) == 0:
                    hr_only_weeks += 1
            if hr_only_weeks > len(recent) / 2:
                has_hr_preference = any(b == "hr" for b in self.zone_preference.values())
                if not has_hr_preference:
                    reason_codes.append("HR_ONLY_MAJORITY")
                    quality = "mixed" if quality == "good" else quality
        
        return quality
    
    def _phase_classify(self, s1: Dict, s2: Dict, previous_phase: Optional[str],
                         data_quality: str) -> Tuple[Optional[str], str, List[str]]:
        """
        Core classification logic. Combines both streams, applies scoring, 
        hysteresis, and confidence.
        
        Returns (phase, confidence, extra_reason_codes).
        """
        reasons = []
        
        s1_phase = s1.get("suggested_phase")
        s2_phase = s2.get("suggested_phase")
        race_prox = s2.get("race_proximity")
        race_cat = s2.get("race_category")
        tss_delta = s2.get("planned_tss_delta")
        next_week_delta = s2.get("next_week_tss_delta")
        ctl_slope = s1.get("ctl_slope")
        hard_avg = s1.get("hard_day_avg")
        plan_cov_curr = s2.get("plan_coverage_current_week", 0)
        plan_cov_next = s2.get("plan_coverage_next_week", 0)
        weeks = s1.get("weeks_available", 0)
        
        # planned_tss_delta is only meaningful if enough sessions are planned in the next 7 days.
        # With few planned sessions, planned TSS is a subset — delta will be misleadingly low.
        next_7d_sessions = s2.get("next_7d_sessions", 0)
        tss_delta_reliable = tss_delta is not None and next_7d_sessions >= 3
        evidence = s2.get("load_evidence") or {}
        aligned = evidence.get("day_aligned") or {}
        aligned_delta = aligned.get("tss_delta")
        completed_delta = evidence.get("completed_tss_delta")
        load_available = s2.get("load_basis_available", True)
        # Live execution can contradict low-load readings even before reduction
        # is established. Backfill has no day_aligned entry and keeps its rules.
        live_load_contradicted = bool(aligned) and (
            aligned.get("status") == "not_reduced"
            or (aligned_delta is not None and aligned_delta > 0.80)
            or (completed_delta is not None and completed_delta > 0.80))
        
        # === Insufficient data guard ===
        if data_quality == "poor" and weeks < 2:
            reasons.append("INSUFFICIENT_DATA")
            return None, "low", reasons
        
        # === Priority 1: Overreached (convergence gate, not a safety stop) ===
        # Reached only via _phase_from_stream1's monotony-gated paths. The
        # SAFETY_ACWR_OR_MONOTONY reason code is legacy naming, consumer-visible,
        # and deliberately unchanged.
        if s1_phase == "Overreached":
            return "Overreached", "high", ["SAFETY_ACWR_OR_MONOTONY"]
        
        # Secondary Overreached check — elevated monotony alone is insufficient.
        # Require actual acute overload evidence (ACWR rising AND hard-day density high).
        # "Rising" ACWR from 0.8→1.0 with 2 hard days is normal Build, not overreaching.
        
        # === Priority 2: Taper (race-anchored) ===
        if race_prox is not None and race_prox <= 14 and race_cat in ("RACE_A", "RACE_B"):
            confidence = "high"
            if tss_delta_reliable and tss_delta <= 0.80:
                reasons.append("RACE_IMMINENT_VOLUME_REDUCING")
            else:
                reasons.append("RACE_IMMINENT")
                confidence = "medium"
            return "Taper", confidence, reasons
        
        # === Priority 3: Peak (race approaching, not yet tapering) ===
        if race_prox is not None and race_prox <= 21 and race_cat in ("RACE_A", "RACE_B"):
            if not tss_delta_reliable or tss_delta > 0.80:
                ctl_values = s1.get("ctl_values", [])
                if ctl_values and len(ctl_values) >= 3:
                    current_ctl = ctl_values[-1]
                    max_ctl = max(ctl_values)
                    if current_ctl >= max_ctl * 0.95:
                        # At actual peak, CTL often flattens (slope ~0) as the athlete
                        # is at cycle high but no longer gaining. Allow marginal decline.
                        if ctl_slope is not None and ctl_slope >= -0.5:
                            return "Peak", "medium", ["RACE_APPROACHING_CTL_HIGH"]
        
        # === Priority 3.5: Recovery (early check for clearly declining/idle athletes) ===
        # Extended low load + 0 hard days + declining CTL → Recovery before Build/Base scoring
        if (not live_load_contradicted and ctl_slope is not None and ctl_slope < -1.0 and
                hard_avg is not None and hard_avg < 0.5 and weeks >= 3):
            confidence = "medium" if data_quality != "poor" else "low"
            reasons.append("DECLINING_LOAD_NO_HARD_DAYS")
            return "Recovery", confidence, reasons
        
        # === Priority 4: Deload→Build transition ===
        # When previous phase was Deload, expected next state is Build.
        # TSS delta is unreliable here (prior 3-week avg includes the deload week).
        # Use completed hard days with nonreduced execution, or planned content.
        if previous_phase == "Deload":
            if live_load_contradicted and s2.get("current_week_hard_days_completed", 0) > 0:
                return "Build", "low", ["BUILD_RESUMING_AFTER_DELOAD_TENTATIVE"]
            hard_planned = s2.get("hard_sessions_planned", 0)
            if hard_planned >= 2:
                # Plan content is prospective intent, not verified complete load.
                return "Build", "low", ["BUILD_RESUMING_AFTER_DELOAD_TENTATIVE"]
            elif hard_planned >= 1 or (plan_cov_curr > 0 and (not tss_delta_reliable or tss_delta > 0.80)):
                return "Build", "low", ["BUILD_RESUMING_AFTER_DELOAD_TENTATIVE"]
        
        # === Priority 5: Deload (calendar-driven or retrospective) ===
        # Deload = Build history + reduced/easy planned load + ≤1 hard session planned.
        # The 3-week Build history gate (weeks >= 3, rising CTL, hard_avg >= 1.5) is
        # intentional: an athlete doing their first-ever deload with <3 weeks of Build
        # data gets Recovery instead. This is the safer classification — without sufficient
        # Build evidence, we can't distinguish "planned deload" from "athlete just isn't
        # training hard". False Recovery is less harmful than false Deload.
        # Three paths:
        #  A) Day-aligned completed TSS ≤ 0.80 + ≤1 remaining hard session
        #  B) Reduced remainder or sparse easy plan + Build history → tentative candidate
        #  C) No plan at all + completed week TSS ≤ 80% of prior 3-week avg → retrospective Deload
        hard_planned = s2.get("hard_sessions_planned", 0)
        build_history = (ctl_slope is not None and ctl_slope > 0 and
                        hard_avg is not None and hard_avg >= 1.5 and
                        weeks >= 3)
        
        deload_signal = False
        deload_path = None
        
        # Allow ≤1 hard session during deload — real deload weeks often keep
        # one short quality session for neuromuscular maintenance (e.g., deload SS).
        # 2+ hard sessions = not structurally a deload.
        # When hard_planned == 1, require ≥3 planned sessions to trust the plan
        # is representative — a 2-session plan with 1 hard is too sparse to judge.
        if load_available and (hard_planned == 0 or (hard_planned == 1 and next_7d_sessions >= 3)):
            # Path A: reduction over the calibrated same-weekday execution span.
            if aligned.get("status") == "reduced" and build_history:
                deload_signal = True
                deload_path = "A"
            elif tss_delta_reliable and tss_delta <= 0.80 and build_history:
                deload_signal = True
                deload_path = "B"
            # Path B: sparse plan, all easy, strong Build history
            elif (next_7d_sessions > 0 and not tss_delta_reliable and build_history
                  and ctl_slope > 1.0 and hard_avg >= 2.0
                  and not evidence.get("remaining", {}).get("missing_tss")):
                deload_signal = True
                deload_path = "B"
        
        # Path C: Retrospective deload — no usable plan, but completed week
        # shows clear TSS reduction vs prior 3 weeks.  Build evidence computed
        # from prior 3 weeks ONLY (excludes the current deload week which
        # would dilute hard_avg / ctl_slope in the 4-week window).
        if load_available and not deload_signal and next_7d_sessions == 0:
            tss_values = s1.get("tss_values", [])
            hard_values = s1.get("hard_day_values", [])
            if len(tss_values) >= 4 and len(hard_values) >= 4:
                current_tss = tss_values[-1]
                prior_3_avg = statistics.mean(tss_values[-4:-1])
                prior_3_hard_avg = statistics.mean(hard_values[-4:-1])
                
                # Build evidence from PRIOR 3 weeks only
                prior_build = (prior_3_hard_avg >= 1.5 and
                               prior_3_avg > 0 and
                               weeks >= 4)
                
                if prior_build:
                    actual_ratio = current_tss / prior_3_avg if prior_3_avg > 0 else 1.0
                    # ≤80% of prior volume — same threshold as Path A (≥20%
                    # reduction).  Validated against 26 weeks of history: catches
                    # confirmed deload weeks with zero false positives.
                    # Hard-day count is NOT gated here: deload weeks often keep
                    # 1-2 reduced-volume quality sessions (e.g., 2x10m SS) that
                    # still trigger the zone ladder as "hard". The TSS reduction
                    # captures the volume difference that matters.
                    if actual_ratio <= 0.80:
                        deload_signal = True
                        deload_path = "C"
        
        if deload_signal:
            if (live_load_contradicted or (deload_path in ("A", "B")
                    and completed_delta is not None and completed_delta > 0.80)):
                return None, "low", ["DELOAD_CONTRADICTED_BY_COMPLETED_LOAD"]
            if deload_path in ("A", "B"):
                support = aligned.get("name_support") or {}
                name_reasons = (["DELOAD_NAME_SUPPORT"] if support.get("planned_events")
                                or support.get("completed_activities") else [])
                if deload_path == "A":
                    if next_week_delta is not None and next_week_delta >= 0.80:
                        return "Deload", "high", ["BUILD_HISTORY_REDUCED_LOAD_REBOUND_CONFIRMED"] + name_reasons
                    return "Deload", "medium", ["BUILD_HISTORY_DAY_ALIGNED_REDUCTION"] + name_reasons
                # Names can support an existing remainder candidate at medium,
                # but cannot establish day-aligned reduction or rebound high.
                confidence = "medium" if name_reasons else "low"
                return "Deload", confidence, ["DELOAD_CURRENT_REDUCTION_UNVERIFIED"] + name_reasons
            if next_week_delta is not None and next_week_delta >= 0.80:
                return "Deload", "high", ["BUILD_HISTORY_REDUCED_LOAD_REBOUND_CONFIRMED"]
            elif plan_cov_next < 0.3:
                reasons.append("PLAN_GAP_NEXT_WEEK")
                conf = "medium" if deload_path == "A" else "medium"
                return "Deload", conf, reasons
            else:
                return "Deload", "medium", ["BUILD_HISTORY_REDUCED_LOAD"]
        
        # Non-Build-history reduction: Recovery (only if CTL is also declining)
        # A Base athlete with stable CTL and low planned TSS isn't recovering — they're maintaining.
        if not live_load_contradicted and tss_delta_reliable and tss_delta <= 0.80 and hard_planned <= 1:
            if not build_history and ctl_slope is not None and ctl_slope < -1.0:
                confidence = "medium" if data_quality != "poor" else "low"
                return "Recovery", confidence, ["NO_BUILD_HISTORY_LOW_LOAD"]
        
        # === Priority 6: Build / Base (scored) ===
        build_score = 0
        base_score = 0
        
        # CTL slope
        if ctl_slope is not None:
            if ctl_slope > 2.0:
                build_score += 3
            elif ctl_slope > 1.0:
                build_score += 2
            elif ctl_slope > 0:
                build_score += 1
            elif -1.0 <= ctl_slope <= 0:
                base_score += 2
            # ctl_slope < -1.0 already handled in Recovery early check
        
        # Hard-day density
        if hard_avg is not None:
            if hard_avg >= 2.5:
                build_score += 2
            elif hard_avg >= 1.5:
                build_score += 1
            elif hard_avg <= 1.0:
                base_score += 2
            else:
                base_score += 1
        
        # ACWR trend
        acwr_trend = s1.get("acwr_trend")
        if acwr_trend == "rising":
            build_score += 1
        elif acwr_trend == "stable":
            base_score += 1
        elif acwr_trend == "falling":
            base_score += 1
        
        # Current-week hard-day intent (Stream 2) — uses completed (so far) +
        # planned (remaining) so the score doesn't drop on Mon/Tue of a new
        # week just because most hard sessions haven't happened yet. Only
        # applied when there are enough planned sessions for the signal to
        # mean anything.
        if next_7d_sessions >= 3:
            cw_hard_total = s2.get("current_week_hard_days_total")
            # Fallback to legacy planned-only field if merged value missing
            if cw_hard_total is None:
                cw_hard_total = s2.get("hard_sessions_planned", 0)
            if cw_hard_total >= 2:
                build_score += 1
            elif cw_hard_total <= 1:
                base_score += 1
        
        # Determine winner
        margin = build_score - base_score
        
        if margin >= 2:
            phase = "Build"
        elif margin <= -2:
            phase = "Base"
        elif margin > 0:
            phase = previous_phase if previous_phase in ("Build", "Base") else "Build"
        elif margin < 0:
            phase = previous_phase if previous_phase in ("Build", "Base") else "Base"
        else:
            if previous_phase in ("Build", "Base"):
                phase = previous_phase
            else:
                phase = None
                reasons.append("BUILD_BASE_AMBIGUOUS")
        
        if phase is None:
            confidence = "low"
        elif abs(margin) >= 3 and data_quality == "good":
            confidence = "high"
        elif abs(margin) >= 2 or data_quality == "good":
            confidence = "medium"
        else:
            confidence = "low"
        
        # === Hysteresis for normal transitions ===
        if phase and previous_phase and phase != previous_phase:
            if previous_phase not in ("Overreached", None):
                reasons.append(f"PHASE_TRANSITION_{previous_phase}_TO_{phase}")
        
        # Adjust confidence for data quality
        if data_quality == "poor" and confidence == "high":
            confidence = "medium"
        elif data_quality == "poor" and confidence == "medium":
            confidence = "low"
        
        # Adjust confidence for plan coverage
        if plan_cov_curr == 0 and plan_cov_next == 0:
            if confidence == "high":
                confidence = "medium"
            reasons.append("NO_PLANNED_WORKOUTS")
        
        return phase, confidence, reasons
    
    def _determine_seasonal_context(self) -> str:
        """
        Determine seasonal context based on current month.
        Assumes Northern Hemisphere cycling calendar.
        """
        month = datetime.now().month
        
        if month in [11, 12]:
            return "Off-season / Transition"
        elif month in [1, 2]:
            return "Early Base"
        elif month in [3, 4]:
            return "Late Base / Build"
        elif month in [5, 6]:
            return "Build / Early Race Season"
        elif month in [7, 8]:
            return "Peak Race Season"
        elif month in [9, 10]:
            return "Late Season / Transition"
        else:
            return "Unknown"
    
    def _load_weekly_rows_for_phase(self) -> List[Dict]:
        """Load recent weekly_180d rows from history.json for phase detection lookback."""
        history_path = self.data_dir / self.HISTORY_FILE
        if not history_path.exists():
            return []
        try:
            with open(history_path, 'r') as f:
                history_data = json.load(f)
            rows = history_data.get("weekly_180d", [])
            compatible = (history_data.get("phase_load_schema") == self._phase_load_schema()
                          and (history_data.get("report_intensity_schema") or {}).get("selection_config")
                          == self._report_intensity_schema()["selection_config"])
            for row in rows:
                row["_phase_load_compatible"] = compatible
            # Retained pre-upgrade history may survive refresh backoff. Recompute
            # before slicing, using the complete supplied week sequence.
            self._couple_weekly_acwr(rows)
            # Return last 4 weeks for lookback
            return rows[-4:] if len(rows) >= 4 else rows
        except Exception:
            return []
    
    # === ALERTS SYSTEM (v3.3.0) ===
    
    def _generate_alerts(self, derived_metrics: Dict, wellness_7d: List[Dict],
                         tss_7d_total: float, tss_28d_total: float) -> List[Dict]:
        """
        Generate graduated alerts array based on Section 11 v11.4 thresholds.
        
        Severity levels: "info" → "warning" → "alarm"
        Empty array = green light.
        
        Monotony alerts use only the additive combined main-sport diagnostic.
        """
        alerts = []
        
        acwr = derived_metrics.get("acwr")
        monotony = derived_metrics.get("monotony")
        effective_monotony = derived_metrics.get("effective_monotony")
        primary_sport = derived_metrics.get("primary_sport")
        primary_sport_monotony = derived_metrics.get("primary_sport_monotony")
        is_multi_sport = derived_metrics.get("multi_sport_detected", False)
        main_strain = derived_metrics.get("strain_main_sports") or {}
        strain = main_strain.get("value") if main_strain.get("status") == "available" else None
        ri = derived_metrics.get("recovery_index")
        ri_yesterday = derived_metrics.get("recovery_index_yesterday")
        latest_hrv = derived_metrics.get("latest_hrv")
        latest_rhr = derived_metrics.get("latest_rhr")
        hrv_baseline_7d = derived_metrics.get("hrv_baseline_7d")
        rhr_baseline_7d = derived_metrics.get("rhr_baseline_7d")
        
        # --- ACWR Alerts ---
        # High-side only. Low ACWR = undertraining / reduced recent load context,
        # not overload risk. Low-side is surfaced via derived_metrics.acwr_interpretation.
        # v3.127: these fire on the LIVE value, which includes today's completed load.
        # severity is unchanged for consumer compatibility, but the risk claim is gone:
        # ACWR is not a standalone injury-risk conclusion (Impellizzeri et al. 2020).
        # scope and readiness_eligible say explicitly that this is reporting, not a
        # decision input — an AI acting on an "alarm" between sessions would recreate
        # the same-day veto the start-of-day basis removes.
        if acwr is not None:
            if acwr >= 1.35:
                alerts.append({
                    "metric": "acwr",
                    "value": acwr,
                    "severity": "alarm",
                    "threshold": "1.35",
                    "context": f"Live ACWR {acwr} crossed the 1.35 reporting threshold. Retrospective load context only — not a standalone injury-risk conclusion and not a readiness decision. It includes today's completed load, so it must not decide a later same-day session, and must not decide tomorrow before tomorrow morning's new start-of-day calculation. Today's readiness used readiness_decision.signals.acwr (start-of-day).",
                    "persistence_days": None,
                    "tier": 2,
                    "scope": "live_retrospective",
                    "readiness_eligible": False
                })
            elif acwr >= 1.3:
                alerts.append({
                    "metric": "acwr",
                    "value": acwr,
                    "severity": "warning",
                    "threshold": "1.3",
                    "context": f"Live ACWR {acwr} crossed the 1.3 reporting threshold; 1.35 is the next band. Retrospective load context only — not a standalone injury-risk conclusion and not a readiness decision. It includes today's completed load, so it must not decide a later same-day session, and must not decide tomorrow before tomorrow morning's new start-of-day calculation.",
                    "persistence_days": None,
                    "tier": 2,
                    "scope": "live_retrospective",
                    "readiness_eligible": False
                })
        
        # --- Monotony Alerts (same selected set for acute/chronic context) ---
        main_monotony = derived_metrics.get("monotony_main_sports") or {}
        effective_monotony = (main_monotony.get("value")
                             if main_monotony.get("status") == "available" else None)
        if effective_monotony is not None:
            deload_context = main_monotony.get("deload_context")

            multi_sport_note = " (combined main sports: " + ", ".join(main_monotony["sports"]) + ")"

            if effective_monotony >= 2.5:
                if deload_context:
                    alerts.append({
                        "metric": "monotony",
                        "value": effective_monotony,
                        "severity": "info",
                        "threshold": 2.5,
                        "context": f"Monotony {effective_monotony} ≥ 2.5 but {deload_context}. Structural artifact, not overuse risk. Will normalize as 7-day window rolls forward.{multi_sport_note}",
                        "persistence_days": None,
                        "tier": 2
                    })
                else:
                    alerts.append({
                        "metric": "monotony",
                        "value": effective_monotony,
                        "severity": "alarm",
                        "threshold": 2.5,
                        "context": f"Monotony {effective_monotony} ≥ 2.5. Overuse risk elevated. Vary training load.{multi_sport_note}",
                        "persistence_days": None,
                        "tier": 2
                    })
            elif effective_monotony >= 2.3:
                if deload_context:
                    alerts.append({
                        "metric": "monotony",
                        "value": effective_monotony,
                        "severity": "info",
                        "threshold": 2.3,
                        "context": f"Monotony {effective_monotony} approaching threshold but {deload_context}. Expected, not actionable.{multi_sport_note}",
                        "persistence_days": None,
                        "tier": 2
                    })
                else:
                    alerts.append({
                        "metric": "monotony",
                        "value": effective_monotony,
                        "severity": "warning",
                        "threshold": 2.3,
                        "context": f"Monotony {effective_monotony} approaching overuse threshold. Alarm at 2.5.{multi_sport_note}",
                        "persistence_days": None,
                        "tier": 2
                    })
        
        for alert in alerts:
            if alert["metric"] == "monotony":
                alert.update(basis="main_sports", sports=list(main_monotony["sports"]))

        # --- Strain Alerts ---
        if strain is not None and strain > 3500:
            alerts.append({
                "metric": "strain",
                "value": strain,
                "severity": "alarm",
                "threshold": 3500,
                "context": f"Main-sport strain {strain} > 3500 ({', '.join(main_strain.get('sports', []))}). High cumulative stress. Consider load reduction.",
                "basis": "main_sports", "sports": list(main_strain.get("sports", [])),
                "scope": "reporting", "readiness_eligible": False,
                "persistence_days": None,
                "tier": 2
            })
        
        # --- Recovery Index Alerts ---
        # Aligned with readiness_decision RI rule:
        #   alarm: ri < 0.6 (single day, immediate)
        #   warning: ri < 0.7 AND ri_yesterday < 0.7 (persistent, 2+ days)
        # Single-day dips 0.6–0.7 are context only, not warning-grade.
        if ri is not None:
            if ri < 0.6:
                alerts.append({
                    "metric": "recovery_index",
                    "value": ri,
                    "severity": "alarm",
                    "threshold": 0.6,
                    "context": f"RI {ri} < 0.6. Immediate deload required.",
                    "persistence_days": None,
                    "tier": 1
                })
            elif ri < 0.7 and ri_yesterday is not None and ri_yesterday < 0.7:
                alerts.append({
                    "metric": "recovery_index",
                    "value": ri,
                    "severity": "warning",
                    "threshold": 0.7,
                    "context": f"RI {ri} < 0.7 for 2+ consecutive days (yesterday {ri_yesterday}). Monitor — if persists 3+ days, deload review required.",
                    "persistence_days": 2,
                    "tier": 1
                })
        
        # --- HRV Alerts ---
        if latest_hrv and hrv_baseline_7d and hrv_baseline_7d > 0:
            hrv_change_pct = ((latest_hrv - hrv_baseline_7d) / hrv_baseline_7d) * 100
            if hrv_change_pct <= -20:
                # Check persistence: count consecutive days with HRV ↓>20%
                hrv_low_days = self._count_hrv_low_days(wellness_7d, hrv_baseline_7d)
                
                if hrv_low_days > 2:
                    alerts.append({
                        "metric": "hrv",
                        "value": round(latest_hrv, 1),
                        "severity": "alarm",
                        "threshold": f"↓>20% vs baseline ({round(hrv_baseline_7d, 1)})",
                        "context": f"HRV {round(latest_hrv, 1)} is {round(abs(hrv_change_pct), 1)}% below baseline, persisting {hrv_low_days} days.",
                        "persistence_days": hrv_low_days,
                        "tier": 1
                    })
                else:
                    alerts.append({
                        "metric": "hrv",
                        "value": round(latest_hrv, 1),
                        "severity": "warning",
                        "threshold": f"↓>20% vs baseline ({round(hrv_baseline_7d, 1)})",
                        "context": f"HRV {round(latest_hrv, 1)} is {round(abs(hrv_change_pct), 1)}% below baseline. Monitor — alarm if persists >2 days.",
                        "persistence_days": hrv_low_days,
                        "tier": 1
                    })
        
        # --- RHR Alerts ---
        if latest_rhr and rhr_baseline_7d and rhr_baseline_7d > 0:
            rhr_change = latest_rhr - rhr_baseline_7d
            if rhr_change >= 5:
                # Check persistence
                rhr_high_days = self._count_rhr_high_days(wellness_7d, rhr_baseline_7d)
                
                if rhr_high_days > 2:
                    alerts.append({
                        "metric": "rhr",
                        "value": round(latest_rhr, 1),
                        "severity": "alarm",
                        "threshold": f"↑≥5bpm vs baseline ({round(rhr_baseline_7d, 1)})",
                        "context": f"RHR {round(latest_rhr, 1)} is {round(rhr_change, 1)}bpm above baseline, persisting {rhr_high_days} days.",
                        "persistence_days": rhr_high_days,
                        "tier": 1
                    })
                else:
                    alerts.append({
                        "metric": "rhr",
                        "value": round(latest_rhr, 1),
                        "severity": "warning",
                        "threshold": f"↑≥5bpm vs baseline ({round(rhr_baseline_7d, 1)})",
                        "context": f"RHR {round(latest_rhr, 1)} is {round(rhr_change, 1)}bpm above baseline. Monitor — alarm if persists >2 days.",
                        "persistence_days": rhr_high_days,
                        "tier": 1
                    })
        
        # --- Durability Alerts (v3.4.0; N-gate added v3.104) ---
        # Aggregate decoupling trend from capability metrics.
        # Reliability gate: alarm requires N28>=5; declining warning requires N7>=3 AND N28>=5.
        # Below the gate, metrics are still surfaced in capability.durability but no alert fires.
        # The high_drift_count warning (>=3 sessions in 7d) is count-based and naturally
        # self-guarding — not subject to the reliability gate.
        capability = derived_metrics.get("capability", {})
        durability = capability.get("durability", {})
        dur_mean_7d = durability.get("mean_decoupling_7d")
        dur_mean_28d = durability.get("mean_decoupling_28d")
        dur_trend = durability.get("trend")
        dur_high_drift_7d = durability.get("high_drift_count_7d", 0)
        dur_n_7d = durability.get("qualifying_sessions_7d", 0)
        dur_n_28d = durability.get("qualifying_sessions_28d", 0)

        # Alarm: sustained high decoupling (28d mean > 5%, requires N28>=5)
        if (dur_mean_28d is not None and dur_mean_28d > 5.0
                and dur_n_28d >= 5):
            alerts.append({
                "metric": "durability",
                "value": dur_mean_28d,
                "severity": "alarm",
                "threshold": "28d mean > 5% (N28>=5)",
                "context": f"Sustained high decoupling ({dur_mean_28d}% 28d mean). Aerobic efficiency concern — review volume and recovery.",
                "persistence_days": None,
                "tier": 3
            })
        # Warning: declining trend with >2% delta (requires N7>=3 AND N28>=5)
        elif (dur_trend == "declining" and dur_mean_7d is not None
              and dur_mean_28d is not None
              and (dur_mean_7d - dur_mean_28d) > 2.0
              and dur_n_7d >= 3 and dur_n_28d >= 5):
            alerts.append({
                "metric": "durability",
                "value": dur_mean_7d,
                "severity": "warning",
                "threshold": "7d > 28d by > 2% (N7>=3, N28>=5)",
                "context": f"Durability declining: 7d mean decoupling {dur_mean_7d}% vs 28d {dur_mean_28d}%. Check fatigue and recovery.",
                "persistence_days": None,
                "tier": 3
            })

        # Warning: repeated poor durability (>= 3 high-drift sessions in 7d)
        # Count-based; not subject to the reliability gate.
        if dur_high_drift_7d >= 3:
            alerts.append({
                "metric": "durability",
                "value": dur_high_drift_7d,
                "severity": "warning",
                "threshold": ">= 3 sessions with >5% decoupling in 7d",
                "context": f"Repeated poor durability: {dur_high_drift_7d} sessions with >5% decoupling in last 7 days.",
                "persistence_days": None,
                "tier": 3
            })

        for alert in alerts:
            if alert["metric"] == "durability":
                alert.update(sport="cycling", scope="reporting", readiness_eligible=False)
                alert["context"] = "Cycling: " + alert["context"]

        alerts.extend(self._report_tid_alerts(derived_metrics))
        
        # Sort by tier (lower = more important), then severity
        severity_order = {"alarm": 0, "warning": 1, "info": 2}
        alerts.sort(key=lambda a: (a["tier"], severity_order.get(a["severity"], 3)))
        
        return alerts
    
    def _detect_deload_context(self, tss_7d_total: float, tss_28d_total: float) -> Optional[str]:
        """
        Detect if current period is a deload or post-deload transition.
        
        A deload is detected when trailing 7-day TSS is ≥20% below the 28-day weekly average.
        Returns context string if deload detected, None otherwise.
        """
        if not tss_28d_total or tss_28d_total == 0:
            return None
        
        weekly_avg_28d = tss_28d_total / 4  # 4 weeks
        
        if weekly_avg_28d == 0:
            return None
        
        deficit_pct = ((weekly_avg_28d - tss_7d_total) / weekly_avg_28d) * 100
        
        if deficit_pct >= 20:
            return f"deload pattern detected (7-day TSS {round(tss_7d_total)} is {round(deficit_pct)}% below 28-day weekly avg {round(weekly_avg_28d)})"
        
        return None

    @staticmethod
    def _is_valid_hrv(value: float) -> bool:
        """
        Check if HRV value is within valid physiological range (10-250ms RMSSD).
        Filters sensor errors while preserving legitimate high values in elite athletes.

        rMSSD only. Apple Watch SDNN (wellness hrvSDNN) falls in the same numeric
        range and would pass this check if routed through it, so passing is not
        evidence a value is rMSSD. Nothing routes hrvSDNN here today; never add a
        path that does in order to substitute it for hrv (issue #25).
        """
        return value is not None and 10 <= value <= 250

    def _count_hrv_low_days(self, wellness_7d: List[Dict], baseline: float) -> int:
        """Count consecutive days (from most recent) where HRV is ↓>20% below baseline"""
        threshold = baseline * 0.8
        count = 0
        for w in reversed(wellness_7d):
            hrv = w.get("hrv")
            if self._is_valid_hrv(hrv) and hrv < threshold:
                count += 1
            else:
                break
        return count
    
    def _count_rhr_high_days(self, wellness_7d: List[Dict], baseline: float) -> int:
        """Count consecutive days (from most recent) where RHR is ↑≥5bpm above baseline"""
        threshold = baseline + 5
        count = 0
        for w in reversed(wellness_7d):
            rhr = w.get("restingHR")
            if rhr is not None and rhr >= threshold:
                count += 1
            else:
                break
        return count
    
    # === READINESS DECISION (v3.72) ===
    
    def _get_phase_modifiers(self, phase: Optional[str], race_week_active: bool) -> Dict:
        """Return threshold modifiers based on current phase and race proximity.
        
        Returns:
            amber_threshold: int — number of amber signals before Modify triggers
            tsb_amber: float — TSB threshold for amber classification
            tighten_red: bool — whether single red = Skip (not just Modify)
            modifier_applied: str — audit label for which rule was applied
        """
        if race_week_active:
            return {"amber_threshold": 1, "tsb_amber": -15, "tighten_red": True, "modifier_applied": "race_week_tightened"}
        
        modifiers = {
            "Build":       {"amber_threshold": 3, "tsb_amber": -20, "tighten_red": False, "modifier_applied": "build_loosened"},
            "Taper":       {"amber_threshold": 1, "tsb_amber": -15, "tighten_red": True,  "modifier_applied": "taper_tightened"},
        }
        
        default = {"amber_threshold": 2, "tsb_amber": -15, "tighten_red": False, "modifier_applied": "default"}
        return modifiers.get(phase, default)
    
    def _compute_readiness_decision(self, derived_metrics: Dict, alerts: List[Dict],
                                     latest_wellness: Dict, activities: List[Dict],
                                     race_calendar: Dict, current_tsb: float = None) -> Dict:
        """
        Pre-compute deterministic readiness decision (go/modify/skip).
        
        Priority ladder (first match wins):
          P0 — Safety stop: RI < 0.6 or any tier-1 alarm → Skip
          P1 — Acute overload: start-of-day ACWR >= 1.5 WITH a Tier-1 signal amber/red, compound TSB+HRV, RI < 0.7 + persistent alerts → Skip/Modify
          P2 — Accumulated fatigue: signal counting with phase-adjusted thresholds → Modify
          P3 — Green light → Go
        
        Phase modifiers shift amber thresholds (Build loosens, Taper/Race week tightens).
        AI reads the decision and writes the coaching note. Can override with explanation.
        """
        # --- Gather inputs ---
        ri = derived_metrics.get("recovery_index")
        # v3.127: readiness reads the start-of-day basis, never the live value. A
        # workout completed today must not change today's readiness result.
        acwr_sod = derived_metrics.get("acwr_start_of_day") or {}
        acwr = acwr_sod.get("value")
        acwr_as_of = acwr_sod.get("as_of_date")
        tsb = current_tsb
        
        latest_hrv = derived_metrics.get("latest_hrv")
        latest_rhr = derived_metrics.get("latest_rhr")
        hrv_baseline_7d = derived_metrics.get("hrv_baseline_7d")
        rhr_baseline_7d = derived_metrics.get("rhr_baseline_7d")
        
        phase_detection = derived_metrics.get("phase_detection", {})
        current_phase = phase_detection.get("phase")
        phase_duration = phase_detection.get("phase_duration_weeks")
        
        race_week_active = race_calendar.get("race_week", {}).get("active", False)
        
        # Sleep from latest wellness
        sleep_secs = latest_wellness.get("sleepSecs")
        sleep_hours = round(sleep_secs / 3600, 2) if sleep_secs else None
        sleep_quality = latest_wellness.get("sleepQuality")
        
        # Phase modifiers
        modifiers = self._get_phase_modifiers(current_phase, race_week_active)
        
        # --- Compute signal statuses ---
        signals = {}
        
        # HRV signal
        if latest_hrv and hrv_baseline_7d and hrv_baseline_7d > 0:
            hrv_delta_pct = round(((latest_hrv - hrv_baseline_7d) / hrv_baseline_7d) * 100, 1)
            if hrv_delta_pct <= -20:
                hrv_status = "red"
            elif hrv_delta_pct <= -10:
                hrv_status = "amber"
            else:
                hrv_status = "green"
            signals["hrv"] = {"status": hrv_status, "value": round(latest_hrv, 1), "baseline_7d": round(hrv_baseline_7d, 1), "delta_pct": hrv_delta_pct}
        else:
            hrv_delta_pct = None
            signals["hrv"] = {"status": "unavailable", "value": latest_hrv, "baseline_7d": hrv_baseline_7d, "delta_pct": None}
            # v3.126: readiness reads rMSSD only. A wellness record carrying SDNN but
            # no usable rMSSD reads "unavailable" with no stated cause; state the
            # cause, never substitute (issue #25). SDNN is the native Apple Watch
            # export, but the check is on the data, not the device. The latest_hrv
            # guard is defensive: a valid rMSSD always contributes to hrv_baseline_7d,
            # so this branch is currently unreachable with latest_hrv set - the guard
            # holds if baseline depth ever gains a minimum. Omitted when it does not
            # apply: consumers must treat the key as optional.
            if latest_hrv is None and latest_wellness.get("hrvSDNN") is not None:
                signals["hrv"]["reason"] = "rmssd_missing_sdnn_available"
        
        # RHR signal
        if latest_rhr and rhr_baseline_7d and rhr_baseline_7d > 0:
            rhr_delta = round(latest_rhr - rhr_baseline_7d, 1)
            if rhr_delta >= 5:
                rhr_status = "red"
            elif rhr_delta >= 3:
                rhr_status = "amber"
            else:
                rhr_status = "green"
            signals["rhr"] = {"status": rhr_status, "value": round(latest_rhr, 1), "baseline_7d": round(rhr_baseline_7d, 1), "delta_bpm": rhr_delta}
        else:
            rhr_delta = None
            signals["rhr"] = {"status": "unavailable", "value": latest_rhr, "baseline_7d": rhr_baseline_7d, "delta_bpm": None}
        
        # Sleep signal (hours only — sleep quality/score excluded from readiness; v3.90)
        if sleep_hours is not None:
            sleep_red = sleep_hours < 5
            sleep_amber = (not sleep_red) and sleep_hours < 7
            if sleep_red:
                sleep_status = "red"
            elif sleep_amber:
                sleep_status = "amber"
            else:
                sleep_status = "green"
            signals["sleep"] = {"status": sleep_status, "hours": sleep_hours, "quality": sleep_quality}
        else:
            signals["sleep"] = {"status": "unavailable", "hours": None, "quality": sleep_quality}
        
        # ACWR signal — START-OF-DAY basis (v3.127), not the live value.
        # Readiness: high-side only. Low ACWR = reduced recent load (taper/undertraining),
        # not a fatigue/overload signal — context surfaces via acwr_interpretation.
        if acwr is not None:
            if acwr >= 1.5:
                acwr_status = "red"
            elif acwr >= 1.3:
                acwr_status = "amber"
            else:
                acwr_status = "green"
            signals["acwr"] = {"status": acwr_status, "value": acwr,
                               "scope": "start_of_day", "as_of_date": acwr_as_of,
                               "current_day_load_included": False}
        else:
            signals["acwr"] = {"status": "unavailable", "value": None,
                               "scope": "start_of_day", "as_of_date": acwr_as_of,
                               "current_day_load_included": False}
        
        # RI signal — amber requires 2-day persistence to filter single-night noise.
        #   red: ri < 0.6 (single day, immediate)
        #   amber: ri < 0.7 AND ri_yesterday < 0.7 (persistent)
        #   green: otherwise (single-day dips 0.6–0.7 remain visible via value, not counted)
        ri_yesterday = derived_metrics.get("recovery_index_yesterday")
        if ri is not None:
            if ri < 0.6:
                ri_status = "red"
            elif ri < 0.7 and ri_yesterday is not None and ri_yesterday < 0.7:
                ri_status = "amber"
            else:
                ri_status = "green"
            signals["ri"] = {"status": ri_status, "value": ri, "value_yesterday": ri_yesterday}
        else:
            signals["ri"] = {"status": "unavailable", "value": None, "value_yesterday": ri_yesterday}
        
        # --- Count signals ---
        green_count = sum(1 for s in signals.values() if s["status"] == "green")
        amber_count = sum(1 for s in signals.values() if s["status"] == "amber")
        red_count = sum(1 for s in signals.values() if s["status"] == "red")
        unavailable_count = sum(1 for s in signals.values() if s["status"] == "unavailable")
        
        signal_summary = {"green": green_count, "amber": amber_count, "red": red_count, "unavailable": unavailable_count}
        
        # Collect amber/red signal names for reason strings
        amber_signals = [k for k, v in signals.items() if v["status"] == "amber"]
        red_signals = [k for k, v in signals.items() if v["status"] == "red"]
        
        # --- P0: Safety stop ---
        tier1_alarms = [a for a in alerts if a.get("severity") == "alarm" and a.get("tier") == 1]
        
        if (ri is not None and ri < 0.6) or tier1_alarms:
            alarm_refs = [a["metric"] for a in tier1_alarms]
            reasons = []
            if ri is not None and ri < 0.6:
                reasons.append(f"RI {ri} < 0.6")
            if tier1_alarms:
                reasons.append(f"tier-1 alarms: {', '.join(alarm_refs)}")
            
            return {
                "recommendation": "skip",
                "priority": 0,
                "signals": signals,
                "signal_summary": signal_summary,
                "phase_context": {
                    "phase": current_phase,
                    "phase_week": phase_duration,
                    "amber_threshold": modifiers["amber_threshold"],
                    "modifier_applied": modifiers["modifier_applied"]
                },
                "race_week_defers": False,
                "modification": None,
                "reason": f"P0 safety stop. {'; '.join(reasons)}.",
                "alarm_refs": alarm_refs
            }
        
        # --- P1: Acute overload ---
        p1_skip_reasons = []
        p1_modify_reasons = []
        p1_alarm_refs = []
        
        # v3.127: ACWR is Tier-2 load. Tier 2 must not override Tier-1 primary readiness
        # (Metric Evaluation Hierarchy), and ACWR is not validated as a standalone
        # clearance metric (Impellizzeri et al. 2020), so a spike alone no longer forces
        # a non-overridable Skip. It stops the session only when a Tier-1 primary signal
        # corroborates it; uncorroborated it counts as an ordinary P2 red.
        acwr_corroborating = [k for k in ("hrv", "rhr", "sleep", "ri")
                              if signals.get(k, {}).get("status") in ("amber", "red")]
        if acwr is not None and acwr >= 1.5 and acwr_corroborating:
            p1_skip_reasons.append(
                f"start-of-day ACWR {acwr} (as of {acwr_as_of}, today's load excluded) "
                f">= 1.5, corroborated by {', '.join(acwr_corroborating)}"
            )
            # No alarm_ref. The acwr alert object carries the LIVE value and
            # readiness_eligible False, so it is not the alert that triggered this branch
            # and cannot truthfully be cited as one. The reason string above and
            # signals["acwr"] are the start-of-day audit trail. alarm_refs may therefore
            # be empty on a P1 skip — already the case for the TSB+HRV composite branch.
        
        # Compound: deep TSB + HRV confirming
        if tsb is not None and tsb < -30 and hrv_delta_pct is not None and hrv_delta_pct < -10:
            p1_skip_reasons.append(f"TSB {tsb} < -30 with HRV {hrv_delta_pct}% below baseline")
            # no discrete alert object for the TSB+HRV composite -> no alarm_ref (schema requires refs resolve to alerts[])
        
        # RI < 0.7 + persistent tier-1 alerts
        tier1_persistent = [a for a in alerts if a.get("tier") == 1 and a.get("severity") in ("warning", "alarm") and a.get("persistence_days") is not None and a.get("persistence_days") >= 2]
        if ri is not None and ri < 0.7 and tier1_persistent:
            persistent_metrics = [a["metric"] for a in tier1_persistent]
            p1_skip_reasons.append(f"RI {ri} < 0.7 with persistent alerts: {', '.join(persistent_metrics)}")
            p1_alarm_refs.extend(persistent_metrics)
        
        if p1_skip_reasons:
            return {
                "recommendation": "skip",
                "priority": 1,
                "signals": signals,
                "signal_summary": signal_summary,
                "phase_context": {
                    "phase": current_phase,
                    "phase_week": phase_duration,
                    "amber_threshold": modifiers["amber_threshold"],
                    "modifier_applied": modifiers["modifier_applied"]
                },
                "race_week_defers": False,
                "modification": None,
                "reason": f"P1 acute overload. {'; '.join(p1_skip_reasons)}.",
                "alarm_refs": p1_alarm_refs
            }
        
        # P1 modify tier (sub-skip thresholds)
        # v3.127: the standalone ACWR >= 1.3 Modify branch is removed. 1.3 is the top of
        # the Gabbett sweet spot — the edge of normal, not a danger zone — and a Tier-2
        # metric must not produce a non-overridable P1 alone. ACWR >= 1.3 still registers
        # as a P2 amber via signals["acwr"].
        if tsb is not None and tsb < -25 and hrv_delta_pct is not None and hrv_delta_pct < -10:
            p1_modify_reasons.append(f"TSB {tsb} < -25 with HRV {hrv_delta_pct}% below baseline")
        
        if p1_modify_reasons:
            return {
                "recommendation": "modify",
                "priority": 1,
                "signals": signals,
                "signal_summary": signal_summary,
                "phase_context": {
                    "phase": current_phase,
                    "phase_week": phase_duration,
                    "amber_threshold": modifiers["amber_threshold"],
                    "modifier_applied": modifiers["modifier_applied"]
                },
                "race_week_defers": race_week_active,
                "modification": self._build_modification(amber_signals),
                "reason": f"P1 acute overload (modify). {'; '.join(p1_modify_reasons)}.",
                "alarm_refs": []
            }
        
        # --- P2: Accumulated fatigue (signal counting) ---
        # Phase-adjusted TSB signal (override default if phase shifts threshold)
        tsb_amber_threshold = modifiers["tsb_amber"]
        if tsb is not None:
            if tsb < -30:
                signals["tsb"] = {"status": "red", "value": round(tsb, 1)}
            elif tsb < tsb_amber_threshold:
                signals["tsb"] = {"status": "amber", "value": round(tsb, 1)}
            else:
                signals["tsb"] = {"status": "green", "value": round(tsb, 1)}
        else:
            signals["tsb"] = {"status": "unavailable", "value": None}
        
        # Recount after TSB added
        amber_count = sum(1 for s in signals.values() if s["status"] == "amber")
        red_count = sum(1 for s in signals.values() if s["status"] == "red")
        green_count = sum(1 for s in signals.values() if s["status"] == "green")
        unavailable_count = sum(1 for s in signals.values() if s["status"] == "unavailable")
        signal_summary = {"green": green_count, "amber": amber_count, "red": red_count, "unavailable": unavailable_count}
        amber_signals = [k for k, v in signals.items() if v["status"] == "amber"]
        red_signals = [k for k, v in signals.items() if v["status"] == "red"]
        
        # Red signal handling
        if red_count >= 2 or (red_count >= 1 and modifiers["tighten_red"]):
            triggers = red_signals + amber_signals
            return {
                "recommendation": "skip" if red_count >= 2 else "modify",
                "priority": 2,
                "signals": signals,
                "signal_summary": signal_summary,
                "phase_context": {
                    "phase": current_phase,
                    "phase_week": phase_duration,
                    "amber_threshold": modifiers["amber_threshold"],
                    "modifier_applied": modifiers["modifier_applied"]
                },
                "race_week_defers": race_week_active and red_count < 2,
                "modification": self._build_modification(triggers) if red_count < 2 else None,
                "reason": f"P2 signal count. {red_count} red ({', '.join(red_signals)}), {amber_count} amber ({', '.join(amber_signals)}).",
                "alarm_refs": []
            }
        
        if red_count >= 1:
            # Single red (not tightened phase) = modify
            triggers = red_signals + amber_signals
            return {
                "recommendation": "modify",
                "priority": 2,
                "signals": signals,
                "signal_summary": signal_summary,
                "phase_context": {
                    "phase": current_phase,
                    "phase_week": phase_duration,
                    "amber_threshold": modifiers["amber_threshold"],
                    "modifier_applied": modifiers["modifier_applied"]
                },
                "race_week_defers": race_week_active,
                "modification": self._build_modification(triggers),
                "reason": f"P2 signal count. 1 red ({', '.join(red_signals)}), {amber_count} amber ({', '.join(amber_signals)}).",
                "alarm_refs": []
            }
        
        # Amber threshold check
        if amber_count >= modifiers["amber_threshold"]:
            return {
                "recommendation": "modify",
                "priority": 2,
                "signals": signals,
                "signal_summary": signal_summary,
                "phase_context": {
                    "phase": current_phase,
                    "phase_week": phase_duration,
                    "amber_threshold": modifiers["amber_threshold"],
                    "modifier_applied": modifiers["modifier_applied"]
                },
                "race_week_defers": race_week_active,
                "modification": self._build_modification(amber_signals),
                "reason": f"P2 signal count. {amber_count} amber ({', '.join(amber_signals)}) >= threshold {modifiers['amber_threshold']}.",
                "alarm_refs": []
            }
        
        # --- P3: Green light ---
        # Check data availability
        available_count = green_count + amber_count + red_count
        reason = f"P3 green light. {green_count} green, {amber_count} amber (threshold {modifiers['amber_threshold']}), {red_count} red."
        if unavailable_count > 3:
            reason += f" Note: {unavailable_count} signals unavailable — limited data."
        
        return {
            "recommendation": "go",
            "priority": 3,
            "signals": signals,
            "signal_summary": signal_summary,
            "phase_context": {
                "phase": current_phase,
                "phase_week": phase_duration,
                "amber_threshold": modifiers["amber_threshold"],
                "modifier_applied": modifiers["modifier_applied"]
            },
            "race_week_defers": False,
            "modification": None,
            "reason": reason,
            "alarm_refs": []
        }
    
    def _build_modification(self, triggers: List[str]) -> Dict:
        """Build structured modification guidance from trigger signals.
        
        Returns adjustment directions as data — AI writes the coaching language.
        Trigger → adjustment mapping is deterministic.
        """
        if not triggers:
            return {"triggers": [], "suggested_adjustments": {"intensity": "preserve", "volume": "preserve", "cap_zone": None}}
        
        # Determine adjustment directions based on trigger pattern
        has_sleep = "sleep" in triggers
        has_hrv = "hrv" in triggers
        has_rhr = "rhr" in triggers
        has_acwr = "acwr" in triggers
        has_tsb = "tsb" in triggers
        has_ri = "ri" in triggers
        
        autonomic = has_hrv or has_rhr or has_ri
        load = has_acwr or has_tsb
        multiple = len(triggers) >= 2
        
        # ACWR-driven: cap intensity, cut volume
        if has_acwr:
            return {"triggers": triggers, "suggested_adjustments": {"intensity": "reduce", "volume": "reduce", "cap_zone": "Z2"}}
        
        # Combined (2+ triggers): reduce both
        if multiple:
            return {"triggers": triggers, "suggested_adjustments": {"intensity": "reduce", "volume": "reduce", "cap_zone": None}}
        
        # Sleep-only: reduce volume, preserve intensity
        if has_sleep and not autonomic and not load:
            return {"triggers": triggers, "suggested_adjustments": {"intensity": "preserve", "volume": "reduce", "cap_zone": None}}
        
        # Autonomic-only (HRV/RHR/RI): reduce intensity, preserve volume
        if autonomic and not has_sleep and not load:
            return {"triggers": triggers, "suggested_adjustments": {"intensity": "reduce", "volume": "preserve", "cap_zone": None}}
        
        # TSB-only: reduce volume
        if has_tsb and not autonomic and not has_sleep:
            return {"triggers": triggers, "suggested_adjustments": {"intensity": "preserve", "volume": "reduce", "cap_zone": None}}
        
        # Fallback: reduce both
        return {"triggers": triggers, "suggested_adjustments": {"intensity": "reduce", "volume": "reduce", "cap_zone": None}}
    
    # === HISTORY GENERATION (v3.3.0) ===
    
    def _get_history_confidence(self) -> Dict:
        """
        Check history.json availability and return confidence metadata.
        """
        history_path = self.data_dir / self.HISTORY_FILE
        
        if history_path.exists():
            try:
                with open(history_path, 'r') as f:
                    history_data = json.load(f)
                generated_at = history_data.get("generated_at", "")
                
                # Calculate age
                try:
                    gen_date = datetime.fromisoformat(generated_at.replace("Z", "+00:00"))
                    age_days = (datetime.now() - gen_date.replace(tzinfo=None)).days
                except:
                    age_days = None
                
                # Determine confidence from data range
                total_months = history_data.get("data_range", {}).get("total_months", 0)
                if total_months >= 12:
                    confidence = "high"
                elif total_months >= 3:
                    confidence = "medium"
                else:
                    confidence = "low"
                
                return {
                    "available": True,
                    "last_generated": generated_at[:10] if generated_at else None,
                    "age_days": age_days,
                    "total_months": total_months,
                    "history_confidence": confidence
                }
            except Exception as e:
                if self.debug:
                    print(f"  Could not read history.json: {e}")
        
        return {
            "available": False,
            "history_confidence": "low",
            "note": "No history.json available. Longitudinal analysis limited to current 28-day window."
        }
    
    @staticmethod
    def _history_stamp_utc(value) -> Optional[datetime]:
        """
        A history timestamp as aware UTC, or None when absent or unusable.

        An aware stamp is converted. A naive stamp, which is what generate_history()
        writes, is interpreted as host-local wall time, so DST is applied for that
        date. A naive stamp written on another host keeps that host's offset error.
        """
        if not isinstance(value, str) or not value:
            return None
        try:
            dt = datetime.fromisoformat(value.replace("Z", "+00:00"))
            if dt.tzinfo is None:
                dt = dt.astimezone()
            return dt.astimezone(timezone.utc)
        except (ValueError, OverflowError, OSError):
            return None

    def _history_backoff_active(self, history_data: Dict, now_utc: datetime) -> bool:
        """
        True while a recorded failed automatic refresh is still backing off.

        Only state recorded by the CURRENT script applies, so changed code always
        gets an immediate attempt. A malformed block is ignored, never fatal, and
        a next attempt further away than the maximum delay is treated as stale
        (clock regression) and ignored.
        """
        state = history_data.get("refresh_state")
        if not isinstance(state, dict):
            return False
        if state.get("attempt_script_hash") != self.script_hash:
            return False
        nxt = state.get("next_attempt_after")
        if not isinstance(nxt, str) or not nxt:
            return False
        try:
            due = datetime.fromisoformat(nxt)
        except ValueError:
            return False
        if due.tzinfo is None:
            return False
        remaining = (due - now_utc).total_seconds()
        if remaining <= 0 or remaining > self.HISTORY_RETRY_MAX_SECS:
            return False
        return True

    def _history_run_budget_hold(self, env=None) -> Optional[str]:
        """
        Why the GitHub Actions run budget holds an automatic refresh of an
        existing history.json on this run, or None when it does not.

        Applies only when GITHUB_ACTIONS is "true" and GITHUB_EVENT_NAME is not
        workflow_dispatch, so local runs and manual Sync Now runs are never
        held. Any other event, custom push or repository_dispatch included, is
        held unless GITHUB_RUN_NUMBER is a plain positive integer that is a
        multiple of HISTORY_ACTIONS_RUN_BUDGET. A missing or malformed number is
        held, and its raw value is never echoed. A re-run keeps its number, so
        it gets the same answer. `env` is for tests; it defaults to os.environ.
        """
        env = os.environ if env is None else env
        if env.get("GITHUB_ACTIONS") != "true":
            return None
        if env.get("GITHUB_EVENT_NAME") == "workflow_dispatch":
            return None
        raw = env.get("GITHUB_RUN_NUMBER")
        if not (isinstance(raw, str) and raw.isascii() and raw.isdigit() and raw[0] != "0"):
            return "the run number is missing or not a positive integer"
        number = int(raw)
        if number % self.HISTORY_ACTIONS_RUN_BUDGET:
            return f"run {number} is not a multiple of {self.HISTORY_ACTIONS_RUN_BUDGET}"
        return None

    def should_generate_history(self, now: Optional[datetime] = None) -> bool:
        """
        Determine if history.json needs to be (re)generated by the automatic path.

        Triggers, in order:
        - history.json missing, unreadable or not a JSON object → generate
          (first-run scenario; no backoff, there is nothing to carry state in)
        - sync.py changed (script_hash differs) → regenerate
        - generated_at missing, unparseable or more than a day in the future → regenerate
        - older than HISTORY_REFRESH_AGE_DAYS whole days (> 28) → regenerate
        The last three are skipped while a failed attempt by this same script is
        backing off (refresh_state), and otherwise in GitHub Actions runs that the
        run budget holds (_history_run_budget_hold). There is no weekday or
        time-of-day window: outside GitHub Actions an overdue file is refreshed on
        the first run after it becomes due.
        Ages are compared in UTC; a naive generated_at is host-local time.

        `now` is for tests; it defaults to the current time.
        """
        history_path = self.data_dir / self.HISTORY_FILE
        now_utc = now if now is not None else datetime.now(timezone.utc)
        if now_utc.tzinfo is None:
            now_utc = now_utc.astimezone()
        now_utc = now_utc.astimezone(timezone.utc)

        # If history.json doesn't exist, ALWAYS generate
        if not history_path.exists():
            if self.debug:
                print("  history.json missing — will generate (first run)")
            return True

        try:
            with open(history_path, 'r') as f:
                history_data = json.load(f)
        except Exception:
            return True
        if not isinstance(history_data, dict):
            return True

        backing_off = self._history_backoff_active(history_data, now_utc)

        def due(reason: str) -> bool:
            if backing_off:
                if self.debug:
                    print(f"  history.json {reason} — refresh backing off until "
                          f"{history_data['refresh_state'].get('next_attempt_after')}")
                return False
            hold = self._history_run_budget_hold()
            if hold is not None:
                print(f"  ⏸️ history.json {reason}: automatic refresh deferred, {hold}. "
                      f"In GitHub Actions only runs numbered in multiples of "
                      f"{self.HISTORY_ACTIONS_RUN_BUDGET} refresh it automatically; a manual "
                      f"Sync Now skips only this limit and still waits out any retry backoff "
                      f"and refreshes only a due file.")
                return False
            if self.debug:
                print(f"  history.json {reason} — will regenerate")
            return True

        # If sync.py changed, regenerate regardless of age
        if history_data.get("script_hash") != self.script_hash:
            return due("stale (sync.py changed)")

        gen_utc = self._history_stamp_utc(history_data.get("generated_at"))
        if gen_utc is None:
            return due("has no usable generated_at")
        if (gen_utc - now_utc).total_seconds() > self.HISTORY_FUTURE_TOLERANCE_SECS:
            return due("generated_at is in the future")

        age_days = (now_utc - gen_utc).days
        if age_days > self.HISTORY_REFRESH_AGE_DAYS:
            return due(f"is {age_days} days old")
        if self.debug:
            print(f"  history.json is {age_days} days old — fresh enough")
        return False
    
    @preserve_budget_outputs
    def generate_history(self) -> Dict:
        self._budget_history = True
        try:
            return self._generate_history_impl()
        finally:
            self._budget_history = False

    def _generate_history_impl(self) -> Dict:
        """
        Generate history.json with tiered granularity.
        
        Pulls fresh from Intervals.icu API:
        - 90-day tier: daily rows (15 fields)
        - 180-day tier: weekly aggregates (18 fields)
        - 1/2/3-year tiers: monthly aggregates (17 fields)
        - FTP timeline from API
        - Data gaps flagged factually
        
        When a history.json that loads as a JSON object already exists, a failed
        activities, wellness or athlete fetch aborts generation by re-raising and
        the existing file is kept untouched. Without one (first run, or an
        unreadable file) a failed activities or wellness fetch still degrades to an
        empty list as before. A successful empty response is valid data. The file
        is written atomically. Callers decide criticality: the automatic path
        treats a raise as non-critical, the explicit --generate-history does not.
        """
        print("\n📊 Generating history.json...")
        
        prior_valid = self._history_prior_is_valid()
        now = datetime.now()
        
        # Determine how far back we can go (up to 3 years)
        earliest_3y = (now - timedelta(days=365 * 3)).strftime("%Y-%m-%d")
        newest = now.strftime("%Y-%m-%d")
        
        # Fetch all activities for full range
        print("  Fetching full activity history (up to 3 years)...")
        try:
            all_activities = self._intervals_get("activities", {
                "oldest": earliest_3y, "newest": newest
            })
            self._update_route_eta_history(all_activities, full_history=True)
        except Exception as e:
            print(f"  ⚠️ Could not fetch full history: {e}")
            if prior_valid:
                print("  ⚠️ History refresh aborted — existing history.json kept")
                raise
            all_activities = []
        
        # Fetch all wellness for full range
        print("  Fetching full wellness history...")
        try:
            all_wellness = self._intervals_get("wellness", {
                "oldest": earliest_3y, "newest": newest
            })
        except Exception as e:
            print(f"  ⚠️ Could not fetch wellness history: {e}")
            if prior_valid:
                print("  ⚠️ History refresh aborted — existing history.json kept")
                raise
            all_wellness = []
        
        # Fetch athlete data for FTP history from API
        print("  Fetching athlete settings...")
        athlete = self._intervals_get("")
        # v3.109: athlete_units sourced once and threaded into every tier
        # builder so weight/distance/elevation get display blocks consistent
        # with latest.json's display semantics.
        athlete_units = self._athlete_units_from_dict(athlete)
        
        # Determine actual data range
        activity_dates = sorted([a.get("start_date_local", "")[:10] for a in all_activities if a.get("start_date_local")])
        
        if activity_dates:
            earliest_date = activity_dates[0]
            latest_date = activity_dates[-1]
        else:
            earliest_date = newest
            latest_date = newest
        
        try:
            earliest_dt = datetime.strptime(earliest_date, "%Y-%m-%d")
            total_months = max(1, int((now - earliest_dt).days / 30.44))
        except:
            total_months = 0
        
        # Build wellness lookup by date
        wellness_by_date = {}
        for w in all_wellness:
            date_str = w.get("id", "")
            if date_str:
                wellness_by_date[date_str] = w
        
        # Build activity lookup by date
        activities_by_date = defaultdict(list)
        for a in all_activities:
            date_str = a.get("start_date_local", "")[:10]
            if date_str:
                activities_by_date[date_str].append(a)
        
        # === FTP TIMELINE (from wellness sportInfo history or settings) ===
        ftp_timeline = self._build_ftp_timeline(all_wellness, athlete)
        
        # === DATA GAPS ===
        data_gaps = self._find_data_gaps(activity_dates, earliest_date, latest_date)
        
        # === 90-DAY DAILY ===
        print("  Building 90-day daily tier...")
        daily_90d = self._build_daily_tier(activities_by_date, wellness_by_date, days=90,
                                           athlete_units=athlete_units)
        
        # === 180-DAY WEEKLY ===
        print("  Building 180-day weekly tier...")
        weekly_180d = self._build_weekly_tier(activities_by_date, wellness_by_date, days=180,
                                              athlete_units=athlete_units)
        try:
            previous_history = json.loads((self.data_dir / self.HISTORY_FILE).read_text())
            if not isinstance(previous_history, dict):
                previous_history = {}
        except (OSError, ValueError):
            previous_history = {}
        fun_facts_power = self._history_fun_fact_power(weekly_180d, all_activities, previous_history)
        
        # === PHASE BACKFILL ===
        # Retroactively classify phase for each COMPLETED weekly row using
        # trailing 4-week window. The in-progress current week (last row) is
        # skipped — it's not finalized, only has partial data, and its phase
        # is determined live each run by _detect_phase_v2 in the main flow.
        # Stream 2 (planned calendar) is unavailable for historical weeks —
        # confidence is limited.
        empty_race_cal = {"next_race": None, "all_races": [], "taper_alert": {"active": False}, "race_week": {"active": False}}
        for i in range(len(weekly_180d) - 1):  # skip last row (in-progress)
            lookback = weekly_180d[max(0, i-3):i+1]
            prev_phase = weekly_180d[i-1].get("phase_detected") if i > 0 else None
            result = self._detect_phase_v2(
                weekly_rows=lookback,
                planned_workouts=[],
                race_calendar=empty_race_cal,
                previous_phase=prev_phase,
                today=weekly_180d[i]["week_start"],
                is_backfill=True,
                load_activities=all_activities,
            )
            weekly_180d[i]["phase_detected"] = result["phase"]
            weekly_180d[i]["phase_load_basis"] = self._pack_phase_load(result["basis"]["main_sport_load"])
        if weekly_180d:
            weekly_180d[-1]["phase_load_basis"] = self._pack_phase_load(self._main_phase_load(
                all_activities, weekly_180d[-4:], now.strftime("%Y-%m-%d")))
        
        # === MONTHLY TIERS ===
        monthly_tiers = {}
        report_month_cache = {}
        for years in [1, 2, 3]:
            label = f"{years}y"
            days_back = years * 365
            if total_months >= years * 12 * 0.5:  # Only generate if enough data
                print(f"  Building {label} monthly tier...")
                monthly_tiers[f"monthly_{label}"] = self._build_monthly_tier(
                    activities_by_date, wellness_by_date, days=days_back,
                    athlete_units=athlete_units, weekly_180d=weekly_180d,
                    report_cache=report_month_cache
                )
            else:
                monthly_tiers[f"monthly_{label}"] = []
        
        # A month owns one compact block in the first tier that contains it.
        # Other fields on overlapping rows retain their exact legacy values.
        report_months_seen = set()
        for tier in monthly_tiers.values():
            for row in tier:
                if row["month"] in report_months_seen:
                    row.pop("report_intensity", None)
                else:
                    report_months_seen.add(row["month"])

        # === SUMMARIES ===
        summaries = self._build_history_summaries(daily_90d, weekly_180d, monthly_tiers)
        
        history = {
            "generated_at": now.isoformat(),
            "source": "Intervals.icu API",
            "sync_version": self.VERSION,
            "script_hash": self.script_hash,
            "data_range": {
                "earliest": earliest_date,
                "latest": latest_date,
                "total_months": total_months
            },
            "ftp_timeline": ftp_timeline,
            "data_gaps": data_gaps,
            "summaries": summaries,
            "daily_90d": daily_90d,
            "weekly_180d": weekly_180d,
            "report_intensity_schema": self._report_intensity_schema(),
            "phase_load_schema": self._phase_load_schema(),
            "report_intensity_season": self._report_pack(self._report_season_intensity(
                all_activities, weekly_180d, newest), ready=True),
            "fun_facts_power": fun_facts_power,
            "fun_facts": {"scope": "cycling", "sport_identity_rule": self.SPORT_IDENTITY_RULE,
                          "season": self._season_fun_facts(weekly_180d)},
            "longest_session_schema": self._longest_session_schema(),
            "acwr_definition": "coupled_7_28",
            **monthly_tiers
        }

        sport_facts = self._build_sport_fun_facts(
            all_activities, {"season": history["report_intensity_season"]})
        if sport_facts is not None:
            history["sport_fun_facts"] = sport_facts

        # The complete season summary above is retained. Only attributed power
        # maxima need persistence between refreshes; other weekly facts are
        # rebuilt from the already fetched activities, not read from this cache.
        for week in weekly_180d:
            week["fun_facts"] = self._pack_weekly_fact_power(week["fun_facts"], fun_facts_power)
        
        # Save locally (atomic: a failed write leaves any previous file intact)
        history_path = self._history_write(history)
        if getattr(self, "_acquisition", None) is not None:
            self._acquisition.companion_success["history"] = now.timestamp()
        print(f"  ✅ history.json saved to {history_path} ({len(daily_90d)} daily, {len(weekly_180d)} weekly rows)")
        
        return history
    
    def _history_prior_is_valid(self) -> bool:
        """True when history.json exists and loads as a JSON object."""
        try:
            with open(self.data_dir / self.HISTORY_FILE, 'r') as f:
                return isinstance(json.load(f), dict)
        except Exception:
            return False
    
    def _history_write(self, data: Dict) -> Path:
        """
        Atomic same-directory write of history.json: temp file plus os.replace.
        On any failure the temp file is removed and the previous file, if any, is
        left exactly as it was.
        """
        history_path = self.data_dir / self.HISTORY_FILE
        tmp_path = history_path.with_name(history_path.name + ".tmp")
        try:
            with open(tmp_path, 'w') as f:
                json.dump(data, f, indent=2, default=str)
            os.replace(tmp_path, history_path)
        except BaseException:
            try:
                if tmp_path.exists():
                    tmp_path.unlink()
            except OSError:
                pass
            raise
        return history_path
    
    def _history_error_info(self, error: BaseException) -> Dict:
        """
        Bounded, sanitized classification of a failed refresh: kind and HTTP
        status only. No exception text, which could carry a URL, a token or
        athlete data. retry_after is used for scheduling and never persisted.
        """
        kind, status, retry_after = "internal", None, None
        json_errors = (json.JSONDecodeError,)
        requests_json_error = getattr(requests.exceptions, "JSONDecodeError", None)
        if requests_json_error is not None:
            json_errors += (requests_json_error,)
        if isinstance(error, requests.exceptions.HTTPError):
            kind = "http_status"
            response = getattr(error, "response", None)
            code = getattr(response, "status_code", None)
            if isinstance(code, int) and not isinstance(code, bool):
                status = code
                if code in (429, 503):
                    retry_after = self._parse_retry_after(response.headers.get("Retry-After"))
        elif isinstance(error, json_errors):
            kind = "decode"
        elif isinstance(error, requests.exceptions.Timeout):
            kind = "timeout"
        elif isinstance(error, requests.exceptions.ConnectionError):
            kind = "connection"
        return {"kind": kind, "status": status, "retry_after": retry_after}
    
    def _history_backoff_secs(self, failures: int, retry_after_secs: Optional[int] = None) -> int:
        """Ladder delay; Retry-After may raise it but never lower it; capped at the maximum."""
        delay = self.HISTORY_RETRY_LADDER[-1][1]
        for through, secs in self.HISTORY_RETRY_LADDER:
            if through is None or failures <= through:
                delay = secs
                break
        if retry_after_secs is not None:
            delay = max(delay, int(retry_after_secs))
        return min(delay, self.HISTORY_RETRY_MAX_SECS)
    
    def _record_history_refresh_failure(self, error: BaseException,
                                        now: Optional[datetime] = None) -> Optional[Dict]:
        """
        Record a failed AUTOMATIC refresh in the existing history.json and return
        the new refresh_state, or None when nothing was recorded.
        
        Only an existing file that loads as a JSON object carries state; every
        other key, generated_at included, is preserved exactly and only
        refresh_state changes. Nothing is recorded for a missing or unreadable
        file (first run). Never raises: a failure here must not touch the main
        sync. Publication failures are not generation failures and never reach
        this method.
        
        Cross-run reach: locally the file persists. In GitHub Actions the state
        reaches the next fresh runner only if that whole run is published; a run
        that fails later discards it, so the next runner attempts again once the
        run budget (_history_run_budget_hold) allows it.
        """
        if isinstance(error, RequestBudgetRefused):
            return None
        try:
            history_path = self.data_dir / self.HISTORY_FILE
            if not history_path.exists():
                return None
            with open(history_path, 'r') as f:
                prev = json.load(f)
            if not isinstance(prev, dict):
                return None
            now_utc = now if now is not None else datetime.now(timezone.utc)
            if now_utc.tzinfo is None:
                now_utc = now_utc.astimezone()
            now_utc = now_utc.astimezone(timezone.utc)
            prev_state = prev.get("refresh_state")
            failures = 0
            if isinstance(prev_state, dict) and prev_state.get("attempt_script_hash") == self.script_hash:
                count = prev_state.get("consecutive_failures")
                if isinstance(count, int) and not isinstance(count, bool) and count >= 0:
                    failures = count
            failures += 1
            info = self._history_error_info(error)
            delay = self._history_backoff_secs(failures, info["retry_after"])
            state = {
                "last_attempt_at": now_utc.isoformat(),
                "consecutive_failures": failures,
                "next_attempt_after": (now_utc + timedelta(seconds=delay)).isoformat(),
                "attempt_script_hash": self.script_hash,
                "last_error": {"kind": info["kind"], "status": info["status"]},
            }
            data = dict(prev)
            data["refresh_state"] = state
            self._history_write(data)
            print(f"   ⚠️ Existing history.json kept; next automatic refresh attempt after {state['next_attempt_after']}")
            return state
        except Exception as e:
            print(f"   ⚠️ Could not record history refresh state (non-critical): {type(e).__name__}")
            return None
    
    def _build_daily_tier(self, activities_by_date: Dict, wellness_by_date: Dict, 
                          days: int,
                          athlete_units: Optional[Dict[str, str]] = None) -> List[Dict]:
        """Build daily resolution rows for the 90-day tier.
        
        athlete_units (v3.109): when provided, each row gets a `display` block
        with weight (display.weight) alongside canonical weight_kg.
        """
        rows = []
        now = datetime.now()
        
        for i in range(days - 1, -1, -1):
            date = (now - timedelta(days=i))
            date_str = date.strftime("%Y-%m-%d")
            
            day_activities = activities_by_date.get(date_str, [])
            wellness = wellness_by_date.get(date_str, {})
            
            total_tss = sum(a.get("icu_training_load", 0) or 0 for a in day_activities)
            total_seconds = sum(a.get("moving_time", 0) or 0 for a in day_activities)
            activity_types = list(dict.fromkeys(a.get("type", "Unknown") for a in day_activities)) if day_activities else ["Rest"]
            
            # Hard day detection via shared classifier (power + HR fallback)
            day_zones_by_basis = {}
            for a in day_activities:
                sf = self.SPORT_FAMILIES.get(a.get("type", ""), None)
                zones, basis = self._get_activity_zones(a, sport_family=sf)
                if zones and basis:
                    if basis not in day_zones_by_basis:
                        day_zones_by_basis[basis] = {}
                    for zid, secs in zones.items():
                        day_zones_by_basis[basis][zid] = day_zones_by_basis[basis].get(zid, 0) + secs
            
            is_hard, intensity_basis = self._classify_hard_day(day_zones_by_basis)
            
            rows.append({
                "date": date_str,
                "total_hours": round(total_seconds / 3600, 2),
                "total_tss": round(total_tss, 0),
                "activity_count": len(day_activities),
                "activity_types": ", ".join(activity_types),
                "ctl": wellness.get("ctl"),
                "atl": wellness.get("atl"),
                "tsb": round(wellness.get("ctl", 0) - wellness.get("atl", 0), 1) if wellness.get("ctl") and wellness.get("atl") else None,
                "hrv": wellness.get("hrv"),
                "rhr": wellness.get("restingHR"),
                "sleep_hours": round(wellness.get("sleepSecs", 0) / 3600, 2) if wellness.get("sleepSecs") else None,
                "sleep_formatted": self._format_duration(int(wellness.get("sleepSecs", 0)) // 60 * 60) if wellness.get("sleepSecs") else None,
                "sleep_quality": wellness.get("sleepQuality"),
                "sleep_score": wellness.get("sleepScore"),
                "weight_kg": wellness.get("weight"),
                "display": {
                    "weight": self._to_display(wellness.get("weight"), "weight", athlete_units),
                },
                "is_hard_day": is_hard,
                "intensity_basis": intensity_basis,
                # Subjective state (categorical 1-4, see wellness_field_scales in READ_THIS_FIRST)
                "fatigue": wellness.get("fatigue"),
                "soreness": wellness.get("soreness"),
                "stress": wellness.get("stress"),
                "mood": wellness.get("mood"),
                "motivation": wellness.get("motivation"),
                "injury": wellness.get("injury"),
                "hydration": wellness.get("hydration"),
                # Vitals
                "spO2": wellness.get("spO2"),
                "blood_glucose": wellness.get("bloodGlucose"),
                "systolic": wellness.get("systolic"),
                "diastolic": wellness.get("diastolic"),
                "baevsky_si": wellness.get("baevskySI"),
                "lactate": wellness.get("lactate"),
                "respiration": wellness.get("respiration"),
                # Body composition
                "body_fat_pct": wellness.get("bodyFat"),
                "abdomen_cm": wellness.get("abdomen"),
                # Lifestyle / nutrition
                "steps": wellness.get("steps"),
                "hydration_volume_l": wellness.get("hydrationVolume"),
                "kcal_consumed": wellness.get("kcalConsumed"),
                "carbohydrates_g": wellness.get("carbohydrates"),
                "protein_g": wellness.get("protein"),
                "fat_g": wellness.get("fatTotal"),
                # Cycle
                "menstrual_phase": wellness.get("menstrualPhase"),
                "menstrual_phase_predicted": wellness.get("menstrualPhasePredicted"),
                # Platform
                "readiness": wellness.get("readiness")
            })
        
        return rows
    
    def _build_weekly_tier(self, activities_by_date: Dict, wellness_by_date: Dict,
                           days: int,
                           athlete_units: Optional[Dict[str, str]] = None) -> List[Dict]:
        """Build weekly aggregate rows for the 180-day tier.
        
        athlete_units (v3.109): when provided, each row gets a `display` block
        with weight (display.weight) alongside canonical weight_kg.
        """
        rows = []
        now = datetime.now()
        report_activities = [a for group in activities_by_date.values() for a in group]
        report_sport = self._report_primary_sport(report_activities)
        
        # Calculate weeks
        start_date = now - timedelta(days=days)
        # Align to configured week start day
        days_since_week_start = (start_date.weekday() - self.week_start_day) % 7
        start_aligned = start_date - timedelta(days=days_since_week_start)
        
        current = start_aligned
        while current < now:
            week_end = current + timedelta(days=6)
            if week_end > now:
                week_end = now
            
            week_tss = 0
            week_seconds = 0
            week_activities = 0
            week_hrv = []
            week_rhr = []
            week_sleep = []
            week_feel = []
            week_rpe = []
            week_weight = []
            hard_days = 0
            daily_tss_list = []
            intensity_basis_counts = {"power": 0, "hr": 0}
            longest_ride = 0
            z1_z2_time = 0
            z3_time = 0
            z4_plus_time = 0
            total_zone_time = 0
            ctl_end = None
            atl_end = None
            tsb_end = None
            ramp_rate = None
            sport_tss = defaultdict(float)
            
            for d in range(7):
                date = current + timedelta(days=d)
                if date > now:
                    break
                date_str = date.strftime("%Y-%m-%d")
                
                day_activities = activities_by_date.get(date_str, [])
                wellness = wellness_by_date.get(date_str, {})
                
                day_tss = sum(a.get("icu_training_load", 0) or 0 for a in day_activities)
                day_seconds = sum(a.get("moving_time", 0) or 0 for a in day_activities)
                
                week_tss += day_tss
                week_seconds += day_seconds
                week_activities += len(day_activities)
                daily_tss_list.append(day_tss)

                if self._is_valid_hrv(wellness.get("hrv")):
                    week_hrv.append(wellness["hrv"])
                if wellness.get("restingHR"):
                    week_rhr.append(wellness["restingHR"])
                if wellness.get("sleepSecs"):
                    week_sleep.append(wellness["sleepSecs"] / 3600)
                if wellness.get("weight"):
                    week_weight.append(wellness["weight"])
                
                ctl_end = wellness.get("ctl") or ctl_end
                atl_end = wellness.get("atl") or atl_end
                ramp_rate = wellness.get("rampRate") or ramp_rate
                
                # Zone distribution + hard day analysis (shared helper)
                day_zones_by_basis = {}
                for a in day_activities:
                    ride_seconds = a.get("moving_time", 0) or 0
                    if ride_seconds > longest_ride:
                        longest_ride = ride_seconds
                    
                    sf = self.SPORT_FAMILIES.get(a.get("type", ""), None)
                    a_tss = a.get("icu_training_load", 0) or 0
                    if a_tss > 0 and sf:
                        sport_tss[sf] += a_tss
                    zones, basis = self._get_activity_zones(a, sport_family=sf)
                    if zones and basis:
                        # Accumulate for hard day classification (separate by basis)
                        if basis not in day_zones_by_basis:
                            day_zones_by_basis[basis] = {}
                        for zid, secs in zones.items():
                            day_zones_by_basis[basis][zid] = day_zones_by_basis[basis].get(zid, 0) + secs
                        
                        # Accumulate for weekly zone distribution (combined)
                        for zid, secs in zones.items():
                            if zid in ("z1", "z2"):
                                z1_z2_time += secs
                            elif zid == "z3":
                                z3_time += secs
                            elif zid in ("z4", "z5", "z6", "z7"):
                                z4_plus_time += secs
                            total_zone_time += secs
                    
                    feel = a.get("feel")
                    if feel is not None:
                        week_feel.append(feel)
                    rpe = a.get("icu_rpe")
                    if rpe is not None:
                        week_rpe.append(rpe)
                
                is_hard, hard_basis = self._classify_hard_day(day_zones_by_basis)
                if is_hard:
                    hard_days += 1
                    if hard_basis in ("power", "hr"):
                        intensity_basis_counts[hard_basis] += 1
            
            if ctl_end and atl_end:
                tsb_end = round(ctl_end - atl_end, 1)
            
            # Monotony: mean(daily_tss) / stdev(daily_tss) — Foster (1998)
            # Requires 5+ days for meaningful value; partial weeks produce garbage
            # (e.g., 2 similar days → near-zero stdev → monotony 40+)
            week_monotony = None
            days_with_data = sum(1 for t in daily_tss_list if t > 0)
            if len(daily_tss_list) >= 5 and days_with_data >= 3:
                try:
                    m = statistics.mean(daily_tss_list)
                    s = statistics.stdev(daily_tss_list)
                    week_monotony = round(m / s, 2) if s > 0 else None
                except Exception:
                    week_monotony = None
            
            week_primary_sport = max(sport_tss, key=sport_tss.get) if sport_tss else None
            week_primary_sport_tss = round(sport_tss[week_primary_sport], 0) if week_primary_sport else None

            # Weekly capability rollup (v3.110) — trajectory layer for Season Report v2.
            # Mirrors gating rules from _calculate_durability / _calculate_efficiency_factor /
            # _calculate_hrrc_trend but operates on the week's activities without the trend
            # or alert layer. N>=1 is sufficient; qualifying count lets the report calibrate.
            # Durability: explicit is not None check (avoids silent drop of 0.0 values).
            _week_acts = [
                a for d in range(7)
                for a in activities_by_date.get(
                    (current + timedelta(days=d)).strftime("%Y-%m-%d"), []
                )
                if (current + timedelta(days=d)) <= now
            ]
            _CYCLING_EF_TYPES = {"Ride", "VirtualRide", "MountainBikeRide", "GravelRide"}

            # Durability (VI<=1.05, VI>0, mt>=5400, decoupling not None)
            _dur_vals = self._cycling_durability_values(_week_acts)
            week_durability_mean = round(statistics.mean(_dur_vals), 2) if _dur_vals else None
            week_durability_qualifying = len(_dur_vals)

            # EF (cycling only, VI<=1.05, VI>0, mt>=1200, EF not None)
            _ef_vals = []
            for _a in _week_acts:
                _ef = _a.get("icu_efficiency_factor")
                _vi = _a.get("icu_variability_index")
                _mt = _a.get("moving_time", 0) or 0
                if (_ef is not None and _a.get("type", "") in _CYCLING_EF_TYPES
                        and _vi is not None and _vi > 0 and _vi <= 1.05 and _mt >= 1200):
                    _ef_vals.append(_ef)
            week_ef_mean = round(statistics.mean(_ef_vals), 2) if _ef_vals else None
            week_ef_qualifying = len(_ef_vals)

            # HRRc (icu_hrr not None, >0)
            _hrrc_vals = []
            for _a in _week_acts:
                _hrrc = _a.get("icu_hrr")
                if isinstance(_hrrc, dict):
                    _v = _hrrc.get("value")
                    if _v is None:
                        _v = _hrrc.get("hrr")
                    _hrrc = _v
                if isinstance(_hrrc, (int, float)) and _hrrc > 0:
                    _hrrc_vals.append(float(_hrrc))
            week_hrrc_mean = round(statistics.mean(_hrrc_vals), 1) if _hrrc_vals else None
            week_hrrc_qualifying = len(_hrrc_vals)

            rows.append({
                "week_start": current.strftime("%Y-%m-%d"),
                "total_hours": round(week_seconds / 3600, 2),
                "total_tss": round(week_tss, 0),
                "primary_sport": week_primary_sport,
                "primary_sport_tss": week_primary_sport_tss,
                "sport_tss_breakdown": {k: round(v, 0) for k, v in sport_tss.items()} if sport_tss else None,
                "seiler_tid_primary": self._report_seiler_tid(_week_acts, report_sport),
                "report_intensity": self._report_pack(self._report_intensity(
                    report_activities, current.strftime("%Y-%m-%d"), week_end.strftime("%Y-%m-%d"),
                    as_of=now.strftime("%Y-%m-%d"))),
                "activity_count": week_activities,
                "ctl_end": round(ctl_end, 1) if ctl_end else None,
                "atl_end": round(atl_end, 1) if atl_end else None,
                "tsb_end": tsb_end,
                "ramp_rate": round(ramp_rate, 2) if ramp_rate else None,
                "avg_hrv": round(statistics.mean(week_hrv), 1) if week_hrv else None,
                "avg_rhr": round(statistics.mean(week_rhr), 1) if week_rhr else None,
                "avg_sleep_hours": round(statistics.mean(week_sleep), 2) if week_sleep else None,
                "z1_z2_pct": round((z1_z2_time / total_zone_time) * 100, 1) if total_zone_time > 0 else None,
                "z3_pct": round((z3_time / total_zone_time) * 100, 1) if total_zone_time > 0 else None,
                "z4_plus_pct": round((z4_plus_time / total_zone_time) * 100, 1) if total_zone_time > 0 else None,
                "hard_days": hard_days,
                "longest_ride_hours": round(longest_ride / 3600, 2),
                "hard_days_coverage": self._hard_days_coverage(_week_acts),
                "avg_feel": round(statistics.mean(week_feel), 1) if week_feel else None,
                "feel_count": len(week_feel) if week_feel else 0,
                "avg_rpe": round(statistics.mean(week_rpe), 1) if week_rpe else None,
                "rpe_count": len(week_rpe) if week_rpe else 0,
                "weight_kg": round(week_weight[-1], 1) if week_weight else None,
                "display": {
                    "weight": self._to_display(
                        round(week_weight[-1], 1) if week_weight else None,
                        "weight", athlete_units
                    ),
                },
                "monotony": week_monotony,
                "monotony_main_sports": self._weekly_main_monotony(
                    report_activities, current.strftime("%Y-%m-%d"),
                    week_end.strftime("%Y-%m-%d")),
                "intensity_basis_breakdown": intensity_basis_counts if hard_days > 0 else None,
                "acwr": None,  # computed in post-pass below
                "phase_detected": None,  # populated by _detect_phase_v2
                "durability_mean": week_durability_mean,
                "durability_qualifying": week_durability_qualifying,
                "durability_sport": "cycling",
                "longest_session_by_sport": self._longest_sessions(
                    report_activities, current.strftime("%Y-%m-%d"), week_end.strftime("%Y-%m-%d")),
                "ef_mean": week_ef_mean,
                "ef_qualifying": week_ef_qualifying,
                "hrrc_mean": week_hrrc_mean,
                "hrrc_qualifying": week_hrrc_qualifying,
            })
            
            current += timedelta(days=7)
        
        self._couple_weekly_acwr(rows)
        return rows

    @staticmethod
    def _couple_weekly_acwr(rows):
        """Same coupled 7:28 definition as live ACWR; no partial-week scaling."""
        for i, row in enumerate(rows):
            row["acwr"] = None
            if i < 3:
                continue
            # Do not silently bridge missing calendar weeks in a retained file.
            dates = [datetime.strptime(r["week_start"], "%Y-%m-%d") for r in rows[i - 3:i + 1]]
            if any((b - a).days != 7 for a, b in zip(dates, dates[1:])):
                continue
            acute = row["total_tss"] / 7 if row["total_tss"] else 0
            chronic_tss = sum(rows[j]["total_tss"] or 0 for j in range(i - 3, i + 1))
            chronic = chronic_tss / 28 if chronic_tss else 0
            if chronic > 0:
                row["acwr"] = round(acute / chronic, 2)
    
    def _build_monthly_tier(self, activities_by_date: Dict, wellness_by_date: Dict,
                            days: int,
                            athlete_units: Optional[Dict[str, str]] = None,
                            weekly_180d: Optional[List[Dict]] = None,
                            report_cache: Optional[Dict] = None) -> List[Dict]:
        """Build monthly aggregate rows for 1/2/3-year tiers.

        athlete_units (v3.109): when provided, each row gets a `display` block
        with avg_weight (display.avg_weight) alongside canonical avg_weight_kg.
        Aggregate naming preserved — point-in-time rows expose `display.weight`.

        weekly_180d (v3.110): when provided, dominant_phase is derived via modal
        aggregation of already-computed phase_detected values from weekly rows
        whose span overlaps the month (overlap: week_start < next_month AND
        week_end >= current_month). TSS-weighted tie-break. None when no
        overlapping weekly rows exist (month outside 180d window).
        """
        rows = []
        now = datetime.now()
        report_activities = [a for group in activities_by_date.values() for a in group]
        report_sport = self._report_primary_sport(report_activities)
        start_date = now - timedelta(days=days)
        report_cache = {} if report_cache is None else report_cache
        
        # Group by month
        current_month = datetime(start_date.year, start_date.month, 1)
        
        while current_month <= now:
            month_str = current_month.strftime("%Y-%m")
            
            # Determine days in this month
            if current_month.month == 12:
                next_month = datetime(current_month.year + 1, 1, 1)
            else:
                next_month = datetime(current_month.year, current_month.month + 1, 1)
            
            month_tss = 0
            month_seconds = 0
            month_activities = 0
            month_hrv = []
            month_rhr = []
            month_weight = []
            ctl_values = []
            hard_days_total = 0
            longest_ride = 0
            z1_z2_time = 0
            z3_time = 0
            z4_plus_time = 0
            total_zone_time = 0
            days_with_data = 0
            total_days_in_month = 0
            month_acts = []
            
            date = current_month
            while date < next_month and date <= now:
                date_str = date.strftime("%Y-%m-%d")
                total_days_in_month += 1
                
                day_activities = activities_by_date.get(date_str, [])
                month_acts.extend(day_activities)
                wellness = wellness_by_date.get(date_str, {})
                
                if day_activities or wellness:
                    days_with_data += 1
                
                day_tss = sum(a.get("icu_training_load", 0) or 0 for a in day_activities)
                day_seconds = sum(a.get("moving_time", 0) or 0 for a in day_activities)
                
                month_tss += day_tss
                month_seconds += day_seconds
                month_activities += len(day_activities)


                if self._is_valid_hrv(wellness.get("hrv")):
                    month_hrv.append(wellness["hrv"])
                if wellness.get("restingHR"):
                    month_rhr.append(wellness["restingHR"])
                if wellness.get("weight"):
                    month_weight.append(wellness["weight"])
                if wellness.get("ctl"):
                    ctl_values.append(wellness["ctl"])
                
                day_zones_by_basis = {}
                for a in day_activities:
                    ride_seconds = a.get("moving_time", 0) or 0
                    if ride_seconds > longest_ride:
                        longest_ride = ride_seconds
                    
                    sf = self.SPORT_FAMILIES.get(a.get("type", ""), None)
                    zones, basis = self._get_activity_zones(a, sport_family=sf)
                    if zones and basis:
                        # Accumulate for hard day classification (separate by basis)
                        if basis not in day_zones_by_basis:
                            day_zones_by_basis[basis] = {}
                        for zid, secs in zones.items():
                            day_zones_by_basis[basis][zid] = day_zones_by_basis[basis].get(zid, 0) + secs
                        
                        # Accumulate for monthly zone distribution (combined)
                        for zid, secs in zones.items():
                            if zid in ("z1", "z2"):
                                z1_z2_time += secs
                            elif zid == "z3":
                                z3_time += secs
                            elif zid in ("z4", "z5", "z6", "z7"):
                                z4_plus_time += secs
                            total_zone_time += secs
                
                is_hard, _basis = self._classify_hard_day(day_zones_by_basis)
                if is_hard:
                    hard_days_total += 1
                
                date += timedelta(days=1)
            
            # Calculate weeks in this month for per-week averages
            weeks_in_period = max(1, total_days_in_month / 7)
            
            # Determine dominant phase via modal aggregation of weekly_180d phase_detected
            # values whose week span overlaps this month (v3.110). Overlap test:
            #   week_start < next_month AND week_end >= current_month
            # Catches boundary weeks that straddle month edges.
            # Rule: most-frequent label wins. TSS is tie-break only (not primary weight).
            # Falls back to None when no overlapping rows exist (month outside 180d window).
            dominant_phase = None
            if weekly_180d:
                phase_counts: Dict[str, int] = {}
                phase_tss_tb: Dict[str, float] = {}  # TSS tie-break accumulator
                for wrow in weekly_180d:
                    phase = wrow.get("phase_detected")
                    if not phase:
                        continue
                    try:
                        ws = datetime.strptime(wrow["week_start"], "%Y-%m-%d")
                    except (KeyError, ValueError):
                        continue
                    we = ws + timedelta(days=6)
                    if ws < next_month and we >= current_month:
                        phase_counts[phase] = phase_counts.get(phase, 0) + 1
                        phase_tss_tb[phase] = phase_tss_tb.get(phase, 0.0) + (wrow.get("total_tss") or 0.0)
                if phase_counts:
                    max_count = max(phase_counts.values())
                    candidates = [p for p, c in phase_counts.items() if c == max_count]
                    # Single winner — no tie-break needed
                    if len(candidates) == 1:
                        dominant_phase = candidates[0]
                    else:
                        # Tie: pick candidate with highest accumulated TSS
                        dominant_phase = max(candidates, key=lambda p: phase_tss_tb.get(p, 0.0))
            
            if month_str not in report_cache:
                report_cache[month_str] = self._report_pack(self._report_intensity(
                    report_activities, current_month.strftime("%Y-%m-%d"),
                    min(now, next_month - timedelta(days=1)).strftime("%Y-%m-%d"),
                    weekly_rescue=True, as_of=now.strftime("%Y-%m-%d")))
            rows.append({
                "month": month_str,
                "seiler_tid_primary": self._report_seiler_tid(month_acts, report_sport),
                "report_intensity": report_cache[month_str],
                "total_hours": round(month_seconds / 3600, 2),
                "total_tss": round(month_tss, 0),
                "activity_count": month_activities,
                "longest_session_by_sport": self._longest_sessions(
                    report_activities, current_month.strftime("%Y-%m-%d"),
                    min(now, next_month - timedelta(days=1)).strftime("%Y-%m-%d")),
                "ctl_peak": round(max(ctl_values), 1) if ctl_values else None,
                "ctl_low": round(min(ctl_values), 1) if ctl_values else None,
                "ctl_end": round(ctl_values[-1], 1) if ctl_values else None,
                "avg_hrv": round(statistics.mean(month_hrv), 1) if month_hrv else None,
                "avg_rhr": round(statistics.mean(month_rhr), 1) if month_rhr else None,
                "z1_z2_pct": round((z1_z2_time / total_zone_time) * 100, 1) if total_zone_time > 0 else None,
                "z3_pct": round((z3_time / total_zone_time) * 100, 1) if total_zone_time > 0 else None,
                "z4_plus_pct": round((z4_plus_time / total_zone_time) * 100, 1) if total_zone_time > 0 else None,
                "hard_days_avg_per_week": round(hard_days_total / weeks_in_period, 1),
                "longest_ride_hours": round(longest_ride / 3600, 2),
                "avg_weight_kg": round(statistics.mean(month_weight), 1) if month_weight else None,
                "display": {
                    "avg_weight": self._to_display(
                        round(statistics.mean(month_weight), 1) if month_weight else None,
                        "weight", athlete_units
                    ),
                },
                "dominant_phase": dominant_phase,
                "days_with_data": days_with_data
            })
            
            current_month = next_month
        
        return rows
    
    def _build_ftp_timeline(self, all_wellness: List[Dict], athlete: Dict) -> List[Dict]:
        """
        Build FTP timeline from ftp_history.json (actual user-set FTP values).
        Falls back to current sportSettings if no history file exists.
        """
        timeline = []
        
        # Primary source: ftp_history.json (tracked by sync.py on each run)
        ftp_history = self._load_ftp_history()
        
        for ftp_type in ["indoor", "outdoor"]:
            entries = ftp_history.get(ftp_type, {})
            for date_str, ftp_val in sorted(entries.items()):
                timeline.append({
                    "date": date_str,
                    "ftp": ftp_val,
                    "type": ftp_type,
                    "source": "FTP"
                })
        
        # Fallback: add current user-set FTP if not already in timeline
        cycling_settings = None
        if athlete.get("sportSettings"):
            for sport in athlete["sportSettings"]:
                sport_types = sport.get("types") or []             # v3.124: present-but-null
                if "Ride" in sport_types or "VirtualRide" in sport_types:
                    cycling_settings = sport
                    break
        
        if cycling_settings:
            today = datetime.now().strftime("%Y-%m-%d")
            outdoor_ftp = cycling_settings.get("ftp")
            indoor_ftp = cycling_settings.get("indoor_ftp")
            
            # Check if current FTP is already the latest in timeline
            outdoor_dates = {e["date"]: e["ftp"] for e in timeline if e["type"] == "outdoor"}
            indoor_dates = {e["date"]: e["ftp"] for e in timeline if e["type"] == "indoor"}
            
            latest_outdoor = outdoor_dates.get(max(outdoor_dates.keys())) if outdoor_dates else None
            latest_indoor = indoor_dates.get(max(indoor_dates.keys())) if indoor_dates else None
            
            if outdoor_ftp and outdoor_ftp != latest_outdoor:
                timeline.append({"date": today, "ftp": outdoor_ftp, "type": "outdoor", "source": "user_set"})
            if indoor_ftp and indoor_ftp != latest_indoor:
                timeline.append({"date": today, "ftp": indoor_ftp, "type": "indoor", "source": "user_set"})
        
        # Sort chronologically
        timeline.sort(key=lambda x: (x["date"], x["type"]))
        
        return timeline
    
    def _find_data_gaps(self, activity_dates: List[str], earliest: str, latest: str) -> List[Dict]:
        """
        Find periods with no activity data (gaps ≥ 3 days).
        Flags factually without inference about reasons.
        """
        gaps = []
        if not activity_dates:
            return gaps
        
        date_set = set(activity_dates)
        
        try:
            start = datetime.strptime(earliest, "%Y-%m-%d")
            end = datetime.strptime(latest, "%Y-%m-%d")
        except:
            return gaps
        
        gap_start = None
        current = start
        
        while current <= end:
            date_str = current.strftime("%Y-%m-%d")
            
            if date_str not in date_set:
                if gap_start is None:
                    gap_start = current
            else:
                if gap_start is not None:
                    gap_days = (current - gap_start).days
                    if gap_days >= 3:
                        gaps.append({
                            "period": f"{gap_start.strftime('%Y-%m-%d')} to {(current - timedelta(days=1)).strftime('%Y-%m-%d')}",
                            "days_missing": gap_days
                        })
                    gap_start = None
            
            current += timedelta(days=1)
        
        # Handle trailing gap
        if gap_start is not None:
            gap_days = (end - gap_start).days + 1
            if gap_days >= 3:
                gaps.append({
                    "period": f"{gap_start.strftime('%Y-%m-%d')} to {end.strftime('%Y-%m-%d')}",
                    "days_missing": gap_days
                })
        
        return gaps
    
    def _build_history_summaries(self, daily_90d: List[Dict], weekly_180d: List[Dict],
                                  monthly_tiers: Dict) -> Dict:
        """Build pre-computed summaries for each tier."""
        summaries = {}
        
        # 90-day summary from daily data
        if daily_90d:
            tss_values = [d["total_tss"] for d in daily_90d if d["total_tss"]]
            hours_values = [d["total_hours"] for d in daily_90d if d["total_hours"]]
            ctl_values = [d["ctl"] for d in daily_90d if d["ctl"]]
            
            summaries["90d"] = {
                "avg_weekly_tss": round(sum(tss_values) / max(1, len(daily_90d) / 7), 0) if tss_values else None,
                "avg_weekly_hours": round(sum(hours_values) / max(1, len(daily_90d) / 7), 1) if hours_values else None,
                "ctl_start": round(ctl_values[0], 1) if ctl_values else None,
                "ctl_end": round(ctl_values[-1], 1) if ctl_values else None,
                "total_activities": sum(1 for d in daily_90d if d["activity_count"] > 0),
                "rest_days": sum(1 for d in daily_90d if d["activity_count"] == 0),
                "hard_days": sum(1 for d in daily_90d if d.get("is_hard_day"))
            }
        
        # 180-day summary from weekly data
        if weekly_180d:
            tss_values = [w["total_tss"] for w in weekly_180d if w["total_tss"]]
            hours_values = [w["total_hours"] for w in weekly_180d if w["total_hours"]]
            ctl_values = [w["ctl_end"] for w in weekly_180d if w["ctl_end"]]
            
            summaries["180d"] = {
                "avg_weekly_tss": round(statistics.mean(tss_values), 0) if tss_values else None,
                "avg_weekly_hours": round(statistics.mean(hours_values), 1) if hours_values else None,
                "ctl_start": round(ctl_values[0], 1) if ctl_values else None,
                "ctl_end": round(ctl_values[-1], 1) if ctl_values else None,
                "weeks_tracked": len(weekly_180d)
            }
        
        # Yearly summaries from monthly data
        for key in ["monthly_1y", "monthly_2y", "monthly_3y"]:
            monthly = monthly_tiers.get(key, [])
            if monthly:
                tss_values = [m["total_tss"] for m in monthly if m["total_tss"]]
                ctl_values = [m["ctl_end"] for m in monthly if m["ctl_end"]]
                
                label = key.replace("monthly_", "")
                summaries[label] = {
                    "avg_monthly_tss": round(statistics.mean(tss_values), 0) if tss_values else None,
                    "ctl_peak": round(max(ctl_values), 1) if ctl_values else None,
                    "ctl_low": round(min(ctl_values), 1) if ctl_values else None,
                    "months_tracked": len(monthly)
                }
        
        return summaries
    
    # === UPDATE NOTIFICATIONS (v3.3.0) ===
    
    def check_upstream_updates(self):
        """
        Check CrankAddict/section-11 for new releases and create a GitHub Issue.
        
        Tries manifest.json first (version-based comparison). Falls back to
        changelog.json (notification_id-based) if manifest.json is not available.
        """
        if not self.github_token or not self.github_repo:
            if self.debug:
                print("  Skipping update check — no GitHub credentials")
            return
        
        headers = {
            "Authorization": f"token {self.github_token}",
            "Accept": "application/vnd.github+json"
        }
        
        # GitHub Issues use changelog.json for human-readable release notes
        # (manifest.json is for local --update only)
        self._check_updates_via_changelog(headers)
    
    def _check_updates_via_manifest(self, manifest, headers):
        """Create a GitHub Issue if manifest file hashes have changed."""
        files = manifest.get("files", {})
        
        # Generate deterministic fingerprint from sorted path:hash pairs
        hash_pairs = sorted(f"{k}:{v.get('hash', '?')}" for k, v in files.items())
        fingerprint = "|".join(hash_pairs)
        
        # Use a short hash for the issue title
        fp_hash = hashlib.md5(fingerprint.encode()).hexdigest()[:8]
        issue_title = f"Section 11 updates — {fp_hash}"
        
        # Check if issue already exists
        if self._issue_exists(issue_title, headers):
            if self.debug:
                print(f"  Update notification already exists: {issue_title}")
            return
        
        # Build issue body
        body = "## Section 11 Update Available\n\n"
        body += "### Tracked files:\n"
        for path in sorted(files.keys()):
            info = files[path]
            desc = info.get("description", "")
            desc_str = f" — {desc}" if desc else ""
            body += f"- **{path}**{desc_str}\n"
        body += f"\n### Repository:\n"
        body += f"https://github.com/{self.UPSTREAM_REPO}\n"
        body += f"\n### Update instructions:\n"
        body += f"- **Local users:** `python section11/examples/sync.py --update`\n"
        body += f"- **GitHub users:** download the latest files from the repository\n"
        body += f"\n*This issue was auto-created by sync.py v{self.VERSION}*"
        
        self._create_issue(issue_title, body, headers)
    
    def _check_updates_via_changelog(self, headers):
        """Legacy: Create a GitHub Issue from changelog.json notification_id."""
        try:
            url = f"https://raw.githubusercontent.com/{self.UPSTREAM_REPO}/main/{self.CHANGELOG_FILE}"
            response = requests.get(url, timeout=10)
            if response.status_code != 200:
                if self.debug:
                    print(f"  No changelog.json found upstream (HTTP {response.status_code})")
                return
            
            changelog = response.json()
        except Exception as e:
            if self.debug:
                print(f"  Could not fetch upstream changelog: {e}")
            return
        
        notification_id = changelog.get("notification_id")
        if not notification_id:
            if self.debug:
                print("  No notification_id in changelog")
            return
        
        issue_title = f"Section 11 updates — {notification_id}"
        
        if self._issue_exists(issue_title, headers):
            if self.debug:
                print(f"  Update notification already exists: {issue_title}")
            return
        
        # Build issue body
        changes = changelog.get("changes", [])
        body = f"## Section 11 Update Available\n\n"
        body += f"**Notification ID:** {notification_id}\n\n"
        body += "### Changes:\n"
        for change in changes:
            body += f"- {change}\n"
        body += f"\n### Repository:\n"
        body += f"https://github.com/{self.UPSTREAM_REPO}\n"
        body += f"\n*This issue was auto-created by sync.py v{self.VERSION}*"
        
        self._create_issue(issue_title, body, headers)
    
    def _issue_exists(self, title, headers):
        """Check if a GitHub Issue with this title already exists."""
        try:
            search_url = f"{self.GITHUB_API_URL}/search/issues"
            search_params = {
                "q": f'repo:{self.github_repo} "{title}" in:title'
            }
            response = requests.get(search_url, headers=headers, params=search_params, timeout=10)
            
            if response.status_code == 200:
                results = response.json()
                return results.get("total_count", 0) > 0
        except Exception as e:
            if self.debug:
                print(f"  Could not search issues: {e}")
        return False
    
    def _create_issue(self, title, body, headers):
        """Create a GitHub Issue."""
        try:
            issues_url = f"{self.GITHUB_API_URL}/repos/{self.github_repo}/issues"
            payload = {
                "title": title,
                "body": body,
                "labels": ["update-notification"]
            }
            response = requests.post(issues_url, headers=headers, json=payload, timeout=10)
            
            if response.status_code == 201:
                print(f"  📢 Update notification created: {title}")
            else:
                if self.debug:
                    print(f"  Could not create issue (HTTP {response.status_code}): {response.text}")
        except Exception as e:
            if self.debug:
                print(f"  Could not create update issue: {e}")
    
    # Structure shares interval retention, but not interval/DFA interpretation.
    STRUCTURE_VERSION = 6
    STRUCTURE_MAX_STEPS = 20
    STRUCTURE_MAX_EFFORTS = 8
    PLAN_KEY_VERSION = 2
    STRUCTURE_FTP_UNITS = ("%", "%ftp", "percent_ftp")

    @staticmethod
    def _structure_number(value):
        return (isinstance(value, (int, float)) and not isinstance(value, bool)
                and math.isfinite(value) and abs(value) <= 1e12)

    def _plan_duration_check(self, planned, actual):
        valid = lambda v: self._structure_number(v) and 0 < v <= 604800
        planned = planned if valid(planned) else None
        actual = actual if valid(actual) else None
        tolerance = max(planned * .05, 300) if planned is not None else None
        delta = actual - planned if planned is not None and actual is not None else None
        return {"planned_s": planned, "actual_s": actual, "delta_s": delta,
                "tolerance_s": tolerance,
                "within_tolerance": abs(delta) <= tolerance if delta is not None else None}

    def _plan_targets_intensity(self, event, act):
        """Explicit Z3+ intent only; never infer intensity from a workout name."""
        doc = event.get("workout_doc") if isinstance(event, dict) else None
        steps = doc.get("steps") if isinstance(doc, dict) else None
        if not isinstance(steps, list):
            return None
        if not steps:
            return False
        pending, assessed, unknown = list(steps), [], False
        for _ in range(10000):
            if not pending:
                break
            step = pending.pop()
            if not isinstance(step, dict):
                unknown = True
                continue
            if isinstance(step.get("steps"), list):
                pending.extend(step["steps"])
                continue
            known = False
            for kind in ("power", "hr"):
                target = step.get(kind)
                if not isinstance(target, dict):
                    continue
                units = str(target.get("units", "")).lower()
                values = [target[k] for k in ("value", "min", "max", "start", "end")
                          if self._structure_number(target.get(k))]
                zone = target.get("zone")
                if self._structure_number(zone):
                    assessed.append(zone >= 3)
                    known = True
                elif values and units in ("zone", "zones", "power_zone", "hr_zone"):
                    assessed.append(max(values) >= 3)
                    known = True
                elif values and kind == "power" and units in ("%", "%ftp", "percent_ftp"):
                    assessed.append(max(values) > 75)
                    known = True
                else:
                    resolved = step.get("_" + kind, target)
                    absolute = (isinstance(resolved, dict) and
                                (resolved is not target or units in ("w", "watts", "bpm")))
                    nums = [resolved[k] for k in ("value", "min", "max", "start", "end")
                            if absolute and self._structure_number(resolved.get(k))]
                    bounds = act.get("icu_power_zones" if kind == "power" else "icu_hr_zones")
                    boundary = bounds[1] if isinstance(bounds, list) and len(bounds) > 1 else None
                    if not self._structure_number(boundary) and kind == "power":
                        ftp = act.get("icu_ftp")
                        boundary = ftp * .75 if self._structure_number(ftp) and ftp > 0 else None
                    if nums and self._structure_number(boundary) and boundary > 0:
                        assessed.append(max(nums) > boundary)
                        known = True
            unknown |= not known
        if any(assessed):
            return True
        return False if assessed and not unknown and not pending else None

    def _current_plan_pairing(self, act, event_map, reverse_map):
        """Refresh current identity for every sport using already-fetched events."""
        paired = act.get("paired_event_id")
        reverse = reverse_map.get(str(act.get("id")), [])
        if paired is None and len(reverse) == 1:
            paired = reverse[0].get("id")
        matches = event_map.get(str(paired), []) if paired is not None else []
        conflict = (len(matches) > 1 or len(reverse) > 1 or
                    (paired is not None and any(str(e.get("id")) != str(paired) for e in reverse)))
        event = matches[0] if len(matches) == 1 and not conflict else None
        intent = self._structure_plan(dict(act, paired_event_id=paired), event)
        if conflict:
            intent = {"status": "ambiguous_pairing"}
        reference = {"event_id": str(paired)[:80], "name": None} if paired is not None else None
        if reference is not None:
            reference.update(intent.get("reference", {}))
        return {"paired": paired is not None, "plan": reference,
                "status": intent["status"],
                "duration": self._plan_duration_check((reference or {}).get("duration_s"), act.get("moving_time")),
                "targets_intensity": self._plan_targets_intensity(event, act)
                    if "reference" in intent else None,
                "definition_key": self._plan_definition_key(event.get("workout_doc"))
                    if "reference" in intent else None,
                "definition_key_version": self.PLAN_KEY_VERSION}

    @staticmethod
    def _structure_date(value):
        try:
            result = datetime.fromisoformat(value.replace("Z", "+00:00"))
            return result if result.tzinfo is not None else None
        except (TypeError, ValueError, AttributeError):
            return None

    @staticmethod
    def _structure_fingerprint(value):
        return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(",", ":"),
                                         default=str).encode()).hexdigest()

    def _plan_definition_key(self, doc):
        """Hash authored numeric structure, never endpoint-resolved settings.

        Preserve array order and nested repetitions. A key is not an archive
        of coaching text, roles or essential secondary instructions.
        """
        if not isinstance(doc, dict) or not isinstance(doc.get("steps"), list):
            return None
        count = 0

        def scalar(value):
            if value is None or isinstance(value, (str, bool)):
                return value
            if self._structure_number(value):
                return int(value) if value == int(value) else value
            raise ValueError("Invalid definition scalar")

        def step(value, depth=0):
            nonlocal count
            count += 1
            if count > 10000 or depth > 64 or not isinstance(value, dict):
                raise ValueError("Invalid or oversized definition")
            result = {k: scalar(value[k]) for k in
                      ("duration", "distance", "reps", "repeat", "ramp") if k in value}
            for kind in ("power", "hr", "pace", "cadence"):
                if kind in value:
                    target = value[kind]
                    result[kind] = ({k: scalar(target[k]) for k in
                                     ("value", "start", "end", "min", "max", "units", "zone", "ramp")
                                     if k in target} if isinstance(target, dict) else scalar(target))
            if "steps" in value:
                if not isinstance(value["steps"], list):
                    raise ValueError("Invalid nested steps")
                result["steps"] = [step(child, depth + 1) for child in value["steps"]]
            return result

        try:
            canonical = {"steps": [step(s) for s in doc["steps"]]}
            if "duration" in doc:
                canonical["duration"] = scalar(doc["duration"])
            return self._structure_fingerprint(canonical)
        except (ValueError, RecursionError):
            return None

    def _structure_ftp_basis(self, act):
        """Ride-specific FTP, then same-environment history at the local date."""
        ftp = act.get("icu_ftp")
        if self._structure_number(ftp) and ftp > 0:
            return {"source": "activity.icu_ftp", "ftp": ftp}
        indoor = self._fact_indoor(act)
        date = self._fact_date(act.get("start_date_local"))
        if indoor is not None and date and getattr(self, "data_dir", None) is not None:
            environment = "indoor" if indoor else "outdoor"
            history = self._load_ftp_history()
            entries = history.get(environment) if isinstance(history, dict) else None
            if isinstance(entries, dict):
                eligible = [d for d, value in entries.items()
                            if self._fact_date(d) == d and d <= date
                            and self._structure_number(value) and value > 0]
                if eligible:
                    at = max(eligible)
                    return {"source": "ftp_history", "ftp": entries[at],
                            "environment": environment, "date": at}
        return {"source": "intervals_resolved"}

    def _structure_plan(self, act, event, reason=None):
        """Normalize paired intent for computation; never emit raw definitions."""
        plan = {"status": reason or ("unknown" if act.get("paired_event_id") is not None
                                    else "no_plan"), "steps": []}
        if reason or not isinstance(event, dict):
            return plan
        if (str(event.get("id")) != str(act.get("paired_event_id"))
                or act.get("paired_event_id") is None
                or (event.get("paired_activity_id") is not None
                    and str(event["paired_activity_id"]) != str(act.get("id")))
                or (event.get("athlete_id") is not None and act.get("athlete_id") is not None
                    and str(event["athlete_id"]) != str(act["athlete_id"]))):
            plan["status"] = "pairing_conflict"
            return plan
        plan["reference"] = {"event_id": str(event["id"])[:80],
                             "updated": str(event.get("updated") or "")[:80] or None}
        doc = event.get("workout_doc")
        if isinstance(event.get("name"), str):
            plan["reference"]["name"] = event["name"]
        duration, source = event.get("moving_time"), "moving_time"
        if not (self._structure_number(duration) and 0 <= duration <= 604800):
            duration = doc.get("duration") if isinstance(doc, dict) else None
            source = "workout_doc.duration"
        if self._structure_number(duration) and 0 <= duration <= 604800:
            plan["reference"].update(duration_s=duration, duration_source=source)
        if not isinstance(doc, dict) or not isinstance(doc.get("steps"), list):
            plan["status"] = "missing_steps"
            return plan
        steps = doc["steps"]
        plan["status"] = "steps_present" if steps else "no_steps"
        # Bound input work independently of the output cap, which counts sets.
        for step in steps[:10000]:
            entry = {"supported": False}
            if isinstance(step, dict):
                duration = step.get("duration")
                prescribed = step.get("power")
                target = prescribed
                if (isinstance(prescribed, dict)
                        and prescribed.get("units") not in self.SUMMARY_WATT_UNITS):
                    target = step.get("_power")
                    if str(prescribed.get("units", "")).lower() in self.STRUCTURE_FTP_UNITS:
                        if "power_target_basis" not in plan:
                            basis = self._structure_ftp_basis(act)
                            resolved_ftp = doc.get("ftp")
                            if ("ftp" in basis and self._structure_number(resolved_ftp)
                                    and resolved_ftp > 0 and resolved_ftp != basis["ftp"]):
                                basis["plan_ftp"] = resolved_ftp
                            plan["power_target_basis"] = basis
                        ftp = plan["power_target_basis"].get("ftp")
                        if ftp is not None:
                            # Preserve own ranges; resolved start/end is only a band.
                            target = {k: prescribed[k] * ftp / 100
                                      if self._structure_number(prescribed[k]) else None
                                      for k in ("value", "min", "max") if k in prescribed}
                            target["units"] = "w"
                allowed = {"duration", "power", "_power", "hr", "_hr", "cadence", "_cadence",
                           "text", "description", "role", "ramp"}
                if self._structure_number(duration) and 1 <= duration <= 604800:
                    entry["duration_s"] = duration
                if isinstance(target, dict):
                    units = target.get("units")
                    absolute = (units in self.SUMMARY_WATT_UNITS
                                or (target is step.get("_power") and units is None))
                    low = high = target.get("value")
                    if (step.get("ramp") or (isinstance(prescribed, dict)
                            and ("start" in prescribed or "end" in prescribed
                                 or prescribed.get("ramp")))):
                        absolute = False
                    elif "min" in target or "max" in target:
                        low, high = target.get("min"), target.get("max")
                    if (absolute and self._structure_number(low) and self._structure_number(high)
                            and 0 <= low <= high <= 3000):
                        entry["target_w"] = low if low == high else [low, high]
                if set(step) <= allowed and "duration_s" in entry and "target_w" in entry:
                    entry.pop("supported")
            plan["steps"].append(entry)
        if any(s.get("supported") is False for s in plan["steps"]):
            plan["status"] = "unsupported_steps"
        elif steps:
            total = sum(s["duration_s"] for s in plan["steps"])
            if not self._structure_number(doc.get("duration")) or abs(total - doc["duration"]) > 1:
                plan["status"] = "plan_total_mismatch"
        plan["profile"] = plan["steps"]
        plan["steps"] = self._structure_sets(plan["steps"])
        omitted = max(0, len(plan["steps"]) - self.STRUCTURE_MAX_STEPS) + max(0, len(steps) - 10000)
        if omitted:
            plan.update(status="truncated", omitted_steps=omitted)
            plan["steps"] = plan["steps"][:self.STRUCTURE_MAX_STEPS]
        return plan

    def _structure_sets(self, steps):
        """Reuse the summary detector; compress exact short-recovery patterns only.

        Long recoveries remain ordinary steps. Approximate summary compression is
        insufficient for numeric comparison, so durations and targets must agree
        exactly within each side of a set. No raw atoms are discarded on failure.
        """
        data = [(s.get("duration_s"), s.get("target_w"))
                if s.get("supported") is not False and not isinstance(s.get("target_w"), list)
                else (None, None) for s in steps]
        result, i = [], 0
        while i < len(steps):
            block = self._try_alternating_block(data, i)
            if block:
                count, wd, wp, rd, rp, pairs, tail, trailing = block
                # Keep a differing/long tail outside the set. A last work bout
                # immediately before it still belongs to this set.
                if tail is not None:
                    # The summary detector may also see the next set's first
                    # work bout as trailing. Stop before the long recovery.
                    count, trailing = pairs, False
                consumed = pairs * 2 + int(trailing) - int(tail is not None)
                selected = data[i:i + consumed]
                if (count >= 3 and rd < 60
                        and all(v == data[i + j % 2] for j, v in enumerate(selected))):
                    result.append({"duration_s": sum(d for d, _ in selected),
                                   "target_w": steps[i]["target_w"],
                                   "repeat": [count, wd, rd]})
                    i += consumed
                    continue
            result.append(steps[i])
            i += 1
        return result

    def _structure_streams(self, act, streams):
        """Elapsed horizon, no gap filling, no extrapolated final sample."""
        number = self._structure_number
        horizon = act.get("elapsed_time")
        times = streams.get("time") if isinstance(streams, dict) else None
        reason = None
        if (not isinstance(times, list) or len(times) < 2 or len(times) > 1000000
                or any(not number(t) or t < 0 for t in times)
                or any(b <= a for a, b in zip(times, times[1:]))):
            times, reason = [], "missing_or_invalid_time"
        if not number(horizon) or not 0 < horizon <= 604800:
            horizon = times[-1] if times and 0 < times[-1] <= 604800 else 0
            reason = reason or "activity_elapsed_unavailable"
        if times and times[-1] > horizon + 1:
            times, reason = [], "stream_exceeds_elapsed"
        values = {}
        for field in ("watts", "heartrate", "cadence"):
            value = streams.get(field) if isinstance(streams, dict) else None
            values[field] = value if isinstance(value, list) and len(value) == len(times) else []
        return horizon, times, values, reason

    def _structure_offset(self, steps, times, watts, shift, horizon):
        """One bounded recording-time alignment, using the entire target profile."""
        def error(offset):
            index, end = 0, shift + offset + steps[0]["duration_s"]
            squared, observed = 0.0, 0.0
            for i, t in enumerate(times[:-1]):
                a, b = max(t, shift + offset), min(t + 1, times[i + 1], horizon)
                value = watts[i]
                if not self._structure_number(value) or value < 0:
                    continue
                while a < b:
                    while index < len(steps) and a >= end:
                        index += 1
                        if index < len(steps):
                            end += steps[index]["duration_s"]
                    if index == len(steps):
                        break
                    target = steps[index]["target_w"]
                    if isinstance(target, list):
                        target = sum(target) / 2
                    dt = min(b, end) - a
                    squared += (value - target) ** 2 * dt
                    observed += dt
                    a += dt
            return squared / observed if observed else float("inf")
        # min preserves the smallest integer offset on exact ties.
        return min(range(9), key=error)

    def _structure_window(self, start, end, times, values, precise=False, windows=None):
        windows = windows if windows is not None else [(start, end)]
        span = sum(b - a for a, b in windows)
        sums, durations = [0.0] * 3, [0.0] * 3
        zero = 0.0
        first = 0
        for i in range(len(times) - 1):
            t = times[i]
            if t >= end:
                break
            while first < len(windows) and windows[first][1] <= t:
                first += 1
            dt, j = 0, first
            sample_end = min(t + 1, times[i + 1])
            while j < len(windows) and windows[j][0] < sample_end:
                a, b = windows[j]
                dt += max(0, min(b, sample_end) - max(a, t))
                j += 1
            if not dt:
                continue
            for j, key in enumerate(("watts", "heartrate", "cadence")):
                v = values[key][i] if values[key] else None
                if self._structure_number(v) and (v > 0 if key == "heartrate" else v >= 0):
                    sums[j] += v * dt
                    durations[j] += dt
                    if j == 0 and v == 0:
                        zero += dt
        means = [(s / d if precise else round(s / d, 1)) if d else None
                 for s, d in zip(sums, durations)]
        coverage = [(100 * d / span if precise else round(100 * d / span, 2)) if span > 0 else 0
                    for d in durations]
        return [start, end, means[0], round(sums[0] / 1000, 1) if durations[0] else None,
                means[1], means[2], *coverage,
                round(100 * zero / durations[0], 2) if durations[0] else None]

    def _structure_bouts(self, windows, times, watts):
        """Exact completion/adherence evidence in one monotone sample pass.

        Windows are ordered, non-overlapping bouts/steps on recording time.
        Standard bounds retain the one-second exclusion; the caller selects
        adherence bounds by prescribed duration before clipping. Schema is in
        SECTION_11; no rounding, gap filling or final-sample extrapolation.
        """
        rows, i = [], 0
        for nominal, start, end, adherence_start, adherence_end in windows:
            observed, adherence_observed, joules, zero = 0.0, 0.0, 0.0, 0.0
            while i + 1 < len(times) and times[i + 1] <= start:
                i += 1
            while i + 1 < len(times) and times[i] < end:
                t = times[i]
                sample_end = min(t + 1, times[i + 1], end)
                value = watts[i]
                if self._structure_number(value) and value >= 0:
                    observed += max(0, sample_end - max(t, start))
                    dt = max(0, min(sample_end, adherence_end) - max(t, adherence_start))
                    adherence_observed += dt
                    joules += value * dt
                    if value == 0:
                        zero += dt
                if times[i + 1] > end:
                    break
                i += 1
            rows.append([nominal, start, end, observed, adherence_start,
                         adherence_observed, joules if adherence_observed else None,
                         zero if adherence_observed else None])
        return rows

    def _structure_sprints(self, windows, times, watts, source_times):
        """Observed standard means and best contiguous W-second means, unrounded.

        Piecewise-constant sample support matches standard windows. A peak
        cannot bridge missing power or an original recording-stop gap, even
        though plan alignment compresses the latter out of recording time.
        """
        from bisect import bisect_right

        rows, i = [], 0
        for start, end, width in windows:
            runs, observed, joules = [], 0.0, 0.0
            while i + 1 < len(times) and times[i + 1] <= start:
                i += 1
            while i + 1 < len(times) and times[i] < end:
                a, b = max(times[i], start), min(times[i] + 1, times[i + 1], end)
                value = watts[i]
                if b > a and self._structure_number(value) and value >= 0:
                    observed += b - a
                    joules += value * (b - a)
                    if (not runs or runs[-1][-1][1] != a
                            or (i and source_times[i] - source_times[i - 1] > 1)):
                        runs.append([])
                    runs[-1].append((a, b, value))
                if times[i + 1] > end:
                    break
                i += 1
            best_start, best_j = None, None
            for run in runs:
                if run[-1][1] - run[0][0] < width:
                    continue
                edges = [run[0][0]] + [b for _, b, _ in run]
                prefix = [0.0]
                for a, b, value in run:
                    prefix.append(prefix[-1] + value * (b - a))

                def integral(t):
                    j = bisect_right(edges, t) - 1
                    return prefix[j] + (run[j][2] * (t - edges[j]) if j < len(run) else 0)

                # A sliding integral changes slope only at a support boundary
                # or W seconds before one. Include both, also for fractional
                # timestamp spacing, rather than counting samples.
                starts = sorted({t for t in edges if t + width <= edges[-1]}
                                | {t - width for t in edges if t - width >= edges[0]})
                for at in starts:
                    energy = integral(at + width) - integral(at)
                    if best_j is None or energy > best_j:
                        best_start, best_j = at, energy
            rows.append([joules / observed if observed else None, best_start,
                         best_j / width if best_j is not None else None])
        return rows

    def _build_session_structure(self, act, event, streams, raw_intervals=None,
                                 plan_reason=None):
        if act.get("type") in ("Walk", "Hike"):
            return None
        plan = self._structure_plan(act, event)
        horizon, times, values, timing_reason = self._structure_streams(act, streams)
        window = lambda a, b: self._structure_window(a, b, times, values)
        out = {"version": self.STRUCTURE_VERSION, "method": "fixed_elapsed_thirds",
               "status": "unknown"}
        if "reference" in plan:
            out["plan"] = plan["reference"]
        if "power_target_basis" in plan:
            out["power_target_basis"] = plan["power_target_basis"]
        if plan["steps"]:
            out["steps"] = plan["steps"]
        if plan.get("omitted_steps"):
            out["omitted_steps"] = plan["omitted_steps"]
        issues = []
        shift = act.get("workout_shift_secs")
        if plan_reason:
            issues.append(plan_reason)
        elif plan["status"] in ("no_plan", "no_steps"):
            out["status"] = plan["status"]
        elif plan["status"] != "steps_present":
            issues.append(plan["status"])
        elif shift is not None and (not self._structure_number(shift) or abs(shift) > 604800):
            issues.append("invalid_workout_shift")
        elif timing_reason or not values["watts"]:
            issues.append(timing_reason or "missing_power")
        else:
            # Time-stream gaps are unrecorded time. Compress only those gaps;
            # null watts and real zero-power samples retain their recording time.
            removed, recorded = 0, [times[0]]
            for before, after in zip(times, times[1:]):
                removed += max(0, after - before - 1)
                recorded.append(after - removed)
            plan_horizon = horizon - removed
            plan_window = lambda a, b, ranges=None, precise=False: self._structure_window(
                a, b, recorded, values, precise=precise, windows=ranges)
            offset = self._structure_offset(plan["profile"], recorded, values["watts"],
                                            shift or 0, plan_horizon)
            if offset:
                out["offset_s"] = offset
            cursor = (shift or 0) + offset
            total = sum(s["duration_s"] for s in plan["steps"])
            # The offset models power-response lag, not extra prescribed riding.
            # Judge ride duration on the original workout timer; clip lagged
            # measurements at the recording end and expose their fraction.
            delta = plan_horizon - ((shift or 0) + total)
            results, agrees, disagrees, low_coverage = [], 0, 0, False
            bout_windows, evidence_steps = [], []
            sprint_windows, sprint_steps = [], []
            incomplete = False
            for step in plan["steps"]:
                end = cursor + step["duration_s"]
                clip = lambda t: max(0, min(t, plan_horizon))
                a, b = clip(min(cursor + 1, end)), clip(end)
                ranges = [(a, b)]
                planned_work = step["duration_s"] - 1
                if "repeat" in step:
                    reps, work, rest = step["repeat"]
                    ranges = [(clip(cursor + n * (work + rest) + 1),
                               clip(cursor + n * (work + rest) + work)) for n in range(reps)]
                    planned_work = reps * (work - 1)
                row = plan_window(a, b, ranges)
                exact = plan_window(a, b, ranges, precise=True)
                work_span = sum(y - x for x, y in ranges)
                fraction = work_span / planned_work if planned_work else 0
                adequate = work_span > 0 and exact[6] >= 95
                low_coverage |= work_span > 0 and not adequate
                incomplete |= clip(end - offset) - clip(cursor - offset) < step["duration_s"]
                target = step["target_w"]
                low, high = target if isinstance(target, list) else (target * .95, target * 1.05)
                agreement = low <= exact[2] <= high if adequate else None
                agrees += agreement is True
                disagrees += agreement is False
                result = {"target_w": target, "duration_s": step["duration_s"],
                          "actual": row, "match": agreement}
                if "repeat" in step:
                    result.update(repeat=step["repeat"], work_s=work_span)
                    evidence_steps.append((result, len(bout_windows), reps, True))
                    for n, (start, stop) in enumerate(ranges):
                        aligned = cursor + n * (work + rest)
                        # Exclude the prescribed trailing second before clipping,
                        # never another observed second from a shortened window.
                        bout_windows.append((aligned - offset, start, stop,
                                             clip(min(aligned + (2 if work <= 60 else 1),
                                                      aligned + work)),
                                             clip(aligned + work - (1 if 20 < work <= 60 else 0))))
                elif step["duration_s"] <= 60:
                    evidence_steps.append((result, len(bout_windows), 1, False))
                    bout_windows.append((cursor - offset, a, b, clip(min(cursor + 2, end)),
                                         clip(end - (1 if step["duration_s"] > 20 else 0))))
                sprint_duration = work if "repeat" in step else step["duration_s"]
                if sprint_duration <= 20:
                    width = max(3, math.ceil(.30 * sprint_duration))
                    sprint_steps.append((result, len(sprint_windows), len(ranges), width))
                    sprint_windows.extend((start, stop, width) for start, stop in ranges)
                if not adequate:
                    for index in (2, 3, 4, 5, 9):
                        row[index] = None
                if fraction < 1:
                    result.update(duration_s=step["duration_s"], observed_window_fraction=round(fraction, 4))
                results.append(result)
                cursor = end
            duration_off = abs(delta) > max(total * .05, 300)
            if (duration_off and abs(delta) > total * .5) or disagrees > (agrees + disagrees) / 2:
                out["status"] = "not_followed"
                issues.append("gross_duration_difference" if duration_off and abs(delta) > total * .5 else "most_steps_disagree")
            elif agrees == len(results) and not duration_off:
                out["status"] = "followed"
            else:
                out["status"] = "partly_followed"
                issues.append("insufficient_power_coverage" if low_coverage or not agrees + disagrees
                              else "shortened_or_extended" if duration_off
                              else "some_steps_disagree")
            if out["status"] in ("followed", "partly_followed"):
                # The marker also identifies checked long-only blocks, so old
                # version-5 caches cannot conceal missing step/sprint evidence.
                out.update(method="paired_plan_windows", steps=results, bout_metrics_version=4)
                if bout_windows:
                    bouts = self._structure_bouts(bout_windows, recorded, values["watts"])
                    for result, first, count, is_set in evidence_steps:
                        if is_set:
                            result["bouts"] = bouts[first:first + count]
                        else:
                            result["adherence"] = bouts[first][4:]
                if sprint_windows:
                    sprints = self._structure_sprints(sprint_windows, recorded, values["watts"], times)
                    for result, first, count, width in sprint_steps:
                        target = result["target_w"]
                        result["sprint_target_w"] = target[0] if isinstance(target, list) else target
                        result["sprint_window_s"] = width
                        if "repeat" in result:
                            result["sprints"] = sprints[first:first + count]
                        else:
                            result["sprint"] = sprints[first]
                if shift:
                    out["shift_s"] = shift
                unassigned = []
                if (shift or 0) + offset > 0:
                    unassigned.append(plan_window(0, min((shift or 0) + offset, plan_horizon)))
                if delta > 30:
                    unassigned.append(plan_window(max(0, cursor), plan_horizon))
                if unassigned:
                    out["unassigned"] = unassigned
        if out["method"] == "fixed_elapsed_thirds":
            edges = [0, math.floor(horizon / 3), math.floor(2 * horizon / 3), horizon]
            out["thirds"] = [window(a, b) for a, b in zip(edges, edges[1:])]
            if timing_reason and timing_reason not in issues:
                issues.append(timing_reason)
            efforts, omitted = [], 0
            if isinstance(raw_intervals, list):
                for iv in raw_intervals:
                    if not isinstance(iv, dict) or iv.get("type") != "WORK":
                        continue
                    a = iv.get("start_time", iv.get("start_secs"))
                    b = iv.get("end_time", iv.get("end_secs"))
                    if not (self._structure_number(a) and self._structure_number(b) and 0 <= a < b <= horizon + 1):
                        if "efforts_partial" not in issues:
                            issues.append("efforts_partial")
                        continue
                    if len(efforts) == self.STRUCTURE_MAX_EFFORTS:
                        omitted += 1
                        continue
                    metrics = [iv.get(raw, iv.get(formatted)) for raw, formatted in
                               (("average_watts", "avg_power"), ("average_heartrate", "avg_hr"),
                                ("average_cadence", "avg_cadence"))]
                    efforts.append([a, b] + [v if self._structure_number(v) and v >= 0 else None
                                             for v in metrics])
                if efforts:
                    out["efforts"] = efforts
                if omitted:
                    out["omitted_efforts"] = omitted
            else:
                issues.append("efforts_unavailable")
        if issues:
            out["issues"] = issues
        return out

    @staticmethod
    def _activity_plan_match(activity):
        """Read current exports and pre-migration persisted inputs."""
        block = activity.get("interval_data")
        if isinstance(block, dict):
            summary = block.get("plan_match")
            return summary if isinstance(summary, dict) else None
        summary = activity.get("structure_summary")
        return summary if isinstance(summary, dict) else None

    def _compact_step_evidence(self, step, index, nominal, offset):
        """One compact power/time row; no role selection or new measurements."""
        number = self._structure_number
        target = step.get("target_w")
        bounds = target if isinstance(target, list) else [target, target]
        valid_target = (len(bounds) == 2 and all(number(v) and v >= 0 for v in bounds)
                        and bounds[0] <= bounds[1])
        repeat = step.get("repeat")
        duration = repeat[1] if isinstance(repeat, list) and len(repeat) == 3 else step.get("duration_s")
        duration = duration if number(duration) and duration > 0 else None
        evaluator = (None if duration is None else "sprint" if duration <= 20 else
                     "short_avg" if duration <= 60 else "long_avg")
        count = repeat[0] if isinstance(repeat, list) and len(repeat) == 3 else 1
        row = [index, target if valid_target else None, duration, evaluator,
               None, None, count if type(count) is int and count > 0 else None, False]
        # Sets are populated by the existing precise per-bout evaluator below.
        if repeat is not None or not valid_target or duration is None or not number(nominal):
            return row
        try:
            actual = step["actual"]
            if len(actual) != 10:
                return row
            start, end, mean, coverage = actual[0], actual[1], actual[2], actual[6]
            if (not all(number(v) for v in (start, end, coverage))
                    or not 0 <= start <= end or not 0 <= coverage <= 100
                    or end > max(0, nominal + offset + duration)
                    or start != min(end, max(0, nominal + offset + min(1, duration)))):
                return row
            # The stored coverage is rounded to two decimal places. A rounded
            # boundary alone cannot establish the >=95% standard-window floor.
            row[4] = (None if nominal < 0 or end <= start else
                      False if duration - 1 - (end - start) > offset else
                      True if coverage - .005 >= 95 and number(mean) and mean >= 0 else None)
            power = None
            if evaluator == "sprint":
                width = max(3, math.ceil(.30 * duration))
                if step.get("sprint_window_s") != width or step.get("sprint_target_w") != bounds[0]:
                    return row
                _, at, peak = step["sprint"]
                if (number(at) and number(peak) and peak >= 0
                        and start <= at <= end - width):
                    power = peak >= bounds[0]
            else:
                low = bounds[0] - max(3, bounds[0] * .01)
                high = bounds[1] + max(3, bounds[1] * .05)
                if evaluator == "short_avg":
                    astart, observed, joules, zero = step["adherence"]
                    aend = min(end, max(0, nominal + offset + duration - 1))
                    if (not all(number(v) for v in (astart, observed))
                            or astart != min(end, max(0, nominal + offset + min(2, duration)))
                            or not 0 <= observed <= max(0, aend - astart)):
                        return row
                    if (observed > 0 and aend > astart and observed / (aend - astart) >= .95
                            and number(joules) and joules >= 0 and number(zero) and 0 <= zero <= observed):
                        power = low <= joules / observed <= high
                elif number(mean) and mean >= 0:
                    # Existing long-step means are rounded to one decimal.
                    # Every value in that rounding interval must agree.
                    if mean - .05 >= low and mean + .05 <= high:
                        power = True
                    elif mean + .05 < low or mean - .05 > high:
                        power = False
            if row[4] is True and power is not None:
                row[5], row[7] = int(power), True
        except (KeyError, TypeError, ValueError, IndexError, ZeroDivisionError):
            pass
        return row

    def _compact_compliance(self, block, pairing):
        """Bounded power/time evidence, never inferred roles or secondary constraints.

        Per-step evidence includes all power steps without selecting main work.
        The aggregate remains restricted to the existing compressed work sets.
        Context review remains mandatory even when every counted step passes.
        """
        result = {"status": "unavailable", "scope": "compressed_work_bouts",
                  "completion": None, "on_target": None, "total": None,
                  "sets": [], "steps": [], "adherence_available": False}
        reason = "detail_unavailable"
        if block:
            reason = "unqualified_detail"
            cache = block.get("cache") or {}
            identity_ok = (pairing.get("paired")
                           and pairing.get("status") not in ("ambiguous_pairing", "pairing_conflict")
                           and (block.get("plan") or {}).get("event_id") == (pairing.get("plan") or {}).get("event_id")
                           and cache.get("plan_key_version") == self.PLAN_KEY_VERSION
                           and pairing.get("definition_key_version") == self.PLAN_KEY_VERSION
                           and cache.get("plan_key") is not None
                           and cache.get("plan_key") == pairing.get("definition_key"))
            if (block.get("version") == self.STRUCTURE_VERSION
                    and block.get("bout_metrics_version") == 4
                    and block.get("method") == "paired_plan_windows"
                    and block.get("status") in ("followed", "partly_followed")
                    and cache.get("status") not in ("stale", "unavailable") and identity_ok):
                reason = "main_work_selection_required"
                patterns, completion = set(), []
                offset = block.get("offset_s", 0)
                number = self._structure_number
                if not number(offset) or not 0 <= offset <= 8:
                    result["reason"] = "invalid_evidence"
                    return result
                nominal = block.get("shift_s", 0)
                per_step = {}
                for index, step in enumerate(block.get("steps", [])):
                    if "target_w" in step:
                        row = self._compact_step_evidence(step, index + 1, nominal, offset)
                        result["steps"].append(row)
                        per_step[index] = row
                    duration = step.get("duration_s")
                    nominal = nominal + duration if number(nominal) and number(duration) and duration > 0 else None
                for index, step in enumerate(block.get("steps", [])):
                    if "repeat" not in step:
                        continue
                    try:
                        count, duration, rest = step["repeat"]
                        rows = step["bouts"]
                        target = step["target_w"]
                        if (not isinstance(count, int) or isinstance(count, bool) or count < 3
                                or not all(number(v) for v in (duration, rest, target))
                                or duration <= 0 or not 0 <= rest < 60 or target < 0
                                or len(rows) != count):
                            raise ValueError
                        times, powers = [], []
                        first = rows[0][0]
                        for n, row in enumerate(rows):
                            nominal, start, end, observed, astart, aobs, joules, zero = row
                            if (not all(number(v) for v in row[:6])
                                    or nominal != first + n * (duration + rest)
                                    or not 0 <= start <= astart <= end
                                    or not 0 <= observed <= end - start
                                    or start != min(end, max(0, nominal + offset + 1))
                                    or astart != min(end, max(0, nominal + offset + min(2 if duration <= 60 else 1, duration)))
                                    or end > max(0, nominal + offset + duration)):
                                raise ValueError
                            aend = min(end, max(0, nominal + offset + duration - (1 if 20 < duration <= 60 else 0)))
                            if (not 0 <= aobs <= max(0, aend - astart)
                                    or aobs > observed or aobs and (
                                        not number(joules) or joules < 0
                                        or not number(zero) or not 0 <= zero <= aobs)
                                    or not aobs and (joules is not None or zero is not None)):
                                raise ValueError
                            time_ok = (None if nominal < 0 or end <= start else
                                       False if duration - 1 - (end - start) > offset else
                                       True if observed / (end - start) >= .95 else None)
                            times.append(time_ok)
                            if duration <= 20:
                                sprints = step.get("sprints", [])
                                if (len(sprints) != count or step.get("sprint_window_s") != max(3, math.ceil(.30 * duration))
                                        or step.get("sprint_target_w") != target):
                                    raise ValueError
                                _, at, peak = sprints[n]
                                if at is None or peak is None:
                                    powers.append(None)
                                elif (number(at) and number(peak) and peak >= 0
                                      and start <= at <= end - step["sprint_window_s"]):
                                    powers.append(peak >= target)
                                else:
                                    raise ValueError
                            else:
                                powers.append(target - max(3, target * .01) <= joules / aobs <= target + max(3, target * .05)
                                              if aend > astart and aobs / (aend - astart) >= .95 else None)
                        complete = False if False in times else None if None in times else True
                        on_target = sum(powers) if complete is True and None not in powers else None
                        result["sets"].append({"step": index + 1, "completion": complete,
                                               "on_target": on_target, "total": count})
                        per_step[index][4:] = [complete, on_target, count, on_target is not None]
                        completion.append(complete)
                        patterns.add((duration, rest))
                    except (KeyError, TypeError, ValueError, IndexError, ZeroDivisionError):
                        result.update(sets=[], reason="invalid_evidence")
                        return result
                if completion:
                    result["completion"] = False if False in completion else None if None in completion else True
                    result["total"] = sum(s["total"] for s in result["sets"])
                    if len(patterns) != 1:
                        reason = "mixed_patterns"
                    elif any(s["on_target"] is None for s in result["sets"]):
                        reason = "incomplete_or_missing_evidence"
                    else:
                        result.update(status="context_required", on_target=sum(s["on_target"] for s in result["sets"]))
                        reason = "main_work_and_constraints_require_review"
                if result["steps"]:
                    if result["status"] == "unavailable":
                        result["aggregate_reason"] = ("no_compressed_sets" if reason == "main_work_selection_required" else reason)
                    result["status"] = "context_required"
                    reason = "ai_selects_main_work_from_authoritative_prescription_and_reviews_constraints"
        result["reason"] = reason
        return result

    @staticmethod
    def _structure_summary(block):
        """Small, self-contained comparison data that can outlive interval detail."""
        summary = {"method": "plan_match_v2", "status": block["status"]}
        if block.get("plan"):
            summary["plan"] = dict(block["plan"])
        if block.get("steps"):
            rows = []
            for step in block["steps"]:
                actual = step.get("actual")
                duration = actual[1] - actual[0] if actual else step.get("duration_s")
                if "repeat" in step:
                    duration = step.get("work_s", step["repeat"][0] * step["repeat"][1])
                rows.append([duration, step.get("target_w"),
                             actual[2] if actual else None, step.get("match")])
                if "repeat" in step:
                    rows[-1].append(step["repeat"])
            summary["steps"] = rows
        if block.get("issues"):
            summary["issues"] = block["issues"][:]
        if block.get("omitted_steps"):
            summary["omitted_steps"] = block["omitted_steps"]
        return summary

    def _prepare_session_structures(self, activities, events, previous_lookup, now=None):
        """Full blocks persist in intervals.json; expired summaries need no fetch."""
        now = now or datetime.now(timezone.utc)
        cutoff = (now.astimezone() - timedelta(days=self.INTERVAL_RETENTION_DAYS)).strftime("%Y-%m-%d")
        event_map = defaultdict(list)
        for event in events or []:
            if isinstance(event, dict) and event.get("id") is not None:
                event_map[str(event["id"])].append(event)
        entries = self._intervals_data.setdefault("activities", [])
        interval_map = {str(e.get("activity_id")): e for e in entries}
        result = {}
        for act in activities:
            if act.get("type") in ("Walk", "Hike"):
                entry = interval_map.get(str(act.get("id")))
                if entry:
                    entry.pop("session_structure", None)
                continue
            date = act.get("start_date_local", "")[:10]
            if not date or date < cutoff:
                continue
            aid = str(act.get("id"))
            paired = act.get("paired_event_id")
            matches = event_map.get(str(paired), []) if paired is not None else []
            event = matches[0] if len(matches) == 1 else None
            entry = interval_map.get(aid) or {}
            old = entry.get("session_structure") or {}
            cache = old.get("cache") or {}
            old_basis = old.get("power_target_basis")
            basis = self._structure_ftp_basis(act) if old_basis else None
            basis_matches = not old_basis or {k: v for k, v in old_basis.items()
                                              if k != "plan_ftp"} == basis
            activity_key = self._structure_fingerprint({k: act.get(k) for k in
                ("id", "paired_event_id", "start_date", "elapsed_time", "moving_time", "icu_sync_date",
                 "icu_intervals_edited", "icu_average_watts", "icu_joules", "workout_shift_secs",
                 "icu_intervals", "recording_stops", "icu_recording_time", "type")})
            event_key = self._structure_fingerprint(matches) if matches else None
            due = self._structure_date(cache.get("next_refresh_at"))
            if (old.get("version") == self.STRUCTURE_VERSION and cache.get("activity_key") == activity_key
                    and cache.get("plan_key_version") == self.PLAN_KEY_VERSION and basis_matches
                and (old.get("method") != "paired_plan_windows" or old.get("bout_metrics_version") == 4)
                    and (old.get("method") != "paired_plan_windows"
                         or all(self._structure_number(s.get("duration_s")) and s["duration_s"] > 0
                                for s in old.get("steps", [])))
                    and cache.get("event_key") == event_key and due and now < due):
                result[aid] = old
                if cache.get("status") not in ("stale", "unavailable") and old.get("status") not in ("unavailable", "unknown"):
                    self._adopt_native_cache("activity_details", aid, True)
                    self._adopt_native_cache("activity_streams", aid, True)
                continue
            reason, failures, retry_after = None, [], 0
            if len(matches) > 1:
                reason = "ambiguous_pairing"
            elif paired is not None and event is None:
                try:
                    event = self._intervals_get(f"events/{paired}", {"resolve": "true"})
                    if not isinstance(event, dict) or str(event.get("id")) != str(paired):
                        reason = "paired_event_unavailable"
                except (requests.exceptions.RequestException, ValueError) as exc:
                    reason = "paired_event_unavailable"
                    response = getattr(exc, "response", None)
                    if response is not None and response.status_code == 429:
                        retry_after = self._parse_retry_after(response.headers.get("Retry-After")) or 0
                if reason:
                    failures.append(reason)
            plan_key = self._plan_definition_key(event.get("workout_doc")) if isinstance(event, dict) else None
            status, streams = self._fetch_activity_streams(aid, ["time", "watts", "heartrate", "cadence"])
            if status == "deferred":
                if old:
                    result[aid] = old
                continue
            retry_after = max(retry_after, getattr(self, "_last_retry_after_secs", None) or 0)
            if status != "ok":
                streams = {}
                failures.append("streams_" + status)
            raw = act.get("icu_intervals")
            cached_efforts = False
            if not isinstance(raw, list):
                raw = entry.get("intervals")
                cached_efforts = isinstance(raw, list)
            block = self._build_session_structure(act, event, streams, raw, reason)
            if block["method"] == "fixed_elapsed_thirds" and not isinstance(raw, list):
                iv_status, payload = self._fetch_activity_intervals(aid)
                retry_after = max(retry_after, getattr(self, "_last_retry_after_secs", None) or 0)
                raw = payload if iv_status in ("ok", "no_data") else None
                if raw is None:
                    failures.append("efforts_" + iv_status)
                block = self._build_session_structure(act, event, streams, raw, reason)
            if cached_efforts and block.get("efforts"):
                block.setdefault("issues", []).append("efforts_from_interval_cache")
            if failures:
                block = self._build_session_structure(act, event, streams, raw, failures[0])
                block["issues"] = list(dict.fromkeys(block.get("issues", []) + failures))
                if status != "ok" and old.get("thirds"):
                    block["thirds"] = old["thirds"]
                if ("paired_event_unavailable" in failures
                        and (old.get("plan") or {}).get("event_id") == str(paired)):
                    block["plan"] = dict(old["plan"])
                    if old.get("steps"):
                        block["steps"] = []
                        for step in old["steps"]:
                            retained = {k: step[k] for k in ("duration_s", "target_w", "supported", "repeat") if k in step}
                            if "duration_s" not in retained and step.get("actual"):
                                retained["duration_s"] = (step["actual"][1] - step["actual"][0]
                                                          + (1 if old.get("version", 1) >= 2 else 0))
                            block["steps"].append(retained)
                    if old.get("omitted_steps"):
                        block["omitted_steps"] = old["omitted_steps"]
                if cached_efforts and block.get("efforts"):
                    block["issues"].append("efforts_from_interval_cache")
            attempts = min(3, int(cache.get("failures", 0)) + 1) if failures else 0
            delay = max((3600, 21600, 86400)[attempts - 1], retry_after) if failures else 86400
            block["cache"] = {"activity_key": activity_key, "event_key": event_key,
                              "plan_key": plan_key or (cache.get("plan_key")
                                  if cache.get("plan_key_version") == self.PLAN_KEY_VERSION else None),
                              "plan_key_version": self.PLAN_KEY_VERSION,
                              "sampled_at": cache.get("sampled_at") if status != "ok" else now.isoformat(),
                              "next_refresh_at": (now + timedelta(seconds=delay)).isoformat()}
            if failures:
                block["cache"].update(status="stale" if old else "unavailable", failures=attempts)
            if not entry:
                entry = {"activity_id": act.get("id"), "date": date,
                         "start_datetime": act.get("start_date_local", ""),
                         "type": act.get("type", "Unknown"), "name": act.get("name", ""),
                         "interval_summary": act.get("interval_summary"), "intervals": []}
                entries.append(entry)
                interval_map[aid] = entry
            entry["session_structure"] = block
            result[aid] = block
        return result

    def _format_activities(self, activities: List[Dict], interval_activity_ids: set = None,
                           temp_unit: str = "C", wind_unit: str = "MPS",
                           speed_unit: str = "KPH",
                           previous_latest_lookup: Optional[Dict[str, Dict]] = None,
                           athlete_units: Optional[Dict[str, str]] = None,
                           paired_events: Optional[List[Dict]] = None) -> List[Dict]:
        """Format activities for LLM analysis.
        
        Unit kwargs default to metric for backward compatibility with any caller
        not yet passing them; collect_training_data passes the athlete's actual
        account preferences (or KPH for speed since sync.py force-converts).
        
        previous_latest_lookup and athlete_units are used to populate
        terrain_summary and weather_summary fields per activity (v3.107).
        Empty dict / None defaults preserve callers that don't need these.
        """
        interval_activity_ids = interval_activity_ids or set()
        previous_latest_lookup = previous_latest_lookup or {}
        athlete_units = athlete_units or {"wind": "m/s", "temp": "c", "rain": "mm"}
        # Current identity/duration only: no stream fetch or new step assessment.
        event_map = defaultdict(list)
        reverse_map = defaultdict(list)
        for event in paired_events or []:
            if isinstance(event, dict) and event.get("id") is not None:
                event_map[str(event["id"])].append(event)
                if event.get("paired_activity_id") is not None:
                    reverse_map[str(event["paired_activity_id"])].append(event)
        # v3.100: O(1) lookup from intervals.json entries for has_intervals/has_dfa split.
        intervals_by_id = {
            str(e.get("activity_id")): e
            for e in (self._intervals_data or {}).get("activities", [])
            if e.get("activity_id") is not None
        }
        chat_notes_cutoff = (datetime.now() - timedelta(days=7)).strftime("%Y-%m-%d")

        def _first_set(src: Dict, *keys: str):
            """First value among keys that is present and not None (0 is kept)."""
            for key in keys:
                value = src.get(key)
                if value is not None:
                    return value
            return None

        formatted = []
        for i, act in enumerate(activities):
            avg_power = (act.get("average_watts") or act.get("avg_watts") or 
                        act.get("average_power") or act.get("avgWatts") or
                        act.get("icu_average_watts"))
            norm_power = (act.get("weighted_average_watts") or act.get("np") or 
                         act.get("icu_pm_np") or act.get("normalizedPower") or
                         act.get("icu_weighted_avg_watts"))
            avg_hr = (act.get("average_heartrate") or act.get("avg_hr") or 
                     act.get("average_heart_rate") or act.get("avgHr") or
                     act.get("icu_average_hr"))
            max_hr = (act.get("max_heartrate") or act.get("max_hr") or 
                     act.get("max_heart_rate") or act.get("maxHr") or
                     act.get("icu_max_hr"))
            
            avg_cadence = (act.get("average_cadence") or act.get("avg_cadence") or
                          act.get("icu_average_cadence"))
            # v3.139: 0 °C is a real temperature; fall through only on absent/None.
            avg_temp = _first_set(act, "average_weather_temp", "average_temp",
                                  "avg_temp", "average_temperature")
            joules = act.get("icu_joules")
            work_kj = round(joules / 1000, 1) if joules else None
            calories = act.get("calories") or act.get("icu_calories")
            variability_index = act.get("icu_variability_index")
            # v3.139: 0.0 % decoupling is a real value; fall through only on absent/None.
            decoupling = act.get("decoupling")
            
            avg_speed_ms = act.get("average_speed")
            max_speed_ms = act.get("max_speed")
            avg_speed = round(avg_speed_ms * 3.6, 1) if avg_speed_ms else None
            max_speed = round(max_speed_ms * 3.6, 1) if max_speed_ms else None
            avg_pace = act.get("average_pace") or act.get("icu_pace")
            
            weather = act.get("weather_description") or act.get("weather")
            humidity = act.get("humidity") or act.get("average_humidity")
            # v3.139: calm (0) is a real wind speed; fall through only on absent/None.
            wind_speed = _first_set(act, "average_wind_speed", "wind_speed")
            
            carbs_used = act.get("carbs_used")
            carbs_ingested = act.get("carbs_ingested")
            
            hr_zones = {}
            power_zones = {}
            
            icu_hr_zone_times = act.get("icu_hr_zone_times", [])
            if icu_hr_zone_times and isinstance(icu_hr_zone_times, list):
                zone_labels = ["z1_time", "z2_time", "z3_time", "z4_time", "z5_time", "z6_time", "z7_time"]
                for idx, secs in enumerate(icu_hr_zone_times):
                    if idx < len(zone_labels):
                        hr_zones[zone_labels[idx]] = secs if secs is not None else 0
            
            icu_zone_times = act.get("icu_zone_times", [])
            if icu_zone_times:
                for zone in icu_zone_times:
                    zone_id = zone.get("id", "").lower()
                    secs = zone.get("secs", 0)
                    if zone_id in ["z1", "z2", "z3", "z4", "z5", "z6", "z7"]:
                        power_zones[f"{zone_id}_time"] = secs if secs is not None else 0
            
            zone_dist = {}
            if hr_zones:
                zone_dist["hr_zones"] = hr_zones
            if power_zones:
                zone_dist["power_zones"] = power_zones
            
            if not zone_dist:
                zone_dist = None
            
            activity_name = act.get("name", "")
            
            raw_hrrc = act.get("icu_hrr")
            if isinstance(raw_hrrc, dict):
                _v = raw_hrrc.get("value")
                if _v is None:
                    _v = raw_hrrc.get("hrr")
                raw_hrrc = _v
            
            distance_km = round((act.get("distance") or 0) / 1000, 2)
            elevation_m = act.get("total_elevation_gain")
            
            activity = {
                "id": act.get("id", f"unknown_{i+1}"),
                "date": act.get("start_date_local", "unknown"),
                "type": act.get("type", "Unknown"),
                "name": activity_name,
                "duration_hours": round((act.get("moving_time") or 0) / 3600, 2),
                "duration_formatted": self._format_duration(int(act.get("moving_time") or 0)),
                "moving_time_s": self._fact_number(act.get("moving_time")),
                "distance_m": self._fact_number(act.get("distance")),
                "indoor": self._fact_indoor(act),
                "distance_km": distance_km,
                "tss": act.get("icu_training_load"),
                "intensity_factor": act.get("icu_intensity"),
                "avg_power": avg_power,
                "normalized_power": norm_power,
                "avg_hr": avg_hr,
                "max_hr": max_hr,
                "avg_cadence": avg_cadence,
                "avg_speed": avg_speed,
                "avg_speed_unit": speed_unit,
                "max_speed": max_speed,
                "max_speed_unit": speed_unit,
                "avg_pace": avg_pace,
                "avg_temp": avg_temp,
                "avg_temp_unit": temp_unit,
                "weather": weather,
                "humidity": humidity,
                "wind_speed": wind_speed,
                "wind_speed_unit": wind_unit,
                "work_kj": work_kj,
                "calories": calories,
                "carbs_used": carbs_used,
                "carbs_ingested": carbs_ingested,
                "variability_index": variability_index,
                "decoupling": decoupling,
                "efficiency_factor": act.get("icu_efficiency_factor"),
                "hrrc": raw_hrrc,
                "elevation_m": elevation_m,
                "display": {
                    # v3.109: display-ready values converted from canonical metric.
                    # AI quotes these for narration; canonical fields above remain
                    # the calculation source. avg_speed/max_speed are km/h on input
                    # (sync.py force-converts m/s → km/h) — display.speed converts
                    # to mph for imperial athletes, resolving the avg_speed_unit
                    # always-KPH asymmetry preserved on the sibling fields above.
                    "distance":   self._to_display(distance_km, "distance", athlete_units),
                    "elevation":  self._to_display(elevation_m, "elevation", athlete_units),
                    "avg_speed":  self._to_display(avg_speed, "speed", athlete_units),
                    "max_speed":  self._to_display(max_speed, "speed", athlete_units),
                },
                "feel": act.get("feel"),
                "rpe": act.get("icu_rpe"),
                "effort_response": self._classify_effort_response(
                    act.get("icu_intensity"), act.get("icu_rpe")
                ),
                "zone_distribution": zone_dist,
                "zone_reference": self._zone_reference(act),
                "has_intervals": False,
                "has_dfa": False,
            }
            structure = (intervals_by_id.get(str(act.get("id"))) or {}).get("session_structure")
            activity["has_structure"] = bool(structure)
            activity["structure_summary"] = (self._structure_summary(structure) if structure else
                self._activity_plan_match(previous_latest_lookup.get(str(act.get("id"))) or {}) or
                {"method": "plan_match_v2", "status": "unknown", "issues": ["detail_unavailable"]})
            pairing = self._current_plan_pairing(act, event_map, reverse_map)
            # The bounded detail preparation may already have resolved an exact event
            # missing from the batch response. Reuse that current, non-stale reference.
            if (structure and pairing["paired"] and len(pairing["plan"]) == 2
                    and (structure.get("plan") or {}).get("event_id") == pairing["plan"]["event_id"]
                    and pairing["status"] not in ("ambiguous_pairing", "pairing_conflict")
                    and (structure.get("cache") or {}).get("status") not in ("stale", "unavailable")):
                pairing["plan"] = dict(structure["plan"])
                pairing["duration"] = self._plan_duration_check(pairing["plan"].get("duration_s"), act.get("moving_time"))
                cache = structure.get("cache") or {}
                if cache.get("plan_key_version") == self.PLAN_KEY_VERSION:
                    pairing["definition_key"] = cache.get("plan_key")
            activity["plan_pairing"] = pairing
            activity["z3_time"] = {
                "power_s": power_zones.get("z3_time"), "hr_s": hr_zones.get("z3_time")}
            summary = dict(activity["structure_summary"])
            old_plan = summary.get("plan") or {}
            old_pairing = (previous_latest_lookup.get(str(act.get("id"))) or {}).get("plan_pairing") or {}
            same_pair = pairing["paired"] and old_plan.get("event_id") == pairing["plan"]["event_id"]
            changed = (old_pairing.get("definition_key_version") == self.PLAN_KEY_VERSION
                       and old_pairing.get("definition_key") is not None
                       and pairing.get("definition_key") is not None
                       and old_pairing["definition_key"] != pairing["definition_key"])
            assessed = summary.get("status") in ("followed", "partly_followed", "not_followed")
            if pairing["paired"]:
                conflict = pairing["status"] in ("ambiguous_pairing", "pairing_conflict")
                if not structure and (not assessed or not same_pair or changed or conflict):
                    previous = summary if assessed else summary.get("retained_step_assessment")
                    summary = {"method": "plan_match_v2",
                               "status": "no_steps" if pairing["status"] == "no_steps" else "not_assessed"}
                    if summary["status"] == "not_assessed":
                        summary["issues"] = ["detail_unavailable"]
                    if previous:
                        summary["retained_step_assessment"] = previous
                summary["plan"] = pairing["plan"]
                if pairing["status"] in ("ambiguous_pairing", "pairing_conflict"):
                    summary["issues"] = list(dict.fromkeys(summary.get("issues", []) + [pairing["status"]]))
                if not structure and assessed and same_pair and not changed and not conflict:
                    summary["assessment_retained"] = True
            elif assessed or old_plan:
                summary = {"method": "plan_match_v2", "status": "no_plan",
                           "retained_step_assessment": summary}
            activity["structure_summary"] = summary
            if act.get("type") in ("Walk", "Hike"):
                activity["has_structure"] = False
                activity["structure_summary"] = {"method": "plan_match_v2", "status": "unknown",
                                                 "issues": ["sport_out_of_scope"]}

            # has_intervals: requires at least one WORK segment. Intervals.icu emits a
            # whole-session RECOVERY placeholder on unstructured endurance rides, so a
            # non-empty intervals list alone is not sufficient.
            # has_dfa flags AlphaHRV sessions; dfa_summary attached only when sufficient.
            _entry = intervals_by_id.get(str(act.get("id")))
            if _entry:
                if any(i.get("type") == "WORK" for i in (_entry.get("intervals") or [])):
                    activity["has_intervals"] = True
                _dfa = _entry.get("dfa")
                if _dfa:
                    activity["has_dfa"] = True
                    if _dfa.get("quality", {}).get("sufficient"):
                        activity["dfa_summary"] = self._build_dfa_summary(
                            _dfa, schema_version=(self._intervals_data or {}).get("schema_version"))
            # Retain compact DFA inputs for the 28-day rollup, never streams or intervals.
            # A fresh entry (including absent/insufficient DFA) supersedes old evidence.
            if _entry:
                if _entry.get("dfa"):
                    block = _entry["dfa"]
                    activity["dfa_rollup"] = {
                        "schema_version": (self._intervals_data or {}).get("schema_version"),
                        "date": activity["date"],
                        "dfa": {key: block[key] for key in (
                            "quality", "avg", "drift", "drift_quality", "tiz_easy",
                            "tiz_endurance", "tiz_tempo", "tiz_supra", "easy_guard_crossing",
                            "lt1_crossing", "lt2_crossing") if key in block}}
            else:
                retained = (previous_latest_lookup.get(str(act.get("id"))) or {}).get("dfa_rollup")
                if isinstance(retained, dict) and retained.get("date") == activity["date"]:
                    activity["dfa_rollup"] = retained
                    block = retained.get("dfa")
                    self._adopt_native_cache("activity_streams", act.get("id"),
                        retained.get("schema_version") == 2 and isinstance(block, dict)
                        and isinstance(block.get("quality"), dict)
                        and type(block.get("quality", {}).get("sufficient")) is bool)

            # Terrain summary (v3.107) — fetched on first encounter, copied
            # forward thereafter via previous_latest_lookup. Indoor activities
            # produce no terrain field at all (activity.type is the indoor signal).
            terrain_fields = self._build_terrain_for_activity(act, previous_latest_lookup, athlete_units)
            for k, v in terrain_fields.items():
                activity[k] = v
            
            # Weather summary (v3.107) — built from existing activity-list fields
            # when has_weather=True. weather_status="unavailable" otherwise (and
            # NOT copied forward — re-evaluated each sync since Intervals may
            # compute weather later).
            weather_fields = self._build_weather_for_activity(act, previous_latest_lookup, athlete_units)
            for k, v in weather_fields.items():
                activity[k] = v

            # Pass through full description + extract NOTE: lines for push.py round-trip (v3.84)
            raw_desc = act.get("description") or ""
            if raw_desc.strip():
                activity["description"] = raw_desc.strip()
                coach_notes = []
                for line in raw_desc.split("\n"):
                    stripped = line.strip()
                    if stripped.upper().startswith("NOTE:"):
                        note_text = stripped[5:].strip()
                        if note_text:
                            coach_notes.append(note_text)
                    elif stripped:
                        break  # NOTE: lines only extracted from top of description
                if coach_notes:
                    activity["coach_notes"] = coach_notes

            # Fetch activity chat messages for recent activities (v3.84 — unconditional, 7-day window)
            act_date = act.get("start_date_local", "")[:10]
            if act_date >= chat_notes_cutoff:
                activity_id = act.get("id")
                if activity_id:
                    # v3.133: absence of chat_notes previously conflated "no notes"
                    # with "not retrieved". The marker is emitted ONLY on degradation,
                    # so a healthy payload is byte-identical to before.
                    msg_status, notes = self._get_activity_messages(activity_id)
                    if msg_status == "deferred" and not notes:
                        notes = (previous_latest_lookup.get(str(activity_id)) or {}).get("chat_notes", [])
                    if notes:
                        activity["chat_notes"] = notes
                    if msg_status in ("unavailable", "deferred"):
                        activity["chat_notes_status"] = "unavailable"
            
            formatted.append(activity)

        # Run new reads after existing enrichments, preserving their retry budget.
        for act, activity in zip(activities, formatted):
            extra = self._post_workout_fields(
                act, activity["avg_power"], activity["avg_speed"], temp_unit, athlete_units)
            activity["display"].update(extra.pop("display"))
            activity.update(extra)
            has_power = any(isinstance(activity.get(k), (int, float)) and activity[k] > 0
                            for k in ("avg_power", "normalized_power"))
            has_power = has_power or "watts" in (act.get("stream_types") or [])
            activity["power_curve_expected"] = bool(has_power)
            activity.update(self._build_power_curve_for_activity(act, previous_latest_lookup, has_power))

        # New endpoint runs last so existing reads retain their retry opportunities.
        for act, activity in zip(activities, formatted):
            has_hr = (self._structure_number(activity.get("avg_hr")) and activity["avg_hr"] > 0
                      or "heartrate" in (act.get("stream_types") or []))
            activity.update(self._build_decoupling_for_activity(
                act, previous_latest_lookup, activity["power_curve_expected"], has_hr,
                activity["structure_summary"]))
            entry = intervals_by_id.get(str(act.get("id"))) or {}
            detected = act.get("interval_summary", entry.get("interval_summary"))
            activity["interval_data"] = {
                "version": self.INTERVAL_DATA_VERSION,
                "plan_match": activity.pop("structure_summary"),
                "compliance": self._compact_compliance(entry.get("session_structure"), activity["plan_pairing"]),
                "icu_detected": detected if isinstance(detected, list) and all(isinstance(s, str) for s in detected) else None}

        return formatted
    
    def _format_wellness(self, wellness: List[Dict],
                         athlete_units: Optional[Dict[str, str]] = None) -> List[Dict]:
        """Format wellness data.
        
        athlete_units (v3.109): when provided, each row gets a `display` block
        with weight (display.weight) alongside canonical weight_kg.
        """
        formatted = []
        for w in wellness:
            weight_kg = w.get("weight")
            entry = {
                "date": w.get("id", "unknown"),
                # Core metrics
                "weight_kg": weight_kg,
                "display": {
                    "weight": self._to_display(weight_kg, "weight", athlete_units),
                },
                "resting_hr": w.get("restingHR"),
                "hrv_rmssd": w.get("hrv"),
                "hrv_sdnn": w.get("hrvSDNN"),
                "sleep_hours": round(w["sleepSecs"] / 3600, 2) if w.get("sleepSecs") else None,
                "sleep_formatted": self._format_duration(int(w["sleepSecs"]) // 60 * 60) if w.get("sleepSecs") else None,
                "sleep_quality": w.get("sleepQuality"),
                "sleep_score": w.get("sleepScore"),
                "mental_energy": w.get("mentalEnergy"),
                "avg_sleeping_hr": w.get("avgSleepingHR"),
                "vo2max": w.get("vo2max"),
                # Subjective state (categorical 1-4, see wellness_field_scales in READ_THIS_FIRST)
                "fatigue": w.get("fatigue"),
                "soreness": w.get("soreness"),
                "stress": w.get("stress"),
                "mood": w.get("mood"),
                "motivation": w.get("motivation"),
                "injury": w.get("injury"),
                "hydration": w.get("hydration"),
                # Vitals
                "spO2": w.get("spO2"),
                "blood_glucose": w.get("bloodGlucose"),
                "systolic": w.get("systolic"),
                "diastolic": w.get("diastolic"),
                "baevsky_si": w.get("baevskySI"),
                "lactate": w.get("lactate"),
                "respiration": w.get("respiration"),
                # Body composition
                "body_fat_pct": w.get("bodyFat"),
                "abdomen_cm": w.get("abdomen"),
                # Lifestyle / nutrition
                "steps": w.get("steps"),
                "hydration_volume_l": w.get("hydrationVolume"),
                "kcal_consumed": w.get("kcalConsumed"),
                "carbohydrates_g": w.get("carbohydrates"),
                "protein_g": w.get("protein"),
                "fat_g": w.get("fatTotal"),
                # Cycle
                "menstrual_phase": w.get("menstrualPhase"),
                "menstrual_phase_predicted": w.get("menstrualPhasePredicted"),
                # Platform
                "readiness": w.get("readiness")
            }
            
            formatted.append(entry)
        
        return formatted
    
    # v3.135: in-place markers for content a workout_summary cannot render. Each
    # replaces what used to be dropped or misstated; the scope of an unmarked summary
    # is stated in the v3.135 note above. None contains "×" or "sets", so summary
    # availability and the phase hard-session marker are unchanged.
    SUMMARY_STEP_NOT_SUMMARIZED = "[step not summarized]"
    SUMMARY_REPEAT_NOT_SUMMARIZED = "[repeat not summarized]"
    SUMMARY_TARGET_NOT_SHOWN = "[target not shown]"
    SUMMARY_TARGET_KEYS = ("_power", "power", "_hr", "hr", "_pace", "pace")
    # Units under which a target value may be printed as an absolute W / bpm value.
    # A resolved "_power" / "_hr" with no "units" is the resolve=true form the renderer
    # has always printed; a raw "power" / "hr" must name one of these units.
    SUMMARY_WATT_UNITS = ("w", "watts")
    SUMMARY_BPM_UNITS = ("bpm",)

    def _summarize_workout_doc(self, workout_doc: Dict) -> str:
        """
        Summarize a structured workout_doc into a human-readable one-liner.
        
        Legacy repeat matcher, before the flat-list fallback in _format_events:
          Pattern A: Explicit repeats (step has 'reps' + nested 'steps')
          Pattern B: Flat alternating work/rest pairs (min 3 reps, strict guards)
        
        Returns summary string or None if workout doesn't match either pattern
        or if workout_doc is missing/malformed. Never raises exceptions.
        
        Note: workout_doc availability depends on how the workout was created in
        Intervals.icu. Workouts created via the builder will have it; imported or
        manually typed workouts may not. When absent, raw description is preserved.
        """
        try:
            if not workout_doc or not isinstance(workout_doc, dict):
                return None
            steps = workout_doc.get("steps")
            if not steps or not isinstance(steps, list):
                return None
            
            parts = []
            for step in steps:
                rendered = self._render_step(step)
                if rendered:
                    parts.append(rendered)
                elif self._is_repeat_like(step):
                    parts.append(self.SUMMARY_REPEAT_NOT_SUMMARIZED)
                else:
                    parts.append(self.SUMMARY_STEP_NOT_SUMMARIZED)
            
            if not parts:
                return None
            
            # Check if any part is an interval summary (the whole point of this)
            has_interval = any(
                "×" in p or "sets" in p.lower() 
                for p in parts
            )
            if not has_interval:
                return None  # _format_events next tries alternating, then flat lists.
            
            return self._merge_interval_blocks(parts)
        except Exception:
            return None

    def _summarize_flat_workout_doc(self, workout_doc: Dict) -> str:
        """Last-resort ordered flat summary; never introduce a hard-session marker.

        Repeat and alternating renderers retain precedence and their existing
        semantics. Unsupported atoms remain marked; no roles are inferred.
        """
        steps = workout_doc.get("steps") if isinstance(workout_doc, dict) else None
        if not isinstance(steps, list) or not steps or any(self._is_repeat_like(s) for s in steps):
            return None
        rendered = [self._render_step(s) for s in steps[:self.STRUCTURE_MAX_STEPS]]
        if not any(rendered):
            return None
        parts = [s or self.SUMMARY_STEP_NOT_SUMMARIZED for s in rendered]
        if len(steps) > self.STRUCTURE_MAX_STEPS:
            parts.append(self.SUMMARY_STEP_NOT_SUMMARIZED)
        return " | ".join(parts)
    
    def _merge_interval_blocks(self, parts: List[str]) -> str:
        """
        Merge consecutive identical interval blocks in summary parts.
        
        E.g., ["5×(10s @700W + 3m @120W)", "5×(10s @700W + 3m @120W)"] → ["2 × 5×(10s @700W + 3m @120W)"]
        
        No WU/CD labeling — that's a coaching interpretation, not structural data.
        Strict string equality only.
        """
        if not parts:
            return ""
        
        result = []
        i = 0
        while i < len(parts):
            current = parts[i]
            count = 1
            # v3.135: a part carrying a marker never merges; identical text does not
            # prove that the unrendered steps or targets behind it are identical.
            while (i + count < len(parts) and parts[i + count] == current
                    and "[" not in current):
                count += 1
            if count > 1:
                result.append(f"{count} × {current}")
            else:
                result.append(current)
            i += count
        
        return " | ".join(result)
    
    def _render_step(self, step: Dict) -> str:
        """Render a single workout_doc step. Returns string or None."""
        try:
            if not isinstance(step, dict):
                return None
            
            # Pattern A: Explicit repeats. v3.136: any step with repeat semantics goes
            # here; a malformed one returns None and is marked by the caller.
            if self._is_repeat_like(step):
                return self._render_repeat_block(step)
            
            # Pattern B: Check later at block level (handled in _summarize_workout_doc 
            # by scanning sequences). Individual flat steps just render simply.
            return self._render_flat_step(step)
        except Exception:
            return None
    
    def _render_flat_step(self, step: Dict) -> str:
        """Render a non-repeat step as 'duration @power'."""
        try:
            dur = self._summary_duration(step.get("duration"))
            if dur is None:
                return None
            
            dur_str = self._format_duration(dur)
            return f"{dur_str}{self._describe_step_target(step)}"
        except Exception:
            return None
    
    def _render_repeat_block(self, step: Dict) -> str:
        """
        Render a repeat block (Pattern A).
        
        Handles:
        - Simple: reps × (A + B) → "N×(dur @target + dur @target)"
        - With a leading set step: longer, lower-or-equal target step, then alternating pairs

        Structure only (v3.134): no step is labelled recovery. Order and a lower target
        are not evidence of a step's role, so each step keeps its own target.
        
        Bails to None if nested structure has >3 unique step types or is too complex.
        """
        try:
            # v3.136: count and shape are validated first; zero, negative, fractional,
            # non-finite, boolean or non-numeric counts and non-list or empty "steps"
            # fail closed (the caller marks the repeat).
            parts = self._repeat_parts(step)
            if parts is None:
                return None
            reps, nested = parts
            
            # Simple case: 2 nested steps, rendered alike
            if len(nested) == 2:
                first, second = nested[0], nested[1]
                # v3.135: availability is decided exactly as in v3.134 (see
                # _repeat_step_describable); rendering follows _step_target, and a
                # step that cannot render is marked in place, never dropped.
                if not self._repeat_step_describable(first):
                    return None
                # v3.136: a nested repeat child is rendered as a repeat or marked,
                # never by its aggregate duration.
                return f"{reps}×({self._render_child(first)} + {self._render_child(second)})"
            
            # Check for alternating work/rest pattern inside nested steps
            # (e.g., 30/15 sessions: set_recovery, then work, rest, work, rest...)
            if len(nested) >= 3:
                result = self._detect_alternating_in_nested(nested, reps)
                if result:
                    return result
            
            # Too complex — bail
            return None
        except Exception:
            return None
    
    def _detect_alternating_in_nested(self, nested: List[Dict], outer_reps: int) -> str:
        """
        Detect alternating work/rest pairs inside a nested step list.
        Used for 30/15-style sessions where the builder unrolls reps inside a set.
        
        The guards decide only whether the steps compress; they do not establish that
        the lower step is recovery. v3.134 renders both targets and no role label:
        "k×(a + b)", then "+ (a + b')" when the last rest duration differs and
        "+ a" for a trailing rep; a leading set step keeps its target.

        Guards:
        - Both work and rest must have numeric power targets
        - All work targets within ±2W, all rest targets within ±2W
        - All work durations equal, all rest durations equal (one tail exception allowed)
        - Minimum 3 pairs
        """
        try:
            # v3.136: a child with repeat semantics or an unusable duration can never
            # stand in a compressed position (set step, pair or trailing rep).
            def usable(child):
                return (isinstance(child, dict) and not self._is_repeat_like(child)
                        and self._summary_duration(child.get("duration")) is not None)

            # Check if first step is a set recovery (low power, before the main work)
            set_rec = None
            start_idx = 0
            if len(nested) >= 5 and usable(nested[0]) and usable(nested[1]):
                first = nested[0]
                second = nested[1]
                first_power = self._get_power(first)
                second_power = self._get_power(second)
                first_dur = first.get("duration", 0)
                second_dur = second.get("duration", 0)
                # Set recovery: longer duration, lower or equal power than work steps
                if (first_power is not None and second_power is not None 
                    and first_power <= second_power and first_dur > second_dur):
                    set_rec = first
                    start_idx = 1
            
            # Collect remaining steps as candidate pairs
            remaining = nested[start_idx:]
            if len(remaining) < 6:  # need at least 3 pairs
                return None
            
            # Try to consume as (work, rest) pairs
            pairs = []
            pair_steps = []
            i = 0
            while i + 1 < len(remaining):
                work = remaining[i]
                rest = remaining[i + 1]
                w_power = self._get_power(work)
                r_power = self._get_power(rest)
                if not usable(work) or not usable(rest):
                    return None  # v3.136: unusable child — bail (caller marks the repeat)
                w_dur = work.get("duration")
                r_dur = rest.get("duration")
                
                if w_power is None or r_power is None:
                    return None  # Can't compare — bail
                w_power = int(round(w_power))
                r_power = int(round(r_power))
                if w_power <= r_power:
                    return None  # Work should be harder than rest
                if abs(w_power - r_power) < max(10, 0.05 * w_power):
                    return None  # Targets must be meaningfully distinct
                
                pairs.append((w_dur, w_power, r_dur, r_power))
                pair_steps.append((work, rest))
                i += 2
            
            # Trailing solo work step: final rep with no rest (builder drops
            # the last rest when it's followed by set recovery or cooldown).
            has_trailing = False
            if i == len(remaining) - 1:
                trailing = remaining[i]
                t_power = self._get_power(trailing) if usable(trailing) else None
                t_dur = trailing.get("duration") if usable(trailing) else None
                if (t_power is not None and t_dur is not None and pairs):
                    ref_wd = pairs[0][0]
                    ref_wp = pairs[0][1]
                    if (t_dur == ref_wd and
                            abs(int(round(t_power)) - ref_wp) <= 2):
                        has_trailing = True
            
            if len(pairs) + (1 if has_trailing else 0) < 3:
                return None
            
            # Consistency check (pairs only — trailing rep already validated above)
            ref_w_dur, ref_w_power, ref_r_dur, ref_r_power = pairs[0]
            for j, (wd, wp, rd, rp) in enumerate(pairs):
                if wd != ref_w_dur:
                    return None  # Work durations must match exactly
                if abs(wp - ref_w_power) > 2:
                    return None  # Work power within ±2W
                if abs(rp - ref_r_power) > 2:
                    return None  # Rest power within ±2W
                # Rest duration: allow last pair to differ (tail exception)
                if rd != ref_r_dur and j < len(pairs) - 1:
                    return None
            
            # Build summary (structure only; both targets kept, no role label).
            # v3.135: targets are rendered through _step_target / _role_target_suffix,
            # and an unmatched final child is written out instead of dropped.
            n_uniform = len(pairs)
            last_r_dur = pairs[-1][2]
            has_tail = last_r_dur != ref_r_dur
            if has_tail:
                n_uniform -= 1
            work_steps = [w for w, _ in pair_steps]
            if has_trailing:
                work_steps.append(remaining[i])
            rest_steps = [r for _, r in pair_steps]
            if has_tail:
                rest_steps = rest_steps[:-1]
            work_str = (f"{self._format_duration(int(ref_w_dur))}"
                        f"{self._role_target_suffix(work_steps, ref_w_power)}")
            rest_str = (f"{self._format_duration(int(ref_r_dur))}"
                        f"{self._role_target_suffix(rest_steps, ref_r_power)}")

            inner = f"{n_uniform}×({work_str} + {rest_str})"
            compound = False
            if has_tail:
                # Tail exception: render the differing last pair explicitly.
                tail_rest = pair_steps[-1][1]
                tail_str = (f"{self._format_duration(int(last_r_dur))}"
                            f"{self._describe_step_target(tail_rest)}")
                inner += f" + ({work_str} + {tail_str})"
                compound = True
            if has_trailing:
                inner += f" + {work_str}"
                compound = True
            elif i == len(remaining) - 1:
                unmatched = remaining[i]
                inner += f" + {self._render_child(unmatched)}"
                compound = True
            
            if set_rec:
                sr_dur = self._format_duration(int(set_rec.get("duration")))
                inner = f"{sr_dur}{self._describe_step_target(set_rec)} + {inner}"
                compound = True
            
            if outer_reps > 1:
                if compound:
                    return f"{outer_reps} sets × ({inner})"
                return f"{outer_reps} sets × {inner}"
            return inner
        except Exception:
            return None
    
    def _get_power(self, step: Dict) -> float:
        """Extract resolved power value from a step. Returns float or None."""
        try:
            power = step.get("_power") or step.get("power")
            if power and isinstance(power, dict):
                val = power.get("value")
                if val is not None:
                    return float(val)
            return None
        except Exception:
            return None
    
    def _describe_work_step(self, step: Dict) -> str:
        """Describe an atomic step as 'dur @target'; None if its duration is unusable."""
        try:
            if self._is_repeat_like(step):
                return None
            dur = self._summary_duration(step.get("duration"))
            if dur is None:
                return None
            dur_str = self._format_duration(dur)
            return f"{dur_str}{self._describe_step_target(step)}"
        except Exception:
            return None

    # v3.136: one duration policy and one repeat-count policy for every summary path.
    SUMMARY_MAX_NESTED_REPEAT_DEPTH = 4

    @staticmethod
    def _summary_duration(value) -> Optional[int]:
        """
        Seconds a summary may print for a step, or None when the duration is not a
        usable positive finite number (missing, zero, negative, non-finite, boolean,
        string or other type). Fractional seconds are truncated for display, as
        before; a value below 1 s is not usable.
        """
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            return None
        if not math.isfinite(value) or value < 1:
            return None
        return int(value)

    @staticmethod
    def _summary_count(value) -> Optional[int]:
        """
        A repeat count a summary may print, or None unless it is a whole finite
        number of at least 1 (not boolean, not a string, not fractional).
        """
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            return None
        if not math.isfinite(value) or value < 1 or value != int(value):
            return None
        return int(value)

    @staticmethod
    def _is_repeat_like(step) -> bool:
        """A step with repeat semantics ("reps" or "steps" key) is never rendered flat."""
        return isinstance(step, dict) and ("reps" in step or "steps" in step)

    def _repeat_parts(self, step: Dict):
        """(count, children) for a well-formed repeat, else None (fail closed)."""
        if not self._is_repeat_like(step):
            return None
        count = self._summary_count(step.get("reps"))
        children = step.get("steps")
        if count is None or not isinstance(children, list) or not children:
            return None
        return count, children

    def _render_child(self, child, depth: int = 1) -> str:
        """
        Render one child of a repeat: a nested two-step repeat as "N×(A + B)"
        (recursively), any other repeat-like child as the repeat marker, and an atomic
        child through _describe_work_step or the step marker. Never renders a repeat
        by its aggregate duration.
        """
        if self._is_repeat_like(child):
            parts = self._repeat_parts(child)
            if (parts is None or len(parts[1]) != 2
                    or depth > self.SUMMARY_MAX_NESTED_REPEAT_DEPTH):
                return self.SUMMARY_REPEAT_NOT_SUMMARIZED
            count, (a, b) = parts
            return (f"{count}×({self._render_child(a, depth + 1)} + "
                    f"{self._render_child(b, depth + 1)})")
        return self._describe_work_step(child) or self.SUMMARY_STEP_NOT_SUMMARIZED

    def _step_target_value(self, step: Dict):
        """
        The one target policy for every workout_summary output path (v3.135).

        Returns ("W", raw), ("bpm", raw), None (no target key at all) or
        SUMMARY_TARGET_NOT_SHOWN. Presence is decided by key, not truthiness, so
        "power": {} or "power": null is a present target, not an untargeted step.
        Power governs when any power key is present; an unprintable power target is
        marked and never replaced by an HR value. A value is printed only when:
        - it is a finite number in the governing object ("_power" if present, else
          "power"; likewise "_hr" / "hr");
        - its units support the absolute label: a resolved "_power" / "_hr" with no
          "units", or units in SUMMARY_WATT_UNITS / SUMMARY_BPM_UNITS. Relative
          targets (%FTP, zones) are marked, never relabelled or converted;
        - no present object of that kind carries range bounds ("start" / "end"),
          which a single printed value would silently discard.
        A pace key is always marked. Never raises.
        """
        try:
            for resolved, raw, label, units_ok in (
                    ("_power", "power", "W", self.SUMMARY_WATT_UNITS),
                    ("_hr", "hr", "bpm", self.SUMMARY_BPM_UNITS)):
                present = [k for k in (resolved, raw) if k in step]
                if not present:
                    continue
                for k in present:
                    obj = step[k]
                    if isinstance(obj, dict) and ("start" in obj or "end" in obj):
                        return self.SUMMARY_TARGET_NOT_SHOWN
                key = resolved if resolved in step else raw
                obj = step[key]
                if not isinstance(obj, dict):
                    return self.SUMMARY_TARGET_NOT_SHOWN
                val = obj.get("value")
                if (isinstance(val, bool) or not isinstance(val, (int, float))
                        or not math.isfinite(val)):
                    return self.SUMMARY_TARGET_NOT_SHOWN
                units = obj.get("units")
                if key == raw or units is not None:
                    if not isinstance(units, str) or units.strip().lower() not in units_ok:
                        return self.SUMMARY_TARGET_NOT_SHOWN
                return (label, float(val))
            if "_pace" in step or "pace" in step:
                return self.SUMMARY_TARGET_NOT_SHOWN
            return None
        except Exception:
            return self.SUMMARY_TARGET_NOT_SHOWN

    def _step_target(self, step: Dict):
        """_step_target_value with the printable value rounded for display."""
        target = self._step_target_value(step)
        if isinstance(target, tuple):
            return (target[0], int(round(target[1])))
        return target

    def _describe_step_target(self, step: Dict) -> str:
        """Target suffix per _step_target: " @NW", " @Nbpm", "" or " [target not shown]"."""
        target = self._step_target(step)
        if target is None:
            return ""
        if isinstance(target, tuple):
            return f" @{target[1]}{target[0]}"
        return f" {self.SUMMARY_TARGET_NOT_SHOWN}"

    def _role_target_suffix(self, steps: List[Dict], ref_power: float) -> str:
        """
        Target suffix for one role (work or rest) of a compressed alternating block.

        The detectors compare targets through _get_power, which reads any value. The
        rendered suffix follows _step_target: the reference watts are printed only when
        every step in the role has a printable watt target; otherwise the role is
        marked. Detection, and so summary availability, is unchanged.
        """
        targets = [self._step_target_value(s) for s in steps]
        if targets and all(isinstance(t, tuple) and t[0] == "W" for t in targets):
            raw = [t[1] for t in targets]
            # v3.136: the detectors' 2 W tolerance (relative to the reference, the
            # role's first step) is checked on raw values before display rounding;
            # a wider deviation is marked rather than shown as the reference value.
            if all(abs(v - raw[0]) <= 2 for v in raw):
                return f" @{int(round(raw[0]))}W"
        return f" {self.SUMMARY_TARGET_NOT_SHOWN}"

    def _repeat_step_describable(self, step: Dict) -> bool:
        """
        Whether v3.134 _describe_work_step would have returned a string for this step.

        A two-step repeat block exists only when its first step is describable. That
        test is kept exactly as in v3.134 so the target policy cannot change which
        repeats render, and with them summary null status or the phase "×" marker.
        """
        try:
            dur = step.get("duration")
            if not dur:
                return False
            int(dur)
            power = self._get_power(step)
            if power is not None:
                int(round(power))
                return True
            hr = step.get("_hr") or step.get("hr")
            if hr and isinstance(hr, dict):
                val = hr.get("value")
                if val is not None:
                    int(round(val))
            return True
        except Exception:
            return False
    
    @staticmethod
    def _format_duration(seconds: int) -> str:
        """Format seconds into human-readable duration (e.g., 300 → '5m', 90 → '1m30s')."""
        if seconds <= 0:
            return "0s"
        hours = seconds // 3600
        minutes = (seconds % 3600) // 60
        secs = seconds % 60
        
        parts = []
        if hours:
            parts.append(f"{hours}h")
        if minutes:
            parts.append(f"{minutes}m")
        if secs:
            parts.append(f"{secs}s")
        return "".join(parts) if parts else "0s"
    
    def _detect_flat_alternating(self, workout_doc: Dict) -> str:
        """
        Pattern B: Detect flat alternating work/rest pairs in top-level steps.
        
        For workouts like sprint openers where intervals are unrolled without
        repeat markers. Scans top-level steps for blocks of alternating high/low
        power pairs separated by non-matching steps (warmup, cooldown, etc).
        
        Guards:
        - Both work and rest must have numeric power targets (via _power or power)
        - All work targets within ±2W, all rest targets within ±2W
        - All work durations equal, all rest durations equal (one tail exception)
        - Minimum 3 pairs per block
        - Work power must be higher than rest power

        As in the nested detector, the guards decide only whether steps compress.
        v3.134 renders "k×(a + b)" with both targets and no role label, an explicit
        "+ (a + b')" for a differing tail rest and "+ a" for a trailing rep, and
        resumes scanning immediately after the last consumed step.
        """
        try:
            steps = workout_doc.get("steps")
            if not steps or not isinstance(steps, list) or len(steps) < 6:
                return None
            
            # Skip steps that are repeat blocks (already handled by Pattern A)
            if any(s.get("reps") for s in steps if isinstance(s, dict)):
                return None
            
            # Collect (duration, power) for each step
            step_data = []
            for s in steps:
                if not isinstance(s, dict):
                    return None
                # v3.136: a repeat-like step or an unusable duration cannot join a block.
                if self._is_repeat_like(s) or self._summary_duration(s.get("duration")) is None:
                    step_data.append((None, None))
                    continue
                dur = s.get("duration")
                power = self._get_power(s)
                step_data.append((dur, power))
            
            # Try to find alternating blocks
            # Strategy: scan for regions where pairs repeat
            parts = []
            i = 0
            while i < len(step_data):
                dur_i, pow_i = step_data[i]
                
                # Try to start an alternating block at position i
                if (i + 1 < len(step_data) 
                    and dur_i is not None and pow_i is not None
                    and step_data[i+1][0] is not None and step_data[i+1][1] is not None):
                    
                    block = self._try_alternating_block(step_data, i)
                    if block:
                        (count, work_dur, work_power, rest_dur, rest_power,
                         n_pairs, tail_rest_dur, has_trailing) = block
                        # v3.135: targets follow _step_target via _role_target_suffix.
                        work_steps = [steps[i + 2 * k] for k in range(n_pairs)]
                        if has_trailing:
                            work_steps.append(steps[i + 2 * n_pairs])
                        rest_steps = [steps[i + 2 * k + 1] for k in range(n_pairs)]
                        tail_rest = None
                        if tail_rest_dur is not None:
                            tail_rest = rest_steps.pop()
                        work_str = (f"{self._format_duration(int(work_dur))}"
                                    f"{self._role_target_suffix(work_steps, work_power)}")
                        rest_str = (f"{self._format_duration(int(rest_dur))}"
                                    f"{self._role_target_suffix(rest_steps, rest_power)}")
                        n_uniform = n_pairs - (1 if tail_rest_dur is not None else 0)
                        part = f"{n_uniform}×({work_str} + {rest_str})"
                        if tail_rest_dur is not None:
                            # v3.136: the tail rest shows the reference value only when it
                            # and the reference rest are printable and within 2 W raw.
                            tail_suffix = self._role_target_suffix([steps[i + 1], tail_rest],
                                                                   rest_power)
                            tail_str = f"{self._format_duration(int(tail_rest_dur))}{tail_suffix}"
                            part += f" + ({work_str} + {tail_str})"
                        if has_trailing:
                            part += f" + {work_str}"
                        parts.append(part)
                        # v3.134: advance past exactly the consumed steps. count
                        # includes a trailing solo rep, so count * 2 overshot by one
                        # and silently dropped the step after it (e.g. a cool-down).
                        i += n_pairs * 2 + (1 if has_trailing else 0)
                        continue
                
                # Not part of an alternating block — render as flat step
                # v3.135: a step that cannot render is marked, not dropped; v3.136: a
                # repeat-like step gets the repeat marker and is never rendered flat.
                if self._is_repeat_like(steps[i]):
                    parts.append(self.SUMMARY_REPEAT_NOT_SUMMARIZED)
                else:
                    flat = self._render_flat_step(steps[i]) if dur_i is not None else None
                    parts.append(flat or self.SUMMARY_STEP_NOT_SUMMARIZED)
                i += 1
            
            if not parts:
                return None
            
            # Only return if we found at least one alternating block
            has_block = any("×" in p for p in parts)
            if not has_block:
                return None
            
            return self._merge_interval_blocks(parts)
        except Exception:
            return None
    
    def _try_alternating_block(self, step_data: List, start: int) -> tuple:
        """
        Try to consume an alternating work/rest block starting at 'start'.
        Returns (count, work_dur, work_power, rest_dur, rest_power, n_pairs,
        tail_rest_dur, has_trailing) or None. count = n_pairs plus one for a
        trailing solo rep; tail_rest_dur is the last pair's differing rest duration
        (tail exception) or None. Consumed steps: n_pairs * 2 + has_trailing.
        """
        try:
            ref_w_dur, ref_w_power = step_data[start]
            ref_r_dur, ref_r_power = step_data[start + 1]
            
            if ref_w_power is None or ref_r_power is None:
                return None
            # Normalize watts to ints before all comparisons
            ref_w_power = int(round(ref_w_power))
            ref_r_power = int(round(ref_r_power))
            if ref_w_power <= ref_r_power:
                return None  # Work must be harder than rest
            if abs(ref_w_power - ref_r_power) < max(10, 0.05 * ref_w_power):
                return None  # Targets must be meaningfully distinct
            if ref_w_dur is None or ref_r_dur is None:
                return None
            
            count = 1
            tail_rest_dur = None
            j = start + 2
            while j + 1 < len(step_data):
                wd, wp = step_data[j]
                rd, rp = step_data[j + 1]
                
                if wp is None or rp is None or wd is None or rd is None:
                    break
                wp = int(round(wp))
                rp = int(round(rp))
                if abs(wd - ref_w_dur) > 1:
                    break  # Work duration tolerance ±1s
                if abs(wp - ref_w_power) > 2:
                    break
                if abs(rp - ref_r_power) > 2:
                    break
                # Rest duration: allow tail exception on last pair
                if abs(rd - ref_r_dur) > 2:
                    # Long rest (≥1.5× normal) = set break — always consume as tail
                    if rd >= ref_r_dur * 1.5:
                        count += 1
                        tail_rest_dur = rd
                        j += 2
                        break
                    # Otherwise check if more matching pairs follow
                    if j + 3 < len(step_data):
                        nwd, nwp = step_data[j + 2]
                        if (nwd is not None and abs(nwd - ref_w_dur) <= 1 
                            and nwp is not None and abs(int(round(nwp)) - ref_w_power) <= 2):
                            break  # Not the last pair — strict fail
                    count += 1
                    tail_rest_dur = rd
                    j += 2
                    break  # Tail exception consumed, stop
                
                count += 1
                j += 2
            
            # Trailing solo work step: final rep with no paired rest
            n_pairs = count
            has_trailing = False
            if j < len(step_data):
                wd, wp = step_data[j]
                if (wd is not None and wp is not None
                        and abs(wd - ref_w_dur) <= 1
                        and abs(int(round(wp)) - ref_w_power) <= 2):
                    count += 1
                    has_trailing = True
            
            if count < 3:
                return None
            
            return (count, ref_w_dur, ref_w_power, ref_r_dur, ref_r_power,
                    n_pairs, tail_rest_dur, has_trailing)
        except Exception:
            return None
    
    def _format_events(self, events: List[Dict], today: str = None) -> List[Dict]:
        """
        Format planned workouts with workout_summary and tiered detail (v3.6.2).
        
        Tiering:
        - Days 0-7: full output (description + workout_summary + all fields)
        - Days 8-42: skeleton (name, date, type, TSS, duration, workout_summary).
          If workout_summary is null, keeps description_preview (first 3 lines).
        
        Sets self._summary_stats with coverage telemetry.
        """
        if today is None:
            today = datetime.now().strftime("%Y-%m-%d")
        
        day7_cutoff = (datetime.strptime(today, "%Y-%m-%d") + timedelta(days=7)).strftime("%Y-%m-%d")
        
        stats = {"attempted": 0, "success": 0, "patternA": 0, "patternB": 0, "flat": 0,
                 "bail_no_workout_doc": 0, "bail_no_match": 0}
        
        result = []
        for i, evt in enumerate(events):
            evt_date = (evt.get("start_date_local") or "unknown")[:10]
            is_near = evt_date <= day7_cutoff
            
            # Generate workout_summary from workout_doc
            workout_doc = evt.get("workout_doc")
            summary = None
            
            if workout_doc and isinstance(workout_doc, dict) and workout_doc.get("steps"):
                stats["attempted"] += 1
                summary = self._summarize_workout_doc(workout_doc)
                if summary:
                    stats["patternA"] += 1
                else:
                    # Try Pattern B (flat alternating)
                    summary = self._detect_flat_alternating(workout_doc)
                    if summary:
                        stats["patternB"] += 1
                    else:
                        summary = self._summarize_flat_workout_doc(workout_doc)
                        if summary:
                            stats["flat"] += 1
                        else:
                            stats["bail_no_match"] += 1
                if summary:
                    stats["success"] += 1
            elif ((evt.get("description") or "").strip()
                  and evt.get("category", "") in self.TRAINING_EVENT_CATEGORIES):
                # v3.128: this telemetry measures workout_summary coverage over planned
                # training. A SICK / INJURED / NOTE / HOLIDAY description is not a
                # workout that failed to summarise, and counting it inflated the bail
                # rate against a denominator of sessions that were never attempted.
                stats["bail_no_workout_doc"] += 1

            # Parse NOTE: lines from description (v0.3 — coach annotations)
            raw_desc = evt.get("description") or ""
            coach_notes = []
            clean_desc_lines = []
            past_notes = False
            for line in raw_desc.split("\n"):
                stripped = line.strip()
                if not past_notes and stripped.upper().startswith("NOTE:"):
                    note_text = stripped[5:].strip()
                    if note_text:
                        coach_notes.append(note_text)
                elif not past_notes and stripped == "":
                    continue  # skip blank lines between NOTE: lines and workout
                else:
                    past_notes = True
                    clean_desc_lines.append(line)
            clean_desc = "\n".join(clean_desc_lines).strip()

            entry = {
                "id": evt.get("id"),
                "date": evt_date,
                "name": evt.get("name", ""),
                "type": evt.get("category", ""),
                "sport_type": evt.get("type", ""),
                "planned_tss": evt.get("icu_training_load"),
                "duration_hours": round((evt.get("moving_time") or 0) / 3600, 2),
                "duration_formatted": self._format_duration(int(evt.get("moving_time") or 0)),
                "workout_summary": summary,
                **self._planned_route_fields(evt)
            }
            end_date = self._calendar_end_date(evt)
            if end_date > evt_date:
                entry["end_date"] = end_date

            if coach_notes:
                entry["coach_notes"] = coach_notes
            
            entry.update(self._event_start_fields(evt))
            
            # Indoor flag: only include when True
            if evt.get("indoor"):
                entry["indoor"] = True
            
            if is_near:
                # Days 0-7: full detail
                entry["description"] = clean_desc
            else:
                # Days 8-42: skeleton only
                if summary is None:
                    lines = [l.strip() for l in clean_desc.split("\n") if l.strip()][:3]
                    entry["description_preview"] = "\n".join(lines) if lines else None
            
            result.append(entry)
        
        self._summary_stats = stats
        return result
    
    @staticmethod
    def _calendar_end_date(evt: Dict) -> str:
        """Inclusive last calendar-marked day, shared with health context."""
        start = (evt.get("start_date_local") or "")[:10]
        end_date = start
        end_raw = evt.get("end_date_local") or ""
        if end_raw:
            end_day = end_raw[:10]
            end_time = end_raw.split("T")[1][:5] if "T" in end_raw else "00:00"
            if end_time == "00:00":
                try:
                    end_date = (datetime.strptime(end_day, "%Y-%m-%d")
                                - timedelta(days=1)).strftime("%Y-%m-%d")
                except ValueError:
                    end_date = start
            else:
                end_date = end_day
            if end_date < start:
                end_date = start
        return end_date

    def _build_health_context(self, fallback_events: List[Dict], latest_wellness: Dict,
                              today: str, fallback_oldest: str) -> Dict:
        """
        Build the health context block (v3.128, issue #27).

        Calendar markers are matched on the canonical Intervals.icu category, never on
        the event title. Intervals stores an EXCLUSIVE end: a single-day marker carries
        end_date_local at midnight of the following day, so the inclusive last
        CALENDAR-MARKED day is that date minus one. That is the end of the marking, not
        the last day the athlete was unwell. The events endpoint is indexed on start
        date and returns nothing for a date inside a multi-day span, so span detection
        must test the span, not the start date.

        A dedicated filtered fetch (category=SICK,INJURED) with a year-long lookback
        finds markers whose span began before the main event fetch floor. If that fetch
        raises a network/HTTP error the already-fetched event list is used instead:
        source_status becomes "partial", marker_active and recent_marker are OMITTED
        (they were not established - reporting False would claim a check that did not
        happen), and clarification_required stays True. Only RequestException is caught,
        and only around the fetch call itself, so every line that interprets the events
        sits outside the handler: a bug in this builder raises and fails the sync
        loudly rather than masquerading as incomplete coverage. Note that
        requests.exceptions.JSONDecodeError subclasses RequestException, so a malformed
        API response is treated as a failed fetch and degrades to "partial". That is
        deliberate - a bad upstream response is an upstream failure, and the whole sync
        should not die over the health endpoint - but it means "partial" can also mean
        "the endpoint answered with something unparseable", not only "unreachable".

        end_date_local is the end of the calendar MARKING, not evidence that the illness
        ended. Illness is normally marked for the current day because recovery cannot be
        predicted, so there is deliberately no "active" field that could be read as
        "recovered".

        NOT a readiness input. readiness_decision stays physiological and may read "go"
        while clarification_required is True. See SECTION_11.md 'Health Context'.
        """
        today_dt = datetime.strptime(today, "%Y-%m-%d")
        recent_cutoff = (today_dt - timedelta(
            days=self.HEALTH_RECENT_WINDOW_DAYS)).strftime("%Y-%m-%d")

        # Computed before the try block so nothing inside the handler can raise.
        fallback_lookback_days = None
        if fallback_oldest:
            try:
                fallback_lookback_days = (
                    today_dt - datetime.strptime(fallback_oldest[:10], "%Y-%m-%d")).days
            except ValueError:
                fallback_lookback_days = None

        oldest_health = (today_dt - timedelta(
            days=self.HEALTH_EVENT_LOOKBACK_DAYS)).strftime("%Y-%m-%d")
        newest_health = (today_dt + timedelta(
            days=self.HEALTH_EVENT_LOOKAHEAD_DAYS)).strftime("%Y-%m-%d")

        source_status = "ok"
        lookback_days = self.HEALTH_EVENT_LOOKBACK_DAYS
        try:
            source_events = self._intervals_get("events", {
                "oldest": oldest_health,
                "newest": newest_health,
                "category": ",".join(sorted(self.HEALTH_EVENT_CATEGORIES))
            })
            store = getattr(self, "_acquisition", None)
            health_status = store.source_status("health_events") if store else None
            if health_status and health_status["status"] != "fresh":
                source_status = "partial"
        except requests.exceptions.RequestException as e:
            # Degraded, not fatal: fall back to the events already fetched. They cover
            # a narrower window, so coverage is incomplete and must be reported as such.
            # JSONDecodeError subclasses RequestException, so an unparseable response
            # lands here too and is treated as a failed fetch - an upstream failure
            # should not kill a sync whose other data is fine. Only the fetch call is
            # inside this try, so a bug in the parsing below raises normally.
            print(f"   ⚠️  Health event fetch failed ({e}); falling back to main event window")
            source_events = fallback_events or []
            source_status = "partial"
            lookback_days = fallback_lookback_days

        current, recent, upcoming = [], [], []
        for evt in source_events:
            cat = evt.get("category", "")
            if cat not in self.HEALTH_EVENT_CATEGORIES:
                continue
            start = (evt.get("start_date_local") or "")[:10]
            if not start:
                continue

            end_date = self._calendar_end_date(evt)

            entry = {
                "event_id": evt.get("id"),
                "category": cat,
                "start_date": start,
                "end_date": end_date,
                "marker_active_today": start <= today <= end_date,
                "source": "calendar"
            }
            name = (evt.get("name") or "").strip()
            if name:
                entry["name"] = name
            desc = (evt.get("description") or "").strip()
            if desc:
                entry["description"] = desc

            if start > today:
                upcoming.append(entry)
            elif entry["marker_active_today"]:
                current.append(entry)
            elif end_date >= recent_cutoff:
                # days_since_end supports the 14-day illness gate under
                # 'Negative Triggers (Do NOT Suggest a Test)' without date arithmetic
                # in the AI layer.
                entry["days_since_end"] = (
                    today_dt - datetime.strptime(end_date, "%Y-%m-%d")).days
                recent.append(entry)
            # Older than the recent window and not active: outside this block's scope.

        # Deterministic ordering, independent of API return order.
        for bucket in (current, recent, upcoming):
            bucket.sort(key=lambda e: (e["start_date"], e["category"], str(e["event_id"])))

        # Wellness injury: CURRENT value only. The full series stays canonical in
        # wellness_data[] and history.json daily_90d[] - this is a pointer, not a copy.
        # A stale value is visible but triggers nothing: it is a last-known reading,
        # not an observation of today. Were it to trigger, an unchanged entry would make
        # the prompt permanent and therefore ignorable.
        injury = latest_wellness.get("injury")
        wellness_injury = None
        injury_requires_clarification = False
        if injury is not None and injury >= 2:
            injury_date = latest_wellness.get("id")
            days_old = None
            if injury_date:
                try:
                    days_old = (today_dt - datetime.strptime(
                        str(injury_date)[:10], "%Y-%m-%d")).days
                except ValueError:
                    days_old = None
            freshness = "current" if days_old == 0 else "stale"
            store = getattr(self, "_acquisition", None)
            wellness_status = store.source_status("wellness") if store else None
            if wellness_status and wellness_status["status"] != "fresh":
                freshness = "stale"
            wellness_injury = {
                "value": injury,
                "date": injury_date,
                "freshness": freshness,
                "series": "wellness_data[].injury / history.json daily_90d[].injury"
            }
            if days_old is not None:
                wellness_injury["days_old"] = days_old
            injury_requires_clarification = (freshness == "current" and injury >= 3)

        # Key order is fixed so the conditional booleans sit with source_status and the
        # emitted JSON stays byte-stable across syncs.
        context = {"source_status": source_status}
        if source_status == "ok":
            # Omitted under partial coverage: not established, and False would claim a
            # check that did not happen.
            context["marker_active"] = bool(current)
            context["recent_marker"] = bool(recent) and not current
        context["clarification_required"] = bool(
            current or recent or injury_requires_clarification or source_status != "ok"
        )
        context["lookback_days"] = lookback_days
        context["recent_window_days"] = self.HEALTH_RECENT_WINDOW_DAYS
        context["current"] = current
        context["recent"] = recent
        context["upcoming"] = upcoming
        if wellness_injury:
            context["wellness_injury"] = wellness_injury
        context["note"] = (
            "Athlete-reported illness / injury context. NOT a readiness input - "
            "readiness_decision is physiological and may read 'go' while "
            "clarification_required is true. Calendar markers are matched on the "
            "Intervals.icu category (SICK / INJURED), never the event title. end_date "
            "is the INCLUSIVE last CALENDAR-MARKED day (Intervals stores an exclusive "
            "end) - not the last day the athlete was unwell. "
            "end_date_local is the end of the calendar MARKING, not evidence the illness "
            "ended - illness is normally marked for the current day because recovery "
            "cannot be predicted, so a marker in 'recent' with none in 'current' means "
            "recovery status is UNKNOWN, not recovered. When clarification_required is "
            "true, do not give an unqualified full-program recommendation: acknowledge a "
            "current marker and establish severity, or ask whether the athlete has "
            "recovered after a recent one. Never an automatic Skip, and never grounds to "
            "relax an existing Skip. source_status 'partial' means the dedicated health "
            "fetch failed and this block was built from the narrower main event window: "
            "marker_active and recent_marker are omitted because they were not "
            "established, and an empty list is not evidence of no marker. A span "
            "beginning before lookback_days is not visible."
        )
        return context
    
    def _build_race_calendar(self, future_events: List[Dict], current_ctl: float,
                              current_atl: float, current_tsb: float,
                              activities_7d: List[Dict], today: str,
                              athlete_units: Optional[Dict[str, str]] = None) -> Dict:
        """
        Build race calendar with 3-layer awareness (v3.5.0).
        
        Layer 1: All races within 90-day window (always present)
        Layer 2: Taper onset alerts when RACE_A is 8-14 days out
        Layer 3: Race-week protocol when RACE_A/B is ≤7 days out
        
        References: Section 11A Race-Week Protocol
        Scientific basis: Mujika & Padilla (2003), Bosquet et al. (2007), Altini (HRV)
        
        athlete_units (v3.109): when provided, each race entry gets a
        display.distance block alongside canonical distance_meters.
        """
        
        today_date = datetime.strptime(today, "%Y-%m-%d").date()
        
        # Filter to race events only
        race_categories = {"RACE_A", "RACE_B", "RACE_C"}
        race_events = []
        for evt in future_events:
            cat = evt.get("category", "")
            if cat in race_categories:
                start = evt.get("start_date_local", "")[:10]
                if start:
                    try:
                        evt_date = datetime.strptime(start, "%Y-%m-%d").date()
                        days_until = (evt_date - today_date).days
                        if days_until >= 0:
                            distance_meters = evt.get("distance")
                            # Convert meters → km for the display helper (canonical kind="distance" expects km)
                            distance_km_for_display = (distance_meters / 1000) if distance_meters else None
                            race_entry = {
                                "id": evt.get("id"),
                                "name": evt.get("name", "Unnamed Race"),
                                "date": start,
                                "category": cat,
                                "type": evt.get("type", "Unknown"),
                                "days_until": days_until,
                                "moving_time_seconds": evt.get("moving_time"),
                                "distance_meters": distance_meters,
                                "display": {
                                    "distance": self._to_display(
                                        distance_km_for_display, "distance", athlete_units
                                    ),
                                },
                                **self._planned_route_fields(evt),
                                "_raw": evt  # Keep raw for race-week building
                            }
                            race_entry.update(self._event_start_fields(evt))
                            # Indoor flag: only include when True
                            if evt.get("indoor"):
                                race_entry["indoor"] = True
                            race_events.append(race_entry)
                    except ValueError:
                        continue
        
        # Sort by date
        race_events.sort(key=lambda x: x["days_until"])
        
        # Strip _raw from public output
        all_races = [{k: v for k, v in r.items() if k != "_raw"} for r in race_events]
        
        # Next race (any priority)
        next_race = all_races[0] if all_races else None
        
        # Taper alert: RACE_A within 8-14 days
        taper_race = next((r for r in race_events if r["category"] == "RACE_A" and 8 <= r["days_until"] <= 14), None)
        taper_alert = {"active": taper_race is not None}
        if taper_race:
            taper_alert["event_name"] = taper_race["name"]
            taper_alert["event_date"] = taper_race["date"]
            taper_alert["days_until"] = taper_race["days_until"]
            taper_alert["message"] = (
                f"RACE_A '{taper_race['name']}' in {taper_race['days_until']} days. "
                f"Begin volume reduction (target 41-60% over 2 weeks). Maintain intensity. "
                f"CTL should peak now or within the next few days."
            )
        
        # Race-week: RACE_A or RACE_B within 7 days
        # If both exist, prioritise RACE_A
        race_week_candidates = [r for r in race_events if r["category"] in {"RACE_A", "RACE_B"} and r["days_until"] <= 7]
        race_week_target = None
        if race_week_candidates:
            a_races = [r for r in race_week_candidates if r["category"] == "RACE_A"]
            race_week_target = a_races[0] if a_races else race_week_candidates[0]
        
        race_week = {"active": False}
        if race_week_target:
            race_week = self._build_race_week(
                race_event=race_week_target,
                current_ctl=current_ctl,
                current_atl=current_atl,
                current_tsb=current_tsb,
                activities_7d=activities_7d,
                today_date=today_date
            )
        
        return {
            "next_race": next_race,
            "all_races": all_races,
            "taper_alert": taper_alert,
            "race_week": race_week
        }
    
    def _build_race_week(self, race_event: Dict, current_ctl: float,
                          current_atl: float, current_tsb: float,
                          activities_7d: List[Dict], today_date) -> Dict:
        """
        Build race-week protocol data for D-7 through D-0.
        
        All load targets are relative to CTL. Normal weekly TSS = CTL × 7.
        Race-week TSS budget: 40-55% of normal weekly TSS (RACE_A) or 50-65% (RACE_B).
        
        TSB projection uses PMC decay: CTL_decay = e^(-1/42), ATL_decay = e^(-1/7).
        Assumes zero training load for remaining days to project race-day TSB.
        """
        
        evt_date = datetime.strptime(race_event["date"], "%Y-%m-%d").date()
        days_until = race_event["days_until"]
        category = race_event["category"]
        moving_time = race_event.get("moving_time_seconds")
        
        # Current day label
        current_day = f"D-{days_until}" if days_until > 0 else "D-0"
        
        # CTL baseline and normal weekly TSS
        ctl_baseline = current_ctl if current_ctl else 0
        normal_weekly_tss = round(ctl_baseline * 7, 1)
        
        # Race-week TSS budget (relative to category)
        if category == "RACE_A":
            budget_min_pct, budget_max_pct = 0.40, 0.55
        else:  # RACE_B
            budget_min_pct, budget_max_pct = 0.50, 0.65
        
        budget_min = round(normal_weekly_tss * budget_min_pct)
        budget_max = round(normal_weekly_tss * budget_max_pct)
        
        # Race-week TSS spent: sum TSS from activities within race week window
        race_week_start = evt_date - timedelta(days=7)
        tss_spent = 0
        for act in activities_7d:
            act_date_str = act.get("start_date_local", "")[:10]
            if act_date_str:
                try:
                    act_date = datetime.strptime(act_date_str, "%Y-%m-%d").date()
                    if race_week_start <= act_date <= today_date:
                        tss_spent += act.get("icu_training_load", 0) or 0
                except ValueError:
                    continue
        tss_spent = round(tss_spent)
        
        # TSB projection for race day (assume zero load for remaining days)
        ctl_decay = math.exp(-1/42)   # ~0.9765
        atl_decay = math.exp(-1/7)    # ~0.8668
        
        proj_ctl = current_ctl if current_ctl else 0
        proj_atl = current_atl if current_atl else 0
        for _ in range(days_until):
            proj_ctl *= ctl_decay
            proj_atl *= atl_decay
        projected_tsb = round(proj_ctl - proj_atl, 1)
        
        # Event duration classification
        if moving_time is not None:
            if moving_time < 5400:
                duration_class = "short_intense"
            elif moving_time <= 10800:
                duration_class = "medium"
            else:
                duration_class = "long_endurance"
        else:
            # Default by category when not set
            duration_class = "long_endurance" if category == "RACE_A" else "medium"
        
        # TSB target range by duration class
        tsb_targets = {
            "short_intense": {"min": 5, "max": 15},
            "medium": {"min": 10, "max": 20},
            "long_endurance": {"min": 10, "max": 25}
        }
        tsb_range = tsb_targets.get(duration_class, {"min": 10, "max": 25})
        
        # RACE_B: lower TSB target by 5
        if category == "RACE_B":
            tsb_range = {"min": max(0, tsb_range["min"] - 5), "max": tsb_range["max"] - 5}
        
        # Day-by-day decision tree
        day_protocol = self._get_day_protocol(days_until, ctl_baseline, duration_class, category)
        
        # Carb loading
        carb_applicable = False
        if moving_time is not None:
            carb_applicable = moving_time >= 5400
        elif category == "RACE_A":
            carb_applicable = True  # Default assumption for A races
        
        carb_active = carb_applicable and days_until <= 4
        carb_start_date = (evt_date - timedelta(days=4)).strftime("%Y-%m-%d")
        
        # Opener day (D-2)
        opener_date = (evt_date - timedelta(days=2)).strftime("%Y-%m-%d")
        opener_intensity = "lighter" if duration_class == "long_endurance" else (
            "more_intense" if duration_class == "short_intense" else "standard"
        )
        
        # Go/no-go: TSB status
        if projected_tsb >= tsb_range["min"]:
            tsb_status = "green"
            go_notes = []
        elif projected_tsb >= tsb_range["min"] - 10:
            tsb_status = "flag"
            go_notes = [f"Projected race-day TSB {projected_tsb} is below target range {tsb_range['min']}-{tsb_range['max']}. Consider additional rest."]
        else:
            tsb_status = "flag"
            go_notes = [f"Projected race-day TSB {projected_tsb} is significantly below target range {tsb_range['min']}-{tsb_range['max']}. Fatigue may impact performance."]
        
        return {
            "active": True,
            "event_name": race_event["name"],
            "event_date": race_event["date"],
            "event_category": category,
            "event_type": race_event.get("type", "Unknown"),
            "event_duration_class": duration_class,
            "event_moving_time_seconds": moving_time,
            "days_until_event": days_until,
            "current_day": current_day,
            "ctl_baseline": round(ctl_baseline, 1),
            "normal_weekly_tss": normal_weekly_tss,
            "race_week_tss_budget": {"min": budget_min, "max": budget_max},
            "race_week_tss_spent": tss_spent,
            "race_week_tss_remaining": {
                "min": max(0, budget_min - tss_spent),
                "max": max(0, budget_max - tss_spent)
            },
            "projected_race_day_tsb": projected_tsb,
            "tsb_target_range": tsb_range,
            "today": day_protocol,
            "carb_loading": {
                "applicable": carb_applicable,
                "active": carb_active,
                "starts": "D-4",
                "start_date": carb_start_date,
                "note": "10-12 g·kg⁻¹/day. No depletion phase needed." if carb_applicable else None
            },
            "opener": {
                "day": "D-2",
                "date": opener_date,
                "intensity": opener_intensity
            },
            "go_no_go": {
                "tsb_status": tsb_status,
                "notes": go_notes
            }
        }
    
    def _get_day_protocol(self, days_until: int, ctl: float, duration_class: str, category: str) -> Dict:
        """
        Return today's race-week protocol based on days until event.
        Load targets as TSS = percentage of CTL.
        """
        # Day protocol definitions: (label, min_pct, max_pct, zones, purpose)
        protocols = {
            7: ("Last key session", 0.75, 1.00, "3-5 efforts Z4-Z5 (1-3 min)", "Fitness confirmation. Verify strong power/HR response."),
            6: ("Recovery", 0.00, 0.30, "Z1-Z2 only", "Active recovery."),
            5: ("Moderate endurance", 0.40, 0.60, "Z1-Z2 + 2-3 race-pace touches", "Maintain feel without adding fatigue."),
            4: ("Easy / rest", 0.00, 0.40, "Z1-Z2 only", "Volume reduction. Carb loading begins if applicable."),
            3: ("Easy / rest", 0.00, 0.40, "Z1-Z2 only", "Taper tantrums expected (D-4 to D-2). Normal — not lost fitness."),
            2: ("Opener", 0.30, 0.50, "3-5 efforts Z4-Z6 (20-60s), high cadence, full recovery", "Neuromuscular activation."),
            1: ("Rest / minimal", 0.00, 0.20, "Z1 only if active", "Final rest, logistics, equipment check."),
            0: ("Race day", 0.00, 0.00, "Race effort", "Go/no-go assessment. Execute race plan.")
        }
        
        # Default for days > 7 (shouldn't happen in race week, but defensive)
        if days_until > 7:
            return {
                "label": "Pre-race-week",
                "load_target_tss": None,
                "zones": "Normal training",
                "purpose": "Race week protocol not yet active for this day."
            }
        
        label, min_pct, max_pct, zones, purpose = protocols.get(days_until, protocols[0])
        
        # Adjust opener intensity by duration class
        if days_until == 2:
            if duration_class == "long_endurance":
                zones = "3-4 efforts Z4 only (20-60s), moderate cadence, full recovery"
                purpose = "Light neuromuscular activation. Preserve glycogen."
            elif duration_class == "short_intense":
                zones = "5-6 efforts Z4-Z6 (10-30s), high cadence, full recovery"
                purpose = "Full neuromuscular activation for short, intense effort."
        
        # For long endurance events, prefer easy endurance over complete rest on D-4/D-3
        if days_until in (3, 4) and duration_class == "long_endurance":
            min_pct = 0.20  # Nudge minimum up — easy spin preferred over full rest
            purpose = f"{purpose} Easy endurance preferred over complete rest for long events."
        
        min_tss = round(ctl * min_pct)
        max_tss = round(ctl * max_pct)
        
        return {
            "label": label,
            "load_target_tss": {"min": min_tss, "max": max_tss},
            "zones": zones,
            "purpose": purpose
        }
    
    def _generate_race_alerts(self, race_calendar: Dict) -> List[Dict]:
        """Generate race-specific alerts for the alerts array."""
        alerts = []
        
        # Taper onset alert
        taper = race_calendar.get("taper_alert", {})
        if taper.get("active"):
            alerts.append({
                "metric": "race_taper",
                "value": taper.get("days_until"),
                "severity": "info",
                "threshold": "RACE_A within 8-14 days",
                "context": taper.get("message", "Taper onset detected."),
                "persistence_days": None,
                "tier": 1
            })
        
        # Race-week alerts
        rw = race_calendar.get("race_week", {})
        if rw.get("active"):
            # Daily status alert
            today_proto = rw.get("today", {})
            load = today_proto.get("load_target_tss", {})
            alerts.append({
                "metric": "race_week",
                "value": rw.get("days_until_event"),
                "severity": "info",
                "threshold": f"{rw.get('event_category')} within 7 days",
                "context": (
                    f"Race week {rw.get('current_day')} of '{rw.get('event_name')}'. "
                    f"Today: {today_proto.get('label', '?')}, "
                    f"{load.get('min', 0)}-{load.get('max', 0)} TSS. "
                    f"{today_proto.get('zones', '')}"
                ),
                "persistence_days": None,
                "tier": 1
            })
            
            # TSB projection warning
            projected = rw.get("projected_race_day_tsb")
            tsb_range = rw.get("tsb_target_range", {})
            if projected is not None and tsb_range:
                if projected < tsb_range.get("min", 0):
                    alerts.append({
                        "metric": "race_week_tsb",
                        "value": projected,
                        "severity": "warning",
                        "threshold": f"TSB target {tsb_range.get('min')}-{tsb_range.get('max')}",
                        "context": (
                            f"Projected race-day TSB {projected} is below target range "
                            f"{tsb_range.get('min')}-{tsb_range.get('max')}. "
                            f"Consider additional rest to reach target."
                        ),
                        "persistence_days": None,
                        "tier": 1
                    })
        
        return alerts
    
    def _compute_weekly_summary(self, activities: List[Dict], wellness: List[Dict]) -> Dict:
        """Compute weekly training summary from actual activity data"""
        total_tss = sum(act.get("icu_training_load", 0) for act in activities if act.get("icu_training_load"))
        total_seconds = sum(act.get("moving_time", 0) for act in activities)
        total_hours = total_seconds / 3600

        avg_hrv = None
        avg_rhr = None
        if wellness:
            hrv_values = [w.get("hrv") for w in wellness if self._is_valid_hrv(w.get("hrv"))]
            rhr_values = [w.get("restingHR") for w in wellness if w.get("restingHR")]
            avg_hrv = round(sum(hrv_values) / len(hrv_values), 1) if hrv_values else None
            avg_rhr = round(sum(rhr_values) / len(rhr_values), 1) if rhr_values else None

        return {
            "total_training_hours": round(total_hours, 2),
            "total_training_formatted": self._format_duration(int(total_seconds) // 60 * 60),
            "total_tss": round(total_tss, 0),
            "activities_count": len(activities),
            "avg_hrv": avg_hrv,
            "avg_resting_hr": avg_rhr
        }
    
    def _compute_activity_summary(self, activities: List[Dict], days_back: int = 7,
                                  athlete_units: Optional[Dict[str, str]] = None) -> Dict:
        """Compute summary by activity type with human-readable format.
        
        athlete_units (v3.109): when provided, each by_activity_type entry gets a
        display.distance block. Canonical distance_km stays unchanged for any
        consumer that calculates from this surface.
        """
        by_type = defaultdict(lambda: {"count": 0, "seconds": 0, "tss": 0, "distance_km": 0})
        
        for act in activities:
            activity_type = act.get("type", "Unknown")
            by_type[activity_type]["count"] += 1
            
            time_seconds = act.get("moving_time", 0)
            
            by_type[activity_type]["seconds"] += time_seconds
            by_type[activity_type]["tss"] += act.get("icu_training_load", 0) or 0
            by_type[activity_type]["distance_km"] += (act.get("distance", 0) or 0) / 1000
        
        activity_breakdown = {}
        total_seconds = 0
        
        for activity_type, data in sorted(by_type.items()):
            distance_km = round(data["distance_km"], 1)
            entry = {
                "duration_decimal_hours": round(data["seconds"] / 3600, 2),
                "count": data["count"],
                "tss": round(data["tss"], 0),
                "distance_km": distance_km,
                "display": {
                    "distance": self._to_display(distance_km, "distance", athlete_units),
                }
            }
            activity_breakdown[activity_type] = entry
            total_seconds += data["seconds"]
        
        return {
            "period_description": f"Last {days_back} days of training (including today)",
            "note": "Duration calculated from API moving_time field.",
            "total_duration_decimal_hours": round(total_seconds / 3600, 2),
            "total_activities": len(activities),
            "by_activity_type": activity_breakdown
        }
    
    def publish_to_github(self, data: Dict, filepath: str = "latest.json", 
                         commit_message: str = None) -> str:
        """Publish data to GitHub repository"""
        if not self.github_token or not self.github_repo:
            raise ValueError("GitHub token and repo required for publishing")
        
        if not commit_message:
            commit_message = f"Update training data - {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}"
        
        headers = {
            "Authorization": f"token {self.github_token}",
            "Accept": "application/vnd.github+json"
        }
        
        url = f"{self.GITHUB_API_URL}/repos/{self.github_repo}/contents/{filepath}"
        raw_url = f"https://raw.githubusercontent.com/{self.github_repo}/main/{filepath}"
        content_json = json.dumps(data, indent=2, default=str)

        # --- Pre-read gate (v3.133) ---
        # The old code turned ANY failed pre-read into current_sha = None, which sent
        # a create-style PUT at a path that may exist. Only a confirmed 404 can
        # establish absence; every other outcome stops before the PUT.
        try:
            response = self._read_with_retry(
                lambda: requests.get(url, headers=headers,
                                     timeout=self.GITHUB_READ_TIMEOUT),
                charge_instance_budget=False)
        except requests.exceptions.RequestException as e:
            raise PublishPreReadFailed(
                f"{filepath}: pre-read did not complete ({e}); no write attempted")

        if response.status_code == 200:
            # A 200 establishes an existing file only if it carries a usable sha and
            # decodable content. A null, empty or non-string sha would otherwise be
            # dropped by the truthiness test below and produce a create-style PUT,
            # which only a confirmed 404 may authorise.
            try:
                current_file = response.json()
                if not isinstance(current_file, dict):
                    raise ValueError("expected an object")
                current_sha = current_file.get("sha")
                if not isinstance(current_sha, str) or not current_sha:
                    raise ValueError("sha is missing, empty or not a string")
                if current_sha != current_sha.strip():
                    # " s1 " is not a usable sha. Trimming it here would guess at what
                    # the server meant; sending it verbatim puts a value in the PUT
                    # that cannot match.
                    raise ValueError("sha carries surrounding whitespace")
                current_content = self._decode_github_content(
                    current_file.get("content"))
            except Exception as e:
                raise PublishPreReadFailed(
                    f"{filepath}: pre-read returned an unusable body ({e}); "
                    f"no write attempted")
            if current_content == content_json:
                print("⏭️  No changes detected, skipping update")
                return raw_url
        elif response.status_code == 404:
            current_sha = None          # confirmed absent: create is safe
        else:
            raise PublishPreReadFailed(
                f"{filepath}: pre-read returned HTTP {response.status_code}, which "
                f"does not establish whether the path exists; no write attempted")

        payload = {
            "message": commit_message,
            "content": base64.b64encode(content_json.encode()).decode(),
            "branch": "main"
        }
        if current_sha:
            payload["sha"] = current_sha

        # --- Single write attempt (v3.133). There is no second PUT anywhere. ---
        try:
            response = requests.put(url, headers=headers, json=payload,
                                    timeout=self.GITHUB_WRITE_TIMEOUT)
        except requests.exceptions.RequestException as e:
            # Every requests exception raised after dispatch is ambiguous, not just a
            # timeout: a truncated or chunked response stream means the commit may
            # already have happened and only the answer was lost.
            return self._verify_github_publish(url, headers, content_json, raw_url,
                                               filepath,
                                               f"transport: {type(e).__name__}")

        if 200 <= response.status_code < 300:
            return raw_url
        if response.status_code in self.GITHUB_DEFINITIVE_WRITE_STATUSES:
            response.raise_for_status()     # definitive refusal, including 409
        # Everything else, a 429, a 5xx, a redirect or any other unexpected status,
        # is indeterminate. raise_for_status() would let a 3xx through as success, so
        # the status is checked explicitly and the file is read back instead.
        return self._verify_github_publish(
            url, headers, content_json, raw_url, filepath,
            f"http_{response.status_code}")

    def _verify_github_publish(self, url: str, headers: Dict, intended_content: str,
                               raw_url: str, filepath: str, cause: str) -> str:
        """
        Read the remote file back after an ambiguous PUT. Only byte-equal intended
        content proves the write landed. Everything else, including the pre-write
        content, is unknown: a commit can still be in flight, so observing the old
        body does not prove non-application. No second PUT is ever issued; the next
        scheduled sync is the recovery path.
        """
        try:
            response = self._read_with_retry(
                lambda: requests.get(url, headers=headers,
                                     timeout=self.GITHUB_READ_TIMEOUT),
                charge_instance_budget=False)
        except requests.exceptions.RequestException as e:
            raise PublishOutcomeUnknown(
                f"{filepath}: write outcome UNKNOWN after {cause}; verification read "
                f"failed ({e}). No write retry was issued.")
        if response.status_code != 200:
            raise PublishOutcomeUnknown(
                f"{filepath}: write outcome UNKNOWN after {cause}; verification read "
                f"returned HTTP {response.status_code}. No write retry was issued.")
        try:
            body = response.json()
            if not isinstance(body, dict):
                raise ValueError("expected an object")
            remote_content = self._decode_github_content(body.get("content"))
        except Exception as e:
            raise PublishOutcomeUnknown(
                f"{filepath}: write outcome UNKNOWN after {cause}; verification body "
                f"unusable ({e}). No write retry was issued.")
        if remote_content == intended_content:
            print(f"   ✅ {filepath}: write confirmed by read-back after {cause}")
            return raw_url
        raise PublishOutcomeUnknown(
            f"{filepath}: write outcome UNKNOWN after {cause}; remote content does "
            f"not match the intended content. No write retry was issued.")
    
    def save_local_outputs(self, data, filepath):
        """Write companions first, then describe the actual output set in latest."""
        for name, _, _, attribute in DataOverview.COMPANIONS:
            value = getattr(self, attribute, None) if attribute else None
            if value is None:
                continue
            if attribute == "_saved_workouts_data":
                self._sw_write(value)
            else:
                with open(self.data_dir / name, "w") as handle:
                    json.dump(value, handle, indent=2, default=str)
        overview = DataOverview.build(self, data, Path(filepath).name)
        remaining = dict(data)
        remaining.pop("data_overview", None)
        data.clear()
        if "READ_THIS_FIRST" in remaining:
            first = remaining.pop("READ_THIS_FIRST")
            if isinstance(first, dict):
                first["data_overview"] = "Read data_overview immediately below for companion files and route/weather/map status."
            data["READ_THIS_FIRST"] = first
        data["data_overview"] = overview
        data.update(remaining)
        result = self.save_to_file(data, filepath)
        cache = getattr(self, "_hosted_cache", None)
        if cache is not None:
            cache.export(data)
        return result

    def save_to_file(self, data: Dict, filepath: str = "latest.json"):
        """Save data to local JSON file"""
        with open(filepath, 'w') as f:
            json.dump(data, f, indent=2, default=str)
        print(f"Data saved to {filepath}")
        return filepath


